/**
 * Calculates Recall@K for a given set of ranked results against expected card names.
 * @param {Array<string>} rankedResultNames - Array of card names in ranked order.
 * @param {Array<string>} expectedNames - Array of expected target card names.
 * @param {number} k - Cutoff depth (e.g. 5, 10, 20).
 * @returns {number} Fraction of expected cards found in the top K.
 */
function calculateRecallAtK(rankedResultNames, expectedNames, k) {
    if (!expectedNames || expectedNames.length === 0) return 0;
    const topK = rankedResultNames.slice(0, k).map(name => name.toLowerCase());
    const hits = expectedNames.filter(exp => topK.includes(exp.toLowerCase())).length;
    return hits / expectedNames.length;
}

/**
 * Finds the 1-based ranks of expected cards within ranked results.
 * @param {Array<string>} rankedResultNames - Array of card names in ranked order.
 * @param {Array<string>} expectedNames - Array of expected target card names.
 * @param {number} unrankedPenalty - Rank assigned if card is not found in results.
 * @returns {Object} Map of expected card names to their 1-based ranks.
 */
function getExpectedCardRanks(rankedResultNames, expectedNames, unrankedPenalty = 100) {
    const lowerResults = rankedResultNames.map(name => name.toLowerCase());
    const ranks = {};

    for (const exp of expectedNames) {
        const index = lowerResults.indexOf(exp.toLowerCase());
        ranks[exp] = index !== -1 ? index + 1 : unrankedPenalty;
    }

    return ranks;
}

/**
 * Precision@K - of the top K results actually shown, what fraction were expected cards?
 * Recall asks "did we find them"; precision asks "how much noise came with them". A change that
 * lifts recall by flooding the list with near-misses will show up here as a precision drop.
 */
function calculatePrecisionAtK(rankedResultNames, expectedNames, k) {
    if (!rankedResultNames || rankedResultNames.length === 0 || k <= 0) return 0;
    const expectedLower = new Set((expectedNames || []).map(n => n.toLowerCase()));
    const topK = rankedResultNames.slice(0, k).map(n => n.toLowerCase());
    if (topK.length === 0) return 0;
    return topK.filter(n => expectedLower.has(n)).length / topK.length;
}

/**
 * Mean Reciprocal Rank - 1/(rank of the FIRST expected card), 0 if none appear.
 * Recall@K is a step function: it can't tell "the answer was #1" from "the answer was #19".
 * MRR is sensitive to exactly that, which is what you want when tuning ranking rather than
 * retrieval (review Priority 15).
 */
function calculateMRR(rankedResultNames, expectedNames) {
    if (!expectedNames || expectedNames.length === 0) return 0;
    const expectedLower = new Set(expectedNames.map(n => n.toLowerCase()));
    for (let i = 0; i < rankedResultNames.length; i++) {
        if (expectedLower.has(rankedResultNames[i].toLowerCase())) return 1 / (i + 1);
    }
    return 0;
}

/**
 * Normalized Discounted Cumulative Gain at K.
 * Unlike MRR (which only sees the first hit) or Recall@K (which ignores order entirely), NDCG
 * rewards getting ALL the expected cards high up, with a logarithmic position discount - the
 * metric that best reflects "the good alternatives are at the top of my list".
 */
function calculateNDCGAtK(rankedResultNames, expectedNames, k) {
    if (!expectedNames || expectedNames.length === 0) return 0;
    const expectedLower = new Set(expectedNames.map(n => n.toLowerCase()));

    let dcg = 0;
    rankedResultNames.slice(0, k).forEach((name, i) => {
        if (expectedLower.has(name.toLowerCase())) dcg += 1 / Math.log2(i + 2);
    });

    // Ideal DCG: every expected card packed into the top positions.
    let idcg = 0;
    const idealHits = Math.min(expectedNames.length, k);
    for (let i = 0; i < idealHits; i++) idcg += 1 / Math.log2(i + 2);

    return idcg > 0 ? dcg / idcg : 0;
}

/**
 * Per-stage recall from the diagnostics funnel: what fraction of expected cards survived each
 * pipeline stage. This separates "we never retrieved it" from "we retrieved it and then ranked it
 * badly" - two failures Recall@20 reports identically but which need completely different fixes.
 */
function calculateStageRecalls(diagnostics, expectedNames) {
    const empty = { retrieval: 0, filter: 0, dedup: 0, parse: 0, scoring: 0, pruning: 0 };
    if (!diagnostics || !expectedNames || expectedNames.length === 0) return empty;

    const lower = expectedNames.map(n => n.toLowerCase());
    const frac = (set) => set ? lower.filter(n => set.has(n)).length / lower.length : 0;

    return {
        retrieval: frac(diagnostics.rawCandidateNames),
        filter: frac(diagnostics.passedFilterNames),
        dedup: frac(diagnostics.dedupedNames),
        parse: frac(diagnostics.meaningfulParseNames),
        scoring: frac(diagnostics.scoredNames),
        pruning: frac(diagnostics.passedRelevanceFloorNames)
    };
}

/**
 * Identifies the pipeline stage where an expected card was lost, so a failing test says WHY it
 * failed rather than just reporting zero recall.
 */
function diagnoseFailureStage(diagnostics, expectedName, finalRankIndex) {
    if (finalRankIndex !== -1) return 'ranked';
    if (!diagnostics) return 'unknown (no diagnostics)';
    const n = expectedName.toLowerCase();
    if (!diagnostics.rawCandidateNames?.has(n)) return 'retrieval (never returned by any stream)';
    if (!diagnostics.passedFilterNames?.has(n)) return 'hard filters (excluded by constraints)';
    if (!diagnostics.dedupedNames?.has(n)) return 'deduplication';
    // The parse stage was missing from this chain, so a card that failed parsing was reported as
    // failing at "scoring" - pointing debugging at the wrong subsystem entirely (review
    // Priority 4). Checked here, between dedup and scoring, matching the real pipeline order.
    if (diagnostics.meaningfulParseNames && !diagnostics.meaningfulParseNames.has(n)
        && diagnostics.scoredNames?.has(n)) {
        return 'parsing (scored, but text fell back to generic - weak mechanical signal)';
    }
    if (!diagnostics.scoredNames?.has(n)) return 'scoring (not scored)';
    if (diagnostics.relevanceFloorRescued && diagnostics.passedRelevanceFloorNames?.has(n)) return 'relevance-floor rescue';
    if (!diagnostics.passedRelevanceFloorNames?.has(n)) return 'relevance floor (pruned)';
    return 'ranking (fell outside displayed results)';
}

/**
 * Loads SheetJS on demand from a CDN. Done lazily rather than as a page-level <script> so the
 * ~400KB library is only ever fetched when someone actually runs a benchmark.
 * @returns {Promise<Object|null>} the XLSX namespace, or null if it couldn't be loaded
 */
function loadSheetJS() {
    if (window.XLSX) return Promise.resolve(window.XLSX);

    return new Promise((resolve) => {
        const existing = document.querySelector('script[data-sheetjs]');
        if (existing) {
            existing.addEventListener('load', () => resolve(window.XLSX || null));
            existing.addEventListener('error', () => resolve(null));
            return;
        }

        const script = document.createElement('script');
        script.src = 'https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js';
        script.dataset.sheetjs = 'true';
        script.onload = () => resolve(window.XLSX || null);
        script.onerror = () => resolve(null);
        document.head.appendChild(script);
    });
}

/**
 * Forces a browser download of a Blob. Creating the anchor, appending it to the document, and
 * revoking the object URL afterwards are all required - a detached anchor won't reliably fire a
 * download in Firefox, and skipping revokeObjectURL leaks the blob for the page's lifetime.
 * @param {Blob} blob
 * @param {string} filename
 */
function triggerBrowserDownload(blob, filename) {
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    link.style.display = 'none';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    // Delay revocation slightly; revoking synchronously can cancel the download mid-flight.
    setTimeout(() => URL.revokeObjectURL(url), 1000);
}

/**
 * Builds and downloads a multi-sheet workbook of a completed benchmark run.
 *
 * Sheets: Summary (headline metrics), Per-Test Metrics, Category Breakdown, Expected Card Trace
 * (the per-card funnel, including which stage lost each miss), Pipeline Diagnostics, and Stream
 * Coverage. Falls back to a CSV of the per-test metrics if SheetJS can't be loaded, so a run is
 * never lost just because the CDN was unreachable.
 *
 * @param {Object} report - the report object returned by runBenchmarkSuite
 * @returns {Promise<boolean>} whether an .xlsx (true) or the CSV fallback (false) was downloaded
 */
async function downloadBenchmarkWorkbook(report) {
    const stamp = formatBenchmarkDateStamp(report.generatedAt || new Date());
    const baseName = `Benchmark test_${stamp}`;

    const pct = (v) => v === null || v === undefined ? 'n/a' : `${((v || 0) * 100).toFixed(2)}%`;
    const num = (v, d = 4) => (v === null || v === undefined) ? '' : Number((v || 0).toFixed(d));
    const durStr = (ms) => (ms === null || ms === undefined) ? '' : `${(ms / 1000).toFixed(2)}s`;

    // --- Sheet: Overview (a proper dashboard, not just a metrics dump) ---
    const overviewRows = [
        { Metric: 'Run ID', Value: report.runId || '' },
        { Metric: 'ManaSearch app build', Value: MANASEARCH_APP_BUILD },
        { Metric: 'Benchmark started', Value: (report.startedAt || report.generatedAt || new Date()).toLocaleString() },
        { Metric: 'Benchmark finished', Value: (report.finishedAt || report.generatedAt || new Date()).toLocaleString() },
        { Metric: 'Total runtime', Value: durStr(report.durationMs) },
        { Metric: 'Tests total', Value: report.structuredResults.length },
        { Metric: 'Tests successful', Value: report.structuredResults.filter(r => r.strict.testStatus === 'ok').length },
        { Metric: 'Tests errored', Value: report.structuredResults.filter(r => r.strict.testStatus === 'error').length },
        { Metric: 'Tests empty', Value: report.structuredResults.filter(r => r.strict.testStatus === 'empty').length },
        ...(report.benchmarkConfiguration ? [
            { Metric: 'Benchmark ranking', Value: report.benchmarkConfiguration.ranking || '' },
            { Metric: 'Benchmark search methods', Value: report.benchmarkConfiguration.searchMethods || '' },
            { Metric: 'Benchmark ordering features', Value: report.benchmarkConfiguration.orderingFeatures || '' },
            { Metric: 'Benchmark weight offsets', Value: report.benchmarkConfiguration.userWeightOffsets || '' }
        ] : []),
        { Metric: '', Value: '' },
        { Metric: 'Mean Recall@5', Value: pct(report.meanRecall5) },
        { Metric: 'Mean Recall@10', Value: pct(report.meanRecall10) },
        { Metric: 'Mean Recall@20', Value: pct(report.meanRecall20) },
        { Metric: 'Mean Adjusted Recall@20', Value: pct(report.meanAdjustedRecall20) },
        { Metric: 'Mean Semantic Recall@20', Value: report.meanSemanticRecall20 !== null ? pct(report.meanSemanticRecall20) : 'n/a (no preferred-constraint tests)' },
        { Metric: 'Semantic Recall tests measured (denominator)', Value: report.semanticRecallTestCount ?? 0 },
        { Metric: 'Mean Retrieval Recall (ceiling)', Value: pct(report.meanRetrievalRecall) },
        { Metric: 'Mean MRR', Value: num(report.meanMRR) },
        { Metric: 'Mean NDCG@10', Value: num(report.meanNDCG10) },
        { Metric: 'Mean NDCG@20', Value: num(report.meanNDCG20) },
        { Metric: 'Mean Precision@10', Value: num(report.meanPrecision10) },
        { Metric: 'Overall Avg Card Rank', Value: num(report.overallAvgRank, 2) },
        { Metric: 'Embedding cache hits', Value: report.embeddingCacheDiagnostics?.hits ?? 0 },
        { Metric: 'Embedding computations', Value: report.embeddingCacheDiagnostics?.computed ?? 0 },
        { Metric: 'Embedding cache evictions', Value: report.embeddingCacheDiagnostics?.evictions ?? 0 },
        { Metric: 'Embedding cache entries at end', Value: report.embeddingCacheDiagnostics?.entries ?? 0 },
        { Metric: 'Candidate Oracle vectors from semantic-index.bin', Value: report.embeddingCacheDiagnostics?.precomputedOracleHits ?? 0 },
        { Metric: 'Candidate Oracle vector misses', Value: report.embeddingCacheDiagnostics?.precomputedOracleMisses ?? 0 },
        { Metric: 'Semantic worker queries', Value: report.semanticQueryDiagnostics?.workerQueries ?? 0 },
        { Metric: 'Semantic worker elapsed', Value: durStr(report.semanticQueryDiagnostics?.workerElapsedMs ?? 0) },
        { Metric: 'Semantic worker failures', Value: report.semanticQueryDiagnostics?.workerFailures ?? 0 },
        { Metric: 'Semantic fallback scans', Value: report.semanticQueryDiagnostics?.fallbackQueries ?? 0 },
        { Metric: 'Semantic fallback elapsed', Value: durStr(report.semanticQueryDiagnostics?.fallbackElapsedMs ?? 0) }
    ];

    // --- Sheet: vs Previous Run (regression tracking) ---
    let regressionRows = null;
    if (report.previousRun) {
        const p = report.previousRun;
        const rows = (label, key, isPct) => {
            const prev = p[key], curr = report[key];
            if (prev === undefined || prev === null || curr === undefined || curr === null) return null;
            const delta = curr - prev;
            return {
                'Metric': label,
                'Previous': isPct ? pct(prev) : key === 'durationMs' ? durStr(prev) : num(prev),
                'Current': isPct ? pct(curr) : key === 'durationMs' ? durStr(curr) : num(curr),
                'Change': key === 'durationMs' ? `${delta >= 0 ? '+' : ''}${(delta / 1000).toFixed(2)}s`
                    : isPct ? `${delta >= 0 ? '+' : ''}${(delta * 100).toFixed(2)}pp`
                    : `${delta >= 0 ? '+' : ''}${delta.toFixed(4)}`
            };
        };
        regressionRows = [
            rows('Run compared', null, false) && { 'Metric': 'Run ID', 'Previous': p.runId || '', 'Current': report.runId || '', 'Change': '' },
            rows('Recall@20', 'meanRecall20', true),
            rows('Adjusted Recall@20', 'meanAdjustedRecall20', true),
            rows('Retrieval Recall', 'meanRetrievalRecall', true),
            rows('MRR', 'meanMRR', false),
            rows('NDCG@20', 'meanNDCG20', false),
            rows('Avg runtime', 'durationMs', false)
        ].filter(Boolean);
    }

    // --- Sheet: Per-Test Metrics (strict + semantic side by side) ---
    const perTestRows = report.structuredResults.map(r => {
        const s = r.strict;
        return {
            'Test ID': r.id,
            'Name': r.name,
            'Source Card': r.source,
            'Highlights': (r.highlights || []).map(h => `${h.mode}: ${h.text}`).join(' | '),
            'Categories': (r.categories || []).join(', '),
            'Preferred Constraints': (r.preferredConstraints || []).join(', '),
            'Status': s.testStatus,
            'Error': s.errorMessage || '',
            'Duration': durStr(r.durationMs),
            'Recall@5': num(s.recall5, 3),
            'Recall@10': num(s.recall10, 3),
            'Recall@20': num(s.recall20, 3),
            'Adj Recall@20': num(s.adjustedRecall20, 3),
            'Semantic Recall@20': r.semantic ? num(r.semantic.recall20, 3) : '',
            'MRR': num(s.mrr),
            'NDCG@10': num(s.ndcg10),
            'NDCG@20': num(s.ndcg20),
            'Precision@10': num(s.precision10),
            'Retrieval Recall': num(s.stageRecalls.retrieval, 3),
            'Filter Recall': num(s.stageRecalls.filter, 3),
            'Scoring Recall': num(s.stageRecalls.scoring, 3),
            'Pruning Recall': num(s.stageRecalls.pruning, 3),
            'Avg Expected Rank': num(s.avgTestRank, 2),
            'Predicate': r.relevancePredicate || '',
            'Predicate Relevant Set Size': Array.isArray(r.predicateExpected) ? r.predicateExpected.length : '',
            'Predicate Precision@10': s.predicatePrecision10 === null || s.predicatePrecision10 === undefined ? '' : num(s.predicatePrecision10, 3),
            'Predicate NDCG@10': s.predicateNdcg10 === null || s.predicateNdcg10 === undefined ? '' : num(s.predicateNdcg10, 3),
            'Results Returned': (s.rankedResults || []).length
        };
    });

    // --- Sheet: Test Timing ---
    const timingRows = report.structuredResults.map(r => {
        const d = r.strict.diagnostics || {};
        const t = d.timings || {};
        const e = d.embeddingDiagnostics || {};
        const inner = e.stageTimings || {};
        return {
            'Test ID': r.id, 'Source Card': r.source, 'Status': r.strict.testStatus,
            'Total Duration': durStr(r.durationMs),
            'Retrieval': durStr(t.retrievalMs), 'NLP + Scoring': durStr(t.scoringMs),
            'Ranking/Pruning': durStr(t.rankingMs), 'Rendering': durStr(t.renderMs),
            'Search Total (findSimilarCards)': durStr(t.totalMs),
            'Candidate Count': e.totalCandidates ?? '',
            'Semantic Candidates': e.semanticEligibleCount ?? '',
            'Embedding Cache Hits': e.cacheHits ?? '',
            'Embeddings Computed': e.computed ?? '',
            'Embedding Failures': e.failed ?? '',
            'Structural/Profile Pass': durStr(inner.structuralMs),
            'Parse': durStr(inner.structuralDetails?.parseMs),
            'Exactness': durStr(inner.structuralDetails?.exactnessMs),
            'Profile/Graph/Synergy': durStr(inner.structuralDetails?.profileGraphSynergyMs),
            'Mechanical Pairing': durStr(inner.structuralDetails?.mechanicalPairingMs),
            'Role/Highlight/Confidence': durStr(inner.structuralDetails?.roleHighlightConfidenceMs),
            'Category': durStr(inner.structuralDetails?.categoryMs),
            'Triage/Selection': durStr(inner.triageAndSelectionMs),
            'Embedding Preparation': durStr(inner.embeddingTextPreparationMs),
            'Embedding Cache Warm': durStr(inner.embeddingWarmCacheMs),
            'Embedding Batch Calls': e.inferenceBatchCalls ?? '',
            'Embedding Batch Items': e.inferenceBatchItems ?? '',
            'Embedding Max Batch Size': e.inferenceBatchMaxSize ?? '',
            'Embedding Batch Time': durStr(e.inferenceBatchMs),
            'Embedding Batch Failures': e.inferenceBatchFailures ?? '',
            'Embedding Fallback Splits': e.inferenceFallbackSplits ?? '',
            'Graph Similarity Cache Hits': inner.reuseCaches?.graphSimilarityHits ?? '',
            'Graph Similarity Computed': inner.reuseCaches?.graphSimilarityComputed ?? '',
            'Strategic Role Cache Hits': inner.reuseCaches?.strategicRoleHits ?? '',
            'Strategic Role Computed': inner.reuseCaches?.strategicRoleComputed ?? '',
            'Role Fingerprint Cache Hits': inner.reuseCaches?.roleFingerprintHits ?? '',
            'Role Fingerprints Computed': inner.reuseCaches?.roleFingerprintComputed ?? '',
            'Keyword Regex Cache Hits': inner.reuseCaches?.keywordRegexHits ?? '',
            'Keyword Regex Compiled': inner.reuseCaches?.keywordRegexComputed ?? '',
            'Keyword Regex Evictions': inner.reuseCaches?.keywordRegexEvictions ?? '',
            'Token Normalize Cache Hits': inner.reuseCaches?.tokenNormalizationHits ?? '',
            'Token Normalize Computed': inner.reuseCaches?.tokenNormalizationComputed ?? '',
            'Token Normalize Evictions': inner.reuseCaches?.tokenNormalizationEvictions ?? '',
            'Semantic Pass': durStr(inner.semanticPassMs),
            'Calibration': durStr(inner.calibrationMs),
            'Final Score Blend': durStr(inner.finalBlendMs),
            'Unattributed Scoring': durStr(inner.unattributedMs),
            'Recall@20': pct(r.strict.recall20), 'MRR': num(r.strict.mrr)
        };
    });

    // --- Sheet: Expected Card Trace (per-card funnel + score breakdown, strict + semantic) ---
    const traceRows = [];
    const buildTraceRows = (pass, r, passLabel) => {
        if (!pass) return;
        const d = pass.diagnostics;
        const lowerResults = (pass.rankedResults || []).map(n => n.toLowerCase());
        const conflicts = new Set((r.constraintConflicts || []).map(c => c.toLowerCase()));

        r.expected.forEach(expCard => {
            const n = expCard.toLowerCase();
            const rankIndex = lowerResults.indexOf(n);
            const streams = d?.streams ? Object.entries(d.streams).filter(([, set]) => set.has(n)).map(([s]) => s).join(', ') : '';
            const scores = pass.scoreByName?.get(n);

            traceRows.push({
                'Test ID': r.id,
                'Source Card': r.source,
                'Pass': passLabel,
                'Expected Card': expCard,
                'Constraint Conflict': conflicts.has(n) ? 'YES' : '',
                'Retrieved': d?.rawCandidateNames?.has(n) ? 'Y' : 'N',
                'Passed Filters': d?.passedFilterNames?.has(n) ? 'Y' : 'N',
                'Deduplicated': d?.dedupedNames?.has(n) ? 'Y' : 'N',
                'Parsed Meaningfully': d?.meaningfulParseNames?.has(n) ? 'Y' : 'N',
                'Scored': d?.scoredNames?.has(n) ? 'Y' : 'N',
                'Passed Relevance Floor': d?.passedRelevanceFloorNames?.has(n) ? 'Y' : 'N',
                'Final Rank': rankIndex !== -1 ? rankIndex + 1 : '',
                'Mechanical Score': num(scores?.mechanicalScore, 3),
                'Functional Score': num(scores?.functionScore, 3),
                'Semantic Score': num(scores?.contextScore, 3),
                'Synergy Score': num(scores?.synergyScore, 3),
                'Exactness Score': num(scores?.exactnessScore, 3),
                'Category Score': num(scores?.categoryScore, 3),
                'Role Score': num(scores?.roleScore, 3),
                'Highlight Intent Score': num(scores?.highlightIntentScore, 3),
                'Functional Similarity': num(scores?.functionalSimilarityScore, 3),
                'Effect Coverage': num(scores?.effectCoverageScore, 3),
                'Primary Effect Match': num(scores?.primaryEffectMatchScore, 3),
                'Modal Mode Similarity': num(scores?.modalModeSimilarityScore, 3),
                'Core Evidence Score': num(scores?.coreEvidenceScore, 3),
                'Evidence Agreement': num(scores?.evidenceAgreement, 3),
                'Ranking Refinement Signal': num(scores?.rankingRefinementSignal, 3),
                'Deterministic Functional Anchor': num(scores?.deterministicFunctionalAnchor, 3),
                'Primary-Effect Ranking Boost': num(scores?.primaryEffectRankingBoost, 3),
                'Canonical Contradiction Penalty': num(scores?.contradictionPenalty, 3),
                'Pre-Cadence Score': num(scores?.similarityBeforeCadenceAdjustment, 3),
                'Relationship Mismatch': num(scores?.mechanicalBreakdown?.relationshipMismatch, 3),
                'Mechanical Confidence': num(scores?.mechanicalConfidence, 3),
                'Calibrated Blend Score': num(scores?.calibratedBlendScore, 3),
                'Evidence Gate': num(scores?.evidenceGate, 3),
                'Strategic Role Anchor Applied': scores?.strategicRoleAnchored === true ? 'Y' : (scores?.strategicRoleAnchored === false ? 'N' : ''),
                'Ranking Intent': scores?.rankingIntent || '',
                'Ranking Intent Role': scores?.rankingIntentRole || '',
                'Ranking Intent Confidence': num(scores?.rankingIntentConfidence, 3),
                'Acquisition Cadence Factor': num(scores?.acquisitionCadenceRankFactor, 3),
                'Overall Score': num(scores?.similarityScore, 3),
                'Unclamped Score': num(scores?.unclampedSimilarityScore, 4),
                'Mechanic Ranking Tier': scores?.mechanicRankingTier ?? '',
                'Mechanic Ranking Tier Label': scores?.mechanicRankingTierLabel || '',
                'Quantitative Conflict': scores?.quantitativeConflict ? JSON.stringify(scores.quantitativeConflict) : '',
                'Quantitative Conflict Penalty': num(scores?.quantitativeConflictPenalty, 4),
                'Proximity Score': num(scores?.proximityScore, 3),
                'Lost At Stage': diagnoseFailureStage(d, expCard, rankIndex),
                'Filter Mismatch': (d?.filterFailureReasons?.get(n) || [])
                    .map(fr => typeof fr === 'string' ? fr : `${fr.field || fr.type || 'filter'}: expected ${fr.expected ?? ''}, actual ${fr.actual ?? ''}`).join('; '),
                'Retrieved Via': streams
            });
        });
    };
    report.structuredResults.forEach(r => {
        buildTraceRows(r.strict, r, 'Strict');
        buildTraceRows(r.semantic, r, 'Semantic');
    });

    // --- Sheet: Top 20 Results (actual heads of each full benchmark ranking) ---
    const top20Rows = [];
    report.structuredResults.forEach(r => {
        for (const passKey of ['strict', 'semantic']) {
            const pass = r[passKey];
            if (!pass) continue;
            (pass.rankedResults || []).slice(0, 20).forEach((cardName, index) => {
                const scores = pass.scoreByName?.get(String(cardName).toLowerCase()) || {};
                top20Rows.push({
                    'Test ID': r.id, 'Test': r.name, 'Source Card': r.source, 'Pass': passKey,
                    'Rank': index + 1, 'Card': cardName,
                    'Displayed Score': num(scores.similarityScore, 4),
                    'Unclamped Score': num(scores.unclampedSimilarityScore, 4),
                    'Mechanic Ranking Tier': scores.mechanicRankingTier ?? '',
                    'Mechanic Ranking Tier Label': scores.mechanicRankingTierLabel || '',
                    'Quantitative Conflict': scores.quantitativeConflict ? JSON.stringify(scores.quantitativeConflict) : '',
                    'Quantitative Conflict Penalty': num(scores.quantitativeConflictPenalty, 4),
                    'Proximity Score': num(scores.proximityScore, 3),
                    'Ranking Intent': scores.rankingIntent || ''
                });
            });
        }
    });

    // --- Sheet: Pipeline Diagnostics ---
    const pipelineRows = report.structuredResults.map(r => {
        const d = r.strict.diagnostics || {};
        const q = d.benchmarkSignals || {};
        return {
            'Test ID': r.id,
            'Source Card': r.source,
            'Retrieved': d.retrieved ?? '',
            'Passed Filters (raw)': d.passedFiltersRaw ?? '',
            'After Dedup': d.afterHardFilters ?? '',
            'After Relevance Floor': d.afterRelevanceFloor ?? '',
            'Final Results': d.finalResults ?? '',
            'Ranking Mode': q.rankingMode || '',
            'Search Methods': q.searchMethods || '',
            'Ordering Features': q.orderingFeatures || '',
            'Search Intent Text': q.searchIntentText || '',
            'Search A Query': q.searchAQuery || '',
            'Search B Query': q.searchBQuery || '',
            'Functional Queries': q.functionalQueries || '',
            'Source Canonical Functions': q.sourceCanonicalFunctions || ''
        };
    });

    // --- Sheet: Retrieval Cost (per-stream cost vs. haystack size, review Priority 4/10-4) ---
    const retrievalCostRows = report.retrievalCostRows || [];

    // --- Sheet: Stream Coverage (kept for backward compatibility with earlier workbooks) ---
    const coverageRows = [];
    report.structuredResults.forEach(r => {
        const cov = r.strict.diagnostics?.streamCoverage;
        if (!cov) return;
        Object.entries(cov).forEach(([streamName, c]) => {
            if (!c) return;
            coverageRows.push({
                'Test ID': r.id, 'Source Card': r.source, 'Stream': streamName, 'Query': c.query || '',
                'Total Matching Cards': c.totalCards ?? '', 'Retrieved': c.retrievedCount ?? '',
                'Pages Fetched': c.pagesFetched ?? '', 'Page Budget': c.maxPages ?? '',
                'Fully Covered': c.fullyCovered ? 'Y' : 'N'
            });
        });
    });

    const XLSX = await loadSheetJS();

    if (!XLSX) {
        // CSV fallback so the run still leaves the browser with something usable.
        console.warn("SheetJS unavailable - exporting benchmark as CSV instead of .xlsx");
        const csv = rowsToCSV(perTestRows);
        triggerBrowserDownload(new Blob([csv], { type: 'text/csv;charset=utf-8;' }), `${baseName}.csv`);
        return false;
    }

    const workbook = XLSX.utils.book_new();

    // Columns default to a narrow fixed width, which truncates almost everything useful here -
    // Scryfall queries, filter-mismatch explanations and stream lists are all long strings that
    // get visually clipped by the neighbouring cell. Size every column to its widest actual value
    // (clamped, so one long query can't produce a 400-character column).
    //
    // NOTE ON STYLING: `!cols` widths and `!rows` heights are honoured by the free SheetJS
    // community build, and are what actually make this readable. Cell styles (`.s` - wrapText,
    // bold) are a SheetJS Pro feature and are silently ignored by the community build, so they're
    // set as a no-cost upgrade for style-capable builds but nothing depends on them. That's why
    // MAX_WIDTH is generous rather than relying on text wrapping to reveal long values.
    const WRAP_COLUMNS = new Set(['Query', 'Filter Mismatch', 'Lost At Stage', 'Error', 'Card Ranks', 'Categories', 'Retrieved Via', 'Search A Query', 'Search B Query', 'Search Intent Text', 'Functional Queries', 'Source Canonical Functions', 'Search Methods', 'Quantitative Conflict', 'Problem', 'Action', 'Mechanic Ranking Tier Label']);
    const MIN_WIDTH = 12;
    const MAX_WIDTH = 40;
    // Long free-text columns get a much higher cap. Because wrapText is unavailable in the
    // community build, width is the ONLY thing that makes a long value fully visible - a 115-char
    // Scryfall query in a 40-wide column is simply cut off on screen.
    const MAX_WIDTH_WRAPPED = 120;

    const addSheet = (rows, name) => {
        if (!rows || rows.length === 0) return;

        const sheet = XLSX.utils.json_to_sheet(rows);
        const headers = Object.keys(rows[0]);

        // Column widths, measured from the header and every cell value in that column.
        sheet['!cols'] = headers.map(header => {
            const longest = rows.reduce((max, row) => {
                const len = String(row[header] ?? '').length;
                return len > max ? len : max;
            }, header.length);
            // +2 for cell padding so text isn't flush against the gridline.
            const cap = WRAP_COLUMNS.has(header) ? MAX_WIDTH_WRAPPED : MAX_WIDTH;
            return { wch: Math.min(cap, Math.max(MIN_WIDTH, longest + 2)) };
        });

        // Wrap long free-text columns and enable wrapping on every header cell.
        const range = XLSX.utils.decode_range(sheet['!ref']);
        let maxWrappedLines = 1;

        for (let col = range.s.c; col <= range.e.c; col++) {
            const header = headers[col];
            const headerAddr = XLSX.utils.encode_cell({ r: 0, c: col });
            if (sheet[headerAddr]) {
                sheet[headerAddr].s = { font: { bold: true }, alignment: { wrapText: true, vertical: 'top' } };
            }
            if (!WRAP_COLUMNS.has(header)) continue;

            const colWidth = sheet['!cols'][col].wch;
            for (let row = 1; row <= range.e.r; row++) {
                const addr = XLSX.utils.encode_cell({ r: row, c: col });
                if (!sheet[addr]) continue;
                sheet[addr].s = { alignment: { wrapText: true, vertical: 'top' } };
                const lines = Math.ceil(String(sheet[addr].v ?? '').length / colWidth);
                if (lines > maxWrappedLines) maxWrappedLines = lines;
            }
        }

        // Give every row enough height for the tallest wrapped cell, capped so one outlier can't
        // leave the sheet mostly whitespace.
        const rowHeight = Math.min(90, 15 * Math.min(maxWrappedLines, 6));
        sheet['!rows'] = Array.from({ length: range.e.r + 1 }, () => ({ hpt: rowHeight }));

        // Freeze the header row so column meaning stays visible while scrolling long sheets.
        sheet['!freeze'] = { xSplit: 0, ySplit: 1 };
        sheet['!autofilter'] = { ref: sheet['!ref'] };

        XLSX.utils.book_append_sheet(workbook, sheet, name);
    };

    addSheet(overviewRows, 'Overview');
    if (regressionRows?.length) addSheet(regressionRows, 'vs Previous Run');
    addSheet(perTestRows, 'Per-Test Metrics');
    addSheet(timingRows, 'Test Timing');
    addSheet(report.categoryBreakdown, 'Category Breakdown');
    addSheet(traceRows, 'Expected Card Trace');
    addSheet(top20Rows, 'Top 20 Results');
    addSheet((report.labelLintRows && report.labelLintRows.length) ? report.labelLintRows : [{ Status: 'PASS', Detail: 'No impossible expected-card labels detected by preflight.' }], 'Benchmark Label Lint');
    addSheet(retrievalCostRows, 'Retrieval Cost');
    addSheet(pipelineRows, 'Pipeline Diagnostics');
    addSheet(coverageRows, 'Stream Coverage');

    // Write to an ArrayBuffer and download via Blob rather than using XLSX.writeFile, so the
    // download path is identical to the CSV fallback and works in environments where writeFile's
    // own anchor handling misbehaves.
    const buffer = XLSX.write(workbook, { bookType: 'xlsx', type: 'array' });
    const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    triggerBrowserDownload(blob, `${baseName}.xlsx`);

    console.log(`Benchmark workbook downloaded: ${baseName}.xlsx`);
    return true;
}

/**
 * Date stamp for benchmark filenames: YYYY-MM-DD_HH-MM.
 * Uses local time (the user's own clock is what they'll compare against) and only characters that
 * are legal in filenames on Windows, macOS and Linux - colons in particular are not.
 * @param {Date} date
 * @returns {string}
 */
function formatBenchmarkDateStamp(date) {
    const d = date instanceof Date ? date : new Date();
    const p = (n) => String(n).padStart(2, '0');
    return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}_${p(d.getHours())}-${p(d.getMinutes())}`;
}

/**
 * Serializes an array of flat objects to CSV, quoting and escaping every field.
 * @param {Array<Object>} rows
 * @returns {string}
 */
function rowsToCSV(rows) {
    if (!rows || rows.length === 0) return '';
    const headers = Object.keys(rows[0]);
    const escape = (v) => `"${String(v ?? '').replace(/"/g, '""')}"`;
    const lines = [headers.map(escape).join(',')];
    rows.forEach(row => lines.push(headers.map(h => escape(row[h])).join(',')));
    return lines.join('\n');
}

/**
 * Short unique identifier for a benchmark run, so separate exported workbooks (or console runs)
 * can be told apart and eventually compared - "MS-20260915-163717-A7F3" (review Priority 10,
 * "Benchmark run ID").
 * @param {Date} date
 * @returns {string}
 */
function generateBenchmarkRunId(date) {
    const d = date instanceof Date ? date : new Date();
    const p = (n) => String(n).padStart(2, '0');
    const stamp = `${d.getFullYear()}${p(d.getMonth() + 1)}${p(d.getDate())}-${p(d.getHours())}${p(d.getMinutes())}${p(d.getSeconds())}`;
    const rand = Math.random().toString(16).slice(2, 6).toUpperCase();
    return `MS-${stamp}-${rand}`;
}

const BENCHMARK_HISTORY_KEY = 'manamatch_benchmark_last_run';

/**
 * Runs one search pass (via searchFn) and reduces it to every metric the suite needs, without
 * touching suite-level aggregation. Pulled out into its own function so a test with
 * `preferredConstraints` can be run TWICE - once with every constraint as declared ("strict") and
 * once with the preferred fields omitted ("semantic") - without duplicating this whole block
 * (review Priority 2 / Priority 9: hard vs. preferred constraints, Strict vs. Semantic Recall).
 * @param {Function} searchFn
 * @param {Object} test - a BENCHMARK_SUITE entry (or a relaxed clone of one)
 * @returns {Promise<Object>} everything needed for console output + the workbook
 */
function createBenchmarkScoreSnapshot(card) {
    if (!card || typeof card === 'string') return null;
    return {
        mechanicalScore: card.mechanicalScore ?? null,
        contextScore: card.contextScore ?? null,
        functionScore: card.functionScore ?? null,
        synergyScore: card.synergyScore ?? null,
        exactnessScore: card.exactnessScore ?? null,
        categoryScore: card.categoryScore ?? null,
        roleScore: card.roleScore ?? null,
        highlightIntentScore: card.highlightIntentScore ?? null,
        functionalSimilarityScore: card.functionalSimilarityScore ?? null,
        effectCoverageScore: card.effectCoverageScore ?? null,
        primaryEffectMatchScore: card.primaryEffectMatchScore ?? null,
        modalModeSimilarityScore: card.modalModeSimilarityScore ?? null,
        rankingRefinementSignal: card.rankingRefinementSignal ?? null,
        deterministicFunctionalAnchor: card.deterministicFunctionalAnchor ?? card.rankingEvidence?.deterministicFunctionalAnchor ?? null,
        primaryEffectRankingBoost: card.primaryEffectRankingBoost ?? card.rankingEvidence?.primaryEffectRankingBoost ?? null,
        similarityBeforeCadenceAdjustment: card.similarityBeforeCadenceAdjustment ?? card.preCadenceSimilarityScore ?? null,
        calibratedBlendScore: card.calibratedBlendScore ?? null,
        mechanicalConfidence: card.mechanicalConfidence ?? null,
        mechanicalBreakdown: card.mechanicalBreakdown ? { relationshipMismatch: card.mechanicalBreakdown.relationshipMismatch ?? null } : null,
        evidenceGate: card.evidenceGate ?? card.rankingEvidence?.evidenceGate ?? null,
        strategicRoleAnchored: card.strategicRoleAnchored ?? card.rankingEvidence?.strategicRoleAnchored ?? null,
        rankingEvidence: card.rankingEvidence ? {
            rankingIntentRole: card.rankingEvidence.rankingIntentRole ?? null,
            deterministicFunctionalAnchor: card.rankingEvidence.deterministicFunctionalAnchor ?? null,
            primaryEffectRankingBoost: card.rankingEvidence.primaryEffectRankingBoost ?? null,
            relationshipMismatch: card.rankingEvidence.relationshipMismatch ?? null,
            evidenceGate: card.rankingEvidence.evidenceGate ?? null,
            strategicRoleAnchored: card.rankingEvidence.strategicRoleAnchored ?? null,
            channelScore: card.rankingEvidence.channelScore ?? null
        } : null,
        rankingIntent: card.rankingIntent ?? card._rankingIntent?.kind ?? null,
        rankingIntentRole: card.rankingEvidence?.rankingIntentRole ?? card._rankingIntent?.role ?? null,
        rankingIntentConfidence: card.rankingIntentConfidence ?? card._rankingIntent?.confidence ?? null,
        acquisitionCadenceRankFactor: card.acquisitionCadenceRankFactor ?? null,
        relevanceEvidenceScore: card.relevanceEvidenceScore ?? null,
        coreEvidenceScore: card.coreEvidenceScore ?? null,
        supportingEvidenceScore: card.supportingEvidenceScore ?? null,
        evidenceAgreement: card.evidenceAgreement ?? null,
        contradictionPenalty: card.contradictionPenalty ?? null,
        mechanicRankingTier: Number.isInteger(card.mechanicRankingTier) ? card.mechanicRankingTier : null,
        mechanicRankingTierLabel: card.mechanicRankingTierLabel ?? null,
        mechanicRankingConfidence: card.mechanicRankingConfidence ?? null,
        mechanicRankingEvidence: card.mechanicRankingEvidence ?? null,
        quantitativeConflict: card.quantitativeConflict ?? card.mechanicRankingEvidence?.quantitativeConflict ?? null,
        quantitativeConflictPenalty: card.quantitativeConflictPenalty ?? null,
        unclampedSimilarityScore: card.unclampedSimilarityScore ?? null,
        proximityScore: card.proximityScore ?? null,
        similarityScore: card.similarityScore ?? null
    };
}

function mergeBenchmarkScoreSnapshots(scoreByName, snapshots) {
    if (!(scoreByName instanceof Map) || !(snapshots instanceof Map)) return scoreByName;
    snapshots.forEach((snapshot, name) => {
        // Final-list card objects remain authoritative. Snapshots fill gaps for scored candidates
        // that were removed by the relative relevance floor before final ranking.
        if (!scoreByName.has(name)) scoreByName.set(name, snapshot);
    });
    return scoreByName;
}

async function runBenchmarkPass(searchFn, test) {
    let rankedResults = [];
    let diagnostics = null;
    let scoreByName = new Map();
    let testStatus = 'ok';
    let errorMessage = null;

    try {
        const rawResults = await searchFn(test);

        // searchFn returns a structured { results, diagnostics } object. Recovering diagnostics
        // from a property hung off the results array was fragile - any step that built a new
        // array silently dropped it. A plain array is still accepted for backwards compatibility,
        // just without instrumentation (review Priority 3).
        const resultList = Array.isArray(rawResults) ? rawResults : (rawResults?.results || []);
        diagnostics = Array.isArray(rawResults) ? (rawResults.diagnostics || null) : (rawResults?.diagnostics || null);

        rankedResults = resultList.map(card => typeof card === 'string' ? card : card.name);

        // Preserve partial-result diagnostics, but do not count a query stream that explicitly
        // reports incomplete local coverage as a fully measured benchmark pass.
        const coverageRateLimited = (() => {
            const streamCoverage = diagnostics?.streamCoverage && typeof diagnostics.streamCoverage === 'object'
                ? Object.values(diagnostics.streamCoverage).some(cov => cov?.bailedAfterRetries)
                : false;
            const functionalCoverage = Array.isArray(diagnostics?.searchFQueryDetail)
                && diagnostics.searchFQueryDetail.some(item => item?.coverage?.bailedAfterRetries);
            const exactCoverage = Array.isArray(diagnostics?.exactHighlightQueryDetail)
                && diagnostics.exactHighlightQueryDetail.some(item => item?.coverage?.bailedAfterRetries);
            // Static local retrieval has no remote rate-limit circuit. Only explicit local query
            // coverage failures can make this pass incomplete.
            return streamCoverage || functionalCoverage || exactCoverage;
        })();

        // Per-card score breakdown, keyed by lowercase name, so the Expected Card Trace can show
        // WHY a card ranked where it did (mechanical/functional/semantic/exactness/category),
        // not just that it did (review Priority 10, "Expected Card Trace should include score
        // information").
        resultList.forEach(card => {
            if (typeof card === 'string' || !card?.name) return;
            scoreByName.set(card.name.toLowerCase(), {
                mechanicalScore: card.mechanicalScore ?? null,
                contextScore: card.contextScore ?? null,
                functionScore: card.functionScore ?? null,
                synergyScore: card.synergyScore ?? null,
                exactnessScore: card.exactnessScore ?? null,
                categoryScore: card.categoryScore ?? null,
                roleScore: card.roleScore ?? null,
                highlightIntentScore: card.highlightIntentScore ?? null,
                functionalSimilarityScore: card.functionalSimilarityScore ?? null,
                effectCoverageScore: card.effectCoverageScore ?? null,
                primaryEffectMatchScore: card.primaryEffectMatchScore ?? null,
                modalModeSimilarityScore: card.modalModeSimilarityScore ?? null,
                rankingRefinementSignal: card.rankingRefinementSignal ?? null,
                deterministicFunctionalAnchor: card.deterministicFunctionalAnchor ?? card.rankingEvidence?.deterministicFunctionalAnchor ?? null,
                primaryEffectRankingBoost: card.primaryEffectRankingBoost ?? card.rankingEvidence?.primaryEffectRankingBoost ?? null,
                similarityBeforeCadenceAdjustment: card.similarityBeforeCadenceAdjustment ?? card.preCadenceSimilarityScore ?? null,
                calibratedBlendScore: card.calibratedBlendScore ?? null,
                mechanicalConfidence: card.mechanicalConfidence ?? null,
                mechanicalBreakdown: card.mechanicalBreakdown ?? null,
                evidenceGate: card.evidenceGate ?? card.rankingEvidence?.evidenceGate ?? null,
                strategicRoleAnchored: card.strategicRoleAnchored ?? card.rankingEvidence?.strategicRoleAnchored ?? null,
                rankingIntent: card.rankingIntent ?? card._rankingIntent?.kind ?? null,
                rankingIntentRole: card.rankingEvidence?.rankingIntentRole ?? card._rankingIntent?.role ?? null,
                rankingIntentConfidence: card.rankingIntentConfidence ?? card._rankingIntent?.confidence ?? null,
                acquisitionCadenceRankFactor: card.acquisitionCadenceRankFactor ?? null,
                relevanceEvidenceScore: card.relevanceEvidenceScore ?? null,
                coreEvidenceScore: card.coreEvidenceScore ?? null,
                supportingEvidenceScore: card.supportingEvidenceScore ?? null,
                evidenceAgreement: card.evidenceAgreement ?? null,
                contradictionPenalty: card.contradictionPenalty ?? null,
                mechanicRankingTier: Number.isInteger(card.mechanicRankingTier) ? card.mechanicRankingTier : null,
                mechanicRankingTierLabel: card.mechanicRankingTierLabel ?? null,
                mechanicRankingConfidence: card.mechanicRankingConfidence ?? null,
                mechanicRankingEvidence: card.mechanicRankingEvidence ?? null,
                quantitativeConflict: card.quantitativeConflict ?? card.mechanicRankingEvidence?.quantitativeConflict ?? null,
                quantitativeConflictPenalty: card.quantitativeConflictPenalty ?? null,
                unclampedSimilarityScore: card.unclampedSimilarityScore ?? null,
                proximityScore: card.proximityScore ?? null,
                similarityScore: card.similarityScore ?? null
            });
        });

        // Preserve per-candidate scoring diagnostics even for candidates later removed by
        // the relevance floor. These snapshots are captured only during benchmark runs.
        mergeBenchmarkScoreSnapshots(scoreByName, diagnostics?.benchmarkScoreByName);

        if (coverageRateLimited) {
            testStatus = 'blocked_rate_limit';
            errorMessage = 'Scryfall rate-limit/network circuit affected this benchmark pass; partial results were not counted as a complete measurement.';
        } else if (rankedResults.length === 0) {
            testStatus = 'empty';
        }
    } catch (err) {
        if (isRuntimeCardApiRateLimitError(err) || err?.isRuntimeCardApiRateLimit) {
            testStatus = 'blocked_rate_limit';
            errorMessage = err?.message || 'Runtime card API transport is disabled for the static-only application.';
        } else {
            testStatus = 'error';
            errorMessage = err.message;
        }
    }

    const conflictSet = new Set((test.constraintConflicts || []).map(c => c.toLowerCase()));
    const recall5 = calculateRecallAtK(rankedResults, test.expected, 5);
    const recall10 = calculateRecallAtK(rankedResults, test.expected, 10);
    const recall20 = calculateRecallAtK(rankedResults, test.expected, 20);

    const adjustedExpected = test.expected.filter(c => !conflictSet.has(c.toLowerCase()));
    const adjustedRecall5 = adjustedExpected.length > 0 ? calculateRecallAtK(rankedResults, adjustedExpected, 5) : recall5;
    const adjustedRecall10 = adjustedExpected.length > 0 ? calculateRecallAtK(rankedResults, adjustedExpected, 10) : recall10;
    const adjustedRecall20 = adjustedExpected.length > 0 ? calculateRecallAtK(rankedResults, adjustedExpected, 20) : recall20;

    const mrr = calculateMRR(rankedResults, test.expected);
    const ndcg10 = calculateNDCGAtK(rankedResults, test.expected, 10);
    const ndcg20 = calculateNDCGAtK(rankedResults, test.expected, 20);
    const precision10 = calculatePrecisionAtK(rankedResults, test.expected, 10);
    const stageRecalls = calculateStageRecalls(diagnostics, test.expected);
    const predicateExpected = Array.isArray(test.predicateExpected) ? test.predicateExpected : [];
    const hasPredicateEvaluation = Boolean(test.relevancePredicate);
    const predicatePrecision10 = hasPredicateEvaluation ? calculatePrecisionAtK(rankedResults, predicateExpected, 10) : null;
    const predicateNdcg10 = hasPredicateEvaluation ? calculateNDCGAtK(rankedResults, predicateExpected, 10) : null;

    const cardRanks = getExpectedCardRanks(rankedResults, test.expected, 100);
    const rankValues = Object.values(cardRanks);
    const avgTestRank = rankValues.reduce((a, b) => a + b, 0) / (rankValues.length || 1);

    return {
        rankedResults, diagnostics, scoreByName, testStatus, errorMessage, conflictSet,
        recall5, recall10, recall20, adjustedRecall5, adjustedRecall10, adjustedRecall20,
        mrr, ndcg10, ndcg20, precision10, stageRecalls, cardRanks, avgTestRank,
        predicateExpectedCount: hasPredicateEvaluation ? predicateExpected.length : null,
        predicatePrecision10,
        predicateNdcg10
    };
}

/**
 * Prints the Stage 1-7 funnel trace for every expected card in a pass, plus its score breakdown
 * when available.
 * @param {Object} pass - result of runBenchmarkPass
 * @param {Object} test
 * @param {string} label - "STRICT" or "SEMANTIC", for the console header
 */
function printExpectedCardTrace(pass, test, label) {
    const { diagnostics } = pass || {};
    const rankedResults = Array.isArray(pass?.rankedResults) ? pass.rankedResults : [];
    const conflictSet = pass?.conflictSet instanceof Set ? pass.conflictSet : new Set();
    const scoreByName = pass?.scoreByName instanceof Map ? pass.scoreByName : new Map();
    const lowerResults = rankedResults.map(r => String(r).toLowerCase());
    const expectedCards = Array.isArray(test?.expected) ? test.expected : [];

    console.log(`\nExpected Card Funnel Trace [${label}]:`);
    if (!diagnostics) {
        console.log(`  [Warning] No pipeline diagnostics returned.`);
    }

    expectedCards.forEach(expCard => {
        const expLower = expCard.toLowerCase();
        const inCandidatePool  = diagnostics?.rawCandidateNames?.has(expLower) || false;
        const passedFilters    = diagnostics?.passedFilterNames?.has(expLower) || false;
        const wasDeduped       = diagnostics?.dedupedNames?.has(expLower) || false;
        const parsedMeaningful = diagnostics?.meaningfulParseNames?.has(expLower) || false;
        const isScored         = diagnostics?.scoredNames?.has(expLower) || false;
        const passedFloor      = diagnostics?.passedRelevanceFloorNames?.has(expLower) || false;

        const rankIndex = lowerResults.indexOf(expLower);
        const finalRank = rankIndex !== -1 ? `#${rankIndex + 1}` : 'Not found';
        const conflictNote = conflictSet.has(expLower) ? '  [constraint-conflict: excluded from adjusted recall]' : '';

        console.log(`\n  Card: ${expCard}${conflictNote}`);
        console.log(`    Stage 1: Candidate pool?     : ${inCandidatePool ? 'Yes' : 'No'}`);
        console.log(`    Stage 2: Passed filters?     : ${passedFilters ? 'Yes' : 'No'}`);
        console.log(`    Stage 3: Deduplicated?       : ${wasDeduped ? 'Yes' : 'No'}`);
        console.log(`    Stage 4: Parsed meaningfully?: ${parsedMeaningful ? 'Yes' : (isScored ? 'No (fell back to generic)' : 'n/a')}`);
        console.log(`    Stage 5: Scored?             : ${isScored ? 'Yes' : 'No'}`);
        console.log(`    Stage 6: Passed relev. floor?: ${passedFloor ? 'Yes' : 'No'}`);
        console.log(`    Stage 7: Final rank?         : ${finalRank}`);

        const scores = scoreByName.get(expLower);
        if (scores) {
            console.log(`    Scores                       : mech ${fmtScore(scores.mechanicalScore)} | fn ${fmtScore(scores.functionScore)} | sem ${fmtScore(scores.oracleSemanticScore ?? scores.contextScore)} | exact ${fmtScore(scores.exactnessScore)} | cat ${fmtScore(scores.categoryScore)} | role ${fmtScore(scores.roleScore)} | core ${fmtScore(scores.coreEvidenceScore)} | agree ${fmtScore(scores.evidenceAgreement)} | rel ${fmtScore(scores.relevanceEvidenceScore)} | overall ${fmtScore(scores.similarityScore)}`);
        }

        if (rankIndex === -1) {
            console.log(`    >> LOST AT                   : ${diagnoseFailureStage(diagnostics, expCard, rankIndex)}`);
            const reasons = diagnostics?.filterFailureReasons?.get(expLower);
            if (reasons?.length) {
                console.log(`    >> FILTER MISMATCH           : ${reasons.map(r => `${r.field}: expected ${r.expected}, actual ${r.actual}`).join('; ')}`);
            }
        }

        if (diagnostics?.streams) {
            const foundStreams = Object.entries(diagnostics.streams).filter(([, set]) => set.has(expLower)).map(([s]) => s);
            if (foundStreams.length > 0) console.log(`    Retrieved via                : ${foundStreams.join(', ')}`);
        }
    });
}

function fmtScore(v) {
    return (v === null || v === undefined) ? 'n/a' : v.toFixed(2);
}

/**
 * Runs the full benchmark suite against a provided search function.
 * @param {Function} searchFn - Async function taking (testCase) and returning array of ranked card objects with a `.name` property.
 */
function resetBenchmarkColdState({ keepSourceCard = false, keepImmutableEmbeddings = false } = {}) {
    // Benchmark tests must not inherit result-derived state from earlier tests. Static-only card
    // retrieval has no runtime card API transport or remote rate-limit state.
    searchCache.clear();
    // Clear the localStorage-backed search cache too; otherwise a benchmark test could receive
    // a previously stored result even though the in-memory Map was reset.
    try {
        localStorage.removeItem(PERSISTENT_CACHE_STORAGE_KEY);
    } catch (err) {
        // Storage may be unavailable in private/locked-down browser contexts; in that case the
        // in-memory cache reset above is still applied.
    }
    // The benchmark starts with a cold embedding cache once per suite, but subsequent tests may
    // reuse deterministic per-text vectors. These are immutable model outputs, not result/candidate
    // carry-over, and caching them mirrors how a real user runs multiple searches in one session.
    if (!keepImmutableEmbeddings) {
        embeddingCache.clear();
        embeddingCacheStats.hits = 0;
        embeddingCacheStats.computed = 0;
        embeddingCacheStats.evictions = 0;
        embeddingCacheStats.precomputedOracleHits = 0;
        embeddingCacheStats.precomputedOracleMisses = 0;
        staticSemanticQueryStats.workerQueries = 0;
        staticSemanticQueryStats.workerElapsedMs = 0;
        staticSemanticQueryStats.workerFailures = 0;
        staticSemanticQueryStats.fallbackQueries = 0;
        staticSemanticQueryStats.fallbackElapsedMs = 0;
    }
    sessionSemanticCorpus.clear();
    pendingDeeperSearch = null;
    lastSearchResults = [];
    lastSearchDiagnostics = null;
    manualHighlights = [];
    nextHighlightColorIndex = 0;
    highlightComposerOpen = false;
    selectedRelatedCards.clear();
    sourceCards.clear();
    primarySourceCardKey = null;

    // Source-card metadata is immutable input, not retrieval state. Keep the source cache across
    // benchmark tests so a previously loaded benchmark source can be reused without another
    // Resolve source cards strictly from cards.bin. Candidate/search/embedding state is still fully cold.
    if (!keepSourceCard) {
        currentSourceCard = null;
    }
}

function buildBenchmarkHighlightState(testCase, sourceCard = currentSourceCard) {
    const declared = Array.isArray(testCase?.highlights) && testCase.highlights.length
        ? testCase.highlights
        : (testCase?.highlightedOracle
            ? [{ text: testCase.highlightedOracle, mode: 'exact', intent: testCase.highlightIntent || 'benchmark focus' }]
            : []);
    if (!declared.length) return [];

    const sourceText = getCurrentSourceOracleText(sourceCard);
    const lowerSource = sourceText.toLowerCase();
    let cursor = 0;
    const resolved = [];
    const warnings = [];

    for (const h of declared) {
        const text = String(h?.text || '').trim();
        if (!text) continue;

        let start = Number.isFinite(h?.start) ? h.start : null;
        let end = Number.isFinite(h?.end) ? h.end : null;

        if (start === null && text) {
            const fromCursor = lowerSource.indexOf(text.toLowerCase(), Math.max(0, cursor));
            const anywhere = fromCursor >= 0 ? fromCursor : lowerSource.indexOf(text.toLowerCase());
            if (anywhere >= 0) {
                start = anywhere;
                end = anywhere + text.length;
                cursor = end;
            } else {
                warnings.push(`Could not locate benchmark highlight: "${text}"`);
                continue;
            }
        }

        if (start !== null && end !== null && (start < 0 || end <= start || end > sourceText.length)) {
            warnings.push(`Invalid benchmark highlight range for: "${text}"`);
            continue;
        }

        resolved.push({
            text,
            mode: h?.mode === 'variable' ? 'variable' : 'exact',
            start,
            end,
            intent: String(h?.intent || testCase?.highlightIntent || '').trim()
        });
    }

    // Benchmark authoring guardrails: human selections are usually meaningful phrases, not tiny
    // parser atoms or nearly the entire card. These are warnings only; the benchmark must still
    // be able to exercise short exact phrases such as "{1}" and sentence-boundary tests.
    const longSource = sourceText.length > 0 && resolved.some(h => h.text.length > sourceText.length * 0.72);
    if (longSource) warnings.push('One benchmark highlight covers most of the source Oracle text; consider a more natural intent-sized excerpt.');
    if (resolved.length > 4) warnings.push(`Benchmark uses ${resolved.length} highlights; human-style tests are easier to interpret with fewer, broader selections.`);

    // A normal user usually selects one meaningful clause/phrase or a small number of
    // fragments from the same effect. Warn on highly fragmented tests without forbidding legitimate
    // short selections such as mana symbols and exact boundary phrases.
    const tinyFragmentCount = resolved.filter(h =>
        h.text.length <= 3 &&
        !/[{}]/.test(h.text) &&
        h.mode === 'exact'
    ).length;
    if (tinyFragmentCount > 0) {
        warnings.push('Benchmark contains a tiny Exact fragment; prefer a meaningful phrase unless the fragment itself is the intended constraint.');
    }
    if ((testCase?.highlightStyle === 'multi-span-line' || testCase?.highlightStyle === 'multi-span-effect') &&
        resolved.length < 2) {
        warnings.push('Multi-span benchmark style declares fewer than two selections.');
    }

    if (warnings.length) {
        console.warn(`Benchmark highlight authoring warnings — Test #${testCase?.id}:`, warnings);
    }
    if (resolved.length !== declared.length) {
        console.error(`Benchmark Test #${testCase?.id}: one or more declared highlights were not found in the source Oracle text and were excluded from scoring.`);
    }

    // Benchmark selections keep their origin so mixed Exact/Variable selections can behave as
    // semantic intent when they form one grammatical effect (Test #11), while ordinary live-user
    // Exact highlights keep their existing hard-literal semantics.
    const benchmarkResolved = resolved.map(h => ({ ...h, origin: 'benchmark' }));
    annotateHighlightGroups(benchmarkResolved, sourceText);
    return benchmarkResolved;
}

function renderBenchmarkHighlightPreview(testCase, sourceCard = currentSourceCard) {
    const highlights = buildBenchmarkHighlightState(testCase, sourceCard);
    manualHighlights = highlights;
    reapplyOracleHighlights();
    renderHighlightChips();

    // Benchmark selections are shown in the same Oracle markup as real user selections.
    // Keep the benchmark state for scoring, but do not expose a benchmark-only debug panel in
    // the normal Source Card UI.
    document.getElementById('benchmark-highlight-preview')?.remove();
    sourceCardOracle?.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
    return highlights;
}
function clearBenchmarkHighlightPreview() {
    const panel = document.getElementById('benchmark-highlight-preview');
    if (panel) panel.remove();
}

/* V20.17 benchmark runtime status: the benchmark used to spend its first several seconds
   preparing the local corpus before the website showed anything. Keep this deliberately small
   and theme-neutral: it reuses the app's existing CSS variables and does not redefine the
   application's palette or the normal highlight colors. */
function ensureBenchmarkDashboard() {
    if (typeof document === 'undefined') return null;
    let panel = document.getElementById('benchmark-runtime-dashboard');
    if (panel) return panel;

    const styleId = 'benchmark-runtime-dashboard-style';
    if (!document.getElementById(styleId)) {
        const style = document.createElement('style');
        style.id = styleId;
        style.textContent = `
            #benchmark-runtime-dashboard {
                position: relative;
                margin: 0 auto 16px;
                max-width: 1200px;
                padding: 12px 44px 12px 16px;
                background: var(--bg-secondary);
                color: var(--text-main);
                border: 1px solid var(--border-color);
                border-radius: 8px;
                box-sizing: border-box;
            }
            #benchmark-runtime-dashboard[hidden] { display: none !important; }
            .benchmark-runtime-top {
                display: flex;
                justify-content: space-between;
                align-items: center;
                gap: 12px;
                flex-wrap: wrap;
            }
            .benchmark-runtime-title { font-weight: 700; }
            .benchmark-runtime-state { color: var(--text-muted); font-size: 12px; }
            .benchmark-runtime-close {
                position: absolute;
                top: 7px;
                right: 7px;
                width: 30px;
                height: 30px;
                padding: 0;
                border: 1px solid transparent;
                border-radius: 7px;
                background: transparent;
                color: var(--text-muted);
                font-size: 22px;
                line-height: 1;
                cursor: pointer;
            }
            .benchmark-runtime-close:hover,
            .benchmark-runtime-close:focus-visible {
                border-color: var(--border-color);
                background: var(--bg-accent);
                color: var(--text-main);
                outline: none;
            }
            .benchmark-runtime-progress {
                position: relative;
                height: 7px;
                margin-top: 9px;
                background: var(--bg-accent);
                border-radius: 999px;
                overflow: hidden;
            }
            .benchmark-runtime-progress > span {
                position: relative;
                display: block;
                height: 100%;
                width: 0%;
                background: var(--accent-color);
                transition: width .55s cubic-bezier(.22,.61,.36,1);
                will-change: width;
            }
            /* The width communicates completed benchmark stages; the moving sheen communicates
               that the current test is actively running even when its exact completion percentage
               is not yet known. This prevents a static 15%-ish bar from looking frozen for a 40s
               live local corpus retrieval. */
            .benchmark-runtime-progress.is-active::after {
                content: '';
                position: absolute;
                top: 0;
                bottom: 0;
                left: -35%;
                width: 35%;
                background: linear-gradient(90deg, transparent, rgba(255,255,255,.40), transparent);
                animation: benchmark-runtime-sheen 1.35s linear infinite;
                pointer-events: none;
            }
            @keyframes benchmark-runtime-sheen {
                from { transform: translateX(0); }
                to { transform: translateX(386%); }
            }
            .benchmark-runtime-detail {
                margin-top: 7px;
                color: var(--text-muted);
                font-size: 12px;
            }
            .benchmark-runtime-test { font-size: 13px; }
        `;
        document.head.appendChild(style);
    }

    panel = document.createElement('section');
    panel.id = 'benchmark-runtime-dashboard';
    panel.setAttribute('aria-live', 'polite');
    panel.innerHTML = `
        <button type="button" class="benchmark-runtime-close" aria-label="Close benchmark panel" title="Close benchmark panel" hidden>&times;</button>
        <div class="benchmark-runtime-top">
            <div class="benchmark-runtime-title">Benchmark</div>
            <div class="benchmark-runtime-state">Starting…</div>
        </div>
        <div class="benchmark-runtime-test">Preparing benchmark…</div>
        <div class="benchmark-runtime-progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0">
            <span></span>
        </div>
        <div class="benchmark-runtime-detail"></div>
    `;

    const closeBtn = panel.querySelector('.benchmark-runtime-close');
    if (closeBtn) {
        closeBtn.addEventListener('click', () => {
            panel.remove();
        });
    }

    const main = document.querySelector('main');
    if (main) main.insertBefore(panel, main.firstChild);
    else document.body.insertBefore(panel, document.body.firstChild);
    return panel;
}

function updateBenchmarkDashboard({ state, testIndex = 0, totalTests = BENCHMARK_SUITE.length, test = null, detail = '', percent = null } = {}) {
    const panel = ensureBenchmarkDashboard();
    if (!panel) return;
    const stateEl = panel.querySelector('.benchmark-runtime-state');
    const testEl = panel.querySelector('.benchmark-runtime-test');
    const detailEl = panel.querySelector('.benchmark-runtime-detail');
    const fillEl = panel.querySelector('.benchmark-runtime-progress > span');
    const progressEl = panel.querySelector('.benchmark-runtime-progress');
    const closeBtn = panel.querySelector('.benchmark-runtime-close');

    if (stateEl) stateEl.textContent = state || 'Running';
    if (testEl) {
        testEl.textContent = test
            ? `Test #${test.id} of ${totalTests}: ${test.name} — ${test.source}`
            : (detail || 'Preparing benchmark…');
    }
    if (detailEl) detailEl.textContent = detail || '';

    const computed = percent !== null
        ? Math.max(0, Math.min(100, percent))
        : (totalTests > 0 ? Math.max(0, Math.min(100, (testIndex / totalTests) * 100)) : 0);
    if (fillEl) fillEl.style.width = `${computed}%`;
    if (progressEl) {
        const finished = state === 'Finished' || state === 'Stopped';
        progressEl.classList.toggle('is-active', !finished);
        progressEl.setAttribute('aria-valuenow', String(Math.round(computed)));
    }
    if (closeBtn) {
        const finished = state === 'Finished' || state === 'Stopped';
        closeBtn.hidden = !finished;
    }
}

async function preloadBenchmarkSourceCards() {
    const corpus = staticCardCorpusMemory || await loadStaticCardCorpus();
    if (!corpus?.cards?.length) {
        throw new Error('Benchmark requires the bundled cards.bin catalog. Runtime card API lookups are disabled.');
    }
    const uniqueSources = [...new Set((BENCHMARK_SUITE || []).map(test => String(test?.source || '').trim()).filter(Boolean))];
    const missing = [];
    for (const source of uniqueSources) {
        const key = source.toLowerCase();
        let card = getStaticCardByName(source);
        if (!card) {
            const normalized = normalizeLocalCorpusText(source);
            const candidates = corpus.cards.filter(item => normalizeLocalCorpusText(item?.name) === normalized);
            card = candidates[0] || null;
        }
        if (!card) { missing.push(source); continue; }
        benchmarkSourceCardCatalog.set(key, card);
        await backgroundAwareDelay(0);
    }
    if (missing.length) throw new Error(`These benchmark source cards are missing from cards.bin: ${missing.join(', ')}`);
    return uniqueSources.length;
}
function withBenchmarkTimeout(promise, timeoutMs, label = 'operation') {
    return new Promise((resolve, reject) => {
        let settled = false;
        const timer = setTimeout(() => {
            if (settled) return;
            settled = true;
            reject(new Error(`${label} timed out after ${Math.round(timeoutMs / 1000)}s`));
        }, timeoutMs);
        Promise.resolve(promise).then(value => {
            if (settled) return;
            settled = true;
            clearTimeout(timer);
            resolve(value);
        }, error => {
            if (settled) return;
            settled = true;
            clearTimeout(timer);
            reject(error);
        });
    });
}

function buildBenchmarkFiltersForLint(test) {
    const c = test?.constraints || {};
    return {
        types: c.type ? normalizeConstraintList(c.type) : [],
        supertypes: [], subtypes: [], keywords: [],
        type: c.type || '', format: c.format || '', rarity: c.rarity || '',
        identity: c.identity || '', colors: c.colors || '', cmc: c.cmc || '',
        power: c.power || '', toughness: c.toughness || '', set: c.set || '',
        extraOracle: c.extraOracle || '', constraintModes: {}
    };
}

function getBenchmarkOracleText(card) {
    return String(card?.oracle_text || (Array.isArray(card?.card_faces)
        ? card.card_faces.map(face => face?.oracle_text || '').join(' ')
        : '') || '');
}

function matchesBenchmarkRelevancePredicate(card, predicate) {
    const oracle = getBenchmarkOracleText(card);
    const typeLine = String(card?.type_line || '').toLowerCase();
    switch (predicate) {
        case 'counterspell':
            return /\bcounter target spell\b/i.test(oracle) && /\binstant\b/.test(typeLine);
        case 'burn-any-target':
            return /\bdeals?\s+(?:\d+|x)\s+damage\s+to\s+any target\b/i.test(oracle) && /\binstant\b/.test(typeLine);
        case 'tap-for-mana-artifact':
            return /\bartifact\b/.test(typeLine) && /\{t\}\s*:\s*add\b/i.test(oracle);
        case 'unconditional-counter-sentence':
            return /(?:^|\s)counter target spell\.(?=\s|$)/i.test(oracle.replace(/\s+/g, ' ').trim());
        default:
            return false;
    }
}

function buildBenchmarkPredicateExpected(test, corpusCards) {
    if (!test?.relevancePredicate || !Array.isArray(corpusCards)) return [];
    const sourceKey = normalizeCardNameForIdentity(test.source || '');
    const filters = buildBenchmarkFiltersForLint(test);
    const names = new Map();
    for (const card of corpusCards) {
        const key = normalizeCardNameForIdentity(card?.name);
        if (!key || key === sourceKey || !matchesBenchmarkRelevancePredicate(card, test.relevancePredicate)) continue;
        if (!matchesActiveFilters(card, filters, null)) continue;
        if (!names.has(key)) names.set(key, String(card.name));
    }
    return [...names.values()];
}

function lintBenchmarkExpectedLabels(tests, corpusCards) {
    const rows = [];
    if (!Array.isArray(corpusCards) || !corpusCards.length) return rows;
    const byName = new Map();
    for (const card of corpusCards) {
        const key = normalizeCardNameForIdentity(card?.name);
        if (!key) continue;
        if (!byName.has(key)) byName.set(key, []);
        byName.get(key).push(card);
    }
    for (const test of (tests || [])) {
        const sourceKey = normalizeCardNameForIdentity(test.source || '');
        const sourceCard = byName.get(sourceKey)?.[0] || findBenchmarkSourceCard(test.source);
        const filters = buildBenchmarkFiltersForLint(test);
        const highlights = sourceCard ? buildBenchmarkHighlightState(test, sourceCard) : [];
        const intentionalConflicts = new Set((test.constraintConflicts || []).map(normalizeCardNameForIdentity));
        for (const expectedName of (test.expected || [])) {
            const key = normalizeCardNameForIdentity(expectedName);
            const candidates = byName.get(key) || [];
            const failures = [];
            if (!candidates.length) {
                failures.push('expected card not found in local cards.bin corpus');
            } else {
                const filterMatches = candidates.filter(card => matchesActiveFilters(card, filters, null));
                if (!filterMatches.length) failures.push('active benchmark filters reject this expected card');
                else if (highlights.length && !filterMatches.some(card => matchesExactHighlightConstraints(card, highlights))) {
                    const explanations = filterMatches.flatMap(card => explainExactHighlightFailures(card, highlights));
                    failures.push(`exact-highlight constraint rejects this expected card${explanations.length ? `: ${[...new Set(explanations)].join(' | ')}` : ''}`);
                }
            }
            if (failures.length) rows.push({
                'Test ID': test.id, 'Source Card': test.source, 'Expected Card': expectedName,
                'Classification': intentionalConflicts.has(key) ? 'Declared intentional conflict' : 'Potentially impossible label',
                'Problem': failures.join('; '),
                'Action': intentionalConflicts.has(key)
                    ? 'Confirm the declared conflict is intentional; do not count it as a strict-filter ranker failure.'
                    : 'Review the expected label and benchmark hard filters/highlights.'
            });
        }
    }
    return rows;
}

function validateBenchmarkSuiteConfiguration() {
    const errors = [];
    const warnings = [];
    const requiredSelectors = [
        'card-search-input', 'filter-type', 'filter-format', 'filter-rarity', 'filter-identity',
        'filter-colors', 'filter-cmc', 'filter-power', 'filter-toughness', 'filter-extra-oracle'
    ];
    if (typeof document !== 'undefined') {
        requiredSelectors.forEach(id => {
            if (!document.getElementById(id)) errors.push(`Missing benchmark UI control #${id}`);
        });
        if (!document.querySelector('main')) warnings.push('No <main> element; benchmark dashboard will fall back to document.body.');
    }
    if (!Array.isArray(BENCHMARK_SUITE) || BENCHMARK_SUITE.length === 0) errors.push('BENCHMARK_SUITE is empty.');

    const ids = new Set();
    for (const test of (BENCHMARK_SUITE || [])) {
        if (!Number.isFinite(test?.id)) errors.push('Benchmark test has no numeric id.');
        if (ids.has(test.id)) errors.push(`Duplicate benchmark test id: ${test.id}`);
        ids.add(test.id);
        if (!test?.source) errors.push(`Benchmark test #${test?.id ?? '?'} has no source card.`);
        if (!Array.isArray(test?.expected) || test.expected.length === 0) errors.push(`Benchmark test #${test?.id ?? '?'} has no expected cards.`);
        const hs = Array.isArray(test?.highlights) ? test.highlights : [];
        hs.forEach((h, i) => {
            if (!h?.text?.trim()) errors.push(`Benchmark test #${test.id} highlight #${i + 1} has no text.`);
            if (!['exact', 'variable'].includes(h?.mode)) errors.push(`Benchmark test #${test.id} highlight #${i + 1} has invalid mode.`);
        });
    }
    if (errors.length) throw new Error(`Benchmark configuration invalid: ${errors.join(' | ')}`);
    if (warnings.length) console.warn('Benchmark configuration warnings:', warnings);
    return { tests: BENCHMARK_SUITE.length, warnings };
}


// Public benchmark preflight. This performs only deterministic checks and never contacts Scryfall,
// so it is safe to run before a benchmark when debugging the browser integration.
function validateBenchmarkRuntimeInApp() {
    const result = { ok: true, tests: 0, errors: [], warnings: [] };
    try {
        const cfg = validateBenchmarkSuiteConfiguration();
        result.tests = cfg.tests;
        result.warnings = cfg.warnings || [];

        // app.js is an ES module, so its top-level function declarations are module-scoped and
        // are not required to be properties of window/globalThis. Check the actual lexical
        // bindings instead; the old window/globalThis test reported false warnings for functions
        // that the benchmark calls successfully from this same module.
        const requiredFunctions = [
            ['runBenchmarkSuite', typeof runBenchmarkSuite === 'function'],
            ['runBenchmarkPass', typeof runBenchmarkPass === 'function'],
            ['resetBenchmarkColdState', typeof resetBenchmarkColdState === 'function'],
            ['buildBenchmarkHighlightState', typeof buildBenchmarkHighlightState === 'function'],
            ['renderBenchmarkHighlightPreview', typeof renderBenchmarkHighlightPreview === 'function'],
            ['findSessionSemanticMatches', typeof findSessionSemanticMatches === 'function'],
            ['findFullSemanticMatches', typeof findFullSemanticMatches === 'function'],
            ['findFullSemanticExactMatches', typeof findFullSemanticExactMatches === 'function'],
            ['calculateRecallAtK', typeof calculateRecallAtK === 'function'],
            ['calculateMRR', typeof calculateMRR === 'function'],
            ['calculateNDCGAtK', typeof calculateNDCGAtK === 'function'],
            ['calculatePrecisionAtK', typeof calculatePrecisionAtK === 'function']
        ];
        for (const [name, available] of requiredFunctions) {
            if (!available) result.warnings.push(`Benchmark function is unavailable in app module: ${name}`);
        }

        // V25: preflight also audits configured benchmark highlight ranges and their grouped
        // intent. This catches stale/partial snippets before a costly full ranking benchmark.
        // It is deterministic, does not issue network requests, and restores currentSourceCard.
        try {
            const highlightAudit = runManaSearchBenchmarkHighlightSuite({ log: false });
            result.highlightAudit = { passed: highlightAudit.passed, total: highlightAudit.total };
            if (highlightAudit.passed !== highlightAudit.total) {
                result.errors.push(`Benchmark highlight audit failed: ${highlightAudit.passed}/${highlightAudit.total} checks passed.`);
            }
        } catch (auditError) {
            result.errors.push(`Benchmark highlight audit could not run: ${auditError?.message || String(auditError)}`);
        }

        if (typeof document !== 'undefined') {
            const dashboard = ensureBenchmarkDashboard();
            if (!dashboard) result.errors.push('Benchmark dashboard could not be created.');
            const sourceOracle = document.getElementById('source-card-oracle');
            if (!sourceOracle) result.errors.push('Source Oracle text element is missing; benchmark highlights cannot be rendered.');
        }

        result.ok = result.errors.length === 0;
        console.info(`Benchmark preflight: ${result.ok ? 'PASS' : 'FAIL'} — ${result.tests} test(s) configured.`, result);
    } catch (error) {
        result.ok = false;
        result.errors.push(error?.message || String(error));
        console.error('Benchmark preflight: FAIL', result);
    }
    return result;
}


/**
 * Deterministic blocked record used when a benchmark pass cannot be measured. This is a recorded
 * blocked status, not a fake pass, and keeps an environmental issue from contaminating quality
 * metrics with outage-driven zeroes.
 * @param {Object} test
 * @param {string} reason
 * @returns {Object}
 */
function createBenchmarkBlockedPass(test, reason) {
    const expected = Array.isArray(test?.expected) ? test.expected : [];
    const emptyRanks = {};
    expected.forEach(cardName => { emptyRanks[cardName] = 100; });
    return {
        testStatus: 'blocked_rate_limit',
        errorMessage: reason,
        diagnostics: null,
        rankedResults: [],
        scoreByName: new Map(),
        conflictSet: new Set((test?.constraintConflicts || []).map(c => String(c).toLowerCase())),
        results: [],
        recall5: 0,
        recall10: 0,
        recall20: 0,
        adjustedRecall5: 0,
        adjustedRecall10: 0,
        adjustedRecall20: 0,
        mrr: 0,
        ndcg10: 0,
        ndcg20: 0,
        precision10: 0,
        avgTestRank: 100,
        cardRanks: emptyRanks,
        stageRecalls: { retrieval: 0, filter: 0, dedup: 0, scoring: 0, pruning: 0 }
    };
}

/**
 * Static-data-only benchmark readiness hook. Card retrieval reads the bundled corpus and semantic
 * index; no network card API or per-test cooldown is used.
 */
async function waitForBenchmarkStaticDataReady() { return; }

/**
 * Retry an incomplete local-data benchmark pass. Result, session, and retrieval caches are reset
 * for each attempt; deterministic text embeddings remain cached within the suite.
 */
async function runBenchmarkPassWithLocalRecovery(searchFn, test, label = 'benchmark pass', maxAttempts = 3) {
    let lastPass = null;
    const attempts = Math.max(1, maxAttempts);

    for (let attempt = 1; attempt <= attempts; attempt++) {
        await waitForBenchmarkStaticDataReady(`${label} (attempt ${attempt}/${attempts})`);
        resetBenchmarkColdState({ keepImmutableEmbeddings: true });

        if (attempt > 1) {
            console.warn(`Benchmark ${label}: retrying after a local-data test failure (attempt ${attempt}/${attempts}).`);
            try {
                updateBenchmarkDashboard({
                    state: 'Retrying test',
                    totalTests: BENCHMARK_SUITE.length,
                    detail: `Preparing a fresh local-data pass; rerunning ${label} from a cold state (attempt ${attempt}/${attempts})…`,
                    percent: null
                });
            } catch (_) {}
            await backgroundAwareDelay(0);
        }

        const pass = await runBenchmarkPass(searchFn, test);
        lastPass = pass;

        if (pass?.testStatus !== 'blocked_rate_limit') return pass;

        if (attempt < attempts) {
            console.warn(`Benchmark ${label}: rate-limited. The suite will wait for the cooldown before retrying this same test.`);
            await waitForBenchmarkStaticDataReady(`${label} retry`);
        }
    }

    return lastPass || createBenchmarkBlockedPass(
        test,
        `Local benchmark pass remained blocked after ${attempts} attempts; no runtime card API fallback is available.`
    );
}

async function runBenchmarkSuite(searchFn) {
    const benchmarkValidation = validateBenchmarkSuiteConfiguration();
    benchmarkColdMode = true;
    ensureBenchmarkDashboard();
    updateBenchmarkDashboard({
        state: 'Starting',
        testIndex: 0,
        totalTests: BENCHMARK_SUITE.length,
        detail: 'Preparing the model and local benchmark data before Test #1…',
        percent: 2
    });
    await backgroundAwareDelay(0);
    let completedBenchmarkTests = 0;
    let measuredBenchmarkTests = 0;
    let blockedBenchmarkTests = 0;
    let erroredBenchmarkTests = 0;
    try {
        const startedAt = new Date();
    const runId = generateBenchmarkRunId(startedAt);

    benchmarkUseLocalOracleCorpus = false;
    benchmarkLocalOracleCorpus = null;
    benchmarkApiConservativeMode = false;
    updateBenchmarkDashboard({
        state: 'Checking bundled card data',
        totalTests: BENCHMARK_SUITE.length,
        detail: 'Loading cards.bin and semantic-index.bin. Benchmark retrieval and hydration use only bundled local assets.',
        percent: 5
    });
    await backgroundAwareDelay(0);
    const staticReadyForBenchmark = await loadStaticSearchResources({ requireSemantic: true });
    if (!staticReadyForBenchmark || !staticCardCorpusMemory?.cards?.length || fullSemanticIndexMemory?.source !== 'static') {
        throw new Error('Benchmark requires the bundled cards.bin and semantic-index.bin. Runtime Scryfall card fetches are disabled. Check static-data-meta.json and the two .bin assets.');
    }
    console.info('Benchmark retrieval mode: local-only cards.bin + precomputed semantic-index.bin; no card API requests.');

    const benchmarkLabelLintRows = lintBenchmarkExpectedLabels(BENCHMARK_SUITE, staticCardCorpusMemory.cards);
    if (benchmarkLabelLintRows.length) {
        console.warn(`[ManaSearch] Benchmark label lint found ${benchmarkLabelLintRows.length} likely impossible expectation(s).`, benchmarkLabelLintRows);
        console.table(benchmarkLabelLintRows);
    } else {
        console.info('[ManaSearch] Benchmark label lint: no impossible expected-card labels found.');
    }
    const benchmarkPredicateExpectedById = new Map(BENCHMARK_SUITE.map(test => [
        test.id, buildBenchmarkPredicateExpected(test, staticCardCorpusMemory.cards)
    ]));

    // Load the NLP model opportunistically, but never let model startup block the whole suite.
    try {
        updateBenchmarkDashboard({
            state: 'Preparing model',
            totalTests: BENCHMARK_SUITE.length,
            detail: 'Preparing semantic model; benchmark will continue with structural/lexical scoring if it is unavailable…',
            percent: 8
        });
        await withBenchmarkTimeout(getNLPModel(), 20000, 'Semantic model startup');
    } catch (err) {
        console.info('Benchmark semantic model unavailable; continuing with non-ML scoring:', err?.message || err);
        nlpExtractor = { type: 'fallback' };
    }

    // Source-card metadata is resolved exclusively from cards.bin. Every benchmark source and candidate
    // must exist in the local deployed catalog; this benchmark never fetches card records online.
    if (typeof updateBenchmarkDashboard === 'function') {
        updateBenchmarkDashboard({
            state: 'Using bundled local data',
            totalTests: BENCHMARK_SUITE.length,
            detail: 'Bundled card catalog and precomputed semantic index are ready; starting local-only benchmark tests…',
            percent: 12
        });
        await backgroundAwareDelay(0);
    }

    // Every benchmark test starts with cold retrieval/result/session state. Immutable deterministic
    // text embeddings are reused within the suite, just as they are during a real sequence of user
    // searches; no candidate list or prior result ranking is reused.
    resetBenchmarkColdState();

    console.log("==================================================");
    console.log("     ManaSearch Local-Only Benchmark Suite       ");
    console.log(`     Run ID: ${runId}`);
    console.log("==================================================\n");

    const suiteResults = [];
    const retrievalCostRows = [];
    let totalRecall5 = 0, totalRecall10 = 0, totalRecall20 = 0;
    // "Adjusted" recall excludes expected cards flagged as constraintConflicts (see
    // BENCHMARK_SUITE) from the denominator - a card the engine's own hard filters correctly
    // exclude (because the card itself doesn't satisfy the test's own supplied constraints) isn't
    // a retrieval/ranking failure, it's a data problem with the test case.
    let totalAdjustedRecall5 = 0, totalAdjustedRecall10 = 0, totalAdjustedRecall20 = 0;
    let totalMRR = 0, totalNDCG10 = 0, totalNDCG20 = 0, totalPrecision10 = 0, totalRetrievalRecall = 0;
    let allExpectedRanks = [];
    const categoryTotals = {};
    const structuredResults = [];

    // Semantic recall totals are only meaningful for tests that actually declared preferred
    // constraints, so they're averaged over that subset, not the whole suite - diluting them
    // across every test would make "preferred constraints matter a lot for these 2 tests" look
    // like "barely matters at all" (review Priority 2 / Priority 9).
    let semanticTestCount = 0;
    let totalSemanticRecall20 = 0, totalSemanticMRR = 0, totalSemanticNDCG20 = 0;

    for (let benchmarkIndex = 0; benchmarkIndex < BENCHMARK_SUITE.length; benchmarkIndex++) {
        const test = BENCHMARK_SUITE[benchmarkIndex];
        const benchmarkTestStartedAt = Date.now();
        try {
        updateBenchmarkDashboard({
            state: 'Running',
            testIndex: benchmarkIndex,
            totalTests: BENCHMARK_SUITE.length,
            test,
            detail: 'Resetting cold search state…',
            percent: 15 + (benchmarkIndex / Math.max(1, BENCHMARK_SUITE.length)) * 80
        });
        await backgroundAwareDelay(0);
        // EVERY configured test gets an actual search attempt. If a previous test opened the
        // Local-only mode: continue testing independently without remote card-data cooldowns.
        await waitForBenchmarkStaticDataReady(`Test #${test.id}`);

        // Retrieval/result/session state is cold per test; immutable text embeddings remain cached
        // within this benchmark suite to avoid needlessly rerunning transformer inference.
        resetBenchmarkColdState({ keepImmutableEmbeddings: true });

        console.log(`\n--------------------------------------------------`);
        console.log(`Test #${test.id}: ${test.name} (${test.source})`);
        console.log(`--------------------------------------------------`);

        const testStartedAt = benchmarkTestStartedAt;
        updateBenchmarkDashboard({
            state: 'Running test',
            testIndex: benchmarkIndex,
            totalTests: BENCHMARK_SUITE.length,
            test,
            detail: 'Loading source card, applying benchmark highlights, and running the search pipeline…',
            percent: 15 + (benchmarkIndex / Math.max(1, BENCHMARK_SUITE.length)) * 80
        });
        await backgroundAwareDelay(0);

        console.log(`  Benchmark search attempt: Test #${test.id} — running the local in-browser search pipeline.`);
        const predicateExpected = benchmarkPredicateExpectedById.get(test.id) || [];
        const evaluationTest = test.relevancePredicate ? { ...test, predicateExpected } : test;
        const strictPass = await runBenchmarkPassWithLocalRecovery(
            searchFn,
            evaluationTest,
            `Test #${test.id} strict pass`,
            3
        );

        if (strictPass.testStatus === 'blocked_rate_limit') {
            console.warn(`Benchmark Test #${test.id}: Runtime card API fallback was disabled after the retry budget; recording this test as blocked, then continuing.`);
        } else if (strictPass.testStatus === 'error') {
            console.error(`Benchmark Test #${test.id}: isolated strict-pass error; continuing.`);
        }

        // A test with preferredConstraints gets a SECOND pass with those specific fields omitted
        // entirely (not loosened engine-side - the live filters stay exactly as strict as they
        // are). This measures "how well would ManaSearch have done on this source card's real
        // function" separately from "how well did it do while also matching this test's rarity
        // preference" (review Priority 2, "three filter modes"; Priority 9, "Semantic Recall").
        const preferredFields = test.preferredConstraints || [];
        let semanticPass = null;
        if (preferredFields.length > 0) {
            // Preferred-constraint/semantic comparison is also a real search. Never silently skip
            // it because the strict pass encountered a 429; the recovery helper waits for the
            // cooldown and gives the relaxed pass the same opportunity to run.
            const relaxedConstraints = { ...test.constraints };
            preferredFields.forEach(f => { delete relaxedConstraints[f]; });
            semanticPass = await runBenchmarkPassWithLocalRecovery(
                searchFn,
                { ...evaluationTest, constraints: relaxedConstraints },
                `Test #${test.id} semantic pass`,
                3
            );
        }

        const testDurationMs = Date.now() - testStartedAt;
        updateBenchmarkDashboard({
            state: 'Test complete',
            testIndex: benchmarkIndex + 1,
            totalTests: BENCHMARK_SUITE.length,
            test,
            detail: `Completed in ${fmtMs(testDurationMs)}. Preparing the next cold test…`,
            percent: 15 + ((benchmarkIndex + 1) / Math.max(1, BENCHMARK_SUITE.length)) * 80
        });
        await backgroundAwareDelay(0);
        if (strictPass.testStatus === 'error') {
            console.error(`  [ERROR] Test #${test.id} failed:`, strictPass.errorMessage);
        } else if (strictPass.testStatus === 'blocked_rate_limit') {
            console.warn(`  [BLOCKED] Test #${test.id}: ${strictPass.errorMessage}`);
        }

        // Print Funnel Pipeline Counts (strict pass - this is what the live UI actually returns)
        const d = strictPass.diagnostics;
        if (d) {
            console.log(`Pipeline Diagnostics:`);
            console.log(`  Candidates retrieved:        ${d.retrieved}`);
            console.log(`  Passed hard filters (raw):   ${d.passedFiltersRaw ?? 'n/a'}`);
            console.log(`  After dedup:                 ${d.afterHardFilters}`);
            console.log(`  After relevance floor:       ${d.afterRelevanceFloor}`);
    if (d.relevanceFloorRescued) console.log(`  Relevance-floor rescue:      ${d.relevanceFloorRescued} (strict pass was ${d.relevanceFloorStrictCount ?? 0})`);
            console.log(`  Final results:               ${d.finalResults}`);
            if (d.timings) {
                console.log(`  Timing: retrieval ${fmtMs(d.timings.retrievalMs)} | scoring ${fmtMs(d.timings.scoringMs)} | ranking ${fmtMs(d.timings.rankingMs)} | render ${fmtMs(d.timings.renderMs)} | total ${fmtMs(d.timings.totalMs)}`);
            }

            // Search G (session semantic corpus) is new relative to the other streams: it can
            // retrieve zero results on a session's first-ever test and grow more useful as later
            // tests populate the corpus, so its count is worth calling out on its own rather than
            // folding silently into the other stream sizes (see the corpus's own comment for why).
            const searchGCount = d.streams?.['Search G']?.size ?? 0;
            if (searchGCount > 0) {
                console.log(`  Search G (session semantic corpus): ${searchGCount} candidate(s) retrieved by meaning alone`);
            }

            // Embedding cache health for this test: how many candidates needed a fresh model
            // call vs. were already cached, and how many silently fell back to lexical-only
            // scoring because a model call failed (review: embedding diagnostics).
            if (d.embeddingDiagnostics) {
                const { cacheHits, computed, failed, skippedForBudget } = d.embeddingDiagnostics;
                console.log(`  Embedding cache: ${cacheHits} cache hit(s), ${computed} computed, ${failed} failed (fell back to lexical-only)${skippedForBudget ? `, ${skippedForBudget} skipped (semantic-scoring budget, fell back to lexical-only)` : ''}`);
                if (Number.isFinite(d.embeddingDiagnostics.totalCandidates) && Number.isFinite(d.embeddingDiagnostics.semanticEligibleCount)) {
                    console.log(`  Semantic-scoring budget: ${d.embeddingDiagnostics.semanticEligibleCount} of ${d.embeddingDiagnostics.totalCandidates} candidates`);
                }
                const st = d.embeddingDiagnostics.stageTimings;
                if (st) {
                    console.log(`  Scoring breakdown: source/setup ${fmtMs(st.sourceSetupMs)} | structural ${fmtMs(st.structuralMs)} | cache calibration ${fmtMs(st.cacheCalibrationMs)} | candidate triage ${fmtMs(st.triageAndSelectionMs)} | embedding text prep ${fmtMs(st.embeddingTextPreparationMs)} | embedding inference/cache ${fmtMs(st.embeddingWarmCacheMs)} | semantic pass ${fmtMs(st.semanticPassMs)} | calibration ${fmtMs(st.calibrationMs)} | final blend ${fmtMs(st.finalBlendMs)} | other ${fmtMs(st.unattributedMs)} | scorer total ${fmtMs(st.totalMs)}`);
                    if (st.structuralDetails) {
                        const sd = st.structuralDetails;
                        console.log(`  Structural detail: parse ${fmtMs(sd.parseMs)} | exactness ${fmtMs(sd.exactnessMs)} | candidate profiles/graph/synergy ${fmtMs(sd.profileGraphSynergyMs)} | mechanical/effect matching ${fmtMs(sd.mechanicalPairingMs)} | role/highlight/confidence ${fmtMs(sd.roleHighlightConfidenceMs)} | category ${fmtMs(sd.categoryMs)}`);
                    }
                    if (st.pairCache) {
                        const pc = st.pairCache;
                        console.log(`  Pair-cache reuse: effect pairs ${pc.directionalHits.toLocaleString()} reused / ${pc.directionalComputed.toLocaleString()} computed | graph-node pairs ${pc.graphNodeHits.toLocaleString()} reused / ${pc.graphNodeComputed.toLocaleString()} computed`);
                    }
                    if (lastSearchDiagnostics.previewOptimization) {
                        const pv = lastSearchDiagnostics.previewOptimization;
                        console.log(`  Progressive preview work: ${pv.lightweightCandidates.toLocaleString()} cheap previews | ${pv.progressiveFullScored.toLocaleString()} full provisional scores (cap ${pv.progressiveFullScoreCap}) | ${pv.remainingQueuedForFinalPass.toLocaleString()} deferred to authoritative pass`);
                    }
                }
            }

            // Coverage warnings: flag any stream that hit its page cap while a large fraction of
            // its own Scryfall match set was left unfetched (review Priority 4 / E).
            if (d.streamCoverage) {
                const undercovered = Object.entries(d.streamCoverage).filter(([, cov]) => cov && !cov.fullyCovered && cov.totalCards > 0);
                if (undercovered.length > 0) {
                    console.log(`  Coverage warnings:`);
                    undercovered.forEach(([streamName, cov]) => {
                        console.log(`    ${streamName}: fetched ${cov.retrievedCount}/${cov.totalCards} matching cards (${cov.pagesFetched} of ~${Math.ceil(cov.totalCards / 175)} pages)`);
                    });
                }
            }
            if (d.searchFQueryDetail?.length) {
                console.log(`  Search F formulations:`);
                d.searchFQueryDetail.forEach((q, i) => {
                    console.log(`    Query ${i + 1} (${q.narrow ? 'narrow' : 'broad'}): ${q.retrieved} retrieved - ${q.query}`);
                });
            }

            // Retrieval Cost sheet rows: cost (cards fetched vs. haystack size) per stream, so
            // "we're spending N seconds retrieving M cards out of a K-card haystack" is directly
            // visible rather than implied by console warnings alone (review Priority 4 / 10-4).
            Object.entries(d.streamCoverage || {}).forEach(([streamName, cov]) => {
                if (!cov) return;
                retrievalCostRows.push({
                    'Test ID': test.id, 'Source Card': test.source, 'Stream': streamName,
                    'Query': cov.query || '', 'Matches': cov.totalCards ?? '', 'Retrieved': cov.retrievedCount ?? '',
                    'Pages': cov.pagesFetched ?? '', 'Page Budget': cov.maxPages ?? '',
                    'Fully Covered': cov.fullyCovered ? 'Y' : 'N',
                    '% of Haystack Retrieved': cov.totalCards ? `${((cov.retrievedCount / cov.totalCards) * 100).toFixed(2)}%` : ''
                });
            });
            (d.searchFQueryDetail || []).forEach((q, i) => {
                retrievalCostRows.push({
                    'Test ID': test.id, 'Source Card': test.source, 'Stream': `Search F (query ${i + 1})`,
                    'Query': q.query, 'Matches': q.coverage?.totalCards ?? '', 'Retrieved': q.retrieved,
                    'Pages': q.coverage?.pagesFetched ?? '', 'Page Budget': q.coverage?.maxPages ?? '',
                    'Fully Covered': q.coverage?.fullyCovered ? 'Y' : 'N',
                    '% of Haystack Retrieved': q.coverage?.totalCards ? `${((q.retrieved / q.coverage.totalCards) * 100).toFixed(2)}%` : ''
                });
            });
            // Search G has no Scryfall page/coverage concept (it's a local corpus lookup, not a
            // paged network query) - those columns are left blank rather than filled with a
            // fabricated "fully covered" value that wouldn't mean anything for this stream.
            if (d.streams?.['Search G']) {
                retrievalCostRows.push({
                    'Test ID': test.id, 'Source Card': test.source, 'Stream': 'Search G (session semantic corpus)',
                    'Query': '', 'Matches': '', 'Retrieved': d.streams['Search G'].size,
                    'Pages': '', 'Page Budget': '', 'Fully Covered': '', '% of Haystack Retrieved': ''
                });
            }
        } else {
            console.log(`  [Warning] No pipeline diagnostics returned.`);
        }

        printExpectedCardTrace(strictPass, test, 'STRICT');
        if (semanticPass) {
            printExpectedCardTrace(semanticPass, test, 'SEMANTIC (preferred constraints relaxed)');
            console.log(`\n  Strict vs Semantic Recall@20: ${(strictPass.recall20 * 100).toFixed(1)}% -> ${(semanticPass.recall20 * 100).toFixed(1)}%`);
        }

        console.log(`\nRanking metrics: MRR ${strictPass.mrr.toFixed(3)} | NDCG@10 ${strictPass.ndcg10.toFixed(3)} | NDCG@20 ${strictPass.ndcg20.toFixed(3)} | P@10 ${strictPass.precision10.toFixed(3)}`);
        console.log(`Stage recall: retrieval ${(strictPass.stageRecalls.retrieval * 100).toFixed(0)}% -> filter ${(strictPass.stageRecalls.filter * 100).toFixed(0)}% -> dedup ${(strictPass.stageRecalls.dedup * 100).toFixed(0)}% -> scored ${(strictPass.stageRecalls.scoring * 100).toFixed(0)}% -> pruned ${(strictPass.stageRecalls.pruning * 100).toFixed(0)}%`);
        console.log(`Duration: ${(testDurationMs / 1000).toFixed(2)}s`);

        const isBlocked = strictPass.testStatus === 'blocked_rate_limit';
        if (isBlocked) {
            blockedBenchmarkTests++;
        } else {
            measuredBenchmarkTests++;
            totalRecall5 += strictPass.recall5;
            totalRecall10 += strictPass.recall10;
            totalRecall20 += strictPass.recall20;
            totalAdjustedRecall5 += strictPass.adjustedRecall5;
            totalAdjustedRecall10 += strictPass.adjustedRecall10;
            totalAdjustedRecall20 += strictPass.adjustedRecall20;
            totalMRR += strictPass.mrr;
            totalNDCG10 += strictPass.ndcg10;
            totalNDCG20 += strictPass.ndcg20;
            totalPrecision10 += strictPass.precision10;
            totalRetrievalRecall += strictPass.stageRecalls.retrieval;
            allExpectedRanks.push(...Object.values(strictPass.cardRanks));

            (test.categories || ['uncategorized']).forEach(cat => {
                if (!categoryTotals[cat]) categoryTotals[cat] = { count: 0, recall20: 0, ndcg20: 0, mrr: 0, retrieval: 0 };
                categoryTotals[cat].count++;
                categoryTotals[cat].recall20 += strictPass.recall20;
                categoryTotals[cat].ndcg20 += strictPass.ndcg20;
                categoryTotals[cat].mrr += strictPass.mrr;
                categoryTotals[cat].retrieval += strictPass.stageRecalls.retrieval;
            });
        }

        if (semanticPass && semanticPass.testStatus !== 'blocked_rate_limit') {
            semanticTestCount++;
            totalSemanticRecall20 += semanticPass.recall20;
            totalSemanticMRR += semanticPass.mrr;
            totalSemanticNDCG20 += semanticPass.ndcg20;
        }

        const traceSourceCard = isBlocked ? findBenchmarkSourceCard(test.source) : currentSourceCard;
        structuredResults.push({
            id: test.id, name: test.name, source: test.source,
            highlights: buildBenchmarkHighlightState(test, traceSourceCard),
            categories: test.categories || [], constraints: test.constraints || {},
            highlightStyle: test.highlightStyle || 'user-like intent excerpt',
            highlightIntent: test.highlightIntent || '',
            highlightDefinitions: (test.highlights || []).map(h => ({
                text: h.text, mode: h.mode, intent: h.intent || ''
            })),
            expected: test.expected, constraintConflicts: test.constraintConflicts || [],
            relevancePredicate: test.relevancePredicate || '',
            predicateExpected: predicateExpected,
            labelLint: benchmarkLabelLintRows.filter(row => Number(row['Test ID']) === Number(test.id)),
            preferredConstraints: preferredFields,
            durationMs: testDurationMs,
            strict: strictPass,
            semantic: semanticPass
        });

        suiteResults.push({
            "Test ID": test.id,
            "Source Card": test.source,
            "Highlight Style": test.highlightStyle || 'user-like intent excerpt',
            "Highlight Intent": test.highlightIntent || '',
            "Highlights": (test.highlights || (test.highlightedOracle ? [{ text: test.highlightedOracle, mode: 'exact' }] : [])).map(h => `${h.mode}: ${h.text}${h.intent ? ` [intent: ${h.intent}]` : ''}`).join(' | '),
            "Status": strictPass.testStatus,
            "Duration": `${(testDurationMs / 1000).toFixed(2)}s`,
            "Recall@5": `${(strictPass.recall5 * 100).toFixed(1)}%`,
            "Recall@10": `${(strictPass.recall10 * 100).toFixed(1)}%`,
            "Recall@20": `${(strictPass.recall20 * 100).toFixed(1)}%`,
            "Adj. Recall@20": test.constraintConflicts?.length ? `${(strictPass.adjustedRecall20 * 100).toFixed(1)}%` : '-',
            "Semantic Recall@20": semanticPass ? `${(semanticPass.recall20 * 100).toFixed(1)}%` : '-',
            "MRR": strictPass.mrr.toFixed(3),
            "NDCG@20": strictPass.ndcg20.toFixed(3),
            "P@10": strictPass.precision10.toFixed(3),
            "Predicate": test.relevancePredicate || '-',
            "Predicate N": strictPass.predicateExpectedCount ?? '-',
            "Predicate P@10": strictPass.predicatePrecision10 == null ? '-' : strictPass.predicatePrecision10.toFixed(3),
            "Predicate NDCG@10": strictPass.predicateNdcg10 == null ? '-' : strictPass.predicateNdcg10.toFixed(3),
            "Retrieval Recall": `${(strictPass.stageRecalls.retrieval * 100).toFixed(0)}%`,
            "Avg Exp Rank": strictPass.avgTestRank.toFixed(1),
            "Card Ranks": JSON.stringify(strictPass.cardRanks)
        });

        completedBenchmarkTests++;
    } catch (testError) {
        // Hard per-test safety boundary: a trace/reporting bug or unexpected runtime error in one
        // benchmark case must never abort the remaining suite. Record the isolated failure and continue.
        const elapsedMs = Date.now() - benchmarkTestStartedAt;
        const blocked = false;
        const fallbackStatus = 'error';
        const fallbackMessage = testError?.message || String(testError);
        const expected = Array.isArray(test?.expected) ? test.expected : [];
        const fallbackRanks = {};
        expected.forEach(cardName => { fallbackRanks[cardName] = 100; });
        const fallbackPass = createBenchmarkBlockedPass(test, fallbackMessage);
        if (!blocked) {
            fallbackPass.testStatus = 'error';
        }
        if (blocked) blockedBenchmarkTests++;
        else erroredBenchmarkTests++;
        completedBenchmarkTests++;

        console.error(`Benchmark Test #${test?.id ?? benchmarkIndex + 1}: ${fallbackStatus}; continuing to the next test.`, testError);
        suiteResults.push({
            "Test ID": test?.id ?? benchmarkIndex + 1,
            "Source Card": test?.source || '',
            "Highlight Style": test?.highlightStyle || 'user-like intent excerpt',
            "Highlight Intent": test?.highlightIntent || '',
            "Highlights": (test?.highlights || (test?.highlightedOracle ? [{ text: test.highlightedOracle, mode: 'exact' }] : []))
                .map(h => `${h.mode}: ${h.text}${h.intent ? ` [intent: ${h.intent}]` : ''}`).join(' | '),
            "Status": fallbackStatus,
            "Duration": `${(elapsedMs / 1000).toFixed(2)}s`,
            "Recall@5": '0.0%', "Recall@10": '0.0%', "Recall@20": '0.0%',
            "Adj. Recall@20": '-', "Semantic Recall@20": '-', "MRR": '0.000',
            "NDCG@20": '0.000', "P@10": '0.000', "Retrieval Recall": '0%',
            "Avg Exp Rank": '100.0', "Card Ranks": JSON.stringify(fallbackRanks),
            "Error": fallbackMessage
        });
        structuredResults.push({
            id: test?.id ?? benchmarkIndex + 1,
            name: test?.name || `Benchmark Test ${benchmarkIndex + 1}`,
            source: test?.source || '',
            highlights: [],
            categories: test?.categories || [],
            constraints: test?.constraints || {},
            highlightStyle: test?.highlightStyle || 'user-like intent excerpt',
            highlightIntent: test?.highlightIntent || '',
            highlightDefinitions: (test?.highlights || []).map(h => ({ text: h.text, mode: h.mode, intent: h.intent || '' })),
            expected,
            constraintConflicts: test?.constraintConflicts || [],
            preferredConstraints: test?.preferredConstraints || [],
            durationMs: elapsedMs,
            strict: fallbackPass,
            semantic: null
        });
        try {
            updateBenchmarkDashboard({
                state: 'Test complete',
                testIndex: benchmarkIndex + 1,
                totalTests: BENCHMARK_SUITE.length,
                test,
                detail: 'Local-data test error isolated; continuing through the suite…',
                percent: 15 + ((benchmarkIndex + 1) / Math.max(1, BENCHMARK_SUITE.length)) * 80
            });
            await backgroundAwareDelay(0);
        } catch (dashboardError) {
            console.warn('Benchmark dashboard update failed while recovering from a test error:', dashboardError);
        }
    }
    }

    // Aggregate quality metrics over tests that actually reached the ranking pipeline. A blocked
    // test still gets a full result row, but treating its forced-zero scores as measured data would
    // make the benchmark quality numbers depend on temporary API outages rather than ManaSearch.
    const testCount = Math.max(1, measuredBenchmarkTests);
    const benchmarkCompleted = completedBenchmarkTests >= BENCHMARK_SUITE.length;
    const benchmarkFullyMeasured = benchmarkCompleted && blockedBenchmarkTests === 0 && erroredBenchmarkTests === 0;
    const overallAvgRank = allExpectedRanks.length
        ? allExpectedRanks.reduce((a, b) => a + b, 0) / allExpectedRanks.length
        : null;
    const finishedAt = new Date();
    const durationMs = finishedAt.getTime() - startedAt.getTime();

    const categoryBreakdown = Object.entries(categoryTotals).map(([cat, t]) => ({
        "Category": cat, "Tests": t.count,
        "Recall@20": `${((t.recall20 / t.count) * 100).toFixed(1)}%`,
        "NDCG@20": (t.ndcg20 / t.count).toFixed(3),
        "MRR": (t.mrr / t.count).toFixed(3),
        "Retrieval Recall": `${((t.retrieval / t.count) * 100).toFixed(1)}%`
    }));

    console.log("\n==================================================");
    console.log("              TEST SUMMARY BREAKDOWN              ");
    console.log("==================================================");
    console.table(suiteResults);

    console.log("\n--- BREAKDOWN BY CARD CATEGORY ---");
    console.table(categoryBreakdown);

    console.log("--- OVERALL BENCHMARK METRICS ---");
    console.log(`Mean Recall@5:            ${((totalRecall5 / testCount) * 100).toFixed(2)}%`);
    console.log(`Mean Recall@10:           ${((totalRecall10 / testCount) * 100).toFixed(2)}%`);
    console.log(`Mean Recall@20:           ${((totalRecall20 / testCount) * 100).toFixed(2)}%`);
    console.log(`Mean Adjusted Recall@20:  ${((totalAdjustedRecall20 / testCount) * 100).toFixed(2)}%  (excludes constraint-conflict expected cards)`);
    if (semanticTestCount > 0) {
        console.log(`Mean Semantic Recall@20:  ${((totalSemanticRecall20 / semanticTestCount) * 100).toFixed(2)}%  (${semanticTestCount} tests with preferred constraints, preferred fields omitted)`);
    }
    console.log(`Mean Retrieval Recall:    ${((totalRetrievalRecall / testCount) * 100).toFixed(2)}%  (ceiling - ranking can never beat this)`);
    console.log(`Mean MRR:                 ${(totalMRR / testCount).toFixed(4)}`);
    console.log(`Mean NDCG@10:             ${(totalNDCG10 / testCount).toFixed(4)}`);
    console.log(`Mean NDCG@20:             ${(totalNDCG20 / testCount).toFixed(4)}`);
    console.log(`Mean Precision@10:        ${(totalPrecision10 / testCount).toFixed(4)}`);
    console.log(`Overall Avg Card Rank: ${overallAvgRank === null ? 'n/a' : overallAvgRank.toFixed(2)} (Penalty for unranked: 100)`);
    console.log(`Embedding cache: ${embeddingCacheStats.hits.toLocaleString()} hits, ${embeddingCacheStats.computed.toLocaleString()} computations, ${embeddingCacheStats.evictions.toLocaleString()} evictions, ${embeddingCache.size.toLocaleString()}/${EMBEDDING_CACHE_MAX_ENTRIES.toLocaleString()} entries`);
    console.log(`Candidate raw-Oracle vectors reused from semantic-index.bin: ${embeddingCacheStats.precomputedOracleHits.toLocaleString()} hits, ${embeddingCacheStats.precomputedOracleMisses.toLocaleString()} misses`);
    console.log(`Semantic scans: worker ${staticSemanticQueryStats.workerQueries} queries/${(staticSemanticQueryStats.workerElapsedMs / 1000).toFixed(2)}s, ${staticSemanticQueryStats.workerFailures} worker failures; local fallback ${staticSemanticQueryStats.fallbackQueries} scans/${(staticSemanticQueryStats.fallbackElapsedMs / 1000).toFixed(2)}s`);
    console.log(`Total runtime: ${(durationMs / 1000).toFixed(2)}s`);
    if (benchmarkCompleted) {
        console.log(`Benchmark traversed all tests: ${completedBenchmarkTests}/${BENCHMARK_SUITE.length}.`);
        if (blockedBenchmarkTests > 0 || erroredBenchmarkTests > 0) {
            console.log(`Non-measured tests: ${blockedBenchmarkTests} blocked, ${erroredBenchmarkTests} isolated error(s). Quality metrics below report only ${measuredBenchmarkTests} measured test(s).`);
        } else {
            console.log('All tests were fully measured.');
        }
    } else {
        console.log(`Benchmark did not traverse the full suite: ${completedBenchmarkTests}/${BENCHMARK_SUITE.length} tests reached the result-recording stage.`);
    }
    console.log("==================================================\n");

    const summaryMetrics = {
        meanRecall5: totalRecall5 / testCount,
        meanRecall10: totalRecall10 / testCount,
        meanRecall20: totalRecall20 / testCount,
        meanAdjustedRecall20: totalAdjustedRecall20 / testCount,
        meanSemanticRecall20: semanticTestCount > 0 ? totalSemanticRecall20 / semanticTestCount : null,
        semanticRecallTestCount: semanticTestCount,
        meanRetrievalRecall: totalRetrievalRecall / testCount,
        meanMRR: totalMRR / testCount,
        meanNDCG10: totalNDCG10 / testCount,
        meanNDCG20: totalNDCG20 / testCount,
        meanPrecision10: totalPrecision10 / testCount,
        overallAvgRank,
        durationMs,
        completedTests: completedBenchmarkTests,
        measuredTests: measuredBenchmarkTests,
        blockedTests: blockedBenchmarkTests,
        erroredTests: erroredBenchmarkTests,
        totalTests: BENCHMARK_SUITE.length,
        benchmarkCompleted,
        benchmarkFullyMeasured
    };

    // Regression comparison against the previous run, so a change's actual effect is visible
    // immediately rather than requiring the user to keep old workbooks open side by side
    // (review Priority 10, "Add regression comparison"). Best-effort: unavailable outside a
    // browser (no localStorage), or on a machine's very first run, simply skips this section.
    let previousRun = null;
    try {
        if (typeof localStorage !== 'undefined') {
            const stored = localStorage.getItem(BENCHMARK_HISTORY_KEY);
            if (stored) previousRun = JSON.parse(stored);
            localStorage.setItem(BENCHMARK_HISTORY_KEY, JSON.stringify({ runId, generatedAt: finishedAt.toISOString(), ...summaryMetrics }));
        }
    } catch (err) {
        console.warn("Benchmark history read/write skipped:", err.message);
    }

    if (previousRun) {
        console.log("--- VS PREVIOUS RUN ---");
        console.log(`Previous run: ${previousRun.runId || '(unknown)'} at ${previousRun.generatedAt || '(unknown)'}`);
        [['Recall@20', 'meanRecall20', true], ['Retrieval Recall', 'meanRetrievalRecall', true], ['MRR', 'meanMRR', false], ['Avg runtime', 'durationMs', false]]
            .forEach(([label, key, isPct]) => {
                const prev = previousRun[key];
                const curr = summaryMetrics[key];
                if (prev === undefined || prev === null || curr === undefined || curr === null) return;
                const delta = curr - prev;
                const deltaStr = key === 'durationMs'
                    ? `${delta >= 0 ? '+' : ''}${(delta / 1000).toFixed(2)}s`
                    : isPct ? `${delta >= 0 ? '+' : ''}${(delta * 100).toFixed(2)}pp` : `${delta >= 0 ? '+' : ''}${delta.toFixed(4)}`;
                console.log(`  ${label}: ${isPct ? (prev * 100).toFixed(2) + '%' : key === 'durationMs' ? (prev / 1000).toFixed(2) + 's' : prev.toFixed(4)} -> ${isPct ? (curr * 100).toFixed(2) + '%' : key === 'durationMs' ? (curr / 1000).toFixed(2) + 's' : curr.toFixed(4)}  (${deltaStr})`);
            });
        console.log("==================================================\n");
    }

    const report = {
        runId,
        startedAt,
        finishedAt,
        generatedAt: finishedAt,
        ...summaryMetrics,
        categoryBreakdown,
        structuredResults,
        labelLintRows: benchmarkLabelLintRows,
        retrievalCostRows,
        previousRun,
        details: suiteResults,
        completedTests: completedBenchmarkTests,
        measuredTests: measuredBenchmarkTests,
        blockedTests: blockedBenchmarkTests,
        erroredTests: erroredBenchmarkTests,
        totalTests: BENCHMARK_SUITE.length,
        benchmarkCompleted,
        benchmarkFullyMeasured,
        runtimeCardApiUsed: false,
        runtimeCardApiEnabled: false,
        cardDataSource: 'cards.bin + semantic-index.bin',
        embeddingCachePolicy: `Cold at suite start; deterministic text embeddings reusable between tests; bounded at ${EMBEDDING_CACHE_MAX_ENTRIES.toLocaleString()} entries. Result/search/session retrieval caches are reset per test.`,
        embeddingCacheDiagnostics: { ...embeddingCacheStats, entries: embeddingCache.size, maxEntries: EMBEDDING_CACHE_MAX_ENTRIES },
        semanticQueryDiagnostics: { ...staticSemanticQueryStats },
        benchmarkConfiguration: currentBenchmarkConfiguration ? { ...currentBenchmarkConfiguration } : null
    };

    // Automatically download the full run as a spreadsheet.
    try {
        await downloadBenchmarkWorkbook(report);
    } catch (err) {
        console.error("Benchmark workbook export failed:", err);
    }

        return report;
    } finally {
        const dashboard = ensureBenchmarkDashboard();
        if (dashboard) {
            const completed = typeof completedBenchmarkTests === 'number' ? completedBenchmarkTests : 0;
            const complete = completed >= BENCHMARK_SUITE.length;
            updateBenchmarkDashboard({
                state: complete ? 'Finished' : 'Stopped',
                testIndex: completed,
                totalTests: BENCHMARK_SUITE.length,
                detail: complete
                    ? ((blockedBenchmarkTests > 0 || erroredBenchmarkTests > 0)
                        ? `Benchmark run finished. All ${completed}/${BENCHMARK_SUITE.length} tests were traversed; ${blockedBenchmarkTests} were blocked and ${erroredBenchmarkTests} had isolated local-data errors. Results and traces are shown below.`
                        : 'Benchmark run finished. The results and traces are shown below.')
                    : `Benchmark stopped after ${completed}/${BENCHMARK_SUITE.length} completed test${completed === 1 ? '' : 's'}.`,
                percent: complete ? 100 : (BENCHMARK_SUITE.length ? (completed / BENCHMARK_SUITE.length) * 100 : 0)
            });
        }
        benchmarkColdMode = false;
        benchmarkUseLocalOracleCorpus = false;
        benchmarkLocalOracleCorpus = null;
        benchmarkApiConservativeMode = false;
    }
}

function fmtMs(v) {
    return (v === undefined || v === null) ? 'n/a' : `${(v / 1000).toFixed(2)}s`;
}

// Benchmark source-card resolver. Source-card metadata is immutable benchmark input, so it is
// safe to reuse it across tests. Source records are resolved only from cards.bin/cache; runtime
// card API lookups are disabled, so a missing card is an explicit local-data error.
function findBenchmarkSourceCard(sourceName) {
    const key = normalizeCardNameForIdentity(sourceName || '');
    if (!key) return null;

    if (benchmarkLocalOracleCorpus?.chunks) {
        for (const chunk of benchmarkLocalOracleCorpus.chunks) {
            const names = chunk.names || [];
            const cards = chunk.cards || [];
            for (let i = 0; i < Math.min(chunk.count || names.length, names.length); i++) {
                if (normalizeCardNameForIdentity(names[i]) === key && cards[i]) return cards[i];
            }
        }
    }

    for (const [catalogKey, card] of benchmarkSourceCardCatalog) {
        if (normalizeCardNameForIdentity(catalogKey) === key || normalizeCardNameForIdentity(card?.name) === key) return card;
    }

    return sourceCardCache.get(String(sourceName).trim().toLowerCase()) || null;
}

async function loadBenchmarkSourceCard(sourceName) {
    const localCard = findBenchmarkSourceCard(sourceName);
    if (localCard) {
        ++searchRequestId;
        currentSourceCard = localCard;
        lastSearchResults = [];
        lastSearchDiagnostics = null;
        pendingDeeperSearch = null;
        manualHighlights = [];
        displaySourceCard(localCard);
        activeTags = generateTags(localCard);
        renderTags();
        return localCard;
    }
    return loadSourceCard(sourceName);
}

// Benchmark configuration is pinned during runLocalBenchmarkInApp so comparisons are reproducible.
// Ranking mode, hidden search-method checkboxes, optional ordering modes, and user weight offsets
// previously leaked into runs, making a benchmark compare different ranking systems by accident.
let currentBenchmarkConfiguration = null;
const BENCHMARK_METHOD_CONTROL_IDS = [
    'broad-search', 'divergent-search', 'wording-search', 'functional-search',
    'target-search', 'role-search', 'alternate-search', 'synergy-search'
];
const BENCHMARK_WEIGHT_CONTROL_IDS = ['weight-mechanical', 'weight-synergy', 'weight-context', 'weight-exactness', 'weight-category'];
const BENCHMARK_ORDER_CONTROL_IDS = ['order-feature-matrix', 'order-feature-diverse'];
function snapshotBenchmarkControlState() {
    const values = {};
    [...BENCHMARK_METHOD_CONTROL_IDS, ...BENCHMARK_WEIGHT_CONTROL_IDS, ...BENCHMARK_ORDER_CONTROL_IDS, 'sort-results']
        .forEach(id => {
            const el = document.getElementById(id);
            if (!el) return;
            values[id] = el.type === 'checkbox' ? Boolean(el.checked) : String(el.value ?? '');
        });
    return {
        values,
        activeSearchMethodFlags: { ...activeSearchMethodFlags },
        activeOrderFeatureFlags: { ...activeOrderFeatureFlags }
    };
}
function applyDeterministicBenchmarkControlState() {
    const sort = document.getElementById('sort-results');
    if (sort) sort.value = 'overall';
    BENCHMARK_METHOD_CONTROL_IDS.forEach(id => {
        const el = document.getElementById(id);
        if (el) el.checked = false;
    });
    BENCHMARK_ORDER_CONTROL_IDS.forEach(id => {
        const el = document.getElementById(id);
        if (el) el.checked = false;
    });
    BENCHMARK_WEIGHT_CONTROL_IDS.forEach(id => {
        const el = document.getElementById(id);
        if (el) el.value = '0';
    });
    activeSearchMethodFlags = {
        broad: false, divergent: false, wording: false, functional: false,
        target: false, role: false, alternate: false, synergy: false
    };
    activeOrderFeatureFlags = { matrix: false, diverse: false };
    currentBenchmarkConfiguration = {
        ranking: 'Overall Match',
        searchMethods: 'Standard (all optional method switches off)',
        orderingFeatures: 'Matrix Sweep off; Diverse Spread off',
        userWeightOffsets: '0 (default offsets for mechanical, context, synergy, exactness, category)'
    };
    console.info('[ManaSearch] Benchmark uses a deterministic baseline: Overall Match, Standard methods, Matrix/Diverse off, default weight offsets.');
}
function restoreBenchmarkControlState(snapshot) {
    if (!snapshot) return;
    for (const [id, value] of Object.entries(snapshot.values || {})) {
        const el = document.getElementById(id);
        if (!el) continue;
        if (el.type === 'checkbox') el.checked = Boolean(value);
        else el.value = String(value);
        try { el.dispatchEvent(new Event(el.type === 'checkbox' ? 'change' : 'input', { bubbles: true })); } catch (_) {}
    }
    activeSearchMethodFlags = { ...(snapshot.activeSearchMethodFlags || activeSearchMethodFlags) };
    activeOrderFeatureFlags = { ...(snapshot.activeOrderFeatureFlags || activeOrderFeatureFlags) };
}

// Example Integration Handler for browser environment (App context):
let benchmarkRunPromise = null;
let benchmarkRunInProgress = false;

async function runLocalBenchmarkInApp() {
    if (benchmarkRunPromise) return benchmarkRunPromise;
    const originalBenchmarkControls = snapshotBenchmarkControlState();
    applyDeterministicBenchmarkControlState();
    benchmarkRunInProgress = true;

    benchmarkRunPromise = runBenchmarkSuite(async (testCase) => {
        updateBenchmarkDashboard({
            state: 'Preparing test',
            test: testCase,
            totalTests: BENCHMARK_SUITE.length,
            detail: 'Applying benchmark filters and simulated user highlights…'
        });
        await backgroundAwareDelay(0);
        document.getElementById('card-search-input').value = testCase.source;
        document.getElementById('filter-type').value = testCase.constraints.type || '';
        document.getElementById('filter-format').value = testCase.constraints.format || '';
        document.getElementById('filter-rarity').value = testCase.constraints.rarity || '';
        const identityField = document.getElementById('filter-identity');
        identityField.value = testCase.constraints.identity || '';
        identityField.dispatchEvent(new Event('input'));
        const colorsField = document.getElementById('filter-colors');
        colorsField.value = testCase.constraints.colors || '';
        colorsField.dispatchEvent(new Event('input'));
        document.getElementById('filter-cmc').value = testCase.constraints.cmc || '';
        document.getElementById('filter-power').value = testCase.constraints.power || '';
        document.getElementById('filter-toughness').value = testCase.constraints.toughness || '';
        const benchmarkExtraOracle = document.getElementById('filter-extra-oracle');
        if (benchmarkExtraOracle) benchmarkExtraOracle.value = testCase.constraints.extraOracle || '';

        // Cold benchmark: load this test's source card normally instead of reusing a card loaded
        // for another benchmark test.
        await loadBenchmarkSourceCard(testCase.source);
        manualHighlights = renderBenchmarkHighlightPreview(testCase, currentSourceCard);
        updateBenchmarkDashboard({
            state: 'Searching',
            test: testCase,
            totalTests: BENCHMARK_SUITE.length,
            detail: 'Source card and simulated highlights are visible; running the search pipeline now…'
        });
        await backgroundAwareDelay(0);
        console.log(`  Highlight spec: ${manualHighlights.length ? manualHighlights.map(h => `${h.mode.toUpperCase()}: ${h.text}${h.intent ? ` [${h.intent}]` : ''}`).join(' | ') : 'none'}`);
        await findSimilarCards();
        
        return { results: lastSearchResults, diagnostics: lastSearchDiagnostics };
    }).finally(() => {
        restoreBenchmarkControlState(originalBenchmarkControls);
        currentBenchmarkConfiguration = null;
        benchmarkRunInProgress = false;
        benchmarkRunPromise = null;
    });

    // Return the actual suite promise to the console/caller. Without this return, the async
    // wrapper itself resolves immediately with undefined while the benchmark continues in the
    // background, making DevTools misleadingly show `Promise {<fulfilled>: undefined}`.
    return benchmarkRunPromise;
}

window.runLocalBenchmarkInApp = runLocalBenchmarkInApp;
window.validateBenchmarkRuntimeInApp = validateBenchmarkRuntimeInApp;

// Add Tagging Engine Functions
/**
 * Title-cases a keyword/phrase for tag display, matching the style of the existing hand-written
 * tags ("First Strike", "Double Strike") - e.g. Scryfall's own `keywords` array casing is
 * inconsistent ("First strike", "Ninjutsu", "double strike" depending on source), so without
 * normalizing, a keyword the generic loop below picks up could land as a same-word-different-case
 * near-duplicate of an already-hand-tagged entry instead of the same Set entry.
 * @param {string} str
 * @returns {string}
 */
function toTitleCase(str) {
    return str.replace(/\w\S*/g, word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase());
}

/**
 * Adds a tag only if no case-insensitively-equal tag is already present, so a canonical-function
 * tag and a hand-written regex tag that happen to differ only in casing collapse to one entry
 * instead of showing up as two separate, redundant Set members.
 * @param {Set<string>} tagSet
 * @param {string} candidate
 */
function addTagCaseInsensitive(tagSet, candidate) {
    const lower = candidate.toLowerCase();
    for (const existing of tagSet) {
        if (existing.toLowerCase() === lower) return;
    }
    tagSet.add(candidate);
}

// Maps a canonical function (from deriveCanonicalFunction) to the SAME tag name its hand-written
// regex counterpart already uses above, so the parser's judgment and the regex's judgment
// reconcile onto one Set entry instead of silently disagreeing as two different-cased tags
// (review: tag system item 2). A canonical function with no entry here falls back to a
// Title-Cased version of its own name in generateTags.
const CANONICAL_FUNCTION_TAG_NAMES = {
    reanimate: "Reanimate",
    recursion: "Recursion",
    bounce: "Bounce",
    removal: "Removal",
    exile_removal: "Removal",
    counter: "Counterspell",
    tutor: "Tutor",
    library_exile_access: "Impulse Draw",
    opponent_ramp: "Opponent Ramp",
    opponent_gift: "Opponent Gift",
    token_creation: "Token",
    token_multiplier: "Token Doubler",
    tribal_anthem: "Anthem",
    anthem: "Anthem",
    card_draw: "Draw",
    mill: "Graveyard",
    discard: "Discard",
    direct_damage: "Burn",
    mana_ability: "Ramp",
    self_sacrifice: "Sac Outlet",
    gain_life: "Lifegain",
    // Not "Drain" - the existing Drain tag specifically means life loss paired with the opponent's
    // loss becoming your gain ("target opponent loses X life and you gain X life" / extort). A
    // bare, one-sided life-loss effect (a symmetrical edict-style drawback, "each player loses 1
    // life") isn't drain, so it gets its own name instead of overloading Drain's meaning.
    lose_life: "Life Loss",
    // "tap" has no existing hand tag counterpart (falls through to the generic Title-Case
    // fallback, "Tap") - only untap already had one, reused here.
    untap: "Untap"
    // place_counter deliberately has no flat entry here - see the compositional block in
    // generateTags, which maps it to "+1/+1 Counters" or "-1/-1 Counters" depending on
    // counterType. A flat mapping to the existing "+1/+1 Counters" tag would be wrong for a
    // -1/-1 counter placement, which is a debuff/removal-adjacent effect, not the tribal
    // counters-matter archetype that tag means.
};

function generateTags(card, currentTags = []) {
    const text = (card.oracle_text || (card.card_faces ? card.card_faces.map(f => f.oracle_text).join(' ') : '')).toLowerCase();
    const type = (card.type_line || '').toLowerCase();
    const keywords = (card.keywords || []).map(k => k.toLowerCase());
    const tags = new Set();
    
    // Helper to check keywords array or text
    const hasKeyword = (kw) => keywords.includes(kw) || new RegExp(`\\b${kw}\\b`, 'i').test(text);

    // Some patterns use `.*` broadly enough to span past the end of one ability and into an
    // unrelated one on a multi-ability card - "whenever ... enters" matching because clause 1 has
    // "whenever" and an unrelated clause 2 happens to contain "enters" somewhere. Testing against
    // each sentence individually instead of the whole oracle-text blob at once closes that gap for
    // the patterns most exposed to it (review: tag system item 3). A plain sentence split (not the
    // full clause parser) is enough here - this only needs to stop `.*` from crossing a period, not
    // to structurally parse the ability.
    const sentences = text.split(/(?<=[.!?])\s+|\n+/).filter(Boolean);
    const matchesAnySentence = (regex) => sentences.some(s => regex.test(s));

    // --- KEYWORDS & SPEED ---

    if (hasKeyword('flash')) {
        tags.add("Flash");
    }

    if (hasKeyword('haste')) {
        tags.add("Haste");
    }

    if (hasKeyword('deathtouch')) {
        tags.add("Deathtouch");
    }

    // Ward
    if (hasKeyword('ward')) {
        tags.add("Ward");
    }

    // First Strike 
    if (hasKeyword('first strike')) {
        tags.add("First Strike");
    }

    // Double Strike
    if (hasKeyword('double strike')) {
        tags.add("Double Strike");
    }

    // Vigilance
    if (hasKeyword('vigilance')) {
        tags.add("Vigilance");
    }

    // Proliferate
    if (hasKeyword('proliferate') || /proliferate/i.test(text)) {
        tags.add("Proliferate");
    }

    // Connive
    if (hasKeyword('connive') || /connive \d+/i.test(text)) {
        tags.add("Connive");
    }

    // Incubate 
    if (hasKeyword('incubate') || /incubate \d+/i.test(text)) {
        tags.add("Incubate");
    }
    // Amass
    if (hasKeyword('amass') || /amass/i.test(text)) {
        tags.add("Amass");
    }

    // Ninjutsu
    if (hasKeyword('ninjutsu') || /ninjutsu/i.test(text)) {
        tags.add("Ninjutsu");
    }

    // Devotion
    if (/devotion to/i.test(text)) {
        tags.add("Devotion");
    }

    // Affinity
    if (hasKeyword('affinity') || /affinity for/i.test(text)) {
        tags.add("Affinity");
    }

    // Delirium
    if (hasKeyword('delirium') || /delirium/i.test(text)) {
        tags.add("Delirium");
    }

    // Threshold 
    if (hasKeyword('threshold') || /threshold/i.test(text)) {
        tags.add("Threshold");
    }

    // --- CARD ADVANTAGE & TUTORS ---

    // Draw
    if (/draws?|investigate|reveal the top .* put .* into your hand|look at the top .* put .* into your hand/.test(text)) {
        tags.add("Draw");
    }

    // Impulse Draw
    if (/exile the top .* card.* (you may|until) .* (play|cast)|exile .* card.* from top of your library.* you may (play|cast)/.test(text)) {
        tags.add("Impulse Draw");
    }

    // Tutor
    if (/search your library for a (card|creature|instant|sorcery|artifact|enchantment|planeswalker) card/i.test(text) && !/search your library for a (basic )?land/i.test(text)) {
        tags.add("Tutor");
    }

    // --- MANA & LANDS ---

    // Land Fetcher (Fetches land to hand, top of library, or exile)
    if (/search your library for a .* land card/i.test(text) && (!/onto the battlefield/i.test(text) || /(into your hand|onto your library|top of your library)/i.test(text))) {
        tags.add("Land Fetcher");
    }

    // Ramp (Mana acceleration / direct battlefield placement)
    if (
        /add \{|add .* mana|treasure token|powerstone token|gold token|eldrazi scion token|eldrazi spawn token/i.test(text) ||
        /search your library for .*land card.* put .* onto the battlefield/i.test(text) ||
        /put .* land card.* from .* onto the battlefield/i.test(text) ||
        /play (an|a|\d+)? additional land/i.test(text)
    ) {
        tags.add("Ramp");
    }

    // --- TOKENS & MULTIPLIERS ---

    // Token Generation - also tag roughly how many tokens per activation, since "create a 1/1"
    // and "create six 1/1s" are the same family but very different in degree (project spec F).
    if (/create (a|an|\d+|x|two|three|four) .* token|tokens? .* (are|is) created/.test(text)) {
        tags.add("Token");
        const singleToken = /create (a|an)\b/.test(text);
        const manyTokens = /create (\d+|two|three|four|five|six|x) .* tokens/.test(text);
        if (manyTokens && !singleToken) tags.add("Token:multiple");
        else if (singleToken) tags.add("Token:single");
    }

    // Token Doubler / Multiplier
    if (/if one or more tokens would be created|twice as many|twice that many|those tokens plus a .* token/.test(text)) {
        tags.add("Token Doubler");
    }

    // Counter Doubler / Multiplier
    if (/if one or more (\+1\/\+1| counters?) would be put|twice that many \+1\/\+1|twice that many counters|proliferate/.test(text)) {
        tags.add("Counter Doubler");
    }

    // --- OTHER ARTIFACT TOKENS ---
    if (/food token|clue token|blood token|map token/i.test(text)) {
        tags.add("Tokens (Artifact)");
    }

    // --- INTERACTION & CONTROL ---

    // Theft (Fixed: strictly targets control changes and stealing from opponents)
    if (/gain control of|you control target|cast .* (card|spell)s? (you don't own|an opponent owns)|(play|cast) .* (from|top of) (an opponent's|target opponent's)|control of target/.test(text)) {
        tags.add("Theft");
    }

    // Removal - also tag WHAT it removes (creature/permanent/player) and whether it's
    // conditional, since "destroy target creature" and "destroy target creature unless its
    // controller pays {2}" are not equally strong removal (project spec F/B: compositional tags,
    // outcome-aware matching).
    if (/destroy target|exile target|damage to target|destroy each creature chosen/.test(text)) {
        tags.add("Removal");
        const removalObject = /destroy target creature|exile target creature|damage to target creature/.test(text) ? 'creature'
            : /destroy target permanent|exile target permanent/.test(text) ? 'permanent'
            : /damage to target player|damage to any target/.test(text) ? 'any'
            : null;
        if (removalObject) tags.add(`Removal:${removalObject}`);
        if (/unless (its|that player's|their) controller pays/.test(text)) tags.add("Removal:conditional");
    }

    // Boardwipe
    if (/destroy all|exile all|damage to (each|all) creature/.test(text)) {
        tags.add("Boardwipe");
    }

    // Counterspell
    if (/counter target/.test(text)) {
        tags.add("Counterspell");
    }

    // Bounce
    if (/return target .* to its owner's hand/.test(text)) {
        tags.add("Bounce");
    }

    // Protection (Broadened for Teferi's Protection, Grand Abolisher, Phasing, Ward, Shroud, Damage Prevention, and Spell Safety)
    if (
        hasKeyword('hexproof') || 
        hasKeyword('indestructible') || 
        hasKeyword('ward') || 
        hasKeyword('shroud') || 
        hasKeyword('phasing') ||
        /protection (from|of)|phases? out|can't be countered|prevent all damage|prevent that damage/i.test(text) ||
        /opponents? can't cast spells|opponents? can't activate abilities|during your turn/i.test(text) ||
        /your life total can't change|you can't lose the game|you can't lose damage/i.test(text) ||
        /(gains?|have) (hexproof|indestructible|shroud|ward|protection)/i.test(text) ||
        /spells you control can't be targeted|permanents you control gain/i.test(text)
    ) {
        tags.add("Protection");
    }

    // Tax (Mana penalties, cost increases, and conditional payments)
    if (
        /costs? (\{\d+\}|\d+) more|whenever an opponent .* unless|unless (you|they|that player) pay/i.test(text)
    ) {
        tags.add("Tax");
    }

    // Stax (Resource denial, lockouts, forced sac, and hard restrictions)
    if (
        /opponents? can't|players? can't|can't cast more than|can't draw more than/i.test(text) ||
        /don't untap|can't untap|doesn't untap|skip (their|your)? (untap|draw|main) phase/i.test(text) ||
        /can't activate abilities|abilities of .* can't be activated/i.test(text) ||
        /can't search libraries|can't cast spells from/i.test(text) ||
        /each player sacrifices|whenever a .* enters .* sacrifice/i.test(text)
    ) {
        tags.add("Stax");
    }

    // Graveyard Hate
    if (/exile target card from a graveyard|exile all cards from all graveyards|exile all graveyards/.test(text)) {
        tags.add("Graveyard Hate");
    }

    // --- GRAVEYARD & RECURSION ---

    // Graveyard / Mill
    if (/into your graveyard|mill \d+/.test(text) || /\bmill(s|\d+)?\b/i.test(text) || /puts? the top .* card.* into (their|his or her) graveyard/i.test(text)) {
        tags.add("Graveyard");
    }

    // Recursion (Graveyard to hand)
    if (/return target .* from your graveyard to your hand|return .* card from your graveyard to your hand/.test(text)) {
        tags.add("Recursion");
    }

    // Reanimate (Graveyard to battlefield). Fixed a real regex bug: `your?` does NOT mean "the
    // word 'your' is optional" - in regex, `?` only applies to the single preceding character, so
    // `your?` matches "you" or "your" but still REQUIRES that literal "you" substring. Real cards
    // overwhelmingly phrase this as "from A graveyard" (Animate Dead, Reanimate itself) or "from
    // THEIR graveyard" (Exhume) rather than "from YOUR graveyard", so this regex was silently
    // failing on the most common real-world phrasing - confirmed on a live benchmark run where
    // Reanimate's own oracle text failed to produce this tag via this path (the canonical-function
    // reconciliation below happened to compensate for THIS specific case, but this regex is
    // independently wrong regardless and other complex cards may rely on it directly).
    if (/return target .* card from (?:a|your|their)? ?graveyard to the battlefield|put target .* card from (?:a|your|their)? ?graveyard onto the battlefield/.test(text)) {
        tags.add("Reanimate");
    }

    // Sac Outlet
    if (/sacrifice a (creature|permanent|artifact|land):/.test(text)) {
        tags.add("Sac Outlet");
    }

    // Aristocrats
    if (/whenever a creature dies|whenever another creature dies|whenever you sacrifice/.test(text)) {
        tags.add("Aristocrats");
    }

    // --- OTHER MECHANICS ---

    // Modal
    if (/choose one\b|choose two\b|choose three\b|spree\b/.test(text)) {
        tags.add("Modal");
    }

    // Scry
    if (hasKeyword('scry') || /scry \d+/i.test(text)) {
        tags.add("Scry");
    }

    // Surveil
    if (hasKeyword('surveil') || /surveil \d+/i.test(text)) {
        tags.add("Surveil");
    }

    // Blink / Flicker
    if (/exile target .* then return (it|that card) to the battlefield/.test(text)) {
        tags.add("Blink");
    }

    // Lifegain
    if (/gains? (\d+\s+)?life|lifelink/.test(text)) {
        tags.add("Lifegain");
    }

    // --- PARTNER & COMPANIONS ---

    // Partner / Partner with
    if (/partner\b/i.test(text)) {
        tags.add("Partner");
    }

    // Doctor's Companion
    if (/doctor's companion/i.test(text)) {
        tags.add("Doctor's Companion");
    }

    // Companion
    if (hasKeyword('companion') || (/\bcompanion\b/i.test(text) && !/doctor's companion/i.test(text))) {
        tags.add("Companion");
    }

    // --- COMBAT & MECHANICS ---

    // Anthem (Static continuous power/toughness boost to your team). Beyond the coarse label,
    // also add compositional sub-tags (which subtype, how broad the scope is, what magnitude) so
    // category scoring can reward two cards being the SAME kind of anthem - not just both being
    // "some anthem" (project spec F: richer compositional tags, function family + parameters).
    const anthemParams = parseAnthemEffect(text);
    if (anthemParams && anthemParams.action === "stat_buff") {
        tags.add("Anthem");
        if (anthemParams.subtype && anthemParams.subtype !== "all") {
            tags.add(`Anthem:${anthemParams.subtype}`);
        }
        tags.add(`Anthem:scope-${anthemParams.isOther ? 'other' : 'all'}`);
        if (anthemParams.powerToughness) {
            tags.add(`Anthem:${anthemParams.powerToughness}`);
        }
    }

    // Pump (Temporary or target power/toughness boosts)
    if (/gets? \+\d+\/\+\d+|get \+\d+\/\+\d+/i.test(text)) {
        tags.add("Pump");
    }

    // Untap
    if (/untap (target|all|each|another|permanent|creature|land)/i.test(text) || hasKeyword('untap')) {
        tags.add("Untap");
    }

    // Extra Combat
    if (/additional combat phase|extra combat phase|after this phase, there is an additional combat/i.test(text)) {
        tags.add("Extra Combat");
    }

    // Copy (Spell copying, creature copying, token copies)
    if (/copy target|create a token that's a copy|becomes a copy|copy of target|copy that spell|copy of it/i.test(text)) {
        tags.add("Copy");
    }

    // The Ring Tempts You
    if (/the ring tempts you/i.test(text)) {
        tags.add("The Ring Tempts You");
    }

    // Living Weapon
    if (hasKeyword('living weapon') || /living weapon/i.test(text)) {
        tags.add("Living Weapon");
    }

    // Equip Cheat
    if (/attach .* to target creature|equip cost.*\{0\}|equip \{0\}|pay \{0\} rather than pay.*equip|you may pay \{0\} rather than/i.test(text)) {
        tags.add("Equip Cheat");
    }

    // --- GAME ENDERS & FINISHERS ---

    // Finisher (Broad enough for game-ending swings, targeted direct wins, and massive X drains)
    if (
        /win the game|opponents? lose the game/i.test(text) ||
        /each opponent loses x life|target player loses x life/i.test(text) ||
        /for each creature you control, .* get \+x\/\+x/i.test(text) ||
        /creatures you control get \+\d+\/\+\d+ and gain (trample|infect)/i.test(text) ||
        /gain control of all creatures .* until end of turn/i.test(text)
    ) {
        tags.add("Finisher");
    }

    // --- ADDITIONAL POPULAR COMMUNITY TAGS ---

    // Extra Turn
    if (/take an extra turn/i.test(text)) {
        tags.add("Extra Turn");
    }

    // Wheel
    if (/each player discards (their|his or her) hand|discard your hand, then draw/i.test(text)) {
        tags.add("Wheel");
    }

    // Cost Reduction
    if (/spells you cast cost \{\d+\} less|costs? \{\d+\} less to cast/i.test(text)) {
        tags.add("Cost Reduction");
    }

    // Group Hug. "players may" alone was too loose (matches plenty of non-group-hug cards with an
    // optional-action clause naming "players" for an unrelated reason); requiring "each player"
    // specifically keeps the everyone-benefits shape the tag is meant to capture.
    if (/each player (draws|gains|searches|puts|may)/i.test(text) && !/opponents?/i.test(text)) {
        tags.add("Group Hug");
    }

    // Storm
    if (hasKeyword('storm') || /\bstorm\b/i.test(text)) {
        tags.add("Storm");
    }

    // Cascade
    if (hasKeyword('cascade') || /\bcascade\b/i.test(text)) {
        tags.add("Cascade");
    }

    // Cantrip (Instants and Sorceries that draw exactly 1 card)
    if (
        (type.includes('instant') || type.includes('sorcery')) && 
        /draw a card\b/i.test(text) && 
        !/draws? (\d+|two|three|four|x) cards/i.test(text)
    ) {
        tags.add("Cantrip");
    }

    // --- TREASURE & MANA ---

    // Treasure Generation
    if (/treasure token/i.test(text)) {
        tags.add("Treasure");
    }

    // --- COMBAT & EVASION ---

    // Evasion
    if (
        hasKeyword('flying') || 
        hasKeyword('trample') || 
        hasKeyword('menace') || 
        hasKeyword('shadow') || 
        hasKeyword('horsemanship') || 
        /can't be blocked/i.test(text)
    ) {
        tags.add("Evasion");
    }

    // Infect & Toxic
    if (hasKeyword('infect') || hasKeyword('toxic') || /poison counter/i.test(text)) {
        tags.add("Infect / Toxic");
    }

    // --- TRIGGERS & ETB ---

    // ETB (Enters). Per-sentence, not against the whole blob - `.*` here previously let clause 1's
    // "whenever" pair with clause 2's unrelated "enters" on a multi-ability card.
    if (matchesAnySentence(/when(ever)? .* enters/i)) {
        tags.add("ETB");
    }

    // Death Trigger / Dies. Same cross-clause risk as ETB above.
    if (matchesAnySentence(/when(ever)? .* dies/i)) {
        tags.add("Death Trigger");
    }

    /////
    // --- LANDFALL & TRIGGERS ---
    if (/whenever a land enters/i.test(text) || hasKeyword('landfall')) {
        tags.add("Landfall");
    }

    if (/whenever you cast or copy an instant or sorcery|magecraft/i.test(text)) {
        tags.add("Spellslinger");
    }

    // --- MECHANICS & KEYWORDS ---
    if (hasKeyword('discover') || /\bdiscover \d+\b/i.test(text)) {
        tags.add("Discover");
    }

    if (hasKeyword('flashback') || hasKeyword('escape') || hasKeyword('unearth') || hasKeyword('encore') || hasKeyword('jump-start') || hasKeyword('disturb')) {
        tags.add("Graveyard Cast");
    }

    if (hasKeyword('crew') || type.includes('vehicle')) {
        tags.add("Vehicle");
    }

    if (hasKeyword('fight') || /deals damage equal to its power to target/i.test(text)) {
        tags.add("Fight");
    }

    // --- GAME STATE & EMBLEMS ---
    if (/you become the monarch/i.test(text)) {
        tags.add("Monarch");
    }

    if (/take the initiative|into the dungeon/i.test(text)) {
        tags.add("Dungeon / Initiative");
    }

    // --- DRAIN & X SPELLS ---
    if (/each opponent loses .* and you gain/i.test(text) || hasKeyword('extort')) {
        tags.add("Drain");
    }

    if (/\{x\}/i.test(card.mana_cost || '') || /\{x\}/i.test(text)) {
        tags.add("X Spells");
    }

    // --- BURN & DAMAGE MULTIPLIERS ---

    // Burn (Direct damage)
    if (/deals? (\d+|x) damage to (any target|target (player|opponent|creature|planeswalker)|each opponent|each player)/i.test(text)) {
        tags.add("Burn");
    }

    // Burn Doubler / Damage Multiplier
    if (/if a .* source would deal damage|deals double that damage|deals triple that damage|deals that much damage plus \d+/i.test(text)) {
        tags.add("Damage Multiplier");
    }

    // --- MANA & CHEATING ---

    // Mana Doubler
    if (/whenever a (land|permanent) is tapped for mana, add|adds (twice|three times) as much|it produces (twice|three times) that much|adds that much mana of any/i.test(text)) {
        tags.add("Mana Doubler");
    }

    // Free Cast / Mana Cheat
    if (/without paying its mana cost|cast it without paying/i.test(text)) {
        tags.add("Free Cast");
    }

    // --- DISCARD & FORCED COMBAT ---

    // Discard (Hand Disruption & Self-Discard)
    if (/discards? (\d+|a|an|x|two|three|four|their|your|that|all) card|discard your hand|discard a card/i.test(text)) {
        tags.add("Discard");
    }

    // Goad & Forced Combat
    if (hasKeyword('goad') || /goads? target|attacks (each|this) combat if able|attacks each turn if able/i.test(text)) {
        tags.add("Goad");
    }

    // --- CARD TYPES & SUPERTYPES ---

    // Sagas & Battles
    if (type.includes('saga')) {
        tags.add("Saga");
    }

    if (type.includes('battle')){
        tags.add("Battle");
    }

    // Planeswalker Synergies / Superfriends
    if (type.includes('planeswalker') || /loyalty counter|planeswalker/i.test(text)) {
        tags.add("Planeswalker");
    }

    // --- POLYMORPH & REPLACEMENT ---

    // Polymorph (Destroying/exiling/sacrificing/shuffling a permanent to reveal top cards into a replacement)
    if (
        /(reveal|exile|look at)s? cards from (the )?top of (your|their|a player's|his or her) library until/i.test(text) ||
        /(destroy|exile|sacrifice|shuffle|put) .* (reveals?|exiles?) cards from (the )?top of (their|your|a player's) library/i.test(text)
    ) {
        tags.add("Polymorph");
    }

    // Looting (Draw first, then discard)
    if (/draws? .* then discards?/i.test(text)) {
        tags.add("Looting");
    }

    // Rummaging (Discard first, then draw)
    if (/discards? .* then draws?/i.test(text)) {
        tags.add("Rummaging");
    }

    // Enchantress (Draw/triggers on playing or entering enchantments)
    if (/whenever you cast an enchantment spell|whenever an enchantment enters/i.test(text)) {
        tags.add("Enchantress");
    }

    // Pod / Birthing Pod (Sacrifice a permanent to search and put onto the battlefield)
    if (/sacrifice a (creature|permanent).*,? search your library for a .* card .* onto the battlefield/i.test(text)) {
        tags.add("Pod");
    }

    // Group Slug (Punishing players/opponents for standard game actions)
    if (/whenever an opponent (casts|draws|taps|plays)|whenever a land is tapped for mana, .* deals/i.test(text)) {
        tags.add("Group Slug");
    }

    // --- POLITICS & DEALS ---
    // Tightened: "if another player" and "target opponent draws" were broad enough to fire on
    // plenty of cards with nothing to do with multiplayer politics (any conditional referencing
    // another player, or a symmetrical draw effect, tripped them). "each opponent may" was
    // dropped too - that's usually an Edict-style optional sacrifice/discard, not a political deal
    // (review: tag system item 4).
    if (
        hasKeyword('assist') ||
        hasKeyword('gift') ||
        hasKeyword('friend or foe') ||
        hasKeyword('secret council') ||
        hasKeyword('council\'s dilemma') ||
        hasKeyword('will of the council') ||
        hasKeyword('tempting offer') ||
        hasKeyword('join forces') ||
        hasKeyword('parley') ||
        /vote|votes|voting|voted|villainous choice|tempting offer|tempt with|join forces|parley/i.test(text) ||
        /starting with (you|the next opponent|an opponent)|each player chooses|choose a (second|third|another) player|an opponent chooses/i.test(text) ||
        /target opponent gains control|an opponent gains control|you and that player each/i.test(text) ||
        /any player may activate|each mode must target a different player|attacks a player other than/i.test(text)
    ) {
        tags.add("Politics");
    }

    // --- POPULAR COMMUNITY TAGS ---

    // +1/+1 Counters
    if (/\+1\/\+1 counter/i.test(text) || hasKeyword('proliferate') || hasKeyword('adapt') || hasKeyword('evolve') || hasKeyword('graft')) {
        tags.add("+1/+1 Counters");
    }

    // Pillowfort (Deterring attacks against you)
    if (/can't attack you|attack you or planeswalkers you control unless|whenever a creature attacks you|for each creature attacking you/i.test(text)) {
        tags.add("Pillowfort");
    }

    // Equipment & Auras (Voltron support)
    if (type.includes('equipment') || type.includes('aura') || /equipped creature|enchanted creature|attach target (equipment|aura)/i.test(text)) {
        tags.add("Equipment / Auras");
    }

    // Chaos & Coin Flips
    if (/flip .* coin|flips? a coin|at random|chaos ensues/i.test(text)) {
        tags.add("Chaos");
    }

    // Generic keyword coverage: Magic has 100+ official keyword abilities and ships new ones
    // every set (Convoke, Delve, Kicker, Riot, Mentor, Exert, Bestow, Outlast, Rebound, Suspend,
    // Splice, Overload, Buyback, Madness, Miracle, Blitz, Backup, Offspring, Plot, Bargain,
    // Freerunning...). Hand-writing an `if (hasKeyword('x'))` line per keyword above means any
    // keyword nobody explicitly checked for gets zero tag, and that list is stale the day a new
    // set ships. Read Scryfall's own `keywords` array directly instead - every keyword ability the
    // card actually has becomes a tag with no per-keyword code needed, so coverage is
    // self-updating (review: tag system item 1). This is purely additive: title-cased to match
    // the existing named tags' style, so a keyword already handled above (e.g. "flying" ->
    // "Flying") lands on the exact same tag string and the Set simply dedupes it - it never
    // creates a same-keyword-different-casing near-duplicate.
    (card.keywords || []).forEach(kw => {
        if (kw) tags.add(toTitleCase(kw));
    });

    // Retain custom tags matching text or type line. Word-boundary matched, not a raw substring
    // check - a custom tag like "war" previously matched "reward," "warrior," and "toward" since
    // `text.includes(tag)` has no concept of word edges (review: tag system item 6).
    currentTags.forEach(ut => {
        const utLower = ut.toLowerCase();
        const wordBoundaryRegex = new RegExp(`\\b${utLower.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'i');
        if (wordBoundaryRegex.test(text) || wordBoundaryRegex.test(type)) {
            tags.add(ut);
        }
    });

    // --- FUNCTION-DERIVED TAGS (canonical, wording-independent) ---
    // Every tag above is regex/keyword-matched against literal Oracle wording - exactly as
    // brittle to rewording as the rest of the engine is designed NOT to be. The rule parser
    // already derives a canonical function (reanimate, removal, counter, direct_damage...) for
    // scoring, so cards that read nothing alike but do the same thing can share this signal even
    // when neither side's literal wording tripped a regex above.
    //
    // This used to just dump `cf.function.replace(/_/g,' ')` in as a fresh lowercase tag - which
    // meant a card whose text matched, say, the "Reanimate" regex above got BOTH "Reanimate" (from
    // the regex) AND "reanimate" (from this layer) as two separate, case-distinct Set entries:
    // visible clutter in the UI, double-counted weight in category scoring, and no actual
    // reconciliation between the parser's and the regex's independent judgments - exactly the
    // "two competing implementations that can quietly disagree, with nothing surfacing it" problem
    // (review: tag system item 2). CANONICAL_FUNCTION_TAG_NAMES below maps every canonical
    // function to the SAME tag name its hand-written regex counterpart already uses, so the two
    // signals land on one Set entry - which also means a card the regex missed but the parser
    // caught now correctly gets that tag (recall improves), and a function with no hand-tag
    // counterpart still gets a sensible, properly-cased fallback name instead of a bare
    // underscore-stripped function identifier.
    const rawTextForParsing = card.oracle_text || (card.card_faces ? card.card_faces.map(f => f.oracle_text).join(' ') : '');
    const parsedForTags = card._parsedEffects || (rawTextForParsing ? parseMTGEffect(rawTextForParsing) : null);
    // Tag derivation deliberately excludes isSecondaryAtom/isCostEffect entries: those come from
    // extractClauseAtoms re-scanning from each verb's raw text position rather than the clause's
    // own full context (built for multi-effect scoring, not tagging), and can mis-derive a
    // canonical function - e.g. "search for a land, put it onto the battlefield tapped" produced
    // a spurious "cheat_into_play" atom from the word "put" in isolation, on a card that's really
    // just Ramp. The clause-level parse (the effect the sub-parser chain actually matched for that
    // whole clause) is a stable enough signal for a tag; the secondary/cost atoms are not.
    const canonicalFns = getCanonicalFunctions((parsedForTags || []).filter(e => !e.isSecondaryAtom && !e.isCostEffect));

    canonicalFns.forEach(cf => {
        const mappedName = CANONICAL_FUNCTION_TAG_NAMES[cf.function];
        // ramp_tutor and place_counter are both fully handled by the compositional block below
        // (Ramp vs. Land Fetcher depends on destination; +1/+1 vs -1/-1 Counters depends on
        // counterType), so both deliberately have no flat mapping and must not also fall through
        // to a generic "Ramp Tutor"/"Place Counter" tag here.
        if (mappedName) {
            addTagCaseInsensitive(tags, mappedName);
        } else if (cf.function !== 'ramp_tutor' && cf.function !== 'place_counter') {
            addTagCaseInsensitive(tags, toTitleCase(cf.function.replace(/_/g, ' ')));
        }

        // Compositional sub-tags derived straight from the canonical function's own params,
        // extending the same pattern already used for Anthem/Token/Removal to two more families
        // now that the damage and mana parsers exist to support them (review: tag system item 5).
        if (cf.function === 'removal' || cf.function === 'exile_removal' || cf.function === 'direct_damage') {
            const method = cf.function === 'exile_removal' ? 'exile' : cf.function === 'direct_damage' ? 'damage' : 'destroy';
            tags.add(`Removal:${method}`);
            const p = cf.params || {};
            if (p.target === 'all' || p.target === 'each') {
                addTagCaseInsensitive(tags, 'Boardwipe');
            }
        }
        if (cf.function === 'mana_ability') {
            const rampMethod = type.includes('creature') ? 'dork'
                : type.includes('artifact') ? 'rock'
                : (type.includes('instant') || type.includes('sorcery')) ? 'ritual'
                : null;
            addTagCaseInsensitive(tags, 'Ramp');
            if (rampMethod) tags.add(`Ramp:${rampMethod}`);
        }
        if (cf.function === 'ramp_tutor') {
            // A land tutor that lands on the battlefield is ramp (extra mana this turn); one that
            // goes to hand/library/exile is card selection for a land drop later, not
            // acceleration - the existing hand-written tags already draw exactly this line, so
            // the canonical-function path respects it too instead of collapsing both into one tag.
            if ((cf.params || {}).to === 'battlefield') {
                addTagCaseInsensitive(tags, 'Ramp');
                tags.add('Ramp:land');
            } else {
                addTagCaseInsensitive(tags, 'Land Fetcher');
            }
        }
        if (cf.function === 'place_counter') {
            // "+1/+1 Counters" already exists as a hand tag for the counters-matter archetype -
            // reused here for the +1/+1 case specifically. A -1/-1 counter is a debuff/removal-
            // adjacent effect (closer in spirit to a pump-down or -X/-X effect than to the
            // tribal counters archetype), so it gets its own distinct tag rather than being
            // folded into the same one.
            const magnitude = (cf.params || {}).magnitude || '';
            addTagCaseInsensitive(tags, magnitude.includes('-1/-1') ? '-1/-1 Counters' : '+1/+1 Counters');
        }
    });

    return Array.from(tags);
}

function renderTags() {
    const container = document.getElementById('card-tags-list');
    container.innerHTML = '';
    activeTags.forEach(tag => {
        const chip = document.createElement('div');
        chip.className = 'card-chip';

        const label = document.createElement('span');
        label.textContent = tag;

        const removeBtn = document.createElement('span');
        removeBtn.className = 'card-chip-remove';
        removeBtn.textContent = '\u00D7';
        removeBtn.addEventListener('click', () => removeTag(tag));

        chip.appendChild(label);
        chip.appendChild(removeBtn);
        container.appendChild(chip);
    });
}

function removeTag(tagToRemove) {
    activeTags = activeTags.filter(tag => tag.toLowerCase() !== tagToRemove.toLowerCase());
    renderTags();
}

/**
 * Re-wraps every currently-active highlight in the oracle text display, starting from the
 * untouched original HTML (sourceCardOracle.dataset.originalHtml) each time rather than the
 * currently-displayed (already-wrapped) HTML - otherwise removing or re-adding one highlight
 * while others are active would compound stale <strong> wrappers instead of cleanly reflecting
 * the current set.
 *
 * Match positions for every highlight are found against the SAME untouched original text (not
 * against a string other highlights have already wrapped), and overlapping ranges are resolved
 * by claiming longest-highlight-text matches first, before any wrapping happens. Wrapping is
 * done in a single final pass over the resolved ranges. This matters because the previous
 * implementation applied one highlight's regex, then ran the next highlight's regex against the
 * RESULT (now containing that first highlight's <strong> tag) - if two highlights' text
 * overlapped or sat adjacent to each other, the inserted tag could break the plain-text run the
 * next regex needed to match, silently failing to re-apply it or matching an unintended
 * occurrence elsewhere in the text instead.
 */
function escapeHtmlText(text) {
    return String(text ?? '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

function reapplyOracleHighlights() {
    if (!sourceCardOracle) return;

    // Highlight offsets are text offsets, not HTML offsets.  Reconstructing markup by slicing
    // innerHTML is incorrect for characters that are represented as entities (&, <, >, etc.),
    // and it also used to ignore a highlight's recorded start/end position and highlight every
    // occurrence of the same phrase.  Keep one canonical plain-text representation instead.
    const originalText = sourceCardOracle.dataset.originalText ?? sourceCardOracle.textContent ?? '';
    const ranges = [];

    for (const h of manualHighlights) {
        if (!h || !h.text || h.field === 'type') continue;

        // User-authored additions are search-intent tags, not selections from the source
        // Oracle text. They must participate in search/scoring, but should never be rendered as
        // if the same words had been highlighted on the source card.
        if (h.origin === 'user') continue;

        let start = Number.isFinite(h.start) ? h.start : -1;
        let end = Number.isFinite(h.end) ? h.end : -1;

        // Backward-compatible fallback for older highlight objects that did not retain offsets.
        if (start < 0 || end <= start || originalText.slice(start, end).toLowerCase() !== h.text.toLowerCase()) {
            const fallback = originalText.toLowerCase().indexOf(h.text.toLowerCase());
            if (fallback < 0) continue;
            start = fallback;
            end = fallback + h.text.length;
        }

        start = Math.max(0, Math.min(start, originalText.length));
        end = Math.max(start, Math.min(end, originalText.length));
        if (end > start) ranges.push({ start, end, mode: h.mode, colorIndex: Number.isInteger(h.colorIndex) ? h.colorIndex % 4 : 0 });
    }

    // Resolve overlaps deterministically.  A user selection's stored position wins; when two
    // highlights overlap, prefer the longer range, then the earlier range in the source text.
    ranges.sort((a, b) => (b.end - b.start) - (a.end - a.start) || a.start - b.start);
    const claimed = [];
    for (const range of ranges) {
        if (claimed.some(r => range.start < r.end && range.end > r.start)) continue;
        claimed.push(range);
    }
    claimed.sort((a, b) => a.start - b.start);

    let html = '';
    let cursor = 0;
    for (const range of claimed) {
        html += escapeHtmlText(originalText.slice(cursor, range.start));
        const modeClass = ({ variable: 'highlight-variable', exact: 'highlight-exact', context: 'highlight-context', avoid: 'highlight-avoid' })[range.mode] || 'highlight-exact';
        html += `<strong class="highlight-active ${modeClass} highlight-color-${range.colorIndex}">${escapeHtmlText(originalText.slice(range.start, range.end))}</strong>`;
        cursor = range.end;
    }
    html += escapeHtmlText(originalText.slice(cursor));
    sourceCardOracle.innerHTML = html;
}

/**
 * Captures a completed Oracle-text selection and records its exact text offsets so the same
 * occurrence can be re-rendered without accidentally highlighting every matching phrase.
 */
function notifyManaSearchHighlightsChanged() {
    window.dispatchEvent(new CustomEvent('manasearch:source-highlights-changed', {
        detail: { highlights: manualHighlights.map(h => ({ text: h.text, mode: h.mode, field: h.field, origin: h.origin })) }
    }));
}

function findDependentOracleContext(sourceText, start, end) {
    const text = String(sourceText || '');
    if (!Number.isFinite(start) || !Number.isFinite(end) || end <= start || end > text.length) return null;
    const bounds = (position) => {
        let left = 0, right = text.length;
        for (let i = position - 1; i >= 0; i--) if (/[.!?;\n]/.test(text[i])) { left = i + 1; break; }
        for (let i = position; i < text.length; i++) if (/[.!?;\n]/.test(text[i])) { right = i + 1; break; }
        return { start: left, end: right, text: text.slice(left, right).trim() };
    };
    const selected = bounds(start), selectedLast = bounds(Math.max(start, end - 1));
    const selectedText = text.slice(selected.start, selectedLast.end).trim();
    const candidates = [];
    const consider = (left, right) => {
        const clause = text.slice(left, right).trim();
        if (!clause || (left < end && right > start)) return;
        const followup = /^(?:then\b|if you do\b|if you don'?t\b|that player\b|they do\b|you may\b|you can\b|this way\b|for each\b|repeat this process\b|until\b)/i.test(clause);
        const governing = /(?:whenever|when|at the beginning of|at the end of|if |after |before |as .* enters|each time|the next time)\b/i.test(clause) &&
            /^(?:you|target player|target opponent|that player|each opponent|each player|then|if you|draw|create|exile|return|put|deal|gain|lose)\b/i.test(selectedText);
        if (followup || governing) candidates.push({ start: left, end: right, text: clause });
    };
    if (selected.start > 0) {
        let left = 0;
        for (let i = selected.start - 2; i >= 0; i--) if (/[.!?;\n]/.test(text[i])) { left = i + 1; break; }
        consider(left, selected.start);
    }
    if (selectedLast.end < text.length) {
        let right = text.length;
        for (let i = selectedLast.end; i < text.length; i++) if (/[.!?;\n]/.test(text[i])) { right = i + 1; break; }
        consider(selectedLast.end, right);
    }
    return candidates.length === 1 ? candidates[0] : null;
}

function handleSourceTextSelection(root = sourceCardOracle, field = 'oracle') {
    if (!root) return;
    const selection = window.getSelection?.();
    if (!selection || selection.rangeCount === 0) return;
    const range = selection.getRangeAt(0);
    if (!root.contains(range.commonAncestorContainer)) return;
    const selectedText = selection.toString().trim();
    if (!selectedText) return;

    const segment = ['supertype', 'type', 'subtype'].includes(field) ? field : null;
    const canonicalField = segment ? 'type' : 'oracle';
    const originalText = root.dataset.originalText ?? (root.textContent === 'None' ? '' : root.textContent) ?? '';
    if (!originalText) return;
    if (!root.dataset.originalText) root.dataset.originalText = originalText;
    const offsets = normalizeHighlightSelectionOffsets(root, range);
    const trimmed = offsets
        ? trimHighlightRangeText(selectedText, offsets.start, offsets.end)
        : { text: selectedText, start: null, end: null };
    if (!trimmed.text) return;

    const existingIndex = manualHighlights.findIndex(h => h.field === canonicalField &&
        String(h.text || '').toLowerCase() === trimmed.text.toLowerCase() &&
        (canonicalField === 'type'
            ? (h.typeSegment || 'type') === segment && Number.isFinite(h.typeStart) && h.typeStart === trimmed.start && h.typeEnd === trimmed.end
            : Number.isFinite(h.start) && h.start === trimmed.start && h.end === trimmed.end));
    if (existingIndex >= 0) {
        removeHighlight(existingIndex);
    } else {
        const highlight = {
            text: trimmed.text, mode: canonicalField === 'type' ? 'exact' : (['variable', 'exact', 'context', 'avoid'].includes(displayPreferences?.highlightDefaultMode) ? displayPreferences.highlightDefaultMode : 'variable'), origin: 'source', field: canonicalField,
            colorIndex: nextHighlightColorIndex++ % 4, attachedTo: null
        };
        if (canonicalField === 'type') {
            highlight.typeSegment = segment || 'type';
            highlight.typeStart = trimmed.start;
            highlight.typeEnd = trimmed.end;
        } else {
            highlight.start = trimmed.start;
            highlight.end = trimmed.end;
        }
        manualHighlights.push(highlight);
        // Preserve a clearly dependent adjacent sentence as context-only, never as a hard match.
        if (canonicalField === 'oracle' && Number.isFinite(trimmed.start) && Number.isFinite(trimmed.end)) {
            const dependent = findDependentOracleContext(originalText, trimmed.start, trimmed.end);
            if (dependent && !manualHighlights.some(h => h.field === 'oracle' && h.start === dependent.start && h.end === dependent.end)) {
                manualHighlights.push({ text: dependent.text, mode: 'context', origin: 'auto-context', field: 'oracle',
                    start: dependent.start, end: dependent.end, attachedTo: manualHighlights.length - 1,
                    colorIndex: nextHighlightColorIndex++ % 4, inferredRelationship: 'adjacent-dependent-sentence' });
            }
        }
        reapplyOracleHighlights();
        reapplyTypeLineHighlights();
        renderHighlightChips();
    }
    selection.removeAllRanges();
    notifyManaSearchHighlightsChanged();
}

function handleOracleTextSelection() {
    return handleSourceTextSelection(sourceCardOracle, 'oracle');
}

function reapplyTypeLineHighlights() {
    const parts = [
        { id: 'source-card-supertype', key: 'supertype' },
        { id: 'source-card-type', key: 'type' },
        { id: 'source-card-subtype', key: 'subtype' }
    ];
    for (const part of parts) {
        const root = document.getElementById(part.id);
        if (!root) continue;
        const text = root.dataset.originalText ?? (root.textContent === 'None' ? '' : root.textContent) ?? '';
        if (!text) { root.textContent = 'None'; continue; }
        const ranges = manualHighlights
            .filter(h => h?.field === 'type' && (h.typeSegment || 'type') === part.key && Number.isFinite(h.typeStart) && Number.isFinite(h.typeEnd) && h.typeEnd > h.typeStart)
            .map(h => ({ start: h.typeStart, end: h.typeEnd, colorIndex: Number.isInteger(h.colorIndex) ? h.colorIndex % 4 : 0 }))
            .filter(range => text.slice(range.start, range.end));
        ranges.sort((a, b) => (b.end - b.start) - (a.end - a.start) || a.start - b.start);
        const claimed = [];
        for (const range of ranges) if (!claimed.some(existing => range.start < existing.end && range.end > existing.start)) claimed.push(range);
        claimed.sort((a, b) => a.start - b.start);
        let cursor = 0, html = '';
        for (const range of claimed) {
            html += escapeHtmlText(text.slice(cursor, range.start));
            html += `<strong class="highlight-active highlight-type highlight-color-${range.colorIndex}">${escapeHtmlText(text.slice(range.start, range.end))}</strong>`;
            cursor = range.end;
        }
        html += escapeHtmlText(text.slice(cursor));
        root.innerHTML = html;
    }
}


/**
 * Renders the highlight chip list beneath the oracle text - one chip per active highlight, each
 * with a mode-toggle button (exact/required vs. variable/flexible) and a remove button, mirroring
 * the existing tag-chip pattern (renderTags/removeTag above).
 */
function findHighlightRangeInSource(text, preferredStart = null) {
    const sourceText = getCurrentSourceOracleText();
    const needle = String(text || '').trim();
    if (!sourceText || !needle) return null;
    const hay = sourceText.toLowerCase();
    const lowNeedle = needle.toLowerCase();
    const matches = [];
    let from = 0;
    while (from < hay.length) {
        const idx = hay.indexOf(lowNeedle, from);
        if (idx < 0) break;
        matches.push({ start: idx, end: idx + needle.length });
        from = idx + Math.max(1, needle.length);
    }
    if (!matches.length) return null;
    if (!Number.isFinite(preferredStart)) return matches[0];
    return matches.reduce((best, item) =>
        Math.abs(item.start - preferredStart) < Math.abs(best.start - preferredStart) ? item : best,
        matches[0]
    );
}

function highlightParentOptions(excludeIndex = null) {
    return manualHighlights
        .map((h, idx) => ({ h, idx }))
        .filter(({ h, idx }) => idx !== excludeIndex && h && (h.origin !== 'user' || Boolean(h.editedFrom)) && typeof h.text === 'string' && h.text.trim());
}

function getHighlightParentLabel(index) {
    const parent = manualHighlights[index];
    if (!parent) return 'Independent';
    const text = String(parent.text || '').trim();
    return text.length > 34 ? text.slice(0, 31) + '\u2026' : text;
}

// Structured highlight aspects are opt-in. Missing/auto values deliberately preserve legacy ranking.
function normalizeHighlightAspects(aspects) {
    const mana = aspects?.mana || {};
    const quantity = aspects?.quantity || {};
    const validAmount = value => ({
        rule: ['auto','exact','at_least','at_most','any'].includes(value?.rule) ? value.rule : 'auto',
        value: Number.isFinite(Number(value?.value)) && value?.value !== null ? Number(value.value) : null
    });
    const validColor = value => ({
        rule: ['auto','same','specific','any_colored','any'].includes(value?.rule) ? value.rule : 'auto',
        colors: Array.isArray(value?.colors) ? [...new Set(value.colors.map(c => String(c).toLowerCase()).filter(c => ['w','u','b','r','g','c'].includes(c)))] : []
    });
    return {
        mana: { amount: validAmount(mana.amount), color: validColor(mana.color), activation: { rule: ['auto','free','any'].includes(mana.activation?.rule) ? mana.activation.rule : 'auto' }, fullRun: Boolean(mana.fullRun) },
        quantity: { amount: validAmount(quantity.amount) }
    };
}
function hasActiveHighlightAspects(aspects) {
    const a = normalizeHighlightAspects(aspects);
    return a.mana.amount.rule !== 'auto' || a.mana.color.rule !== 'auto' || a.mana.activation.rule !== 'auto' || a.quantity.amount.rule !== 'auto' || a.mana.fullRun;
}
function deriveHighlightAspectKind(highlight, sourceText = getCurrentSourceOracleText()) {
    const text = String(highlight?.text || '').trim();
    const clause = getHighlightSourceClauseInfo(highlight, sourceText)?.clauseText || text;
    const manaContext = /\badd\b[^.!?;]{0,100}(?:mana|\{[wubrgcs]\})/i.test(clause) || /\{[wubrgcs]\}/i.test(text);
    const selectedSymbols = text.match(/\{[wubrgc]\}/gi) || [];
    const clauseSymbols = String(clause || '').match(/\{[wubrgc]\}/gi) || [];
    const useFullRun = Boolean(highlight?.aspects?.mana?.fullRun) && selectedSymbols.length === 1 && clauseSymbols.length > 1;
    const symbols = useFullRun ? clauseSymbols : selectedSymbols;
    const number = text.match(/^\s*(\d+)\s*$/);
    const quantityContext = QUANTITATIVE_MECHANIC_FUNCTIONS instanceof Set && [...QUANTITATIVE_MECHANIC_FUNCTIONS].some(fn => fn) && /\b(?:damage|life|draw|cards?|counters?|tokens?|mill|discard)\b/i.test(clause);
    if (manaContext) return { kind: 'mana', amount: symbols.length ? symbols.length : (number ? Number(number[1]) : null), colors: [...new Set(symbols.map(x => x.slice(1,-1).toLowerCase()))], clause };
    if (number && quantityContext) return { kind: 'quantity', amount: Number(number[1]), colors: [], clause };
    if (quantityContext && /\b\d+\b/.test(text)) return { kind: 'quantity', amount: Number(text.match(/\d+/)[0]), colors: [], clause };
    return null;
}
function getHighlightAspectCandidateEffects(card, kind) {
    const oracle = getCardOracleText(card);
    const parsed = parseMTGEffect(oracle);
    if (kind === 'mana') return parsed.filter(e => e && (e.canonical?.function === 'mana_ability' || e.action === 'add_mana' || e.manaOutputAmount != null || e.canonical?.params?.manaOutputAmount != null));
    return parsed.filter(e => e && (QUANTITATIVE_MECHANIC_FUNCTIONS.has(String(e.canonical?.function || e.action || ''))));
}
function getAspectCandidateAmount(effect) {
    const params = effect?.canonical?.params || effect?.params || {};
    for (const value of [effect?.manaNetAmount, params.manaNetAmount, effect?.manaOutputAmount, params.manaOutputAmount, effect?.quantity, params.quantity, effect?.amount, params.amount, effect?.canonical?.quantity]) {
        if (value !== null && value !== undefined && Number.isFinite(Number(value))) return Number(value);
    }
    const raw = String(effect?.raw || effect?.contextClause || '');
    const m = raw.match(/\b(?:add|deals?|deal|draw|discard|mill|create|put|gets?)\s+(\d+)\b/i);
    return m ? Number(m[1]) : null;
}
function getAspectCandidateColors(effect) {
    const params = effect?.canonical?.params || effect?.params || {};
    const raw = String(effect?.raw || effect?.contextClause || '');
    const rawColors = params.manaOutputColors || effect?.manaOutputColors || effect?.colors || [];
    const colorList = Array.isArray(rawColors) ? rawColors : (typeof rawColors === 'string' ? rawColors.split(/[\s,/]+/) : []);
    const colors = new Set(colorList.map(c => String(c).toLowerCase().replace('colorless','c')).filter(c => ['w','u','b','r','g','c'].includes(c)));
    ['w','u','b','r','g','c'].forEach(c => { if (new RegExp('\\{'+c+'\\}', 'i').test(raw)) colors.add(c); });
    if (/any (?:one )?(?:color|type)/i.test(raw)) ['w','u','b','r','g'].forEach(c => colors.add(c));
    return colors;
}
function highlightAspectEffectMatches(highlight, card, kind = null) {
    const derived = deriveHighlightAspectKind(highlight);
    kind = kind || derived?.kind;
    const implicitAtomicMana = kind === 'mana' && !highlight.aspects && /^(?:\s*\{[wubrgc]\}\s*)+$/i.test(String(highlight.text || ''));
    if (!kind || (!hasActiveHighlightAspects(highlight?.aspects) && !implicitAtomicMana)) return { applies: false, matches: true, score: 1, reason: '' };
    const aspects = normalizeHighlightAspects(highlight.aspects);
    if (kind === 'mana' && aspects.mana.fullRun && derived) {
        aspects.mana.amount = { rule: 'exact', value: derived.amount };
        aspects.mana.color = { rule: 'same', colors: derived.colors };
    }
    // A pure symbol selection is itself a value request: one selected {C} means one colorless mana.
    // Legacy highlights containing no such atomic selection remain untouched.
    if (kind === 'mana' && !highlight.aspects && (String(highlight.text || '').match(/\{[wubrgc]\}/gi) || []).length) {
        aspects.mana.amount = { rule: 'exact', value: derived?.amount ?? null };
        aspects.mana.color = { rule: 'same', colors: derived?.colors || [] };
    }
    const effects = getHighlightAspectCandidateEffects(card, kind);
    if (!effects.length) return { applies: true, matches: false, score: 0, reason: `No matching ${kind} effect was parsed` };
    let best = { applies: true, matches: false, score: 0, reason: '' };
    for (const effect of effects) {
        let matches = true, score = 1, reason = '';
        const amountRule = kind === 'mana' ? aspects.mana.amount : aspects.quantity.amount;
        const amount = getAspectCandidateAmount(effect);
        if (amountRule.rule !== 'auto' && amountRule.rule !== 'any') {
            const target = amountRule.value ?? (derived?.amount ?? null);
            if (amount === null) {
                matches = false;
                score *= 0.18;
                reason = 'Candidate effect quantity is unknown';
            } else if (target !== null) {
                if (amountRule.rule === 'exact') matches = amount === target;
                else if (amountRule.rule === 'at_least') matches = amount >= target;
                else if (amountRule.rule === 'at_most') matches = amount <= target;
                score *= matches ? 1 : 0.18;
                if (!matches) reason = `Amount ${amount} does not satisfy ${amountRule.rule} ${target}`;
            }
        }
        if (kind === 'mana') {
            const colorRule = aspects.mana.color;
            if (colorRule.rule !== 'auto' && colorRule.rule !== 'any') {
                const colors = getAspectCandidateColors(effect);
                const wanted = new Set(colorRule.rule === 'same' ? (derived?.colors || []) : colorRule.colors);
                if (colorRule.rule === 'any_colored') {
                    const colored = ['w','u','b','r','g'].some(c => colors.has(c)) || /any (?:one )?(?:color|type)/i.test(String(effect.raw || ''));
                    matches = matches && colored;
                    score *= colored ? 1 : 0.12;
                    if (!colored) reason = 'Does not produce colored mana';
                } else if (wanted.size) {
                    const includes = [...wanted].every(c => colors.has(c));
                    const same = colorRule.rule !== 'same' || (includes && colors.size === wanted.size);
                    matches = matches && includes && same;
                    score *= includes && same ? 1 : 0.12;
                    if (!(includes && same)) reason = `Mana colors do not match ${[...wanted].join(', ')}`;
                }
            }
            const activationRule = aspects.mana.activation.rule;
            if (activationRule === 'free') {
                const raw = String(effect.raw || effect.contextClause || '');
                const tapOnly = /\{t\}\s*:/i.test(raw) && !/\{(?!t\})[^}]+\}/i.test(raw.replace(/\{t\}/ig, ''));
                matches = matches && tapOnly;
                score *= tapOnly ? 1 : 0.15;
                if (!tapOnly) reason = 'Activation requires more than tapping';
            }
        }
        if (matches) return { applies: true, matches: true, score, reason: '' };
        if (score > best.score) best = { applies: true, matches: false, score, reason };
    }
    return best;
}

function buildHighlightAspectPreview(highlight, detected = deriveHighlightAspectKind(highlight)) {
    if (!detected) return '';
    const a = normalizeHighlightAspects(highlight?.aspects);
    if (detected.kind === 'mana') {
        const amount = a.mana.amount.rule === 'auto' ? (detected.amount == null ? 'a' : `exactly ${detected.amount}`) : a.mana.amount.rule === 'any' ? 'any amount' : `${a.mana.amount.rule.replace('_',' ')} ${a.mana.amount.value ?? detected.amount ?? 'N'}`;
        const colors = a.mana.color.rule === 'same' ? (detected.colors.includes('c') ? 'colorless' : detected.colors.map(c=>c.toUpperCase()).join('/') || 'same colors') : a.mana.color.rule === 'specific' ? a.mana.color.colors.map(c=>c==='c'?'colorless':c.toUpperCase()).join('/') : a.mana.color.rule === 'any_colored' ? 'colored' : a.mana.color.rule === 'any' ? 'any color' : 'mana';
        return `Looking for: ${String(amount).replace('exactly exactly','exactly')} ${colors} mana.`;
    }
    return `Looking for: ${a.quantity.amount.rule === 'auto' ? `the selected ${detected.amount ?? 'quantity'}` : a.quantity.amount.rule === 'any' ? 'any amount' : `${a.quantity.amount.rule.replace('_',' ')} ${a.quantity.amount.value ?? detected.amount ?? 'N'}`} in a similar effect.`;
}

function renderHighlightEditor(idx) {
    if (highlightEditIndex !== idx || !manualHighlights[idx]) return null;
    const h = manualHighlights[idx];
    const editor = document.createElement('div');
    editor.className = 'highlight-edit-composer';
    editor.setAttribute('role', 'group');
    editor.setAttribute('aria-label', 'Edit highlighted search detail');

    const title = document.createElement('div');
    title.className = 'highlight-edit-title';
    title.textContent = h.origin === 'user' ? 'Edit search detail' : 'Edit highlight';

    const textLabel = document.createElement('label');
    textLabel.className = 'highlight-edit-label';
    textLabel.textContent = h.origin === 'user' ? 'Search detail' : 'Highlighted text';

    const input = document.createElement('textarea');
    input.className = 'highlight-edit-input';
    input.rows = 2;
    input.maxLength = 300;
    input.value = String(h.text || '');
    input.setAttribute('aria-label', textLabel.textContent);

    const modeRow = document.createElement('div');
    modeRow.className = 'highlight-edit-row';
    const modeLabel = document.createElement('span');
    modeLabel.className = 'highlight-edit-label-inline';
    modeLabel.textContent = 'Match:';
    modeRow.appendChild(modeLabel);

    let selectedMode = ['variable', 'exact', 'context', 'avoid'].includes(h.mode) ? h.mode : 'exact';
    const makeModeButton = (mode, label, titleText) => {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = `highlight-composer-mode ${mode === selectedMode ? 'selected' : ''}`;
        btn.textContent = label;
        btn.title = titleText;
        btn.addEventListener('click', () => {
            selectedMode = mode;
            modeRow.querySelectorAll('.highlight-composer-mode').forEach(b => b.classList.remove('selected'));
            btn.classList.add('selected');
        });
        return btn;
    };
    modeRow.appendChild(makeModeButton('variable', '≈ Flexible', 'Prefer similar mechanics; wording and values may differ.'));
    modeRow.appendChild(makeModeButton('exact', '= Exact', 'Require this wording to occur in the matching card.'));
    modeRow.appendChild(makeModeButton('context', 'Context only', 'Use this text to understand nearby effects, without making it a requirement.'));
    modeRow.appendChild(makeModeButton('avoid', 'Avoid', 'Prefer cards that do not match this effect or wording.'));
 
    const detectedAspect = deriveHighlightAspectKind(h);
    let aspectControls = null;
    if (detectedAspect) {
        aspectControls = document.createElement('div');
        aspectControls.className = 'highlight-aspects';
        aspectControls.setAttribute('role', 'group');
        aspectControls.setAttribute('aria-label', 'What matters about this highlight');
        const heading = document.createElement('div');
        heading.className = 'highlight-edit-label';
        heading.textContent = 'What matters?';
        aspectControls.appendChild(heading);
        const current = normalizeHighlightAspects(h.aspects);
        if (detectedAspect.kind === 'mana' && (String(h.text || '').match(/\{[wubrgc]\}/gi) || []).length === 1 && (String(detectedAspect.clause || '').match(/\{[wubrgc]\}/gi) || []).length > 1) {
            const fullRunLabel = document.createElement('label'); fullRunLabel.className = 'highlight-aspect-color';
            const fullRun = document.createElement('input'); fullRun.type = 'checkbox'; fullRun.checked = current.mana.fullRun; fullRun.setAttribute('aria-label','Use the whole mana output');
            fullRun.addEventListener('change', () => { const next = normalizeHighlightAspects(h.aspects); next.mana.fullRun = fullRun.checked; h.aspects = next; renderHighlightChips(); });
            fullRunLabel.append(fullRun, document.createTextNode('Use whole mana output instead of just the selected symbol'));
            aspectControls.appendChild(fullRunLabel);
        }
        const addSelect = (labelText, options, value, onChange) => {
            const row = document.createElement('label'); row.className = 'highlight-aspect-row';
            const label = document.createElement('span'); label.textContent = labelText; row.appendChild(label);
            const select = document.createElement('select'); select.className = 'highlight-edit-select'; select.setAttribute('aria-label', labelText);
            options.forEach(([v, text]) => { const opt = document.createElement('option'); opt.value = v; opt.textContent = text; select.appendChild(opt); });
            select.value = value; select.addEventListener('change', () => { onChange(select.value); }); row.appendChild(select); aspectControls.appendChild(row); return select;
        };
        const updateAspect = (path, value) => {
            const next = normalizeHighlightAspects(h.aspects);
            if (path === 'mana.amount.rule') next.mana.amount.rule = value;
            if (path === 'mana.color.rule') next.mana.color.rule = value;
            if (path === 'mana.activation.rule') next.mana.activation.rule = value;
            if (path === 'quantity.amount.rule') next.quantity.amount.rule = value;
            h.aspects = next;
            renderHighlightChips();
        };
        const amountOptions = [['auto','Let ManaSearch decide'],['exact','Exactly N'],['at_least','At least N'],['at_most','At most N'],['any','Any amount']];
        if (detectedAspect.kind === 'mana') {
            addSelect('Amount', amountOptions, current.mana.amount.rule, v => updateAspect('mana.amount.rule',v));
            addSelect('Color', [['auto','Let ManaSearch decide'],['same','Same as highlighted'],['specific','Specific colors'],['any_colored','Any colored mana'],['any','Anything']], current.mana.color.rule, v => updateAspect('mana.color.rule',v));
            if (current.mana.color.rule === 'specific') {
                const chips = document.createElement('div'); chips.className = 'highlight-aspect-colors'; chips.setAttribute('aria-label','Choose mana colors');
                ['w','u','b','r','g','c'].forEach(color => { const label = document.createElement('label'); label.className = 'highlight-aspect-color'; const cb = document.createElement('input'); cb.type='checkbox'; cb.checked=current.mana.color.colors.includes(color); cb.setAttribute('aria-label',`Include ${color.toUpperCase()} mana`); cb.addEventListener('change',()=>{const next=normalizeHighlightAspects(h.aspects);next.mana.color.colors=cb.checked?[...new Set([...next.mana.color.colors,color])]:next.mana.color.colors.filter(c=>c!==color);h.aspects=next;preview.textContent=buildHighlightAspectPreview(h,detectedAspect);}); label.append(cb,document.createTextNode(color.toUpperCase())); chips.appendChild(label); }); aspectControls.appendChild(chips);
            }
            addSelect('Activation', [['auto','Let ManaSearch decide'],['free','Only {T} (no extra cost)'],['any',"Don't care"]], current.mana.activation.rule, v => updateAspect('mana.activation.rule',v));
        } else addSelect('Amount', amountOptions, current.quantity.amount.rule, v => updateAspect('quantity.amount.rule',v));
        const activeAmount = detectedAspect.kind === 'mana' ? current.mana.amount : current.quantity.amount;
        if (!['auto','any'].includes(activeAmount.rule)) {
            const valueRow = document.createElement('label'); valueRow.className = 'highlight-aspect-row';
            const valueLabel = document.createElement('span'); valueLabel.textContent = 'Amount value'; valueRow.appendChild(valueLabel);
            const valueInput = document.createElement('input'); valueInput.type = 'number'; valueInput.min = '0'; valueInput.step = '1'; valueInput.className = 'highlight-edit-select'; valueInput.setAttribute('aria-label','Amount value');
            valueInput.value = String(activeAmount.value ?? detectedAspect.amount ?? ''); valueInput.placeholder = String(detectedAspect.amount ?? 'N');
            valueInput.addEventListener('change', () => { const next = normalizeHighlightAspects(h.aspects); const target = detectedAspect.kind === 'mana' ? next.mana.amount : next.quantity.amount; target.value = valueInput.value.trim() === '' ? null : Math.max(0, Number(valueInput.value)); h.aspects = next; preview.textContent = buildHighlightAspectPreview(h,detectedAspect); });
            valueRow.appendChild(valueInput); aspectControls.appendChild(valueRow);
        }
        const preview = document.createElement('div'); preview.className='highlight-aspect-preview'; preview.setAttribute('aria-live','polite'); preview.textContent=buildHighlightAspectPreview(h,detectedAspect); aspectControls.appendChild(preview);
    }

    const connectRow = document.createElement('div');
    connectRow.className = 'highlight-edit-row';
    const connectLabel = document.createElement('label');
    connectLabel.className = 'highlight-edit-label-inline';
    connectLabel.textContent = 'Connected to:';
    const connectSelect = document.createElement('select');
    connectSelect.className = 'highlight-edit-select';
    connectSelect.setAttribute('aria-label', 'Connect this search detail to a highlight');

    const independent = document.createElement('option');
    independent.value = '';
    independent.textContent = 'Independent';
    connectSelect.appendChild(independent);
    highlightParentOptions(idx).forEach(({ h: parent, idx: parentIdx }) => {
        const option = document.createElement('option');
        option.value = String(parentIdx);
        option.textContent = getHighlightParentLabel(parentIdx);
        connectSelect.appendChild(option);
    });
    if (Number.isInteger(h.attachedTo) && manualHighlights[h.attachedTo]) {
        connectSelect.value = String(h.attachedTo);
    } else {
        connectSelect.value = '';
    }
    connectLabel.htmlFor = `highlight-edit-connect-${idx}`;
    connectSelect.id = connectLabel.htmlFor;
    connectRow.appendChild(connectLabel);
    connectRow.appendChild(connectSelect);

    const help = document.createElement('div');
    help.className = 'highlight-edit-help';
    help.textContent = h.origin === 'user'
        ? 'Connected details become part of the same search intent without pretending the wording exists on the source card.'
        : 'Changing this to text that exists on the source card moves the visual highlight. New wording becomes a search-only detail.';

    const actions = document.createElement('div');
    actions.className = 'highlight-add-actions';
    const cancel = document.createElement('button');
    cancel.type = 'button';
    cancel.className = 'highlight-add-cancel';
    cancel.textContent = 'Cancel';
    cancel.addEventListener('click', () => {
        highlightEditIndex = null;
        renderHighlightChips();
    });

    const save = document.createElement('button');
    save.type = 'button';
    save.className = 'highlight-add-submit';
    save.textContent = 'Save';

    const commit = () => {
        const nextText = input.value.trim();
        if (!nextText) {
            input.focus();
            return;
        }
        const target = manualHighlights[idx];
        if (!target) return;
        const parentValue = connectSelect.value;
        const nextAttachedTo = /^\d+$/.test(parentValue) ? Number(parentValue) : null;
        const sourceOracleBeforeEdit = getCurrentSourceOracleText();
        const previousText = String(target.text || '').trim();
        const priorAnchor = target.editedFrom || (target.origin !== 'user' && Number.isInteger(target.start) && Number.isInteger(target.end)
            && sourceOracleBeforeEdit.slice(target.start, target.end).trim().toLocaleLowerCase() === previousText.toLocaleLowerCase()
            ? { text: previousText, start: target.start, end: target.end, clauseText: extractHighlightClauseContext(sourceOracleBeforeEdit, target.start, target.end) }
            : null);

        const textChanged = nextText.toLowerCase() !== previousText.toLowerCase();
        target.text = nextText;
        target.mode = selectedMode;
        target.attachedTo = Number.isInteger(nextAttachedTo) && nextAttachedTo !== idx ? nextAttachedTo : null;
        target.intentConnection = Number.isInteger(target.attachedTo) ? 'attached' : 'independent';

        // Keep source-backed highlights visually anchored to a real occurrence. If the user
        // intentionally edits one into new wording, convert it to a search-only detail rather than
        // rendering a fake highlight that does not exist on the card.
        // Re-edited search-only chips keep their source anchor. Re-evaluate them as well so a
        // user can change an edited phrase back to literal source text and restore the visual span.
        if ((target.origin !== 'user' || target.editedFrom) && (textChanged || !Number.isFinite(target.start) || !Number.isFinite(target.end))) {
            const found = findHighlightRangeInSource(nextText, target.start);
            if (found) {
                target.start = found.start;
                target.end = found.end;
                target.origin = target.origin === 'benchmark' ? 'benchmark' : 'source';
                delete target.editedFrom;
            } else {
                if (priorAnchor && Number.isInteger(priorAnchor.start) && Number.isInteger(priorAnchor.end)) {
                    target.editedFrom = {
                        text: String(priorAnchor.text || previousText).trim(),
                        start: priorAnchor.start,
                        end: priorAnchor.end,
                        clauseText: priorAnchor.clauseText || extractHighlightClauseContext(sourceOracleBeforeEdit, priorAnchor.start, priorAnchor.end)
                    };
                }
                target.start = null;
                target.end = null;
                target.origin = 'user';
            }
        }

        highlightEditIndex = null;
        reapplyOracleHighlights();
        reapplyTypeLineHighlights();
        renderHighlightChips();
        notifyManaSearchHighlightsChanged();
    };
    save.addEventListener('click', commit);
    input.addEventListener('keydown', (event) => {
        if ((event.ctrlKey || event.metaKey) && event.key === 'Enter') {
            event.preventDefault();
            commit();
        } else if (event.key === 'Escape') {
            event.preventDefault();
            highlightEditIndex = null;
            renderHighlightChips();
        }
    });

    actions.appendChild(cancel);
    actions.appendChild(save);
    editor.appendChild(title);
    editor.appendChild(textLabel);
    editor.appendChild(input);
    editor.appendChild(modeRow);
    if (aspectControls) editor.appendChild(aspectControls);
    editor.appendChild(connectRow);
    editor.appendChild(help);
    editor.appendChild(actions);
    return editor;
}

function renderHighlightChips() {
    const container = document.getElementById('highlight-chips-list');
    if (!container) return;
    container.innerHTML = '';

    const chipsRow = document.createElement('div');
    chipsRow.className = 'highlight-chips-row';

    manualHighlights.forEach((h, idx) => {
        const chip = document.createElement('div');
        chip.className = `card-chip highlight-chip highlight-color-${Number.isInteger(h.colorIndex) ? h.colorIndex % 4 : 0} ${h.field === 'type' ? 'highlight-type-chip' : ''} ${h.origin === 'user' ? 'highlight-user-chip' : 'highlight-source-chip'} ${Number.isInteger(h.attachedTo) ? 'highlight-linked-chip' : ''} ${h.mode === 'context' ? 'highlight-mode-context' : h.mode === 'avoid' ? 'highlight-mode-avoid' : ''}`;

        if (Number.isInteger(h.attachedTo) && manualHighlights[h.attachedTo]) {
            const linked = document.createElement('span');
            linked.className = 'highlight-linked-marker';
            linked.textContent = '\u21b3';
            linked.title = `Connected to: ${manualHighlights[h.attachedTo].text || 'highlight'}`;
            chip.appendChild(linked);
        }

        const origin = document.createElement('span');
        origin.className = 'highlight-origin-label';
        origin.textContent = h.origin === 'auto-context' ? 'Context' : (h.origin === 'user' ? '+' : (h.field === 'type' ? 'Type' : 'Highlight'));
        origin.title = h.origin === 'auto-context'
            ? 'Automatically included because this adjacent sentence appears dependent on your selection. It is context-only and is not a mandatory match.'
            : h.origin === 'user'
                ? (Number.isInteger(h.attachedTo) ? `User-added search detail connected to: ${getHighlightParentLabel(h.attachedTo)}` : 'Independent user-added search detail')
                : (h.field === 'type' ? 'Selected from this card\'s type line' : 'Selected from this card\'s Oracle text');

        const modeBtn = document.createElement('button');
        modeBtn.type = 'button';
        const modeLabels = { variable: '≈ Flexible', exact: '= Exact', context: 'Context only', avoid: 'Avoid' };
        const safeMode = ['variable', 'exact', 'context', 'avoid'].includes(h.mode) ? h.mode : 'exact';
        modeBtn.className = `highlight-mode-btn mode-${safeMode}`;
        modeBtn.textContent = modeLabels[safeMode];
        modeBtn.title = ({ variable: 'Flexible: prefer similar mechanics while allowing wording and values to differ.', exact: 'Exact: the matching card must contain this wording.', context: 'Context only: use this to interpret nearby text, not as a separate requirement.', avoid: 'Avoid: favor candidates that do not match this effect or wording.' })[safeMode];
        modeBtn.addEventListener('click', () => toggleHighlightMode(idx));

        const label = document.createElement('span');
        label.className = 'highlight-chip-text';
        label.textContent = h.text.length > 55 ? h.text.slice(0, 52) + '\u2026' : h.text;
        label.title = h.text;
        if (hasActiveHighlightAspects(h.aspects)) {
            const aspectBadge = document.createElement('span');
            aspectBadge.className = 'highlight-aspect-summary';
            const aspects = normalizeHighlightAspects(h.aspects);
            const parts = [];
            const amount = h.field === 'type' ? null : (aspects.mana.amount.rule !== 'auto' ? aspects.mana.amount.rule.replace('_', ' ') : aspects.quantity.amount.rule !== 'auto' ? aspects.quantity.amount.rule.replace('_', ' ') : '');
            if (amount) parts.push(amount === 'exact' ? `exactly ${aspects.mana.amount.value ?? aspects.quantity.amount.value ?? 'N'}` : amount);
            if (aspects.mana.color.rule === 'same') parts.push((deriveHighlightAspectKind(h)?.colors || []).map(c => c === 'c' ? 'colorless' : c.toUpperCase()).join('/'));
            else if (aspects.mana.color.rule === 'any_colored') parts.push('any colored');
            else if (aspects.mana.color.rule === 'any') parts.push('any color');
            aspectBadge.textContent = parts.filter(Boolean).join(' · ');
            aspectBadge.title = `Structured requirements: ${aspectBadge.text}`;
            if (aspectBadge.text) chip.appendChild(aspectBadge);
        }

        const editBtn = document.createElement('button');
        editBtn.type = 'button';
        editBtn.className = 'highlight-edit-btn';
        editBtn.textContent = 'Edit';
        editBtn.title = 'Edit text, match mode, or connection';
        editBtn.setAttribute('aria-label', `Edit ${h.text}`);
        editBtn.addEventListener('click', () => {
            highlightEditIndex = highlightEditIndex === idx ? null : idx;
            highlightComposerOpen = false;
            renderHighlightChips();
            if (highlightEditIndex === idx) {
                requestAnimationFrame(() => document.querySelector('.highlight-edit-input')?.focus());
            }
        });

        const removeBtn = document.createElement('button');
        removeBtn.type = 'button';
        removeBtn.className = 'card-chip-remove highlight-remove-btn';
        removeBtn.textContent = '\u00D7';
        removeBtn.title = 'Remove this highlight/search detail';
        removeBtn.setAttribute('aria-label', `Remove ${h.text}`);
        removeBtn.addEventListener('click', () => removeHighlight(idx));

        chip.appendChild(origin);
        chip.appendChild(modeBtn);
        chip.appendChild(label);
        chip.appendChild(editBtn);
        chip.appendChild(removeBtn);
        chipsRow.appendChild(chip);

        const editor = renderHighlightEditor(idx);
        if (editor) container.appendChild(editor);
    });

    container.appendChild(chipsRow);

    const relatedHighlightsToggle = document.getElementById('related-use-highlights');
    if (relatedHighlightsToggle) {
        // Keep the control interactive at all times. With no source highlights enabled, checking
        // it simply has no additional text to contribute; disabling it made the checkbox feel broken.
        relatedHighlightsToggle.disabled = false;
        relatedHighlightsToggle.checked = includeSourceHighlightsInRelatedSearch;
    }

    if (manualHighlights.length > 0) {
        const clearAllButton = document.createElement('button');
        clearAllButton.type = 'button';
        clearAllButton.className = 'highlight-clear-all-btn';
        clearAllButton.textContent = 'Clear All Highlights';
        clearAllButton.addEventListener('click', () => {
            manualHighlights = [];
            nextHighlightColorIndex = 0;
            highlightEditIndex = null;
            highlightComposerOpen = false;
            reapplyOracleHighlights();
            reapplyTypeLineHighlights();
            renderHighlightChips();
            notifyManaSearchHighlightsChanged();
        });
        container.appendChild(clearAllButton);
    }

    const addButton = document.createElement('button');
    addButton.type = 'button';
    addButton.className = 'highlight-add-btn';
    addButton.textContent = '+';
    addButton.title = 'Add another search detail';
    addButton.setAttribute('aria-label', 'Add another highlighted-text search detail');
    addButton.setAttribute('aria-expanded', highlightComposerOpen ? 'true' : 'false');
    addButton.addEventListener('click', () => {
        highlightComposerOpen = !highlightComposerOpen;
        highlightEditIndex = null;
        renderHighlightChips();
        if (highlightComposerOpen) {
            requestAnimationFrame(() => document.getElementById('highlight-add-text')?.focus());
        }
    });
    container.appendChild(addButton);

    if (highlightComposerOpen) {
        const composer = document.createElement('div');
        composer.className = 'highlight-add-composer';
        composer.setAttribute('role', 'group');
        composer.setAttribute('aria-label', 'Add search detail');

        const label = document.createElement('label');
        label.className = 'highlight-add-label';
        label.htmlFor = 'highlight-add-text';
        label.textContent = 'Add a search detail';

        const input = document.createElement('textarea');
        input.id = 'highlight-add-text';
        input.className = 'highlight-add-input';
        input.rows = 2;
        input.placeholder = 'e.g. produces 3 colorless mana, can target creatures, costs 2 or less';
        input.maxLength = 300;
        input.setAttribute('aria-label', 'Search detail');

        const modeRow = document.createElement('div');
        modeRow.className = 'highlight-add-mode-row';
        const modeLabel = document.createElement('span');
        modeLabel.className = 'highlight-add-mode-label';
        modeLabel.textContent = 'Match:';
        modeRow.appendChild(modeLabel);

        let selectedMode = ['variable', 'exact', 'context', 'avoid'].includes(displayPreferences?.highlightDefaultMode) ? displayPreferences.highlightDefaultMode : 'variable';
        const makeModeButton = (mode, text, title) => {
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = `highlight-composer-mode ${mode === selectedMode ? 'selected' : ''}`;
            btn.textContent = text;
            btn.title = title;
            btn.addEventListener('click', () => {
                selectedMode = mode;
                modeRow.querySelectorAll('.highlight-composer-mode').forEach(b => b.classList.remove('selected'));
                btn.classList.add('selected');
            });
            return btn;
        };
        modeRow.appendChild(makeModeButton('variable', '≈ Flexible', 'Prefer similar mechanics; wording and values may differ.'));
        modeRow.appendChild(makeModeButton('exact', '= Exact', 'Require this wording to occur in candidate Oracle text.'));
        modeRow.appendChild(makeModeButton('context', 'Context only', 'Use this as context without making it a separate requirement.'));
        modeRow.appendChild(makeModeButton('avoid', 'Avoid', 'Prefer candidates that do not match this effect or wording.'));

        const connectRow = document.createElement('div');
        connectRow.className = 'highlight-add-connection-row';
        const connectLabel = document.createElement('label');
        connectLabel.className = 'highlight-add-mode-label';
        connectLabel.textContent = 'Connect to:';
        const connectSelect = document.createElement('select');
        connectSelect.className = 'highlight-edit-select';
        connectSelect.setAttribute('aria-label', 'Connect added search detail to a highlight');
        let connectionChoiceMade = false;
        connectSelect.addEventListener('change', () => { connectionChoiceMade = true; });
        const independent = document.createElement('option');
        independent.value = '';
        independent.textContent = 'Independent';
        connectSelect.appendChild(independent);
        const parents = highlightParentOptions(null);
        parents.forEach(({ idx }) => {
            const option = document.createElement('option');
            option.value = String(idx);
            option.textContent = getHighlightParentLabel(idx);
            connectSelect.appendChild(option);
        });
        connectRow.appendChild(connectLabel);
        connectRow.appendChild(connectSelect);

        const help = document.createElement('div');
        help.className = 'highlight-add-help';
        help.textContent = 'Connect a search-only detail to a highlighted Oracle effect when it describes a property of that effect rather than a separate requirement.';

        const actionRow = document.createElement('div');
        actionRow.className = 'highlight-add-actions';
        const cancelBtn = document.createElement('button');
        cancelBtn.type = 'button';
        cancelBtn.className = 'highlight-add-cancel';
        cancelBtn.textContent = 'Cancel';
        cancelBtn.addEventListener('click', () => {
            highlightComposerOpen = false;
            renderHighlightChips();
        });

        const addTagBtn = document.createElement('button');
        addTagBtn.type = 'button';
        addTagBtn.className = 'highlight-add-submit';
        addTagBtn.textContent = 'Add';

        const submit = () => {
            const text = input.value.trim();
            if (!text) return;
            const duplicate = manualHighlights.some(h =>
                h.origin === 'user' && h.text.trim().toLowerCase() === text.toLowerCase() &&
                h.mode === selectedMode && h.attachedTo === (connectSelect.value === '' ? null : Number(connectSelect.value))
            );
            if (!duplicate) {
                let attachedTo = /^\d+$/.test(connectSelect.value) ? Number(connectSelect.value) : null;
                // If the user adds an explicit trigger condition while exactly one Oracle effect is
                // highlighted, connect it automatically unless they intentionally changed the
                // connection control to Independent. This turns the natural action "highlight the
                // outcome, then describe when it happens" into a coherent mechanical intent.
                if (attachedTo === null && !connectionChoiceMade && isSearchIntentTriggerPhrase(text)) {
                    const currentOracle = getCurrentSourceOracleText();
                    const plausibleParents = highlightParentOptions(null).filter(({ h }) => {
                        if (h.field === 'type') return false;
                        const anchor = getHighlightSourceAnchor(h, currentOracle);
                        if (!anchor) return false;
                        const clause = extractHighlightClauseContext(currentOracle, anchor.start, anchor.end);
                        const resolution = getResolutionAfterTrigger(clause);
                        return Boolean(resolution && isLikelyEffectOutcomeText(resolution) && resolution.toLowerCase().includes(String(anchor.text || '').trim().toLowerCase()));
                    });
                    if (plausibleParents.length === 1) attachedTo = plausibleParents[0].idx;
                }
                manualHighlights.push({
                    text,
                    mode: selectedMode,
                    origin: 'user',
                    colorIndex: nextHighlightColorIndex++ % 4,
                    start: null,
                    end: null,
                    attachedTo,
                    intentConnection: attachedTo !== null ? 'attached' : (connectionChoiceMade ? 'independent' : 'auto')
                });
            }
            input.value = '';
            highlightComposerOpen = false;
            renderHighlightChips();
            notifyManaSearchHighlightsChanged();
        };
        addTagBtn.addEventListener('click', submit);
        input.addEventListener('keydown', (event) => {
            if ((event.ctrlKey || event.metaKey) && event.key === 'Enter') {
                event.preventDefault();
                submit();
            } else if (event.key === 'Escape') {
                event.preventDefault();
                highlightComposerOpen = false;
                renderHighlightChips();
            }
        });

        actionRow.appendChild(cancelBtn);
        actionRow.appendChild(addTagBtn);
        composer.appendChild(label);
        composer.appendChild(input);
        composer.appendChild(modeRow);
        composer.appendChild(connectRow);
        composer.appendChild(help);
        composer.appendChild(actionRow);
        container.appendChild(composer);
    }
}

function toggleHighlightMode(idx) {
    if (!manualHighlights[idx]) return;
    const modes = ['variable', 'exact', 'context', 'avoid'];
    const current = modes.includes(manualHighlights[idx].mode) ? manualHighlights[idx].mode : 'exact';
    manualHighlights[idx].mode = modes[(modes.indexOf(current) + 1) % modes.length];
    renderHighlightChips();
    reapplyOracleHighlights();
    reapplyTypeLineHighlights();
    notifyManaSearchHighlightsChanged();
}

function removeHighlight(idx) {
    manualHighlights.splice(idx, 1);
    // Keep explicit connection references valid after a removal. A child attached to the removed
    // highlight becomes independent; references after the removed index shift down by one.
    manualHighlights.forEach(h => {
        if (!Number.isInteger(h.attachedTo)) return;
        if (h.attachedTo === idx) h.attachedTo = null;
        else if (h.attachedTo > idx) h.attachedTo -= 1;
    });
    if (highlightEditIndex === idx) highlightEditIndex = null;
    else if (Number.isInteger(highlightEditIndex) && highlightEditIndex > idx) highlightEditIndex -= 1;
    renderHighlightChips();
    reapplyOracleHighlights();
    reapplyTypeLineHighlights();
    notifyManaSearchHighlightsChanged();
}

// Configurable tag weights (Primary: 1.0, Secondary: 0.5, Broad Category: 0.2, Default fallback: 0.5)
const TAG_WEIGHTS = {
    // --- PRIMARY MECHANICS (1.0) ---
    "reanimate": 1.0,
    "tutor": 1.0,
    "counterspell": 1.0,
    "boardwipe": 1.0,
    "extra turn": 1.0,
    "storm": 1.0,
    "cascade": 1.0,
    "polymorph": 1.0,
    "pod": 1.0,
    "stax": 1.0,
    "wheel": 1.0,
    "free cast": 1.0,

    // --- SECONDARY MECHANICS (0.5) ---
    "recursion": 0.5,
    "aristocrats": 0.5,
    "blink": 0.5,
    "ramp": 0.5,
    "token": 0.5,
    "draw": 0.5,
    "removal": 0.5,
    "bounce": 0.5,
    "theft": 0.5,
    "spellslinger": 0.5,
    "landfall": 0.5,
    "sac outlet": 0.5,
    "impulse draw": 0.5,
    "protection": 0.5,
    "tax": 0.5,
    // "Finisher" detects a shape ("this effect ends the game" / "massive X drain"), not a defined
    // mechanic the way Reanimate or Counterspell are - it's inherently the fuzziest tag in this
    // table, so it's deliberately kept out of the 1.0 tier rather than let a heuristic-with-no-
    // precise-definition carry the same scoring authority as an unambiguous rule match
    // (review: tag system item 4).
    "finisher": 0.5,

    // --- BROAD CATEGORIES & GENERAL CONTEXT (0.2) ---
    "graveyard": 0.2,
    "etb": 0.2,
    "death trigger": 0.2,
    "evasion": 0.2,
    "treasure": 0.2,
    "cantrip": 0.2,
    "scry": 0.2,
    "surveil": 0.2,
    "+1/+1 counters": 0.2,
    "untap": 0.2
};

function getTagWeight(tag) {
    const lowerTag = tag.toLowerCase();
    if (TAG_WEIGHTS[lowerTag] !== undefined) return TAG_WEIGHTS[lowerTag];

    // Compositional sub-tags (e.g. "anthem:merfolk", "removal:creature", "token:multiple") carry
    // their base tag's family weight, scaled down since they're a refinement of that family
    // rather than the primary signal on their own - so matching the specific parameter is worth
    // something extra without ever outweighing matching the base family itself
    // (project spec F: richer compositional tags, function family + parameters).
    const colonIndex = lowerTag.indexOf(':');
    if (colonIndex > 0) {
        const baseTag = lowerTag.slice(0, colonIndex);
        const baseWeight = TAG_WEIGHTS[baseTag] !== undefined ? TAG_WEIGHTS[baseTag] : 0.5;
        return baseWeight * 0.6;
    }

    return 0.5;
}

/**
 * Extracts normalized MTG rule restriction keywords (e.g., "noncreature", "basic", "plains").
 * @param {string} text 
 * @returns {string[]} Array of normalized restriction keywords
 */
/**
 * Normalizes a card name for identity comparison ("is this the source card itself?"). A plain
 * `.toLowerCase()` comparison assumes both sides format the name identically, but that can break
 * in ways that are easy to miss: incidental leading/trailing or doubled internal whitespace (from
 * copy-paste, a search-history entry, or a manually-typed search), and double-faced/split/adventure
 * cards, where different Scryfall response shapes can carry the combined "Front // Back" name in
 * one place and just the front face's name in another. This is deliberately generous - it
 * normalizes whitespace AND treats a name as "the same card" if it matches either the full
 * combined name or just the part before " // ", so a DFC comparison can't silently miss due to
 * that asymmetry. Used both for the main hard-filter exclusion and as a last-resort safety net
 * right before rendering, so the source card can never appear in its own results regardless of
 * which comparison point a mismatch slips past.
 * @param {string} name
 * @returns {string}
 */
function normalizeCardNameForIdentity(name) {
    return (name || '').toLowerCase().trim().replace(/\s+/g, ' ');
}

/**
 * True if two card names refer to the same card for exclusion purposes - exact normalized match,
 * or either side's normalized name equals the other's front-face component (before " // ").
 * @param {string} nameA
 * @param {string} nameB
 * @returns {boolean}
 */
function isSameCardName(nameA, nameB) {
    const a = normalizeCardNameForIdentity(nameA);
    const b = normalizeCardNameForIdentity(nameB);
    if (!a || !b) return false;
    if (a === b) return true;
    const aFront = a.split(' // ')[0];
    const bFront = b.split(' // ')[0];
    return aFront === b || bFront === a || aFront === bFront;
}

function extractMTGRestrictions(text) {
    if (!text) return [];

    // "creature you control" vs "creature an opponent controls" describe very different
    // restrictions (self-affecting vs opponent-affecting) but the pronoun words below are
    // otherwise stripped as noise - capture that distinction as an explicit token first so it
    // isn't lost (project spec 2.3 / 2.4: restrictions and target structure).
    const controlTokens = [];
    if (/\byou control\b/i.test(text)) controlTokens.push('controlledbyyou');
    if (/\b(?:an? )?opponents?\s+control(?:s)?\b|\beach opponent\s+control(?:s)?\b/i.test(text)) controlTokens.push('controlledbyopponent');

    const ignoreList = new Set([
        'a', 'an', 'the', 'target', 'each', 'all', 'other', 'another', 'card', 'cards',
        'permanent', 'permanents', 'spell', 'spells', 'or', 'and', 'with', 'you', 'control',
        'your', 'their', 'opponent', 'controls', 'it', 'they', 'from', 'onto', 'into',
        'to', 'under', 'its', 'owner\'s', 'owners', 'then', 'put', 'return', 'have', 'has'
    ]);

    const normalizedText = text.toLowerCase()
        .replace(/non\-([a-z]+)/g, 'non$1') // Normalize "non-creature" to "noncreature"
        .replace(/[^a-z0-9\s\-]/g, '');

    const words = normalizedText
        .split(/\s+/)
        .filter(word => word.length > 1 && !ignoreList.has(word));

    return [...controlTokens, ...words];
}

/**
 * Separates an activation-cost prefix (e.g. "{1}, Sacrifice a creature:") from the effect
 * text that follows it. This matters because the cost prefix often contains its own verb
 * (sacrifice, discard, tap, exile) that is NOT the ability's actual effect - e.g. for
 * "Sacrifice a creature: Draw a card.", the mechanical action is "draw", not "sacrifice".
 * Before this split existed, the whole string was handed to the action sub-parsers, and
 * parseZoneMovementEffect's verb-priority chain would match "sacrifice" first and never see
 * "draw" at all, mis-classifying the ability's real effect (project spec: cost-then-effect
 * sequencing).
 * @param {string} clauseText
 * @returns {{costText: string|null, effectText: string}}
 */
function splitActivationCost(clauseText) {
    const match = clauseText.match(/^\s*([^:]{1,60}):\s*(.+)$/s);
    if (!match) return { costText: null, effectText: clauseText };

    const prefix = match[1];
    // Only treat the prefix as a genuine activation cost when it actually looks like one
    // (mana symbols, sacrifice/discard/exile/pay, or the tap symbol/word). A trigger condition
    // like "When this creature dies:" or "If you control a Merfolk:" uses a colon too but is
    // NOT a cost, so it must stay attached to the effect text.
    const looksLikeCost = /\{[^}]+\}|\bsacrifice\b|\bdiscard\b|\bpay\s+\d|\btap\b/i.test(prefix)
        && !/^\s*(when|whenever|if|at the beginning|as long as)\b/i.test(prefix);

    if (!looksLikeCost) return { costText: null, effectText: clauseText };
    return { costText: prefix.trim(), effectText: match[2].trim() };
}

/**
 * Classifies an isolated activation-cost prefix into a structured shape instead of a single
 * opaque label, so e.g. a compound cost ("{1}, Sacrifice a creature, Discard a card:") can be
 * compared component-by-component rather than only matching on whichever cost type happened
 * to be detected first.
 * @param {string} costText
 * @returns {{raw: string, type: string, parts: string[]}}
 */
function parseManaPaymentRange(costText) {
    const symbols = String(costText || '').match(/\{[^}]+\}/g) || [];
    if (!symbols.length) {
        return { min: 0, max: 0, exact: true, variable: false, symbols: [] };
    }

    let min = 0;
    let max = 0;
    let variable = false;

    const fixedSymbolValue = token => {
        const t = String(token || '').trim().toUpperCase();
        if (!t || t === 'T' || t === 'Q' || t === 'E') return { min: 0, max: 0, variable: false };
        if (t === 'X' || t === 'Y' || t === 'Z') return { min: 0, max: null, variable: true };
        if (/^\d+$/.test(t)) {
            const n = Number(t);
            return { min: n, max: n, variable: false };
        }
        if (t.includes('/')) {
            const options = t.split('/').map(option => {
                const part = option.trim();
                if (part === 'P') return 0;
                if (/^\d+$/.test(part)) return Number(part);
                // Colored/snow mana and other one-symbol payments require one mana.
                return 1;
            });
            return { min: Math.min(...options), max: Math.max(...options), variable: options.length > 1 };
        }
        // {W}{U}{B}{R}{G}{C}{S} and other one-mana symbols each require one mana.
        return { min: 1, max: 1, variable: false };
    };

    for (const symbol of symbols) {
        const token = symbol.slice(1, -1);
        const value = fixedSymbolValue(token);
        min += value.min;
        if (value.max == null) max = null;
        else if (max != null) max += value.max;
        variable = variable || value.variable || value.max == null;
    }

    return {
        min,
        max,
        exact: !variable && max != null && min === max,
        variable,
        symbols
    };
}

function classifyActivationCost(costText) {
    const lower = costText.toLowerCase();
    const parts = [];
    if (/\{t\}|\btap\b/.test(lower)) parts.push('tap');
    const costSymbols = lower.match(/\{[^}]+\}/g) || [];
    if (costSymbols.some(symbol => !/^\{t\}$/i.test(symbol))) parts.push('mana');
    if (/\bsacrifice\b/.test(lower)) parts.push('sacrifice');
    if (/\bdiscard\b/.test(lower)) parts.push('discard');
    if (/\bexile\b/.test(lower)) parts.push('exile');
    if (/\bpay\s+\d+\s+life\b/.test(lower)) parts.push('life');

    const manaPayment = parseManaPaymentRange(costText);
    return {
        raw: costText,
        type: parts[0] || 'other',
        parts,
        manaMin: manaPayment.min,
        manaMax: manaPayment.max,
        manaExact: manaPayment.exact,
        manaVariable: manaPayment.variable,
        manaSymbols: manaPayment.symbols
    };
}

function analyzeManaOutput(text, amount) {
    const raw = String(text || '');
    const lower = raw.toLowerCase();
    const symbols = raw.match(/\{(?:[wubrgcs]|\d+|x)\}/gi) || [];
    const fixedColors = symbols
        .map(symbol => symbol.slice(1, -1).toLowerCase())
        .filter(token => ['w', 'u', 'b', 'r', 'g', 'c', 's'].includes(token));
    const uniqueColors = [...new Set(fixedColors)];

    // A list such as "Add {W}, {U}, or {B}" describes ONE mana with a choice of color,
    // not three mana. Detect the common one-symbol choice form explicitly. The previous parser
    // counted all symbols and therefore treated every Obelisk-style filter as a three-mana rock.
    const afterAdd = lower.match(/\badd\s+(.+?)(?:\s+to\s+(?:your|the)\s+mana\s+pool)?\s*\.?$/i)?.[1] || '';
    const choiceSymbols = afterAdd.match(/\{(?:[wubrgcs])\}/gi) || [];
    const isSimpleSingleManaChoice = /\bor\b/.test(afterAdd)
        && choiceSymbols.length >= 2
        && /^[\s,{}wubrgcsor]+$/i.test(afterAdd)
        && choiceSymbols.every(() => true);

    let mode = 'unknown';
    let semanticAmount = amount != null && Number.isFinite(Number(amount)) ? Number(amount) : null;

    if (isSimpleSingleManaChoice) {
        mode = 'choice_single_fixed_color';
        semanticAmount = 1;
    } else if (symbols.length) {
        if (uniqueColors.length === 1) {
            mode = uniqueColors[0] === 'c' ? 'fixed_colorless'
                : uniqueColors[0] === 's' ? 'fixed_snow'
                : 'fixed_single_color';
        } else if (uniqueColors.length > 1) {
            mode = 'fixed_multi_color';
        } else {
            mode = 'fixed';
        }
    } else if (/\b(?:in|of) any combination of (?:colors|mana types)\b/.test(lower) || /\bany combination of\b/.test(lower)) {
        mode = 'any_combination';
    } else if (/\bany (?:one )?(?:color|type)\b/.test(lower)) {
        mode = 'any_one';
    } else if (/\bany type that\b|\bany color\b[^.]{0,80}\bcould produce\b/.test(lower)) {
        mode = 'any_land_producible';
    } else if (/\bcolorless mana\b/.test(lower)) {
        mode = 'fixed_colorless';
    }

    return {
        amount: semanticAmount,
        mode,
        colors: uniqueColors,
        uniqueColorCount: uniqueColors.length,
        symbolCount: symbols.length,
        isChoice: mode === 'choice_single_fixed_color'
    };
}
function finalizeManaAbilityEffect(effect) {
    if (!effect || effect.action !== 'add_mana') return effect;

    const output = effect.manaOutput || analyzeManaOutput(effect.raw || '', effect.amount);
    const cost = effect.activationCost || null;
    let netAmount = null;
    let netMin = null;
    let netMax = null;

    if (output.amount != null && Number.isFinite(Number(output.amount))) {
        const produced = Number(output.amount);
        const minCost = Number.isFinite(Number(cost?.manaMin)) ? Number(cost.manaMin) : 0;
        const maxCost = cost?.manaMax == null ? null : (Number.isFinite(Number(cost.manaMax)) ? Number(cost.manaMax) : null);
        netMin = maxCost == null ? null : produced - maxCost;
        netMax = produced - minCost;
        if (netMin != null && netMin === netMax) netAmount = netMin;
    }

    effect.manaOutput = {
        ...output,
        netAmount,
        netMin,
        netMax,
        activationManaMin: Number.isFinite(Number(cost?.manaMin)) ? Number(cost.manaMin) : 0,
        activationManaMax: cost?.manaMax == null ? null : (Number.isFinite(Number(cost.manaMax)) ? Number(cost.manaMax) : null),
        activationManaExact: Boolean(cost?.manaExact)
    };
    effect.manaOutputAmount = output.amount;
    effect.manaNetAmount = netAmount;
    effect.manaNetMin = netMin;
    effect.manaNetMax = netMax;
    effect.manaOutputMode = output.mode;
    effect.manaOutputColors = output.colors;
    effect.manaOutputColorCount = output.uniqueColorCount;
    return effect;
}

function manaNumericSimilarity(a, b) {
    // null means unknown, not numeric zero. Treating Number(null) as 0 fabricated a match
    // between unknown net mana values and could hide a real difference in fixed output amounts.
    const hasA = a !== null && a !== undefined && a !== '' && Number.isFinite(Number(a));
    const hasB = b !== null && b !== undefined && b !== '' && Number.isFinite(Number(b));
    if (!hasA || !hasB) return null;
    const na = Number(a), nb = Number(b);
    if (na === nb) return 1;
    return Math.max(0, 1 - Math.abs(na - nb) / Math.max(Math.abs(na), Math.abs(nb), 1));
}

function manaColorProfileSimilarity(a, b) {
    if (!a || !b) return null;
    const modeA = a.mode || 'unknown';
    const modeB = b.mode || 'unknown';

    if (modeA === modeB) {
        if (modeA === 'choice_single_fixed_color') {
            // Both abilities produce exactly one mana, but let the color-choice sets refine the match.
            const sa = new Set(a.colors || []), sb = new Set(b.colors || []);
            if (!sa.size && !sb.size) return 1;
            if (!sa.size || !sb.size) return 0.55;
            const union = new Set([...sa, ...sb]);
            const inter = [...sa].filter(c => sb.has(c)).length;
            return inter / Math.max(1, union.size);
        }
        if (modeA.startsWith('fixed')) {
            const sa = new Set(a.colors || []), sb = new Set(b.colors || []);
            if (!sa.size && !sb.size) return 1;
            if (!sa.size || !sb.size) return 0.35;
            const union = new Set([...sa, ...sb]);
            const inter = [...sa].filter(c => sb.has(c)).length;
            return inter / Math.max(1, union.size);
        }
        return 1;
    }

    const flexible = new Set(['any_one', 'any_combination', 'any_land_producible']);
    if (flexible.has(modeA) && flexible.has(modeB)) return 0.82;
    if ((modeA === 'choice_single_fixed_color' && modeB === 'any_one') || (modeB === 'choice_single_fixed_color' && modeA === 'any_one')) return 0.90;
    if ((modeA === 'choice_single_fixed_color' && modeB === 'fixed_single_color') || (modeB === 'choice_single_fixed_color' && modeA === 'fixed_single_color')) return 0.82;
    if ((modeA === 'choice_single_fixed_color' && modeB === 'fixed_multi_color') || (modeB === 'choice_single_fixed_color' && modeA === 'fixed_multi_color')) return 0.20;
    if (modeA === 'fixed_colorless' && modeB === 'any_one') return 0.62;
    if (modeB === 'fixed_colorless' && modeA === 'any_one') return 0.62;
    if (modeA === 'fixed_single_color' && modeB === 'any_one') return 0.70;
    if (modeB === 'fixed_single_color' && modeA === 'any_one') return 0.70;
    if (modeA === 'fixed_multi_color' && modeB === 'any_combination') return 0.72;
    if (modeB === 'fixed_multi_color' && modeA === 'any_combination') return 0.72;
    if (modeA === 'fixed' && flexible.has(modeB)) return 0.58;
    if (modeB === 'fixed' && flexible.has(modeA)) return 0.58;
    return 0.25;
}
function manaActivationSimilarity(a, b) {
    if (!a || !b) return null;
    const amin = Number.isFinite(Number(a.manaMin)) ? Number(a.manaMin) : 0;
    const bmin = Number.isFinite(Number(b.manaMin)) ? Number(b.manaMin) : 0;
    const amax = a.manaMax == null ? null : Number(a.manaMax);
    const bmax = b.manaMax == null ? null : Number(b.manaMax);
    if (amax == null || bmax == null) return 0.55;
    const minSim = manaNumericSimilarity(amin, bmin);
    const maxSim = manaNumericSimilarity(amax, bmax);
    return minSim == null || maxSim == null ? 0.55 : (0.55 * minSim + 0.45 * maxSim);
}

/**
 * Extracts conditions, payment/activation costs, and secondary ("additional") effects that
 * commonly ride alongside a clause's primary action - e.g. "unless its controller pays {2}",
 * "if you control a Merfolk", "Sacrifice a creature:", "then draw a card". Applied uniformly to
 * every clause type in parseMTGEffect (not just counterspells, where this used to live), so
 * mechanical comparison can actually use this structure instead of it only ever being populated
 * for one specific effect type (project spec 2.3: "Conditions and costs", "Additional effects").
 * @param {string} text
 * @returns {{condition: string|null, conditionDetail: string[]|null, payCost: string|null, additionalEffects: string[]}}
 */
function extractConditionsAndCosts(text) {
    const result = { condition: null, conditionDetail: null, payCost: null, additionalEffects: [], quantity: null };
    if (!text) return result;

    const unlessPay = text.match(/\bunless (?:its|that player's|their)?\s*controller pays\s*(\{[\dwubrgx/]+\}|\d+|[a-z\s]+)/i);
    const ifMatch = text.match(/\bif\s+([^,.:;]+)/i);
    if (unlessPay) {
        result.condition = "unless_pay";
        result.payCost = unlessPay[1].trim();
    } else if (/\bunless\b/i.test(text)) {
        result.condition = "unless_other";
        const unlessDetail = text.match(/\bunless\s+([^,.:;]+)/i);
        if (unlessDetail) result.conditionDetail = extractMTGRestrictions(unlessDetail[1]);
    } else if (/^\s*if\b/i.test(text) || /\bif you control\b|\bif [a-z\s]+ entered\b/i.test(text)) {
        result.condition = "if";
        // Capture WHAT the condition actually checks (e.g. "you control a merfolk"), not just
        // that a condition exists, so two cards with different "if" conditions aren't scored
        // as equivalent just because they're both conditional (project spec: condition detail).
        if (ifMatch) result.conditionDetail = extractMTGRestrictions(ifMatch[1]);
    }

    // Additional/activation cost paid before the ability's colon, e.g.
    // "{1}, Sacrifice a creature: Draw a card."
    const costMatch = text.match(/^\s*([^:]{1,60}):/);
    if (costMatch) {
        const costText = costMatch[1].toLowerCase();
        if (/sacrifice/.test(costText)) result.payCost = result.payCost || "sacrifice";
        else if (/\{[\dwubrgx/]+\}/.test(costText)) result.payCost = result.payCost || "mana";
        else if (/discard/.test(costText)) result.payCost = result.payCost || "discard";
        else if (/\{t\}|\btap\b/.test(costText)) result.payCost = result.payCost || "tap";
    }

    // A numeric quantity attached to the clause's action - "draw 1" vs "draw 3", "deal 2" vs
    // "deal 5", "mill 3" vs "mill 10" describe the *same function at different strength*, not
    // simply "same" or "different" (review #5: quantitative similarity, generalized past just
    // token/anthem counts to every effect type).
    const QTY_WORDS = { a: 1, an: 1, one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10, x: 'X', any: 'ANY' };
    const qtyGeneralMatch = text.match(/\b(?:draws?|deals?|gains?|loses?|mills?|scries?|surveils?|exiles? the top|puts?(?: [a-z]+)? counters?)\s+(a|an|one|two|three|four|five|six|seven|eight|nine|ten|x|any(?: number of)?|\d+)\b/i);
    if (qtyGeneralMatch) {
        const rawQty = qtyGeneralMatch[1].toLowerCase().split(' ')[0];
        result.quantity = QTY_WORDS[rawQty] !== undefined ? QTY_WORDS[rawQty] : (isNaN(parseInt(rawQty, 10)) ? null : parseInt(rawQty, 10));
    }

    // Secondary/chained effects riding along with the clause's primary action.
    if (/\bdraws? a card\b/i.test(text)) result.additionalEffects.push("draw_card");
    if (/\bscry\s*\d*/i.test(text)) result.additionalEffects.push("scry");
    if (/\bsurveil\s*\d*/i.test(text)) result.additionalEffects.push("surveil");
    if (/\bcreates? [a-z\s]*token/i.test(text)) result.additionalEffects.push("create_token");
    if (/\bgains? \d+ life\b/i.test(text)) result.additionalEffects.push("gain_life");
    if (/\bloses? \d+ life\b/i.test(text)) result.additionalEffects.push("lose_life");

    return result;
}

/**
 * Parses one-shot +1/+1 or -1/-1 counter PLACEMENT: "put a +1/+1 counter on target creature",
 * "put two -1/-1 counters on target creature". Distinct from the STATIC team-wide buff
 * parseAnthemEffect already handles ("creatures you control get +1/+1") - a counter placement is
 * a one-time, permanent change to one specific permanent, not a continuous effect over the whole
 * team, and previously had no recognition of its own at all.
 * @param {string} clause
 * @returns {Object|null}
 */
function parseCounterPlacementEffect(clause) {
    const text = String(clause || '').toLowerCase();
    const match = text.match(/\bputs?\s+(a|an|one|two|three|four|five|six|seven|eight|nine|ten|one or more|a number of|x|\d+)\s+([+-]\d+\/[+-]\d+|[a-z][a-z -]{0,24}?)\s+counters?\s+on\s+(?:(?:up to\s+(?:one|two|three|four|five|six|seven|eight|nine|ten|\d+)\s+)?)(?:(target|each|all|another|a|an|one|this|that|enchanted|equipped|you)\s+)?(creatures?|permanents?|artifacts?|enchantments?|lands?|planeswalkers?|battles?|players?|opponents?|it|them)\b/i);
    if (!match) return null;

    const qtyWords = { a: 1, an: 1, one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10, x: 'X', 'one or more': 'ANY', 'a number of': 'ANY' };
    const rawQty = match[1].toLowerCase();
    const subject = match[4].replace(/s$/, '');
    const targetWord = (match[3] || '').toLowerCase();
    const quantity = qtyWords[rawQty] !== undefined ? qtyWords[rawQty] : Number(rawQty);

    return {
        action: 'place_counter',
        object: ['it', 'them'].includes(subject) ? 'permanent' : subject,
        target: targetWord === 'each' || targetWord === 'all' ? targetWord : (targetWord === 'target' ? 'target' : null),
        counterType: match[2].trim(),
        quantity,
        restriction: extractMTGRestrictions(text)
    };
}

/**
 * Parses direct tap/untap effects on a permanent - "tap target creature", "untap all lands you
 * control" - distinct from a mana ability's own {T} activation cost (already stripped out before
 * this runs by splitActivationCost) and from keyword reminder text like "doesn't untap". Requires
 * an explicit target/each/all phrase after the verb specifically so a bare mention isn't misread
 * as an effect. Previously unparsed entirely.
 * @param {string} clause
 * @returns {Object|null}
 */
function parseTapEffect(clause) {
    const text = String(clause || '').trim().toLowerCase();
    // Anchor the action after optional imperative wrappers so trigger conditions such as
    // "Whenever an opponent taps a land" are not mistaken for a tap effect themselves.
    const verbMatch = text.match(/^(?:(?:then|you may|you can|may)\s+)*(untaps?|taps?)\s+/i);
    if (!verbMatch) return null;

    const subjectText = text.slice(verbMatch[0].length);
    const subjectMatch = subjectText.match(/(?:(?:up to\s+)?(one|two|three|four|five|six|seven|eight|nine|ten|\d+)\s+)?(?:(any number of)\s+)?(?:(target|each|all|another|a|an|one|this|that|enchanted|equipped|attacking|blocking|tapped|untapped|non[a-z-]+)\s+)*(creatures?|permanents?|lands?|artifacts?|enchantments?|planeswalkers?|battles?|it|them)\b/i);
    if (!subjectMatch) return null;

    const subject = subjectMatch[4].replace(/s$/, '');
    const prefix = subjectMatch[0].toLowerCase();
    const quantifier = subjectMatch[1]?.toLowerCase();
    const target = /\btarget\b/i.test(prefix) ? 'target'
        : /\beach\b/i.test(prefix) ? 'each'
        : /\ball\b/i.test(prefix) ? 'all'
        : null;
    const quantityWords = { one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10 };
    const quantity = subjectMatch[2] ? 'ANY'
        : quantifier ? (quantityWords[quantifier] ?? Number(quantifier))
        : null;

    return {
        action: verbMatch[1].toLowerCase().startsWith('untap') ? 'untap' : 'tap',
        object: ['it', 'them'].includes(subject) ? 'permanent' : subject,
        target,
        quantity,
        restriction: extractMTGRestrictions(text)
    };
}

/**
 * First-class parsing for common keyword actions whose rules meaning is more specific than
 * generic text: scry/surveil rearrange or move the top cards, while proliferate adds counters to
 * existing objects. Their universal text signatures remain active as additional evidence.
 */
function parseLibraryActionEffect(clause) {
    const text = String(clause || '').trim().toLowerCase();
    const actionMatch = text.match(/^(?:(?:then|you may|you can|may)\s+)*(scry|surveil)\s+(one|two|three|four|five|six|seven|eight|nine|ten|\d+)/i);
    if (actionMatch) {
        const quantityWords = { one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10 };
        const rawQuantity = actionMatch[2].toLowerCase();
        return { action: actionMatch[1].toLowerCase(), object: 'card', quantity: quantityWords[rawQuantity] ?? Number(rawQuantity), target: null, restriction: extractMTGRestrictions(text) };
    }
    if (/^(?:(?:then|you may|you can|may)\s+)*proliferate\b/i.test(text)) {
        return { action: 'proliferate', object: 'counter', quantity: null, target: null, restriction: extractMTGRestrictions(text) };
    }
    return null;
}

/**
 * Parses control-changing effects such as:
 *   "Gain control of target nonland permanent with mana value 1 or less."
 *   "Gain control of target creature until end of turn."
 * These are first-class effects so modal cards can explain non-counterspell modes instead of
 * reducing them to generic/unmatched text.
 */
function parseControlChangeEffect(clause) {
    const text = String(clause || '').trim();
    const match = text.match(/\b(?:gain|gains|take|takes)\s+control\s+of\s+(target\s+)?(.+?)(?:\s+until\s+(.+))?\.?$/i);
    if (!match) return null;

    let objectText = String(match[2] || '').trim().replace(/[.!]+$/g, '').trim();
    let duration = String(match[3] || '').trim();
    const untilIndex = objectText.search(/\s+until\s+/i);
    if (untilIndex >= 0) {
        duration = objectText.slice(untilIndex + 7).trim();
        objectText = objectText.slice(0, untilIndex).trim();
    }
    if (!objectText) return null;

    return {
        action: 'gain_control',
        object: objectText.toLowerCase(),
        target: match[1] ? 'target' : (objectText.toLowerCase().startsWith('target ') ? 'target' : null),
        restriction: extractMTGRestrictions(text),
        duration: duration ? 'temporary' : null,
        controlChangeDuration: duration || null,
        controller: 'you'
    };
}

/**
 * Parses static/continuous spell-cost reductions such as:
 *   "White spells you cast cost {1} less to cast."
 *   "White spells cost {1} less to cast."
 *   "Artifact spells you cast cost {2} less."
 *
 * Cost reduction is a first-class mechanical effect. Previously these clauses fell through to
 * `generic`, which made an otherwise equivalent cost-reduction source/candidate pair report 0.
 */
function parseCostReductionEffect(clause) {
    const text = String(clause || '').trim();
    const patterns = [
        /\b(.+?)\s+spells?\s+(you\s+cast|cast)\s+costs?\s+(\{[^}]+\}|\d+)\s+less(?:\s+to\s+cast)?\b/i,
        /\b(.+?)\s+spells?\s+costs?\s+(\{[^}]+\}|\d+)\s+less(?:\s+to\s+cast)?\b/i,
        /\b(spells?)\s+(you\s+cast|cast)\s+costs?\s+(\{[^}]+\}|\d+)\s+less(?:\s+to\s+cast)?\b/i,
        /\b(spells?)\s+costs?\s+(\{[^}]+\}|\d+)\s+less(?:\s+to\s+cast)?\b/i
    ];
    let match = null;
    for (const pattern of patterns) {
        match = text.match(pattern);
        if (match) break;
    }
    if (!match) return null;

    let qualifier = '';
    let controller = null;
    let discount = null;
    if (match.length === 4) {
        // Qualified + controlled form: [qualifier, controller phrase, discount].
        qualifier = /^spells?$/i.test(match[1] || '') ? '' : String(match[1] || '');
        controller = /^(?:you\s+cast|cast)$/i.test(match[2] || '') ? 'you' : null;
        discount = match[3];
    } else if (match.length === 3) {
        // Either "<qualifier> spells cost ..." or the unqualified "spells you cast cost ..." form.
        qualifier = /^spells?$/i.test(match[1] || '') ? '' : String(match[1] || '');
        discount = match[2];
    }

    const normalizedQualifier = qualifier
        .replace(/^\s*the\s+first\s+/i, '')
        .replace(/\bspells?\b/ig, ' ')
        .replace(/\byou\s+cast\b/ig, ' ')
        .trim();

    const restriction = [];
    if (normalizedQualifier) {
        normalizedQualifier
            .toLowerCase()
            .replace(/\bnon-([a-z]+)/g, 'non$1')
            .split(/\s+(?:or|and)\s+|\s*,\s*|\s+/)
            .map(v => v.trim())
            .filter(Boolean)
            .filter(v => !['the','first','that','this','one'].includes(v))
            .forEach(v => { if (!restriction.includes(v)) restriction.push(v); });
    }

    const manaCost = String(discount || '').trim();
    const inner = manaCost.match(/^\{([^}]+)\}$/)?.[1] || manaCost;
    const numericDiscount = /^\d+$/.test(inner) ? Number(inner) : null;

    return {
        action: 'cost_reduction',
        object: 'spell',
        target: null,
        controller,
        restriction,
        amount: numericDiscount,
        quantity: numericDiscount,
        manaCost,
        effectMode: 'reduction',
        isStatic: true,
        costRestriction: normalizedQualifier || null
    };
}

/**
 * Parses counterspell and counter-ability clauses.
 * @param {string} clause 
 * @returns {Object|null}
 */
function parseCounterEffect(clause) {
    const text = clause.toLowerCase();
    if (!/\bcounter\b/i.test(text)) return null;

    // "Counter" is also a NOUN for permanent counters (+1/+1, loyalty, charge, poison...) - a
    // completely different effect from countering a spell or ability (see
    // parseCounterPlacementEffect for +1/+1 placement specifically). This guard previously matched
    // ANY clause containing the bare word "counter" anywhere, so "put a +1/+1 counter on target
    // creature" was silently misparsed as a fake counterspell (object defaulting to 'spell', which
    // never actually appears in that text) - and because this parser runs first in the chain and
    // always "succeeded", parseCounterPlacementEffect could never run at all for such a clause.
    // Require an actual counterspell/counter-ability shape, and explicitly rule out the permanent-
    // counter noun forms first.
    if (/[+-]1\/[+-]1 counters?|loyalty counters?|charge counters?|poison counters?|\bcounters?\s+(?:on|from|equal to)\b/i.test(text)) {
        return null;
    }
    if (!/\bcounters?\s+(?:target|all|each|that|up to)\b/i.test(text) && !/\b(?:spell|ability|activated ability|triggered ability)\b/i.test(text)) {
        return null;
    }

    const effect = {
        action: "counter",
        object: "spell",
        target: /\btarget\b/i.test(text) ? "target" : (/\ball\b/i.test(text) ? "all" : "each"),
        restriction: [],
        condition: null,
        payCost: null
    };

    if (text.includes("ability") || text.includes("activated ability") || text.includes("triggered ability")) {
        effect.object = "ability";
    }

    const spellMatch = text.match(/\bcounter\s+(?:target\s+|all\s+)?([a-z\s\-]+?)\s*(?:spell|ability)\b/i);
    if (spellMatch) {
        effect.restriction = extractMTGRestrictions(spellMatch[1]);
    }

    const payMatch = text.match(/\bunless (?:its|that player's|their)?\s*controller pays\s*(\{[\dwubrgx/]+\}|\d+|[a-z\s]+)/i);
    if (payMatch) {
        effect.condition = "unless_pay";
        effect.payCost = payMatch[1].trim();
    }

    // condition/payCost (if not already set above) and additionalEffects (e.g. "then draw a
    // card", "then scry") are filled in uniformly by parseMTGEffect via extractConditionsAndCosts.
    return effect;
}

/**
 * True only when the clause explicitly describes drawing cards. A reference to a player's
 * "draw step" is turn structure, not an instruction to draw cards. This guard is shared by the
 * zone-movement parser and its regression tests to prevent draw-step text from becoming a false
 * card-draw function.
 */
function hasExplicitCardDrawAction(value) {
    const text = String(value || '');
    const quantity = '(?:a|an|one|two|three|four|five|six|seven|eight|nine|ten|x|that many|another|an additional|the top(?:\\s+(?:one|two|three|four|five|\\d+))?|half(?: of)?|up to\\s+(?:one|two|three|four|five|\\d+)|\\d+|one or more)';
    const re = new RegExp('\\bdraw(?:s|ing)?\\s+(?:' + quantity + '\\s+)?cards?\\b', 'i');
    return re.test(text);
}

/**
 * Parses movement between battlefield, hand, graveyard, library, and exile.
 * @param {string} clause 
 * @returns {Object|null}
 */
function parseZoneMovementEffect(clause) {
    const text = clause.toLowerCase();
    
    // Every verb here needs its third-person-plural conjugation too ("puts", "returns", "moves",
    // "destroys"), not just the bare/imperative form - most spells say "Put target creature..."
    // (imperative), but a common and completely different template says "Each player puts a
    // creature card..." (third person), and that conjugated form was missing for return/put/move/
    // destroy specifically, even though exile/sacrifice/discard/mill/draw already handled it a few
    // lines down. A clause using only the missing form (no other recognized verb) failed this gate
    // entirely and fell straight to "generic" - confirmed on a real benchmark run where Exhume
    // ("Each player puts a creature card from their graveyard onto the battlefield") produced zero
    // canonical functions at all, the single highest-impact case found by scoring analysis.
    const firstMovementVerb = text.match(/\b(returns?|puts?|moves?|sacrifices?|destroys?|exiles?|discards?|mills?|draws?)\b(?=\s+)/i)?.[1]?.toLowerCase() || null;
    if (!firstMovementVerb) return null;

    const effect = {
        action: null,
        object: "card",
        from: null,
        to: null,
        target: null,
        restriction: [],
        tapped: text.includes("tapped")
    };

    if (/\btarget\b/i.test(text)) effect.target = "target";
    else if (/\beach\b/i.test(text)) effect.target = "each";
    else if (/\ball\b/i.test(text)) effect.target = "all";

    const topLibrarySource = /\btop\s+(?:(?:one|two|three|four|five|six|seven|eight|nine|ten|\d+)\s+)?cards?\s+of\s+(?:your|their|that player(?:'s|’s)|that opponent(?:'s|’s)|an opponent(?:'s|’s)|a player(?:'s|’s))\s+library\b/i.test(text);
    const topCountMatch = text.match(/\btop\s+(one|two|three|four|five|six|seven|eight|nine|ten|\d+)\s+cards?\b/i);
    if (topCountMatch) {
        const countWord = topCountMatch[1].toLowerCase();
        const counts = {one:1,two:2,three:3,four:4,five:5,six:6,seven:7,eight:8,nine:9,ten:10};
        effect.quantity = counts[countWord] ?? Number(countWord);
    }
    const fromMatch = text.match(/\bfrom\s+(?:a|an|the|your|their|any|all|top of your|top of their)?\s*(graveyard|battlefield|hand|library|exile|command zone)\b/i);
    if (topLibrarySource) effect.from = 'library';
    else if (fromMatch) effect.from = fromMatch[1].toLowerCase();

    const toMatch = text.match(/\b(?:to|onto|into)\s+(?:a|an|the|your|their|its owner's|top of your|bottom of your|top of their)?\s*(battlefield|graveyard|hand|library|exile|command zone)\b/i);
    if (toMatch) effect.to = toMatch[1].toLowerCase();

    // A land/permanent entering under an opponent's control is opponent resource gain, not our own
    // ramp or a generic zone change. Store the recipient/controller explicitly for ranking.
    if (/\bunder\s+(?:an?\s+)?opponent(?:'s|’s)\s+control\b/i.test(text)) effect.recipientScope = 'opponent';
    else if (/\bunder\s+your\s+control\b/i.test(text)) effect.recipientScope = 'you';

    if (/^(?:returns?|puts?|moves?)$/.test(firstMovementVerb)) {
        effect.action = /^returns?$/.test(firstMovementVerb) ? "return" : "put";
        const match = text.match(/\b(?:returns?|puts?|moves?)\s+(?:target\s+|all\s+|each\s+)?([a-z\s\-]+?)\s*(?:card|creature|permanent|artifact|enchantment|land|planeswalker)s?\b/i);
        if (match) effect.restriction = extractMTGRestrictions(match[1]);
        effect.object = text.includes('creature') ? 'creature' : (text.includes('land') ? 'land' : 'card');
    } else if (/^sacrifices?$/.test(firstMovementVerb)) {
        effect.action = "sacrifice";
        effect.object = "permanent";
        if (!effect.from) effect.from = "battlefield";
        if (!effect.to) effect.to = "graveyard";
        const sacMatch = text.match(/\bsacrifices?\s+(?:a|an|target|each)?\s*([a-z\s\-]+?)\s*(?:creature|permanent|artifact|enchantment|land)s?\b/i);
        if (sacMatch) effect.restriction = extractMTGRestrictions(sacMatch[1]);
    } else if (/^destroys?$/.test(firstMovementVerb)) {
        effect.action = "destroy";
        effect.object = "permanent";
        if (!effect.from) effect.from = "battlefield";
        if (!effect.to) effect.to = "graveyard";
        const destroyMatch = text.match(/\bdestroys?\s+(?:target|all|each)?\s*([a-z\s\-]+?)\s*(?:creature|permanent|artifact|enchantment|land|planeswalker)s?\b/i);
        if (destroyMatch) effect.restriction = extractMTGRestrictions(destroyMatch[1]);
    } else if (/^exiles?$/.test(firstMovementVerb)) {
        effect.action = "exile";
        effect.object = /\bpermanents?\b/i.test(text) ? 'permanent'
            : /\bcreatures?\b/i.test(text) ? 'creature'
            : /\bartifacts?\b/i.test(text) ? 'artifact'
            : /\benchantments?\b/i.test(text) ? 'enchantment'
            : /\bplaneswalkers?\b/i.test(text) ? 'planeswalker'
            : /\blands?\b/i.test(text) ? 'land'
            : /\bspells?\b/i.test(text) ? 'spell' : 'card';
        if (!effect.to) effect.to = "exile";
        const exileMatch = text.match(/\bexiles?\s+(?:target|all|each)?\s*([a-z\s\-]+?)\s*(?:card|creature|permanent|artifact|enchantment|land|spell)s?\b/i);
        if (exileMatch) effect.restriction = extractMTGRestrictions(exileMatch[1]);
    } else if (/^discards?$/.test(firstMovementVerb)) {
        effect.action = "discard";
        effect.object = "card";
        if (!effect.from) effect.from = "hand";
        if (!effect.to) effect.to = "graveyard";
    } else if (/^mills?$/.test(firstMovementVerb)) {
        effect.action = "mill";
        effect.object = "card";
        if (!effect.from) effect.from = "library";
        if (!effect.to) effect.to = "graveyard";
    } else if (/^draws?$/.test(firstMovementVerb) && hasExplicitCardDrawAction(text)) {
        effect.action = "draw";
        effect.object = "card";
        if (!effect.from) effect.from = "library";
        if (!effect.to) effect.to = "hand";
    }

    return effect.action ? effect : null;
}

// Shared "what can this effect target" vocabulary. Several parsers each used to spell out their
// own version of "target creature / any target / each opponent / all creatures", with slightly
// different coverage between them - a phrasing gap found in one (e.g. "target creature or
// battle") had to be separately noticed and fixed in every other parser that also handles
// targets. New parsers below call this one shared helper instead, so a coverage fix here benefits
// all of them at once (review: parser item 3). Existing, already-working parsers (damage, zone
// movement) keep their own inline patterns rather than being retrofitted onto this - lower risk
// than touching parsers that are already relied on, for the same reconciliation benefit new code
// gets automatically by using the shared helper from the start.
const TARGETABLE_OBJECT_WORDS = ['creature', 'player', 'opponent', 'permanent', 'artifact', 'enchantment', 'planeswalker', 'battle', 'land'];

/**
 * @param {string} text - lowercased clause text
 * @param {string[]} [objectWords] - which object nouns this effect can target
 * @returns {{object: string|null, target: string|null}}
 */
function extractTargetPhrase(text, objectWords = TARGETABLE_OBJECT_WORDS) {
    const objectAlt = objectWords.join('|');
    const re = new RegExp(`\\b(any target|target (?:${objectAlt})|each (?:opponent|player|${objectAlt})|all (?:${objectAlt})s?|that (?:${objectAlt}))\\b`, 'i');
    const match = text.match(re);
    if (!match) return { object: null, target: null };

    const phrase = match[0].toLowerCase();
    let object = null;
    if (phrase.includes('any target')) object = 'any target';
    else object = objectWords.find(w => phrase.includes(w))
        || (phrase.includes('opponent') ? 'opponent' : phrase.includes('player') ? 'player' : null);

    const target = /^each\b/.test(phrase) ? 'each'
        : /^all\b/.test(phrase) ? 'all'
        : (phrase.startsWith('target') || phrase.includes('any target')) ? 'target'
        : null;

    return { object, target };
}

/**
 * Parses direct-damage effects: "deals N damage to X", including "any target", a specific target
 * type, "each opponent/player/creature", and non-fixed amounts (X, "that much damage"). This is
 * one of the most common effect shapes in Magic - burn spells, damage-based removal, reach - and
 * previously had no dedicated recognition at all.
 * @param {string} clause
 * @returns {Object|null}
 */
function parseDamageEffect(clause) {
    const text = clause.toLowerCase();

    // Divided damage (Fireball-style): "deals X damage divided as you choose among any number of
    // target creatures and/or players." A materially different sentence shape from "deals X
    // damage to Y" - there's no single target phrase at all - so the main pattern below never
    // matched it; these X-damage finishers are common and distinct enough to deserve their own
    // case rather than falling to "generic" (review: parser item 2, broaden the damage parser).
    const dividedMatch = text.match(/\bdeals?\s+(\d+|x)\s+damage,?\s+divided\s+as\s+you\s+choose\s+among\s+(?:any number of\s+)?(?:target\s+)?(creatures?|players?|opponents?|any number of targets?)/i);
    if (dividedMatch) {
        const rawAmount = dividedMatch[1].toLowerCase();
        const amount = /^\d+$/.test(rawAmount) ? parseInt(rawAmount, 10) : rawAmount;
        const objPhrase = dividedMatch[2].toLowerCase();
        return {
            action: 'damage',
            object: objPhrase.includes('creature') ? 'creature' : objPhrase.includes('target') ? 'any target' : 'player',
            target: 'divided',
            amount,
            restriction: extractMTGRestrictions(text)
        };
    }

    // Fight-style / stat-scaled damage: "deals damage equal to its power to target creature", or
    // the "fights target creature" shorthand (which is defined by the rules as each dealing
    // damage equal to its power to the other). The amount scales with a creature's own stat rather
    // than being a fixed number printed on the card, so this is functionally its own family - two
    // "fight" effects should match each other more than either matches a same-fixed-number burn
    // spell, and collapsing them into "generic" (as before) lost that entirely.
    const statMatch = text.match(/\bdeals?\s+damage\s+equal\s+to\s+its\s+(power|toughness)\s+to\s+(any target|target (?:creature|player|planeswalker)|that creature)/i);
    const fightMatch = !statMatch && /\bfights?\s+target\s+creature\b/i.test(text);
    if (statMatch || fightMatch) {
        const targetPhrase = statMatch ? statMatch[2].toLowerCase() : 'target creature';
        const object = targetPhrase.includes('any target') ? 'any target'
            : targetPhrase.includes('player') ? 'player'
            : 'creature';
        return {
            action: 'damage',
            object,
            target: 'target',
            // Deliberately unified on "its power" for both a power-based stat effect and a fight
            // effect (which the rules define as power-for-power) so the two canonicalize to the
            // same magnitude and score as the close match they are; a toughness-based effect keeps
            // its own distinct string since that's a genuinely different, rarer shape.
            amount: statMatch && statMatch[1] === 'toughness' ? 'its toughness' : 'its power',
            restriction: extractMTGRestrictions(text)
        };
    }

    const match = text.match(/\bdeals?\s+(\d+|x|that much|twice that much)\s+damage\s+to\s+(any target|target (?:creature or planeswalker|creature or player|player|opponent|creature|planeswalker)|each (?:opponent|player|creature)|that (?:permanent|player|creature))/i);
    if (!match) return null;

    const rawAmount = match[1].toLowerCase();
    // Kept as a string ("x", "that much damage") when it isn't a fixed number - two spells that
    // both scale off something (X spells, or "twice that much") are a closer functional match to
    // each other than either is to a card with a fixed, unrelated amount, so this shouldn't just
    // collapse to null.
    const amount = /^\d+$/.test(rawAmount) ? parseInt(rawAmount, 10) : rawAmount;

    const targetPhrase = match[2].toLowerCase();
    let object;
    if (targetPhrase.includes('any target')) object = 'any target';
    else if (targetPhrase.includes('creature') && targetPhrase.includes('planeswalker')) object = 'creature or planeswalker';
    else if (targetPhrase.includes('creature') && targetPhrase.includes('player')) object = 'creature or player';
    else if (targetPhrase.includes('opponent')) object = 'opponent';
    else if (targetPhrase.includes('planeswalker')) object = 'planeswalker';
    else if (targetPhrase.includes('creature')) object = 'creature';
    else if (targetPhrase.includes('player')) object = 'player';
    else object = 'permanent';

    const target = /^each\b/.test(targetPhrase) ? 'each' : (/^target\b/.test(targetPhrase) || targetPhrase.includes('any target') ? 'target' : null);

    return {
        action: 'damage',
        object,
        target,
        amount,
        restriction: extractMTGRestrictions(text)
    };
}

/**
 * Parses mana-producing abilities: "Add {C}{C}", "Add one mana of any color", "Add X mana of any
 * one color", etc. A mana ability's cost ("{T}:") is already stripped out by splitActivationCost
 * before this runs, leaving just the production clause itself - which matched none of the
 * existing zone-movement/counter/search/token/anthem patterns, so every mana rock and ritual fell
 * to "generic". Requires an actual mana symbol or the word "mana" near "add" so an unrelated
 * "add a +1/+1 counter"-style clause elsewhere isn't misread as mana production.
 * @param {string} clause
 * @returns {Object|null}
 */
// Rules classification is deliberately separate from strategic mana production. Millikin still
// accelerates mana, but under the 2026 rules an ability that moves a card to/from the library as
// part of its cost or effect is not a mana ability under CR 605.1a, even when it adds mana.
function classifyManaAbilityRules(fullAbilityText, effectText = '') {
    const full = String(fullAbilityText || '').replace(/[’]/g, "'");
    const effect = String(effectText || '');
    const reasons = [];
    if (/\btarget\b/i.test(full)) reasons.push('requires_target');
    if (/\bmill(?:s|ed)?\b|\b(?:search|shuffle|reveal|exile|put|return|move|draw)\b[\s\S]{0,100}\blibrary\b|\blibrary\b[\s\S]{0,100}\b(?:search|shuffle|reveal|exile|put|return|move)\b/i.test(full)) reasons.push('moves_cards_to_or_from_library');
    if (/\b(?:loyalty ability|activate only as a sorcery)\b/i.test(full)) reasons.push('not_usable_as_mana_ability_timing');
    const producesMana = /\badd\b[\s\S]{0,70}(?:\{[wubrgcs]\}|\bmana\b)/i.test(effect);
    if (!producesMana) reasons.push('does_not_produce_mana');
    return {
        isRulesManaAbility: producesMana && reasons.length === 0,
        strategicRole: producesMana ? 'mana_production' : null,
        reasons,
        ruleReference: 'CR 605.1a'
    };
}

function parseManaAbilityEffect(clause) {
    const text = clause.toLowerCase();
    if (!/\badd\b/i.test(text)) return null;

    const manaSymbols = clause.match(/\{(?:[wubrgcs]|\d+|x)\}/gi) || [];
    const readsAsManaProduction = manaSymbols.length > 0 || /\badd\b[^.]{0,60}\bmana\b/i.test(text);
    if (!readsAsManaProduction) return null;

    const colors = [];
    if (/\{c\}/i.test(clause) || /\bcolorless mana\b/i.test(text)) colors.push('colorless');
    if (/\{s\}/i.test(clause) || /\bsnow mana\b/i.test(text)) colors.push('snow');
    ['w', 'u', 'b', 'r', 'g'].forEach(c => { if (new RegExp(`\\{${c}\\}`, 'i').test(clause)) colors.push(c); });
    if (/\bany (?:one )?(?:color|type)\b/i.test(text) || /\b(?:in|of) any combination of (?:colors|mana types)\b/i.test(text)) colors.push('any');

    let amount = manaSymbols.length > 0 ? manaSymbols.length : null;
    if (!amount) {
        const wordMatch = text.match(/\badd\s+(one|two|three|four|five|six|seven|eight|nine|ten|x)\b/i);
        if (wordMatch) {
            const words = { one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10 };
            amount = words[wordMatch[1].toLowerCase()] ?? wordMatch[1].toLowerCase();
        }
    }

    const manaOutput = analyzeManaOutput(text, amount);
    const semanticAmount = manaOutput.amount != null && Number.isFinite(Number(manaOutput.amount)) ? Number(manaOutput.amount) : amount;

    return {
        action: 'add_mana',
        object: 'mana',
        colors: colors.length > 0 ? [...new Set(colors)] : null,
        // `amount` is the actual mana produced, not the number of alternative symbols listed in
        // a choice such as "Add {R}, {G}, or {W}". The latter produces one mana, with three color
        // options, and must therefore canonicalize as amount 1.
        amount: semanticAmount,
        manaOutput,
        restriction: extractMTGRestrictions(text)
    };
}

/**
 * Parses direct life-total changes: "target player gains 4 life", "each opponent loses 2 life",
 * "you gain life equal to the damage dealt". Extremely common (lifegain-matters decks, extort,
 * drain finishers) but previously had no canonical function at all - only a loose tag regex
 * (Lifegain/Drain) with nothing structured behind it, so two cards built entirely around life
 * swings had no scorable signal in common beyond both containing the word "life" somewhere.
 * @param {string} clause
 * @returns {Object|null}
 */
function parseLifeEffect(clause) {
    const text = clause.toLowerCase();

    const fixedMatch = text.match(/\b(you|target player|target opponent|each player|each opponent|that player|its controller|their controller|controller)\s+(gains?|loses?)\s+(\d+|x|that much)\s+life\b/i);
    const equalToMatch = !fixedMatch && text.match(/\b(you|target player|target opponent|each player|each opponent|that player)\s+(gains?|loses?)\s+life\s+equal\s+to\b/i);
    const match = fixedMatch || equalToMatch;
    if (!match) return null;

    const subjectPhrase = match[1];
    const verb = match[2];
    const rawAmount = fixedMatch ? fixedMatch[3] : 'variable';
    const amount = /^\d+$/.test(rawAmount) ? parseInt(rawAmount, 10) : rawAmount;

    let object;
    if (subjectPhrase === 'you') object = 'you';
    else if (subjectPhrase.includes('opponent')) object = 'opponent';
    else if (subjectPhrase.includes('player')) object = 'player';
    else object = 'controller';

    const target = /^each\b/.test(subjectPhrase) ? 'each' : (subjectPhrase.startsWith('target') ? 'target' : null);

    return {
        action: verb.startsWith('gain') ? 'gain_life' : 'lose_life',
        object,
        target,
        amount,
        restriction: extractMTGRestrictions(text)
    };
}

/**
 * Parses tutor and land-fetch abilities.
 * @param {string} clause 
 * @returns {Object|null}
 */
function parseSearchEffect(clause) {
    const text = clause.toLowerCase();
    if (!/\bsearch\b/i.test(text)) return null;

    const effect = {
        action: "search",
        from: "library",
        to: "hand", 
        object: "card",
        restriction: [],
        tapped: text.includes("tapped"),
        shuffle: text.includes("shuffle")
    };

    const fromMatch = text.match(/\bsearch\s+(?:your|target player's)?\s*(library|graveyard)\b/i);
    if (fromMatch) effect.from = fromMatch[1].toLowerCase();

    const tutorMatch = text.match(/\bsearch\s+[^.]+?\s+for\s+(?:a|an)?\s*([a-z\s\-]+?)\s*card\b/i);
    if (tutorMatch) {
        effect.restriction = extractMTGRestrictions(tutorMatch[1]);
    } else {
        const landMatch = text.match(/\bsearch\s+[^.]+?\s+for\s+(?:a|an)?\s*([a-z\s\-]+?)\s*land\b/i);
        if (landMatch) {
            effect.restriction = extractMTGRestrictions(landMatch[1] + " land");
        }
    }

    const toMatch = text.match(/\b(?:put|place)\s+[^.]+?\s+(?:onto|into|to|on)\s+(?:the\s+)?(battlefield|hand|graveyard|top of your library|exile)\b/i);
    if (toMatch) {
        effect.to = toMatch[1].toLowerCase();
    } else if (text.includes("onto the battlefield")) {
        effect.to = "battlefield";
    }
    if (/\bput\b[^.]{0,220}\bunder\s+(?:an?\s+)?opponent(?:'s|’s)\s+control\b/i.test(text)) effect.recipientScope = 'opponent';
    else if (/\bput\b[^.]{0,220}\bunder\s+your\s+control\b/i.test(text)) effect.recipientScope = 'you';

    return effect;
}

/**
 * Parses token creation, token duplication, and replacement doublers.
 * @param {string} clause 
 * @returns {Object|null}
 */
function parseTokenEffect(clause) {
    const text = clause.toLowerCase();

    // "Investigate" is rules text for creating a Clue token. Preserve the clue identity so
    // retrieval/ranking can recognize repeatable Clue engines, not merely generic token makers.
    if (/\binvestigates?\b/i.test(text)) {
        return {
            action: "create", object: "token", to: "battlefield", quantity: null,
            tokenType: "clue", recipientScope: /\bunder\s+(?:an?\s+)?opponent(?:'s|’s)\s+control\b/i.test(text) ? 'opponent' : 'you',
            clueDrawEngine: true, isReplacement: false
        };
    }

    if (/\bif\b.*?\btokens?\b.*?\bwould be created\b/i.test(text) || text.includes("twice that many")) {
        return {
            action: "multiply",
            object: "token",
            multiplier: 2,
            isReplacement: true
        };
    }

    if (/\bcopy\b/i.test(text) && text.includes("token")) {
        return {
            action: "copy_token",
            object: "token",
            target: /\btarget\b/i.test(text) ? "target" : "chosen",
            isReplacement: false
        };
    }

    // Oracle grammar uses both imperative "create" and third-person "creates" (e.g.
    // "an opponent creates two Treasure tokens"). Recognize both so opponent-gift clauses don't
    // silently fall through to a generic effect.
    if (!/\b(?:create|creates|creating)\b/i.test(text)) return null;

    const opponentCreates = /\b(?:(?:an?|each|target)\s+)?opponents?\s+creates?\b/i.test(text);
    const underOpponentControl = /\bunder\s+(?:an?\s+)?opponent(?:'s|’s)\s+control\b/i.test(text);
    const underYourControl = /\bunder\s+your\s+control\b/i.test(text);
    const recipientScope = opponentCreates || underOpponentControl ? 'opponent' : (underYourControl ? 'you' : null);
    const effect = {
        action: "create",
        object: "token",
        to: "battlefield",
        quantity: 1,
        stats: null,
        keywords: [],
        tokenType: "token",
        recipientScope,
        controller: opponentCreates ? 'opponent' : null,
        isReplacement: false
    };

    const qtyMap = { 'a': 1, 'an': 1, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5, 'six': 6, 'x': 'X' };
    const qtyMatch = text.match(/\bcreates?\s+(a|an|one|two|three|four|five|six|x|\d+)\b/i);
    if (qtyMatch) {
        const rawQty = qtyMatch[1].toLowerCase();
        effect.quantity = qtyMap[rawQty] !== undefined ? qtyMap[rawQty] : (isNaN(rawQty) ? rawQty : parseInt(rawQty, 10));
    }

    // Extract P/T stats (e.g., 2/2, 1/1)
    const ptMatch = text.match(/(\d+\/\d+|\*[\/*]\*)/);
    if (ptMatch) {
        effect.stats = ptMatch[1];
    }

    // Extract keywords granted to the token
    const keywordCheck = ['flying', 'haste', 'trample', 'lifelink', 'deathtouch', 'vigilance', 'menace'];
    effect.keywords = keywordCheck.filter(kw => text.includes(kw));

    const typeMatch = text.match(/\bcreates?\s+(?:a|an|one|two|three|four|five|six|x|\d+)\s+([a-z0-9\/\s\-]+?)\s*token/i);
    if (typeMatch) {
        effect.tokenType = typeMatch[1].trim().replace(/\s+/g, ' ');
    }
    // "for each" describes a variable count, not a one-token effect. Keep the relation without
    // pretending the token quantity is fixed at one.
    if (/\bfor each\b/i.test(text)) effect.quantity = null;

    return effect;
}

/**
 * Parses static team buffs, tribal anthems, and granted abilities.
 * @param {string} clause 
 * @returns {Object|null}
 */
function parseAnthemEffect(clause) {
    const text = String(clause || '').toLowerCase().replace(/[’]/g, "'");
    const anthemMatch = text.match(/(other\s+)?([a-z\s\-]*?)\s*(?:creatures?\s*)?(you control)?\s*get\s*([\+\-][\dx\/*]+\/[\+\-][\dx\/*]+)/i);
    const keywordVocabulary = '(?:flying|trample|lifelink|deathtouch|vigilance|islandwalk|haste|reach|menace|ward|hexproof|indestructible|first strike|double strike|protection from [a-z]+)';
    // Keyword grants may follow a stat buff in the SAME clause: "creatures you control get
    // +X/+X and gain flying". Search within that subject's local clause rather than requiring
    // "have flying" to immediately follow "creatures you control".
    const keywordMatch = text.match(new RegExp(
        // Require the plural team subject and explicit control scope. A clause such as
        // "If you cast a creature spell this way, it gains haste" affects one spell/creature,
        // not your team, and must not become a false Anthem mechanic. Captures only the optional
        // "other" and granted-keyword list, never a prefix from an earlier trigger clause.
        `\\b(other\\s+)?creatures\\s+you control[\\s\\S]{0,120}?\\b(?:gain|gains|have|has)\\s+(${keywordVocabulary}(?:\\s*(?:,|and|or)\\s*${keywordVocabulary})*)`, 'i'));

    if (!anthemMatch && !keywordMatch) return null;

    let rawSubtype = "all";
    let isOther = false;
    let controller = "all";
    let pt = null;
    let grantedKeywords = [];

    if (anthemMatch) {
        isOther = Boolean(anthemMatch[1]);
        rawSubtype = anthemMatch[2] ? anthemMatch[2].trim()
            .replace(/\bcreatures?\b/gi, ' ')
            .replace(/\byou control\b/gi, ' ')
            .replace(/\bthat are\b/gi, ' ')
            .replace(/\s+/g, ' ').trim() || "all" : "all";
        controller = anthemMatch[3] ? "you_control" : "all";
        pt = anthemMatch[4];
    }

    if (keywordMatch) {
        isOther = isOther || Boolean(keywordMatch[1]);
        // The pattern itself confirms a team-wide, explicitly controlled creature subject.
        controller = "you_control";

        const possibleKeywords = ['flying', 'trample', 'lifelink', 'deathtouch', 'vigilance', 'islandwalk', 'haste', 'reach', 'menace', 'ward', 'hexproof', 'indestructible', 'first strike', 'double strike'];
        const keywordClause = String(keywordMatch[2] || '');
        grantedKeywords = possibleKeywords.filter(kw => new RegExp(`\\b${kw.replace(/ /g, '\\s+')}\\b`, 'i').test(keywordClause));
    }

    return {
        action: "stat_buff",
        object: "creature",
        isOther: isOther,
        subtype: rawSubtype || "all",
        controller: controller,
        powerToughness: pt,
        grantedKeywords: grantedKeywords,
        scalingProfile: /\bwhere\s+x\s+is\s+the\s+number\s+of\s+creatures?\s+you control\b/i.test(text)
            ? { kind: 'count_scaled', source: 'creatures_you_control', quantityUnit: 'creatures', operation: 'power_and_toughness' }
            : (/\b[+\-]x\/[+\-]x\b/i.test(text) ? { kind: 'variable_x', source: 'defined_elsewhere', quantityUnit: null, operation: 'power_and_toughness' } : null),
        isStatic: !/\buntil end of turn\b/i.test(text)
    };
}
// =============================================================================================
// ARCHITECTURE NOTE: THE PARSER IS EVIDENCE, NOT AUTHORITY (review Priority 6)
// =============================================================================================
//
// It's tempting to read a function like calculateMechanicalSimilarity() and think the engine's
// idea of "what this card does" comes from the rule-based parser below - action, canonical
// function, zones, restrictions, quantity. That would be the wrong mental model, and it's worth
// being explicit about why, since nothing about the code itself announces it.
//
// The parser is a REGEX-BASED HEURISTIC. It is confidently wrong on unanticipated phrasing,
// modal spells with unusual headers, triple-nested conditions, and anything using vocabulary
// its patterns don't cover - it will happily emit a structured, plausible-looking {action:
// "generic"} for a card it has completely failed to understand. Treating its output as ground
// truth (a "verdict") rather than as one fallible witness among several would mean the ranking
// silently inherits every one of the parser's blind spots as if they were facts about the card.
//
// So the architecture is not:
//
//         Oracle text --> [Rule Parser] --> "the meaning" --> ranking
//
// it is:
//
//                              Raw Oracle Text
//                                     |
//                    +----------------+----------------+
//                    |                                 |
//                    v                                 v
//          +-------------------+           +-----------------------+
//          |   RULE PARSER      |           |  SEMANTIC EMBEDDING    |
//          |  (parseMTGEffect)  |           |  (MiniLM, holistic -   |
//          |  structured but    |           |   never "confused",   |
//          |  narrow; can miss  |           |   but never precise   |
//          |  or misread text   |           |   about mechanics     |
//          |  it wasn't built   |           |   either)              |
//          |  to recognize      |           |                        |
//          +---------+----------+           +-----------+------------+
//                    |                                  |
//                    v                                  v
//          field-level confidence              contextScore / functionScore
//          (calculateFieldConfidence /                  |
//           calculateCardFieldConfidence)                |
//                    |                                  |
//                    +----------------+-----------------+
//                                     v
//                    CONFIDENCE-WEIGHTED BLEND, not a handoff
//                    (scoreCardBatch's adaptive weighting: effectiveWM/
//                     effectiveWC/effectiveWE shift authority AWAY from
//                     mechanical/exactness and TOWARD semantic precisely
//                     when the parser's own confidence in this pair is low)
//                                     |
//                                     v
//                            Final similarity score
//
// Concretely, this already exists in the code as three separate, real mechanisms - this comment
// names them as one coherent design rather than three unrelated-looking features:
//
//   1. calculateFieldConfidence() / calculateCardFieldConfidence() - the parser reports HOW SURE
//      it is about each field (action, zone, restriction, quantity...), not just an action label.
//   2. calculateParseConfidence() - the coarser clause-level signal (fraction of clauses that
//      resolved to a real action vs. fell back to "generic").
//   3. scoreCardBatch()'s adaptive weighting - both confidence signals are combined into
//      `combinedConfidence`, which then scales how much mechanical/exactness evidence gets to
//      count relative to semantic/functional evidence, for THIS SPECIFIC PAIR of cards. A
//      clean parse on both sides lets the structured read dominate (it's the most precise signal
//      available); a shaky parse on either side automatically defers more to the embedding.
//
// The parser is never given veto power, and the embedding is never given veto power either -
// each is one input the blend trusts in proportion to how reliable it looks for this comparison.
// That's the whole point of confidence-WEIGHTED, as opposed to confidence-GATED: there's no
// threshold below which the parser is ignored or above which it's the only thing that matters.
// =============================================================================================

// Rule-based MTG Effect Parser with Enhanced Zone Movement & Restriction Extraction
/**
 * Master parser splitting text into clauses and running category sub-parsers.
 * @param {string} oracleText 
 * @returns {Array<Object>}
 */
/**
 * Fraction of a card's parsed clauses that resolved to a recognized action rather than falling
 * back to "generic". Used to scale down how much authority a low-confidence parse gets in the
 * final ranking, instead of always trusting the mechanical score at full strength regardless of
 * how much of the text the rule-based parser actually understood (project spec ranking A:
 * confidence-aware mechanical weighting).
 * @param {Array<Object>} parsedEffects
 * @returns {number} 0.0 (nothing recognized) to 1.0 (every clause recognized)
 */
function calculateParseConfidence(parsedEffects) {
    if (!parsedEffects || parsedEffects.length === 0) return 0;
    const meaningful = parsedEffects.filter(e => e.action && e.action !== "generic").length;
    return meaningful / parsedEffects.length;
}

/**
 * Per-FIELD parse confidence for a single effect, rather than one blanket number for the card.
 *
 * "70% parsed" is too coarse to act on: a clause can have a rock-solid action and zones while its
 * restriction list is junk, or a perfect restriction with no quantity found at all. Reporting
 * confidence per field lets the mechanical scorer weight each comparison by how much it actually
 * trusts that specific piece, instead of trusting or distrusting everything at once
 * (review Priority 9).
 *
 * @param {Object} effect
 * @returns {Object} confidence 0..1 per field
 */
function calculateFieldConfidence(effect) {
    if (!effect) return { action: 0, object: 0, zone: 0, target: 0, restriction: 0, quantity: 0, condition: 0 };

    const recognized = Boolean(effect.action && effect.action !== "generic");
    const restrictions = effect.restriction || [];
    // A single stray token is weak evidence; a few coherent tokens is a real restriction.
    const restrictionConfidence = restrictions.length === 0 ? 0
        : restrictions.length === 1 ? 0.45
        : Math.min(1, 0.45 + restrictions.length * 0.18);

    const zoneKnown = (effect.from ? 0.5 : 0) + (effect.to ? 0.5 : 0);

    return {
        action: recognized ? 1 : 0,
        object: effect.object ? 1 : 0,
        zone: zoneKnown,
        target: effect.target ? 1 : 0,
        restriction: restrictionConfidence,
        quantity: (effect.quantity !== null && effect.quantity !== undefined) ? 1 : 0,
        condition: effect.condition ? (effect.conditionDetail?.length ? 1 : 0.6) : 0
    };
}

/**
 * Aggregate field-level confidence across a whole card, weighted toward the effects that matter.
 * @param {Array<Object>} parsedEffects
 * @returns {Object} per-field averages plus an `overall` figure
 */
function calculateCardFieldConfidence(parsedEffects) {
    const fields = ['action', 'object', 'zone', 'target', 'restriction', 'quantity', 'condition'];
    const totals = Object.fromEntries(fields.map(f => [f, 0]));
    let weightSum = 0;

    (parsedEffects || []).forEach(eff => {
        const weight = Math.max(0.05, eff.importance || 0.05);
        const conf = calculateFieldConfidence(eff);
        fields.forEach(f => { totals[f] += conf[f] * weight; });
        weightSum += weight;
    });

    if (weightSum === 0) return { ...Object.fromEntries(fields.map(f => [f, 0])), overall: 0 };

    const result = Object.fromEntries(fields.map(f => [f, totals[f] / weightSum]));
    // Action/zone confidence say the most about whether the structural read is trustworthy.
    result.overall = (result.action * 0.45) + (result.zone * 0.2) + (result.object * 0.15)
        + (result.restriction * 0.1) + (result.target * 0.1);
    return result;
}

// Verbs that can each introduce an independent effect inside a single clause. Conjugated forms
// (puts?, returns?, destroys?) included for the same reason as parseZoneMovementEffect's own
// gate - a third-person "each player puts..." construction needs the same recognition as the
// imperative "put target..." form.
const ATOM_VERBS = 'returns?|puts?|sacrifices?|destroys?|exiles?|discards?|mills?|draws?|search|creates?|creating|counter|deals?|gains?|loses?|taps?|untaps?';

/**
 * Extracts EVERY effect atom in one clause, not just its dominant verb.
 *
 * The sub-parsers each pick a single action via a verb-priority chain, so a compound clause like
 * "Sacrifice a creature, then search your library for a creature card and put it onto the
 * battlefield" collapsed to just `sacrifice` - the tutor and the battlefield entry, which are the
 * whole point of the card, were silently dropped. This re-runs the sub-parsers from each verb
 * occurrence so the clause becomes a SEQUENCE of atoms (review Priority 4: multiple effects per
 * clause).
 *
 * @param {string} effectText
 * @param {string|null} primaryAction - action already captured for this clause, to avoid duplicates
 * @returns {Array<Object>} additional effect atoms, in text order
 */
function extractClauseAtoms(effectText, primaryAction) {
    if (!effectText) return [];

    const atoms = [];
    // Skip only the first atom that repeats the whole-clause parser's dominant action. Further
    // occurrences must survive: Verdant Mastery has two distinct "put ... onto the battlefield"
    // actions with different recipients, and both are strategically meaningful.
    const primaryActionPending = new Set(primaryAction ? [primaryAction] : []);
    const verbRegex = new RegExp(`\\b(${ATOM_VERBS})\\b`, 'gi');

    let match;
    let guard = 0;
    while ((match = verbRegex.exec(effectText)) !== null && guard++ < 12) {
        // A tap/untap verb before the first action separator belongs to a trigger or condition
        // ("Whenever an opponent taps a land for mana, add {G}"), not to the effect sequence.
        // Direct imperative tap effects after the comma/then remain parseable.
        if (/^untaps?$/i.test(match[1]) || /^taps?$/i.test(match[1])) {
            const prefix = effectText.slice(0, match.index);
            const triggerStart = prefix.search(/\b(?:when|whenever|if|as long as)\b/i);
            const precedingSeparator = prefix.search(/[,;]|\bthen\b/i);
            if (triggerStart >= 0 && precedingSeparator < 0) continue;
        }
        // Parse from this verb onward, so each atom sees its own object/zones rather than the
        // whole clause's.
        const slice = effectText.slice(match.index);
        const atom =
            parseCounterEffect(slice) ||
            parseSearchEffect(slice) ||
            parseTokenEffect(slice) ||
            parseCounterPlacementEffect(slice) ||
            parseControlChangeEffect(slice) ||
            parseTapEffect(slice) ||
            parseDamageEffect(slice) ||
            parseLifeEffect(slice) ||
            parseZoneMovementEffect(slice);

        if (atom && atom.action) {
            if (primaryActionPending.has(atom.action)) {
                primaryActionPending.delete(atom.action);
                continue;
            }
            atom.raw = slice.trim();
            atom.contextClause = String(effectText || '').trim();
            atom.isSecondaryAtom = true;
            atoms.push(atom);
        }
    }

    return atoms;
}


// ---------------------------------------------------------------------------
// V14 STRUCTURAL RELATIONSHIP LAYER
// ---------------------------------------------------------------------------
// The parser already recognizes individual effects well enough for ranking. The next level is
// preserving *relationships* around those effects: who/what is targeted, when the effect fires,
// how a quantity is derived, and whether a clause is conditional, a cost, or a follow-up.
// These helpers intentionally add metadata instead of replacing the existing heuristic parser.
function parseStructuredTarget(text) {
    const t = String(text || '').toLowerCase();
    let kind = null;
    if (/\bany target\b/.test(t)) kind = 'any';
    else if (/\beach\s+(?:player|opponent|creature|permanent|artifact|enchantment|planeswalker|spell)\b/.test(t)) kind = 'each';
    else if (/\ball\s+(?:creatures?|players?|opponents?|permanents?|artifacts?|enchantments?|planeswalkers?|spells?)\b/.test(t)) kind = 'all';
    else if (/\btarget\b/.test(t)) kind = 'target';
    else if (/\byou\b/.test(t) && /\b(?:gain|lose|draw|discard|scry|surveil)\b/.test(t)) kind = 'you';

    let scope = null;
    if (/\byou control\b/.test(t)) scope = 'you_control';
    else if (/\ban opponent controls?\b|\bopponent controls?\b/.test(t)) scope = 'opponent_control';
    else if (/\byou own\b/.test(t)) scope = 'you_own';
    else if (/\ban opponent owns?\b|\bopponent owns?\b/.test(t)) scope = 'opponent_own';
    else if (/\byou\b/.test(t)) scope = 'you';
    else if (/\bopponent\b/.test(t)) scope = 'opponent';

    let object = null;
    const objectPatterns = [
        ['creature','creature'], ['permanent','permanent'], ['artifact','artifact'],
        ['enchantment','enchantment'], ['planeswalker','planeswalker'], ['instant or sorcery','spell'],
        ['spell','spell'], ['ability','ability'], ['card','card'], ['player','player'], ['opponent','opponent']
    ];
    for (const [needle, value] of objectPatterns) {
        if (new RegExp('\\b' + needle.replace(/ /g,'\\s+') + '\\b','i').test(t)) { object=value; break; }
    }
    return { kind, scope, object };
}

function parseQuantityProfile(text, parsedQuantity = null) {
    const t = String(text || '').toLowerCase();
    const out = { kind: parsedQuantity != null ? 'fixed' : null, value: parsedQuantity, relation: null, source: null, bound: null };
    if (/\bequal to\b/.test(t)) out.relation = 'equal_to';
    if (/\bfor each\b/.test(t)) out.relation = 'for_each';
    if (/\bthat many\b/.test(t)) out.relation = 'that_many';
    if (/\bbased on\b/.test(t)) out.relation = 'based_on';
    if (/\bequal to the number of\b/.test(t)) { out.relation = 'equal_to'; out.source = 'count'; }
    if (/\bequal to (?:its|their|that)\s+(?:power|toughness)\b/.test(t)) { out.relation = 'derived_stat'; out.source = 'power_or_toughness'; }
    if (/\bup to\b/.test(t)) { out.bound = 'up_to'; out.kind = 'bounded'; }
    if (/\bat least\b/.test(t)) { out.bound = 'at_least'; out.kind = 'bounded'; }
    if (/\bdouble\b|\btwice\b/.test(t)) { out.relation = 'multiplier'; out.source = /\btwice\b/.test(t) ? '2x' : '2x'; }
    if (/(?:\b|^)x(?:\b|\s)/i.test(t) || /\bX\b/i.test(text)) out.kind = 'variable';
    if (out.relation && out.kind === null) out.kind = 'derived';
    if (out.kind === null && parsedQuantity != null) out.kind = 'fixed';
    return out;
}

// Turn timing is parsed separately from the effect that follows it. This matters mechanically:
// "At the beginning of your upkeep, draw a card" is recurring, while
// "At the beginning of your next upkeep, draw a card" is a one-time delayed trigger.
// Older Oracle wording used "draw phase"; treat it as the same cadence family as draw step.
function parseTurnTimingProfile(text) {
    const t = String(text || '').toLowerCase().replace(/[’]/g, "'").replace(/\s+/g, ' ');
    const timingNames = '(?:precombat main phase|postcombat main phase|main phase|draw step|draw phase|upkeep|end step|end phase|end of combat|combat phase|combat|turn)';
    const candidates = [];
    const addMatches = (regex) => {
        let match;
        while ((match = regex.exec(t)) !== null) {
            const matchedText = match[0].trim();
            const cleanText = matchedText.replace(/^[.;\n]+\s*/, '').trim();
            const leadingOffset = Math.max(0, matchedText.indexOf(cleanText));
            candidates.push({ text: cleanText, index: match.index + leadingOffset, timing: String(match[1] || '').trim() });
            if (match[0].length === 0) regex.lastIndex++;
        }
    };
    // Full turn-window expressions, including "each opponent's upkeep", "each player's end step",
    // "combat on your turn", and one-shot "next upkeep/end step" templates.
    addMatches(new RegExp(`\\bat (?:the )?(?:beginning|start|end) of\\s+[^.;,\\n]{0,80}?\\b(${timingNames})\\b`, 'gi'));
    // Shorthand / older phrasing that omits "at the beginning of". Require an explicit timing
    // preposition here; otherwise "Skip your draw step" would look like a recurring trigger.
    addMatches(new RegExp(`\\b(?:during|at)\\s+(?:(?:each|every|your|each player's|each opponent's|each players'|each opponents')\\s+)?(${timingNames})\\b`, 'gi'));
    // Standalone clauses like "Each upkeep, ..." are accepted only at a clause boundary.
    // Do not misread "the first time you cast a spell each turn" as a turn-window trigger.
    addMatches(new RegExp(`(?:^|[.;\\n]\\s*)\\b(?:each|every)\\s+(?:(?:player|opponent)s?'?s?\\s+|of your\\s+|of each\\s+)?(${timingNames})\\b`, 'gi'));
    if (!candidates.length) return null;

    candidates.sort((a, b) => a.index - b.index || b.text.length - a.text.length);
    const candidate = candidates[0];
    const delayed = /\b(?:next|following)\b/i.test(candidate.text);
    const normalizedTiming = candidate.timing.toLowerCase().replace(/\s+/g, '_');
    // Legacy "draw phase" wording refers to the same recurring turn window as the modern draw step.
    const canonicalTiming = normalizedTiming === 'draw_phase' ? 'draw_step' : normalizedTiming;
    const prefix = candidate.text;
    const explicitEnd = /\bat (?:the )?end of\b/i.test(prefix);
    const explicitBeginning = /\bat (?:the )?(?:beginning|start) of\b/i.test(prefix);
    // Informal/legacy phrasings like "at your upkeep" or "each upkeep" describe the same
    // recurring start-of-window cadence as the standard "at the beginning of your upkeep".
    const shorthandBeginning = /^at\s+(?:your|each|every|each player's|each opponent's)\s+/i.test(prefix) || /^(?:each|every)\s+/i.test(prefix);
    const duringWindow = /^during\s+/i.test(prefix);
    const window = explicitEnd
        ? `end_of_${canonicalTiming}`
        : (explicitBeginning || shorthandBeginning)
            ? `beginning_of_${canonicalTiming}`
            : duringWindow ? `during_${canonicalTiming}` : canonicalTiming;
    return {
        cadence: delayed ? 'delayed' : 'periodic',
        timingText: candidate.text,
        timing: canonicalTiming.replace(/_/g, ' '),
        window,
        confidence: delayed ? 0.86 : 0.96
    };
}

function parseTriggerProfile(text) {
    const t = String(text || '').toLowerCase().replace(/[’]/g, "'");
    const timing = parseTurnTimingProfile(t);
    const hasEventTrigger = /\b(?:when|whenever)\b/.test(t);
    const hasConditional = /\bif\b/.test(t);
    if (!timing && !hasEventTrigger && !hasConditional) return null;
    const type = timing ? 'turn_window' : (hasEventTrigger ? 'event' : 'conditional');
    let event = null;

    // Event identity must come from the trigger condition, not from the resolution after the
    // comma. Otherwise "Whenever you cast a spell, draw a card" is misread as a draw trigger.
    const eventCondition = (t.match(/\b(?:when|whenever)\b\s+([^,.;]+)/i) || [null, ''])[1];
    const eventPatterns = [
        [/\benters? (?:the )?battlefield\b|\bcomes into play\b/, 'enter_battlefield'],
        [/\bdies\b|\bis put into a graveyard\b|\bgoes? to a graveyard\b/, 'dies'],
        [/\battacks?\b/, 'attacks'],
        [/\bblocks?\b/, 'blocks'],
        [/\bcasts?\b|\bcast (?:an? )?(?:instant|sorcery|spell)\b/, 'casts_spell'],
        [/\bdraws?\b[^,.;]{0,40}\bcards?\b/, 'draw_card'],
        [/\bdiscards?\b/, 'discard'],
        [/\bsacrifices?\b/, 'sacrifice'],
        [/\bdeals? (?:combat )?damage\b/, 'deals_damage'],
        [/\bgains? life\b/, 'gain_life'],
        [/\bloses? life\b/, 'lose_life'],
        [/\b(?:a|one|another|that) (?:token|permanent|creature|artifact|enchantment) is created\b|\bcreates?\b/, 'create'],
        [/\bleaves? the battlefield\b|\bis put into\b/, 'zone_change']
    ];
    if (hasEventTrigger) {
        for (const [pattern, value] of eventPatterns) {
            if (pattern.test(eventCondition)) { event = value; break; }
        }
    }
    const threshold = (t.match(/\b(?:three|four|five|six|seven|eight|nine|ten|\d+)\+?\b/) || [null])[0];
    return {
        type,
        event,
        window: timing?.window || null,
        timingText: timing?.timingText || null,
        cadence: timing?.cadence || (hasEventTrigger ? 'event' : null),
        threshold,
        conditional: hasConditional || type === 'conditional'
    };
}

function annotateEffectRelationships(effect, sourceText) {
    const raw = String(effect.raw || sourceText || '');
    // Secondary action atoms retain their parent clause. Use that clause for trigger semantics so
    // "At the beginning of your upkeep, draw a card and lose 1 life" gives both atoms the upkeep
    // cadence, while keeping the atom's own raw text for action/target/quantity parsing.
    const relationshipText = String(effect.parentRuleText || effect.contextClause || '').trim() || raw;
    const targetProfile = parseStructuredTarget(raw);
    effect.targetProfile = targetProfile;
    if (!effect.target && targetProfile.kind) effect.target = targetProfile.kind;
    // Recipient/beneficiary scope is action-local. Reading the whole printed sentence here made
    // earlier actions inherit a later opponent benefit (e.g. Ingenious Mastery's draw three cards
    // was incorrectly labeled as an opponent resource because the next action gives Treasure).
    const recipientText = `${raw} ${String(effect.contextClause || '')}`.replace(/[’]/g, "'");
    if (!effect.recipientScope) {
        if (/\b(?:(?:an?|each|target)\s+)?opponents?\s+creates?\b/i.test(recipientText) || /\bunder\s+(?:an?\s+)?opponent's\s+control\b/i.test(recipientText)) effect.recipientScope = 'opponent';
        else if (/\bunder\s+your\s+control\b/i.test(recipientText)) effect.recipientScope = 'you';
    }
    // Opponent creators and opponent-controlled destinations are beneficiaries/recipients, not
    // target objects. Keep that information in recipientScope rather than polluting target data.
    const recipientMentionIsNotTarget = /\bunder\s+(?:an?\s+)?opponent's\s+control\b|\b(?:(?:an?|each|target)\s+)?opponents?\s+creates?\b/i.test(recipientText);
    if (recipientMentionIsNotTarget && !/\btarget opponent\b/i.test(raw)) {
        if (targetProfile.scope === 'opponent' || targetProfile.scope === 'opponent_control') targetProfile.scope = null;
        if (targetProfile.object === 'opponent') targetProfile.object = null;
    }
    if (effect.recipientScope === 'opponent') effect.isOpponentBenefit = true;
    if (targetProfile.scope) {
        effect.controllerScope = targetProfile.scope;
        effect.restriction = Array.from(new Set([...(effect.restriction || []),
            ...(targetProfile.scope === 'you_control' ? ['controlledbyyou'] : []),
            ...(targetProfile.scope === 'opponent_control' ? ['controlledbyopponent'] : [])
        ]));
    }
    effect.quantityProfile = parseQuantityProfile(raw, effect.quantity);
    effect.gameStateConditionProfile = parseGameStateConditionProfile(`${relationshipText} ${raw}`);
    effect.triggerProfile = parseTriggerProfile(relationshipText);
    effect.isTriggered = Boolean(effect.triggerProfile && (effect.triggerProfile.type === 'event' || effect.triggerProfile.type === 'turn_window'));
    effect.isConditional = Boolean(effect.condition || effect.triggerProfile?.conditional || /\bif\b/i.test(relationshipText));
    effect.dependencyProfile = {
        hasThen: /\bthen\b/i.test(raw),
        hasIfYouDo: /\bif you do\b/i.test(raw),
        hasForEach: /\bfor each\b/i.test(raw),
        hasBasedOn: /\bbased on\b/i.test(raw),
        hasInstead: /\binstead\b/i.test(raw),
        hasUntil: /\buntil\b/i.test(raw),
        hasAsLongAs: /\bas long as\b/i.test(raw),
        role: effect.isCostEffect ? 'cost' : (/\bif you do\b/i.test(raw) ? 'dependent_followup' : (/\bthen\b/i.test(raw) ? 'followup' : 'primary'))
    };
    if (/\buntil end of turn\b|\bthis turn\b/i.test(raw)) effect.durationProfile = 'until_end_of_turn';
    else if (/\bas long as\b/i.test(raw)) effect.durationProfile = 'conditional_static';
    else if (/\bwhile\b/i.test(raw)) effect.durationProfile = 'while_condition';
    else if (effect.isStatic) effect.durationProfile = 'static';
    else effect.durationProfile = null;
    effect.effectMode = /\binstead\b/i.test(raw) ? 'replacement'
        : /\bprevent\b/i.test(raw) ? 'prevention'
        : /\bredirect\b/i.test(raw) ? 'redirection'
        : /\bcan't|cannot|can't be|prohibit/i.test(raw) ? 'prohibition'
        : 'normal';
    return effect;
}

function annotateEffectArray(effects) {
    (effects || []).forEach(e => annotateEffectRelationships(e, e.raw));
    return effects;
}

function parseCastTimingPermissionEffect(text) {
    const raw = String(text || '').trim().replace(/[’]/g, "'");
    if (!raw) return null;
    const grantsCastingPermission = /\b(?:you|each player|players)\s+(?:may|can)\s+cast\b/i.test(raw);
    const grantsInstantTiming = /\bas though\s+(?:they|it|those spells?)\s+(?:had|have)\s+flash\b|\bany time\s+(?:that\s+)?(?:you|they|a player|that player)\s+could cast an instant\b/i.test(raw);
    if (!grantsCastingPermission || !grantsInstantTiming) return null;

    // Capture the scope that precedes “spells”; a blank scope means all spells. Keep qualifiers
    // such as historic, artifact, creature, or noncreature as explicit mechanical restrictions.
    const scopeMatch = raw.match(/\bcast\s+([\s\S]{0,80}?)\bspells?\b/i);
    const scope = String(scopeMatch?.[1] || '').trim().replace(/^(?:a|an|any|the)\s+/i, '').replace(/\s+/g, ' ').toLowerCase();
    const normalizedScope = scope || 'all';
    const restriction = scope ? [scope.replace(/\s+/g, '_')] : [];
    return {
        raw: String(text || '').trim(),
        action: 'cast_permission',
        object: 'spell',
        target: null,
        restriction,
        castingScope: normalizedScope,
        timingPermission: 'instant_speed',
        isStatic: true,
        effectMode: 'normal'
    };
}

// Stateful/named mechanic profiles supplement the base clause parser. The profiles are attached
// as synthetic canonical nodes so both the mechanical graph and retrieval planner can reason about
// the mechanic as a connected rules package, while ordinary atoms still score each action.
function appendNamedMechanicProfiles(results, oracleText, cardContext = null) {
    const text = String(oracleText || '').replace(/[’]/g, "'");
    const typeLine = String(cardContext?.type_line || '').replace(/[’]/g, "'");
    const already = new Set((results || []).map(e => e?.mechanicProfile?.key).filter(Boolean));
    const add = (key, label, summary, traits, opts = {}) => {
        if (already.has(key)) return;
        already.add(key);
        const profile = {
            key, label, summary,
            family: opts.family || null,
            traits: Array.from(new Set(traits || [])),
            threshold: opts.threshold ?? null,
            quantity: opts.quantity ?? null,
            condition: opts.condition || '',
            sequence: opts.sequence || [],
            dimensions: opts.dimensions || [],
            isStatic: Boolean(opts.isStatic)
        };
        results.push({
            action: `mechanic_${key}`, object: null, target: null, restriction: [],
            mechanicProfile: profile, isStatic: profile.isStatic,
            raw: `[Named mechanic: ${label}] ${String(opts.evidence || text).slice(0, 420)}`,
            parentRuleText: String(opts.evidence || text).slice(0, 420),
            isSecondaryAtom: false, isCostEffect: false
        });
    };

    if (/\brecruit\b/i.test(text)) {
        const evidence = (text.match(/.{0,80}\brecruit\b.{0,240}/i) || [text])[0];
        add('recruit', 'Recruit', 'Recruit: draw a card, discard a card, then create a 1/1 white Human Soldier token if a nonland card was discarded.',
            ['keyword_action','draw','discard','conditional_token_creation','discarded_nonland','human_soldier_token','graveyard_setup'],
            { evidence, condition: 'discarded_nonland', sequence: ['draw','discard','conditional_create_token'], isStatic: false });
    }
    if (/\bstoried\b|\benduring story\b/i.test(text)) {
        const evidence = (text.match(/.{0,80}(?:storied|enduring story).{0,220}/i) || [text])[0];
        add('storied', 'Storied / enduring story', 'Storied is a static condition: control a permanent with storied and at least three artifacts, legendary permanents, and/or Sagas to gain the lasting enduring-story designation.',
            ['static_ability','condition_storied_permanent','count_artifacts_legendaries_sagas','threshold_three','persistent_player_designation','condition_is_not_lost','ward_one_reward'],
            { evidence, threshold: 3, condition: 'control_storied_permanent_and_three_artifacts_legendaries_or_sagas', isStatic: true });
    }
    if (/\bhone counters?\b/i.test(text)) {
        const evidence = (text.match(/.{0,90}\bhone counters?\b.{0,220}/i) || [text])[0];
        add('hone_counter', 'Hone counters', 'Each hone counter on an Equipment gives the equipped creature +1/+0; the modifier belongs to the equipped creature through the Equipment-counter relationship.',
            ['equipment_counter','equipped_creature','plus_one_power_per_hone_counter','continuous_rule_modifier','attachment_relationship'],
            { evidence, quantity: 1, condition: 'equipment_attached_to_creature', isStatic: true });
    }
    const empowerMatch = text.match(/\bempower Jace(?:\s+(\d+|x))?\b/i);
    if (empowerMatch) {
        const quantity = /^\d+$/.test(empowerMatch[1] || '') ? Number(empowerMatch[1]) : (empowerMatch[1] ? 'X' : null);
        const evidence = (text.match(/.{0,80}\bempower Jace(?:\s+(?:\d+|x))?.{0,220}/i) || [text])[0];
        add('empower_jace', 'Empower Jace', 'Empower Jace: if you control a Jace planeswalker token, add the specified loyalty counters to one; otherwise create the defined blue Jace planeswalker token, then add those counters.',
            ['keyword_action','conditional_token_creation','jace_planeswalker_token_only','loyalty_counter_placement','uses_existing_token_if_present','created_token_has_surveil_and_draw_abilities'],
            { evidence, quantity, condition: 'create_jace_token_only_if_none_controlled', sequence: ['check_controlled_jace_token','create_if_absent','add_loyalty_counters'] });
    }
    if (/\bHeartwood token\b|\bcreate(?:s)? a Heartwood\b/i.test(text)) {
        const evidence = (text.match(/.{0,90}\bHeartwood\b.{0,220}/i) || [text])[0];
        add('heartwood_token', 'Heartwood token', 'Create a predefined red and green artifact token with the Heartwood subtype and {T}: add {R} or {G}; the token also increases artifact count.',
            ['predefined_token','artifact','red','green','heartwood_subtype','tap_for_red_or_green','artifact_count_synergy'],
            { evidence });
    }
    if (/\bplan counters?\b/i.test(text) || /(?:—|–|-)\s*Plan\b/i.test(typeLine)) {
        const evidence = (text.match(/.{0,100}\bplan counters?\b.{0,250}/i) || [text])[0];
        const thresholdMatch = text.match(/when the (\w+) plan counter is put|when (?:the )?(\d+)(?:st|nd|rd|th)? plan counter is put/i);
        const wordNums = { first:1, second:2, third:3, fourth:4, fifth:5, sixth:6, seventh:7, eighth:8, ninth:9, tenth:10 };
        const threshold = thresholdMatch ? (Number(thresholdMatch[2]) || wordNums[String(thresholdMatch[1] || '').toLowerCase()] || null) : null;
        const traits = ['enchantment_subtype_plan','incremental_progress_counter','triggered_milestone_reward'];
        if (/\bsacrifice (?:this|it|that enchantment)\b/i.test(text)) traits.push('sacrifice_plan_at_milestone');
        if (/\bcontrol target opponent\b/i.test(text)) traits.push('control_opponent_next_turn_reward');
        if (/\bcreate\b[\s\S]{0,100}\btoken\b/i.test(text)) traits.push('incremental_token_reward');
        add('plan_progression', 'Plan progression', 'Plan enchantments are staged engines: triggers add plan counters and grant progress rewards, with a milestone trigger delivering a larger completion reward and sometimes sacrificing the Plan.',
            traits, { evidence, threshold, condition: 'plan_counter_milestone', isStatic: true });
    }
    if (/\bworthy\b/i.test(text) || /\bequip\b[\s\S]{0,100}\blegendary\b[\s\S]{0,100}\b(?:red and\/or white|red or white)\b[\s\S]{0,100}\bnot a Villain\b/i.test(text)) {
        const evidence = (text.match(/.{0,90}(?:worthy|equip).{0,220}/i) || [text])[0];
        add('worthy_equip', 'Worthy equipment restriction', 'Equipment activation legality requires a legendary red and/or white creature that is not a Villain; this is an equip-cost restriction, not a continuous detach condition.',
            ['equipment','equip_activation_restriction','legendary_creature','red_or_white','non_villain','restriction_checked_at_activation','existing_attachment_persists_if_condition_changes'],
            { evidence, condition: 'legendary_red_or_white_non_villain' });
    }
    if (/\bVibranium token\b/i.test(text)) {
        const evidence = (text.match(/.{0,90}\bVibranium token\b.{0,240}/i) || [text])[0];
        add('vibranium_token', 'Vibranium token', 'Create a predefined tapped artifact token with indestructible and {T}: add {C}; that mana cannot be spent to cast a nonartifact spell.',
            ['predefined_token','artifact','enters_tapped','indestructible','tap_for_colorless','mana_spend_restriction_nonartifact_spell','artifact_count_synergy'],
            { evidence });
    }
    if (/\b(?:prepared|preparation)\b/i.test(text) && /\b(?:exile|cast|spell)\b/i.test(text)) {
        const evidence = (text.match(/.{0,90}\b(?:prepared|preparation)\b.{0,220}/i) || [text])[0];
        add('prepared_spell', 'Prepare / prepared spell', 'Preparation links a host permanent to a specific spell exiled with it; casting permission depends on the host remaining prepared and the paired exile relationship.',
            ['paired_host_and_exiled_spell','prepared_designation','cast_permission_from_exile','host_state_dependency','relationship_must_not_be_flattened_to_generic_exile'],
            { evidence, condition: 'host_remains_prepared' });
    }
    // Multi-clause cards often exile a card from hand, add time counters, then later grant
    // permission to cast that same exiled card. Keep this linked as temporary hand processing,
    // not battlefield removal or generic exile.
    if (/\bexile\b[\s\S]{0,100}\bfrom (?:your|its owner's|that player's) hand\b/i.test(text) &&
        /\btime counters?\b/i.test(text) && /\b(?:may|can) cast\b/i.test(text) && /\bexil(?:e|ed)\b/i.test(text)) {
        add('delayed_hand_exile_cast_profile', 'Delayed hand-exile casting profile', 'Exile a card from hand, track it with time counters, and grant permission to cast that same card later from exile.',
            ['exile_from_hand','source_zone_hand_not_battlefield','time_counters','delayed_cast_permission_from_exile','paired_exiled_card_lifecycle','alternate_cast_permission'],
            { family: 'delayed_zone_access', evidence: text.slice(0,420), condition: 'hand_exile_time_counter_delayed_cast' });
    }

    // Aggregate high-level signatures for mechanics that share rules structure but should not
    // collapse into identical effects. Scryfall's `keywords` field is the safest signal; narrow
    // Oracle patterns supplement it for keyword actions and imported/test cards lacking metadata.
    const keywordSet = new Set((Array.isArray(cardContext?.keywords) ? cardContext.keywords : [])
        .map(k => normalizeMechanicBridgeKey(String(k || ''))).filter(Boolean));
    const hasKeyword = names => names.some(n => keywordSet.has(normalizeMechanicBridgeKey(n)));
    const detected = (defs) => defs.filter(d => hasKeyword(d.names || []) || (d.re && d.re.test(text)) || (d.typeRe && d.typeRe.test(typeLine)));
    const profileTraits = (defs) => Array.from(new Set(defs.flatMap(d => [
        `mechanic:${normalizeMechanicToken(d.key)}`,
        ...(d.traits || [])
    ])));

    const castingDefs = [
        { key:'flashback', names:['flashback'], re:/\bflashback\s*\{/i, traits:['cast_from_graveyard','alternate_cost'] },
        { key:'jump_start', names:['jump-start','jump start'], re:/\bjump-start\s*\{/i, traits:['cast_from_graveyard','discard_as_additional_cost'] },
        { key:'retrace', names:['retrace'], re:/\bretrace\s*\{/i, traits:['cast_from_graveyard','discard_land_as_additional_cost'] },
        { key:'escape', names:['escape'], re:/\bescape\s*\{/i, traits:['cast_from_graveyard','alternate_cost','exile_graveyard_as_cost'] },
        { key:'disturb', names:['disturb'], re:/\bdisturb\s*\{/i, traits:['cast_from_graveyard','transforms_or_two_face_lifecycle'] },
        { key:'aftermath', names:['aftermath'], re:/\baftermath\b/i, traits:['cast_from_graveyard','split_spell_halves','cast_permission_after_first_half'] },
        { key:'foretell', names:['foretell'], re:/\bforetell\s*\{/i, traits:['exile_face_down_from_hand','cast_later_from_exile','delayed_alternate_cost'] },
        { key:'plot', names:['plot'], re:/\bplot\s*\{/i, traits:['exile_from_hand','cast_later_without_mana_cost','timing_restriction'] },
        { key:'suspend', names:['suspend'], re:/\bsuspend\s+\d+\s*[—-]\s*\{/i, traits:['exile_from_hand_or_zone','time_counters','cast_when_last_counter_removed'] },
        { key:'warp', names:['warp'], re:/\bwarp\s*\{/i, traits:['cast_from_zone_with_limited_window','delayed_zone_change'] },
        { key:'madness', names:['madness'], re:/\bmadness\s*\{/i, traits:['discard_replacement','cast_from_exile_during_discard_resolution'] },
        { key:'miracle', names:['miracle'], re:/\bmiracle\s*\{/i, traits:['first_card_drawn_this_turn','alternate_cost','timing_window'] },
        { key:'rebound', names:['rebound'], re:/\brebound\b/i, traits:['cast_from_hand','exile_after_resolution','delayed_next_upkeep_cast_without_pay'] },
        { key:'adventure', names:['adventure'], re:/\badventure\b/i, traits:['separate_spell_face','exile_after_adventure_resolution','later_cast_creature_from_exile'] },
        { key:'overload', names:['overload'], re:/\boverload\s*\{/i, traits:['alternate_cost','changes_target_scope'] },
        { key:'cleave', names:['cleave'], re:/\bcleave\s*\{/i, traits:['alternate_cost','removes_or_changes_text'] },
        { key:'buyback', names:['buyback'], re:/\bbuyback\s*\{/i, traits:['additional_cost','return_spell_to_hand_instead_of_graveyard'] },
        { key:'replicate', names:['replicate'], re:/\breplicate\s*\{/i, traits:['additional_cost','creates_spell_copies'] },
        { key:'kicker', names:['kicker','multikicker'], re:/\b(?:multi)?kicker\s*\{/i, traits:['optional_additional_cost','enhanced_resolution'] },
        { key:'conspire', names:['conspire'], re:/\bconspire\b/i, traits:['additional_cost','tap_two_creatures','copies_spell'] },
        { key:'casualty', names:['casualty'], re:/\bcasualty\s*\{/i, traits:['additional_cost','sacrifice_creature','copies_spell_if_paid'] },
        { key:'bargain', names:['bargain'], re:/\bbargain\b/i, traits:['optional_additional_cost','sacrifice_artifact_enchantment_or_token','enhanced_resolution'] },
        { key:'spree', names:['spree'], re:/\bspree\s*\{/i, traits:['multiple_optional_cost_modes','choose_one_or_more_modes'] },
        { key:'tiered', names:['tiered'], re:/\btiered\b/i, traits:['choose_cost_tiers','effect_scales_by_cost_tier'] },
        { key:'offering', names:['offering'], re:/\boffering\s*\{/i, traits:['alternate_cost','sacrifice_creature_type','instant_speed_permission'] },
        { key:'convoke', names:['convoke'], re:/\bconvoke\b/i, traits:['tap_creatures_as_cost_reduction'] },
        { key:'improvise', names:['improvise'], re:/\bimprovise\b/i, traits:['tap_artifacts_as_cost_reduction'] },
        { key:'delve', names:['delve'], re:/\bdelve\b/i, traits:['exile_graveyard_cards_as_cost_reduction'] },
        { key:'emerge', names:['emerge'], re:/\bemerge\s*\{/i, traits:['sacrifice_creature_as_alternate_cost','cost_reduction_by_sacrificed_creature'] },
        { key:'evoke', names:['evoke'], re:/\bevoke\s*\{/i, traits:['alternate_cost','sacrifice_on_entry_if_alternate_cost'] },
        { key:'prototype', names:['prototype'], re:/\bprototype\s*\{/i, traits:['alternate_cost','alternate_characteristics'] },
        { key:'mutate', names:['mutate'], re:/\bmutate\s*\{/i, traits:['alternate_cast_target_creature','merge_permanent_characteristics'] },
        { key:'bestow', names:['bestow'], re:/\bbestow\s*\{/i, traits:['alternate_cost','aura_or_creature_mode'] },
        { key:'morph', names:['morph','megamorph'], re:/\b(?:mega)?morph\s*\{/i, traits:['face_down_cast','turn_face_up_cost'] },
        { key:'disguise', names:['disguise'], re:/\bdisguise\s*\{/i, traits:['face_down_cast','ward_on_face_down_creature','turn_face_up_cost'] },
        { key:'cloak', names:['cloak'], re:/\bcloak\b/i, traits:['put_face_down','turn_face_up_if_ability_allows'] },
        { key:'manifest', names:['manifest','manifest dread'], re:/\bmanifest(?: dread)?\b/i, traits:['put_card_face_down_as_permanent','may_turn_face_up_if_creature_card'] },
        { key:'impending', names:['impending'], re:/\bimpending\s*\{/i, traits:['permanent_enters_without_creature_type','time_counters','becomes_creature_after_delay'] },
        { key:'adventure_alt', names:['adventure'], re:/\binstant or sorcery adventure\b/i, traits:['separate_spell_face','exile_after_adventure_resolution','later_cast_creature_from_exile'] }
    ];
    const castingDetected = detected(castingDefs);
    if (castingDetected.length) {
        const tags = profileTraits(castingDetected);
        for (const d of castingDetected) {
            if (d.traits.some(t => /alternate_cost|additional_cost|cost_reduction/.test(t))) tags.push('cost:cast_cost_modified');
            if (d.traits.some(t => /cast_from_graveyard|cast_from_exile/.test(t))) tags.push('zone:cast_from_nonhand_zone');
            if (d.traits.some(t => /time_counters|delayed|later/.test(t))) tags.push('timing:delayed_or_limited');
        }
        const labels = castingDetected.map(d => d.key.replace(/_/g, ' '));
        add('casting_mode_profile', 'Casting mode / alternate cost profile', `Casting-mechanic profile: ${labels.join(', ')}. The engine compares the cast zone, additional or alternate cost, timing window, and resulting spell/permanent lifecycle as separate traits.`,
            [...new Set(tags)], { family: 'casting_mode', evidence: text.slice(0, 420), condition: 'casting_mode_rules_signature' });
    }

    const replayDefs = [
        { key:'storm', names:['storm'], re:/\bstorm\s*\(\s*when you cast this spell/i, traits:['copy_spell','scale_with_spells_previously_cast_this_turn'] },
        { key:'gravestorm', names:['gravestorm'], re:/\bgravestorm\s*\(/i, traits:['copy_spell','scale_with_permanents_put_into_graveyard_this_turn'] },
        { key:'cascade', names:['cascade'], re:/\bcascade\b[\s\S]{0,180}exile cards from the top/i, traits:['library_reveal_until_mana_value_bound','cast_without_paying','remaining_cards_to_bottom'] },
        { key:'discover', names:['discover'], re:/\bdiscover\s+\d+/i, traits:['library_reveal_until_mana_value_bound','choose_cast_without_paying_or_hand','remaining_cards_to_bottom'] },
        { key:'rebound', names:['rebound'], re:/\brebound\b/i, traits:['exile_after_resolution','cast_at_next_upkeep_without_pay'] },
        { key:'cipher', names:['cipher'], re:/\bcipher\b/i, traits:['exile_and_encode_on_creature','trigger_on_combat_damage_to_player','copy_then_cast_without_pay','paired_host_relationship'] },
        { key:'epic', names:['epic'], re:/\bepic\b/i, traits:['repeat_spell_copy_each_turn','prohibit_casting_spells_for_rest_of_game'] },
        { key:'ripple', names:['ripple'], re:/\bripple\s*\d+/i, traits:['reveal_top_n_on_cast','may_cast_matching_name'] },
        { key:'replicate', names:['replicate'], re:/\breplicate\s*\{/i, traits:['additional_cost','copy_spell_for_each_payment'] },
        { key:'demonstrate', names:['demonstrate'], re:/\bdemonstrate\b/i, traits:['copy_spell','opponent_also_gets_copy'] },
        { key:'buyback', names:['buyback'], re:/\bbuyback\s*\{/i, traits:['spell_returns_to_hand_on_resolution_if_cost_paid'] },
        { key:'encore', names:['encore'], re:/\bencore\s*\{/i, traits:['graveyard_activated_ability','create_attacking_copies','sacrifice_at_end_step'] }
    ];
    const replayDetected = detected(replayDefs);
    if (replayDetected.length) {
        const tags = profileTraits(replayDetected);
        tags.push('spell:copy_or_delayed_recast_family');
        const labels = replayDetected.map(d => d.key);
        add('spell_replay_profile', 'Spell copy / replay profile', `Spell-copy and replay profile: ${labels.join(', ')}. The engine preserves what is copied, what event scales or triggers it, whether a copy is cast, and any exile or delayed-cast relation.`,
            [...new Set(tags)], { family: 'spell_replay', evidence: text.slice(0, 420), condition: 'spell_copy_replay_rules_signature' });
    }

    const combatDefs = [
        { key:'flying', names:['flying'], re:/\bflying\b/i, traits:['evasion_flying','harder_to_block_by_nonflying_without_reach'] },
        { key:'reach', names:['reach'], re:/\breach\b/i, traits:['can_block_flying'] },
        { key:'menace', names:['menace'], re:/\bmenace\b/i, traits:['requires_two_or_more_blockers'] },
        { key:'first_strike', names:['first strike'], re:/\bfirst strike\b/i, traits:['first_combat_damage_step'] },
        { key:'double_strike', names:['double strike'], re:/\bdouble strike\b/i, traits:['first_combat_damage_step','regular_combat_damage_step'] },
        { key:'trample', names:['trample'], re:/\btrample\b/i, traits:['excess_combat_damage_to_defender_or_planeswalker'] },
        { key:'vigilance', names:['vigilance'], re:/\bvigilance\b/i, traits:['does_not_tap_to_attack'] },
        { key:'haste', names:['haste'], re:/\bhaste\b/i, traits:['ignore_summoning_sickness_attack_and_tap'] },
        { key:'defender', names:['defender'], re:/\bdefender\b/i, traits:['cannot_attack_normally'] },
        { key:'deathtouch', names:['deathtouch'], re:/\bdeathtouch\b/i, traits:['damage_lethal_to_creatures'] },
        { key:'lifelink', names:['lifelink'], re:/\blifelink\b/i, traits:['damage_causes_controller_life_gain'] },
        { key:'indestructible', names:['indestructible'], re:/\bindestructible\b/i, traits:['cannot_be_destroyed'] },
        { key:'hexproof', names:['hexproof'], re:/\bhexproof\b/i, traits:['opponent_targeting_restriction'] },
        { key:'ward', names:['ward'], re:/\bward\s*\{/i, traits:['targeting_cost_or_penalty'] },
        { key:'shadow', names:['shadow'], re:/\bshadow\b/i, traits:['shadow_combat_blocking_restriction'] },
        { key:'skulk', names:['skulk'], re:/\bskulk\b/i, traits:['cannot_be_blocked_by_higher_power_creatures'] },
        { key:'landwalk', names:['islandwalk','swampwalk','mountainwalk','forestwalk','plainswalk','landwalk'], re:/\b(?:island|swamp|mountain|forest|plains)walk\b/i, traits:['landwalk_evasion','defending_player_controls_matching_land'] },
        { key:'horsemanship', names:['horsemanship'], re:/\bhorsemanship\b/i, traits:['evasion_horsemanship','matching_horsemanship_block_rule'] },
        { key:'fear', names:['fear'], re:/\bfear\b/i, traits:['evasion_artifact_or_black_block_restriction'] },
        { key:'intimidate', names:['intimidate'], re:/\bintimidate\b/i, traits:['evasion_shared_color_or_artifact_block_restriction'] },
        { key:'skulk', names:['skulk'], re:/\bskulk\b/i, traits:['cannot_be_blocked_by_higher_power_creatures'] },
        { key:'space_sculptor', names:['space sculptor'], re:/\bspace sculptor\b/i, traits:['combat_blocking_rules_exception','spacecraft_creature_block_interaction'] },
        { key:'must_be_blocked', names:['must be blocked'], re:/\b(?:must|must be)\s+blocked\b|\bif able,? (?:this|that) creature blocks\b/i, traits:['forced_blocking_requirement','attacking_or_blocking_condition'] },
        { key:'banding', names:['banding'], re:/\bbanding\b/i, traits:['attack_block_assignment_rules','attacking_player_assigns_blocker_damage'] },
        { key:'bushido', names:['bushido'], re:/\bbushido\s+\d+/i, traits:['combat_triggered_stat_bonus'] },
        { key:'flanking', names:['flanking'], re:/\bflanking\s+\d+/i, traits:['blocker_stat_penalty'] },
        { key:'provoke', names:['provoke'], re:/\bprovoke\b/i, traits:['force_creature_to_block','untap_defending_creature'] },
        { key:'annihilator', names:['annihilator'], re:/\bannihilator\s+\d+/i, traits:['attacking_trigger_opponent_sacrifice'] },
        { key:'myriad', names:['myriad'], re:/\bmyriad\b/i, traits:['attacking_copies_against_other_opponents','exile_copies_end_combat'] },
        { key:'mobilize', names:['mobilize'], re:/\bmobilize\s+\d+/i, traits:['attack_trigger_tapped_attacking_token','sacrifice_token_end_combat'] },
        { key:'toxic', names:['toxic'], re:/\btoxic\s+\d+/i, traits:['combat_damage_player_poison_counters'] },
        { key:'decayed', names:['decayed'], re:/\bdecayed\b/i, traits:['cannot_block','sacrifice_after_attacking'] }
    ];
    const combatDetected = detected(combatDefs);
    if (combatDetected.length) {
        const tags = profileTraits(combatDetected);
        const labels = combatDetected.map(d => d.key);
        const subtypeTraits = [];
        if (combatDetected.some(d => d.traits.some(t => /evasion|walk|cannot_be_blocked/.test(t)))) subtypeTraits.push('combat_family:evasion');
        if (combatDetected.some(d => d.traits.some(t => /damage_step|damage_causes|lethal|excess_combat_damage/.test(t)))) subtypeTraits.push('combat_family:damage_rules');
        if (combatDetected.some(d => d.traits.some(t => /attack|block|blocker|combat_triggered/.test(t)))) subtypeTraits.push('combat_family:attack_block_interaction');
        add('combat_rules_profile', 'Combat rules profile', `Combat mechanic profile: ${labels.join(', ')}. Exact keyword rules are kept distinct; related combat functions share only their relevant subfamily traits.`,
            [...new Set([...tags, ...subtypeTraits])], { family: 'combat_rules', evidence: text.slice(0, 420), condition: 'combat_keyword_rules_signature' });
    }

    const stateDefs = [
        { key:'monarch', names:['monarch'], re:/\bbecome the monarch\b|\bthe monarch\b/i, traits:['player_designation','end_step_card_draw','combat_damage_can_change_designation'] },
        { key:'initiative', names:['initiative'], re:/\btake the initiative\b|\bthe initiative\b/i, traits:['player_designation','venture_into_undercity','combat_damage_can_change_designation'] },
        { key:'daybound', names:['daybound','nightbound'], re:/\bdaybound\b|\bnightbound\b/i, traits:['global_day_night_designation','transform_based_on_spells_cast'] },
        { key:'ascend', names:['ascend'], re:/\bascend\b|\bcity's blessing\b/i, traits:['ten_permanents_threshold','persistent_city_blessing_designation'] },
        { key:'venture_dungeon', names:['venture into the dungeon','venture into undercity'], re:/\bventure into (?:the )?(?:undercity|dungeon)\b/i, traits:['dungeon_room_progression','one_room_reward_per_venture'] },
        { key:'ring_tempts_you', names:['the ring tempts you'], re:/\bthe ring tempts you\b/i, traits:['player_ring_designation','ring_bearer_choice','ring_level_progression'] },
        { key:'attraction', names:['attraction','visit an attraction','assemble an attraction'], re:/\b(?:visit|assemble) (?:an? )?attraction\b/i, traits:['game_component_attraction','visit_by_die_roll','attraction-specific_rewards'] },
        { key:'contraption', names:['contraption','assemble a contraption'], re:/\bassemble a contraption\b/i, traits:['game_component_contraption','sprocket_turn_progression'] },
        { key:'the_ring_bearer', names:['ring-bearer','ring bearer'], re:/\bring bearer\b/i, traits:['chosen_creature_role','ring_level_grants_abilities'] }
    ];
    const stateDetected = detected(stateDefs);
    if (stateDetected.length) {
        const tags = profileTraits(stateDetected);
        add('stateful_game_profile', 'Stateful game mechanic profile', `Stateful game mechanics: ${stateDetected.map(d => d.key.replace(/_/g,' ')).join(', ')}. The engine tracks designation, progression, and event hooks as distinct game-state concepts.`,
            [...new Set(tags)], { family: 'stateful_game', evidence: text.slice(0, 420), condition: 'stateful_game_designation_or_progression' });
    }

    const progressionDefs = [
        { key:'saga', names:['saga'], re:/\bchapter [ivx0-9]+\b|\bread ahead\b/i, typeRe:/\bSaga\b/i, traits:['chapter_counter','chapter_trigger','sacrifice_after_final_chapter'] },
        { key:'class', names:['class'], re:/\blevel up\s*\{/i, typeRe:/—.*\bClass\b/i, traits:['level_counter','level_activated_abilities','incremental_level_unlock'] },
        { key:'case', names:['case'], re:/\bsolved\b/i, typeRe:/—.*\bCase\b/i, traits:['unlock_condition','solved_designation','ongoing_ability_after_solved'] },
        { key:'room', names:['room'], re:/\bunlock this door\b|\bdoors? you control\b/i, typeRe:/—.*\bRoom\b/i, traits:['unlockable_room','door_choice','room_ability_activation'] },
        { key:'monstrosity', names:['monstrosity'], re:/\bmonstrosity\s+\d+/i, traits:['one_time_if_not_monster','counter_scaling','state_change_monster'] },
        { key:'adapt', names:['adapt'], re:/\badapt\s+\d+/i, traits:['counter_addition_if_no_plus_counters'] },
        { key:'level_up', names:['level up'], re:/\blevel up\s*\{/i, traits:['level_counter','incremental_ability_unlock'] },
        { key:'craft', names:['craft'], re:/\bcraft with\b/i, traits:['exile_or_sacrifice_materials','transform_after_cost'] },
        { key:'battle_siege', names:['battle','siege'], typeRe:/\bBattle\b/i, traits:['battle_permanent','defense_counter_tracking','protecting_player_condition','defeat_or_battle_state_transition'] },
        { key:'spacecraft_station', names:['spacecraft','station'], typeRe:/—.*\b(?:Spacecraft|Station)\b/i, traits:['spacecraft_or_station_permanent','crew_or_station_progression','state_dependent_characteristics'] },
        { key:'transform', names:['transform'], re:/\btransform this (?:creature|permanent|card)\b/i, traits:['two_faced_state_transition'] },
        { key:'meld', names:['meld'], re:/\bmelds? with\b/i, traits:['combine_named_cards_into_single_permanent'] },
        { key:'reconfigure', names:['reconfigure'], re:/\breconfigure\s*\{/i, traits:['equipment_or_creature_mode','attach_and_unattach_transition'] },
        { key:'vehicle_crew', names:['crew','living metal'], re:/\bcrew\s*\d+/i, traits:['tap_creatures_by_total_power','becomes_artifact_creature_until_end_of_turn'] },
        { key:'incubate', names:['incubate'], re:/\bincubate\s+\d+/i, traits:['create_incubator_token_with_counters','transform_token_to_phyrexian_creature'] },
        { key:'earthbend', names:['earthbend'], re:/\bearthbend\s+\d+/i, traits:['land_becomes_creature','plus_one_counters','tapped_mana_ability'] },
        { key:'blight', names:['blight'], re:/\bblight\s+\d+/i, traits:['opponent_places_minus_one_counters','opponent_chooses_creatures'] },
        { key:'time_travel', names:['time travel','time travel action'], re:/\btime travel\b/i, traits:['modify_time_counters','suspended_or_related_card_progression'] }
    ];
    const progressionDetected = detected(progressionDefs);
    if (progressionDetected.length) {
        const tags = profileTraits(progressionDetected);
        add('permanent_progression_profile', 'Permanent progression / state transition profile', `Permanent progression mechanics: ${progressionDetected.map(d => d.key.replace(/_/g,' ')).join(', ')}. Counter progression, unlocking, transforming, attaching, and final-state conditions remain separate traits.`,
            [...new Set(tags)], { family: 'permanent_progression', evidence: text.slice(0, 420), condition: 'permanent_progression_state_transition' });
    }

    const politicalDefs = [
        { key:'vote', names:['vote'], re:/\bvote\b|\bvotes\b/i, traits:['players_choose_between_options','vote_count_resolves_choice','opponent_choice_can_change_outcome'] },
        { key:'council_dilemma', names:["council's dilemma","council's dilemma"], re:/\bcouncil's dilemma\b/i, traits:['each_player_chooses_option','choices_resolve_by_option_votes','multiplayer_choice'] },
        { key:'join_forces', names:['join forces'], re:/\bjoin forces\b/i, traits:['optional_mana_contribution_by_players','shared_scaling_resource','multiplayer_choice'] },
        { key:'tempting_offer', names:['tempting offer'], re:/\btempting offer\b/i, traits:['opponent_may_accept_offer','opponent_choice','repeatable_opponent_choice_trigger'] },
        { key:'will_of_the_council', names:['will of the council'], re:/\bwill of the council\b/i, traits:['voting','majority_decides_effect','multiplayer_choice'] },
        { key:'villainous_choice', names:['villainous choice'], re:/\bvillainous choice\b/i, traits:['each_opponent_selects_cost_or_effect','opponent_choice','multiplayer_choice'] },
        { key:'parley', names:['parley'], re:/\bparley\b/i, traits:['reveal_top_card_per_player','shared_reveal_count','multiplayer_condition'] },
        { key:'opponent_choice', names:['opponent choice'], re:/\b(?:an opponent|each opponent|target opponent)\s+(?:chooses?|may choose|votes?)\b/i, traits:['opponent_makes_choice','opponent_choice_affects_outcome'] }
    ];
    const politicalDetected = detected(politicalDefs);
    if (politicalDetected.length) {
        const tags = profileTraits(politicalDetected);
        add('multiplayer_decision_profile', 'Multiplayer choice / politics profile', `Multiplayer decision mechanics: ${politicalDetected.map(d => d.key.replace(/_/g,' ')).join(', ')}. The model preserves who chooses, whether players vote or contribute resources, and whether opponent decisions change the outcome.`,
            [...new Set(tags)], { family: 'multiplayer_decision', evidence: text.slice(0,420), condition: 'multiplayer_player_choice_or_vote' });
    }

    const auxiliaryDefs = [
        { key:'planechase', names:['planeswalk','planechase'], re:/\bplaneswalk\b|\bplanechase\b/i, traits:['shared_plane_or_phenomenon_state','planeswalk_event','global_game_rule'] },
        { key:'archenemy_scheme', names:['scheme','archenemy'], re:/\b(archenemy|scheme)\b/i, traits:['shared_scheme_zone','scheme_reveal_or_set_in_motion','asymmetric_multiplayer_role'] },
        { key:'sticker_ticket', names:['sticker','ticket'], re:/\bstickers?\b|\btickets?\b/i, traits:['sticker_or_ticket_resource','object_attaches_sticker','ticket_payment_or_count'] },
        { key:'conspiracy_hidden_agenda', names:['conspiracy','hidden agenda','double agenda'], re:/\b(hidden agenda|double agenda|conspiracy)\b/i, traits:['outside_deck_setup_choice','face_down_designation','deck_construction_or_start_game_rule'] }
    ];
    const auxiliaryDetected = detected(auxiliaryDefs);
    if (auxiliaryDetected.length) {
        const tags = profileTraits(auxiliaryDetected);
        add('auxiliary_game_component_profile', 'Auxiliary game component profile', `Auxiliary game components: ${auxiliaryDetected.map(d => d.key.replace(/_/g,' ')).join(', ')}. The model records special zones, setup choices, physical game components, and global game-state effects separately from ordinary card actions.`,
            [...new Set(tags)], { family: 'auxiliary_game_component', evidence: text.slice(0,420), condition: 'auxiliary_component_or_global_game_state' });
    }

    // Rules-changing effects need their own profile because replacement, prevention,
    // phasing and regeneration are not interchangeable with destruction or ordinary stat buffs.
    const rulesModificationDefs = [
        { key:'replacement', re:/\binstead\b|\bwould\b[\s\S]{0,100}\binstead\b/i, traits:['replacement_effect','changes_would_happen_event','instead_replacement_wording'] },
        { key:'damage_prevention', re:/\bprevent(?:s|ed|ing)?\b[\s\S]{0,90}\bdamage\b/i, traits:['damage_prevention_effect','damage_event_modified','not_damage_based_removal'] },
        { key:'regeneration', re:/\bregenerate\b|\bregenerates\b/i, traits:['regeneration_shield','replace_destroy_event','tap_and_remove_damage'] },
        { key:'phasing', re:/\bphases? out\b|\bphasing\b|\bphases? in\b/i, traits:['phasing_state_transition','temporary_out_of_phase','not_zone_change'] },
        { key:'protection', re:/\bprotection from\b/i, traits:['protection_keyword_rules','damage_prevention','targeting_restriction','blocking_restriction'] },
        { key:'ward', re:/\bward\s*\{/i, traits:['ward_keyword_rules','targeting_cost_trigger','targeted_spell_or_ability_tax'] },
        { key:'hexproof', re:/\bhexproof\b/i, traits:['hexproof_keyword_rules','opponent_targeting_restriction'] },
        { key:'shroud', re:/\bshroud\b/i, traits:['shroud_keyword_rules','all_targeting_restriction'] }
    ];
    const rulesModificationDetected = rulesModificationDefs.filter(d => d.re.test(text));
    if (rulesModificationDetected.length) {
        const tags = profileTraits(rulesModificationDetected);
        add('rules_modification_profile', 'Replacement / prevention / rules-modification profile', `Rules-modification mechanics: ${rulesModificationDetected.map(d => d.key).join(', ')}. Replacement effects, damage prevention, regeneration, phasing, and targeting restrictions remain separate from destruction and zone movement.`,
            [...new Set(tags)], { family: 'rules_modification', evidence: text.slice(0,420), condition: 'replacement_prevention_or_rule_restriction' });
    }

    const lowerConditionProfile = parseGameStateConditionProfile(text);
    if (lowerConditionProfile?.conditions?.length) {
        const conditionTraits = lowerConditionProfile.conditions.flatMap(c => [
            `condition:${c.key}`, `dimension:${c.dimension}`, c.measure ? `measure:${c.measure}` : '',
            c.zone ? `zone:${c.zone}` : '', c.scope ? `scope:${c.scope}` : '',
            c.window ? `window:${c.window}` : '', c.operator ? `operator:${c.operator}` : '',
            c.threshold != null ? `threshold:${c.threshold}` : '', c.qualifier ? `qualifier:${c.qualifier}` : ''
        ].filter(Boolean));
        add('game_state_condition_profile', 'Game-state condition signature', `Structured game-state conditions: ${lowerConditionProfile.conditions.map(c => `${c.key} (${c.dimension}${c.threshold == null ? '' : `, ${c.operator} ${c.threshold}`})`).join('; ')}. Conditions count the relevant resource, zone, event window, and threshold rather than serving as generic keywords.`,
            [...new Set([...lowerConditionProfile.traits.map(t => `condition_name:${t}`), ...conditionTraits])],
            { family: 'game_state_condition', threshold: lowerConditionProfile.threshold, dimensions: lowerConditionProfile.conditions, condition: lowerConditionProfile.conditions.map(c => c.key).join('|'), evidence: text.slice(0,420), isStatic: true });
        results[results.length - 1].gameStateConditionProfile = lowerConditionProfile;
    }
}

function parseGameStateConditionProfile(value) {
    const text = String(value || '').replace(/[’]/g, "'");
    const lower = text.toLowerCase();
    const traits = [];
    const conditions = [];
    const add = (key, test, spec = {}) => {
        if (!test.test(lower)) return;
        traits.push(key);
        conditions.push({
            key,
            dimension: spec.dimension || key,
            measure: spec.measure || null,
            zone: spec.zone || null,
            scope: spec.scope || null,
            window: spec.window || null,
            operator: spec.operator || 'condition_met',
            threshold: spec.threshold ?? null,
            unit: spec.unit || null,
            qualifier: spec.qualifier || null
        });
    };
    const extractThreshold = (patterns, fallback = null) => {
        for (const re of patterns) {
            const m = lower.match(re);
            if (m) {
                const raw = m[1];
                if (raw && /^\d+$/.test(raw)) return Number(raw);
                const words = { zero:0, one:1, two:2, three:3, four:4, five:5, six:6, seven:7, eight:8, nine:9, ten:10 };
                if (raw && words[raw] != null) return words[raw];
            }
        }
        return fallback;
    };
    const graveyardThreshold = extractThreshold([/\b(\d+) or more cards? in your graveyard\b/, /\b(seven|six|five|four|three|two) or more cards? in your graveyard\b/]);
    const artifactThreshold = extractThreshold([/\b(\d+) or more artifacts?\b/, /\b(three|four|five|six|seven) or more artifacts?\b/]);
    const numbers = [...lower.matchAll(/\b(\d+)\s+or more\b/g)].map(m => Number(m[1]));

    add('devotion', /\bdevotion to\b|\bfor each mana symbol of .* among permanents you control/, { dimension:'mana_symbols_among_controlled_permanents', measure:'colored_mana_symbols', scope:'you_control', qualifier:'color_specific' });
    add('party', /\bparty\b|\bcleric\b[\s\S]{0,50}\brogue\b[\s\S]{0,50}\bwarrior\b/, { dimension:'distinct_party_roles', measure:'distinct_creature_roles', threshold:4, scope:'you_control' });
    add('domain', /\bnumber of basic land types\b|\bdomain\b/, { dimension:'basic_land_types_among_controlled_lands', measure:'distinct_land_types', scope:'you_control' });
    add('undergrowth', /\bcreature cards? in your graveyard\b/, { dimension:'graveyard_card_count', measure:'creature_cards', zone:'graveyard', scope:'you' });
    add('fathomless_descent', /\bpermanent cards? in your graveyard\b/, { dimension:'graveyard_card_count', measure:'permanent_cards', zone:'graveyard', scope:'you' });
    add('vivid', /\bcharge counters? on this permanent\b|\bvivid\b/, { dimension:'counter_count', measure:'charge_counters', scope:'this_permanent' });
    add('coven', /\bthree or more creatures? with different powers\b|\bcoven\b/, { dimension:'controlled_creatures_different_powers', measure:'creatures', threshold:3, scope:'you_control', qualifier:'different_powers' });
    add('metalcraft', /\bthree or more artifacts\b|\bmetalcraft\b/, { dimension:'controlled_artifact_count', measure:'artifacts', threshold:artifactThreshold ?? 3, scope:'you_control' });
    add('ferocious', /\bcreature you control has power 4 or greater\b|\bferocious\b/, { dimension:'max_power_among_controlled_creatures', measure:'creature_power', threshold:4, operator:'greater_than_or_equal' });
    add('formidable', /\btotal power 8 or greater\b|\bformidable\b/, { dimension:'total_power_controlled_creatures', measure:'power_sum', threshold:8, operator:'greater_than_or_equal' });
    add('delirium', /\bfour or more card types among cards in your graveyard\b|\bdelirium\b/, { dimension:'distinct_card_types_in_graveyard', measure:'card_types', threshold:4, zone:'graveyard', scope:'you' });
    add('spell_mastery', /\btwo or more instant and\/or sorcery cards? in your graveyard\b|\bspell mastery\b/, { dimension:'graveyard_card_count', measure:'instant_and_sorcery_cards', threshold:2, zone:'graveyard', scope:'you' });
    add('threshold', /\bseven or more cards? in your graveyard\b|\bthreshold\b/, { dimension:'graveyard_card_count', measure:'cards', threshold:graveyardThreshold ?? 7, zone:'graveyard', scope:'you' });
    add('descend', /\bpermanent card was put into your graveyard this turn\b|\bdescend\b/, { dimension:'zone_change_event_count', measure:'permanent_cards_put_into_graveyard', threshold:1, window:'this_turn', scope:'you' });
    add('morbid', /\bcreature died this turn\b|\bcreature has died this turn\b|\bmorbid\b/, { dimension:'zone_change_event_count', measure:'creatures_died', threshold:1, window:'this_turn' });
    add('raid', /\battacked this turn\b|\braid\b/, { dimension:'combat_event', measure:'you_attacked', threshold:1, window:'this_turn', scope:'you' });
    add('revolt', /\ba permanent you controlled left the battlefield this turn\b|\brevolt\b/, { dimension:'zone_change_event_count', measure:'your_permanents_left_battlefield', threshold:1, window:'this_turn', scope:'you_control' });
    add('celebration', /\btwo or more nonland permanents entered the battlefield\b|\bcelebration\b/, { dimension:'zone_change_event_count', measure:'nonland_permanents_entered_battlefield', threshold:2, window:'this_turn' });
    add('expend', /\bspent \d+ or more mana to cast spells this turn\b|\bexpend\s*\d+\b|\bexpend\b/, { dimension:'mana_spent_casting_spells', measure:'mana', threshold:extractThreshold([/\bexpend\s*(\d+)/, /\bspent\s+(\d+) or more mana/]), window:'this_turn' });
    add('infusion', /\bgained life this turn\b|\binfusion\b/, { dimension:'life_gain_event', measure:'life_gained', threshold:1, window:'this_turn', scope:'you' });
    add('historic', /\bhistoric spell\b|\bhistoric permanent\b|\bhistoric\b/, { dimension:'historic_card_class', measure:'artifact_legendary_saga', qualifier:'card_type_or_supertype_group' });
    add('modified', /\bmodified creature\b|\bmodified creatures\b|\bmodified\b/, { dimension:'permanent_modification_state', measure:'aura_equipment_or_counter', scope:'creature' });
    add('commit_a_crime', /\bcommitted a crime this turn\b|\bcommit a crime\b/, { dimension:'crime_event', measure:'targeted_opponent_or_opponent_permanent_spell', threshold:1, window:'this_turn' });
    add('outlaw', /\boutlaw\b|\bassassin, mercenary, pirate, rogue, and warlock\b/, { dimension:'controlled_creature_type_group', measure:'assassin_mercenary_pirate_rogue_warlock', scope:'you_control' });
    add('hellbent', /\bno cards? in your hand\b|\bhellbent\b/, { dimension:'hand_card_count', measure:'cards', threshold:0, operator:'equal', zone:'hand', scope:'you' });
    add('fateful_hour', /\bfive or less life\b|\bfateful hour\b/, { dimension:'life_total', measure:'life', threshold:5, operator:'less_than_or_equal', scope:'you' });
    add('city_blessing', /\bcity's blessing\b|\bten or more permanents\b/, { dimension:'controlled_permanent_count', measure:'permanents', threshold:10, operator:'greater_than_or_equal', scope:'you_control', qualifier:'persistent_designation_once_gained' });
    add('battalion', /\bwhenever this creature and at least two other creatures attack\b|\bbattalion\b/, { dimension:'attacking_creature_count', measure:'creatures', threshold:3, window:'this_attack' });
    add('pack_tactics', /\btotal power 6 or greater\b|\bpack tactics\b/, { dimension:'attacking_creature_total_power', measure:'power_sum', threshold:6, window:'this_attack' });
    add('poison_threshold', /\bthree or more poison counters?\b|\bten or more poison counters?\b|\bpoison counter threshold\b/, { dimension:'player_poison_counter_count', measure:'poison_counters', threshold:extractThreshold([/\b(\d+) or more poison counters?/]) });
    add('corrupted', /\bcorrupted\b/, { dimension:'opponent_poison_counter_count', measure:'poison_counters', threshold:3, operator:'greater_than_or_equal', qualifier:'opponent_has_poison_counters' });

    if (!traits.length) return null;
    const uniqueConditions = Array.from(new Map(conditions.map(c => [c.key, c])).values());
    const legacyThreshold = numbers.length ? Math.max(...numbers) : (graveyardThreshold ?? artifactThreshold ?? null);
    return { traits: Array.from(new Set(traits)).sort(), threshold: legacyThreshold, conditions: uniqueConditions };
}

function parseMTGEffect(oracleText, cardContext = null) {
    if (!oracleText) return [];

    // Split on sentences, semicolons, bullet points, and rule keywords. Newlines are always a
    // hard boundary (not just when preceded by sentence punctuation) - otherwise a modal header
    // ending in an em dash ("Choose one —") never separates from its first bullet line, since
    // "—" isn't sentence punctuation.
    // Keep the printed rule/sentence that owns each split clause. Splitting on "then" is useful
    // for extracting separate actions, but those actions still share semantic context: for example,
    // "look at the top card of that player's library, then exile it" is library access, not removal.
    const ruleGroups = String(oracleText)
        .split(/\n+|(?<=[.!?;])\s+/)
        .map(s => s.trim())
        .filter(Boolean);
    const clauses = [];
    const parentRuleTexts = [];
    const previousRuleTexts = [];
    let mostRecentLandSearch = '';
    let mostRecentLandSearchIndex = -100;
    for (let ruleGroupIndex = 0; ruleGroupIndex < ruleGroups.length; ruleGroupIndex++) {
        const ruleGroupText = ruleGroups[ruleGroupIndex];
        const isSearchForLandGroup = /\bsearch(?:es)?\s+(?:your|the|a|target player's|target opponent's)?\s*library\b[\s\S]{0,180}\b(?:basic\s+)?land cards?\b/i.test(ruleGroupText);
        const distanceToLandSearch = ruleGroupIndex - mostRecentLandSearchIndex;
        const relatedLandSearchContext = mostRecentLandSearch && distanceToLandSearch > 0 && distanceToLandSearch <= 3
            ? mostRecentLandSearch
            : (ruleGroupIndex > 0 ? ruleGroups[ruleGroupIndex - 1] : '');
        const ruleClauses = ruleGroupText.split(/\b(?:then|otherwise)\b/i).map(s => s.trim()).filter(Boolean);
        for (const ruleClause of ruleClauses) {
            clauses.push(ruleClause);
            parentRuleTexts.push(ruleGroupText);
            previousRuleTexts.push(relatedLandSearchContext);
        }
        if (isSearchForLandGroup) {
            mostRecentLandSearch = ruleGroupText;
            mostRecentLandSearchIndex = ruleGroupIndex;
        }
    }

    // Modal spells ("Choose one —" / "Choose two —" / "Choose one or more —") list their modes
    // as separate bullet-prefixed lines. Track the active mode group across clauses so each
    // mode is tagged with which group and "choose how many" header it belongs to, instead of
    // looking like unrelated standalone effects (project spec: multiple simultaneous modes).
    const modalHeaderRegex = /^\s*choose\s+(up to two|up to three|up to four|one or more|any number|one|two|three|four)\b(?:\s*[—–:-]|\s*\.)?\s*$/i;
    const bulletPrefixRegex = /^[•●]\s*|^-\s+/;
    let activeModeGroup = null;
    let modeGroupCounter = 0;

    const results = [];

    for (let clauseIndex = 0; clauseIndex < clauses.length; clauseIndex++) {
        const rawClause = clauses[clauseIndex];
        const parentRuleText = parentRuleTexts[clauseIndex] || rawClause;
        const previousRuleText = previousRuleTexts[clauseIndex] || '';
        const modalHeaderMatch = rawClause.match(modalHeaderRegex);
        if (modalHeaderMatch) {
            modeGroupCounter++;
            activeModeGroup = { count: modalHeaderMatch[1].toLowerCase(), groupId: modeGroupCounter };
            continue; // the header itself isn't a scoreable effect
        }

        const isBulletLine = bulletPrefixRegex.test(rawClause);
        const clause = rawClause.replace(bulletPrefixRegex, '');
        // A mode-count instruction sentence belongs to the modal header, but is not itself an
        // option. Keep the group active while skipping it instead of resetting before the bullets.
        if (activeModeGroup && !isBulletLine && /^(?:you may choose (?:the )?same mode|you may choose any (?:one )?mode|you may choose modes|choose the same mode)\b/i.test(clause)) {
            continue;
        }

        const { costText, effectText } = splitActivationCost(clause);

        const parsed =
            parseCastTimingPermissionEffect(effectText) ||
            parseCostReductionEffect(effectText) ||
            parseCounterEffect(effectText) ||
            parseSearchEffect(effectText) ||
            parseTokenEffect(effectText) ||
            parseAnthemEffect(effectText) ||
            parseCounterPlacementEffect(effectText) ||
            parseControlChangeEffect(effectText) ||
            parseTapEffect(effectText) ||
            parseLibraryActionEffect(effectText) ||
            parseDamageEffect(effectText) ||
            parseManaAbilityEffect(effectText) ||
            parseLifeEffect(effectText) ||
            parseZoneMovementEffect(effectText) ||
            {
                raw: clause,
                action: "generic",
                object: null,
                target: /\btarget\b/i.test(effectText) ? "target" : null,
                restriction: extractMTGRestrictions(effectText)
            };
        parsed.raw = parsed.raw || clause;
        parsed.parentRuleText = parsed.parentRuleText || parentRuleText;
        parsed.previousRuleText = parsed.previousRuleText || previousRuleText;

        // The sub-parsers capture restrictions from the text BEFORE the noun ("destroy target
        // [artifact] creature"), so a qualifier that trails the noun - "destroy target creature
        // YOU CONTROL" - was being dropped entirely. That's the single most important restriction
        // there is: it flips an effect from removal into a sacrifice outlet. Re-scan the whole
        // clause for control scope and merge it in, so the contradiction penalty can actually see
        // it (review Priority 7).
        const clauseControlTokens = extractMTGRestrictions(effectText)
            .filter(t => t === 'controlledbyyou' || t === 'controlledbyopponent');
        if (clauseControlTokens.length > 0) {
            parsed.restriction = Array.from(new Set([...(parsed.restriction || []), ...clauseControlTokens]));
        }

        // Layer in condition/payCost/additionalEffects for every clause type, not just the ones
        // whose specialized sub-parser happens to detect them - fills gaps only, so a sub-parser's
        // own (more precise) detection is never overwritten (project spec 2.3).
        const extra = extractConditionsAndCosts(clause);
        if (parsed.condition === undefined || parsed.condition === null) parsed.condition = extra.condition;
        if (!parsed.conditionDetail) parsed.conditionDetail = extra.conditionDetail;
        if (parsed.payCost === undefined || parsed.payCost === null) parsed.payCost = extra.payCost;
        if (parsed.quantity === undefined || parsed.quantity === null) parsed.quantity = extra.quantity;
        parsed.additionalEffects = Array.from(new Set([...(parsed.additionalEffects || []), ...extra.additionalEffects]));

        // A genuine activation cost (isolated above from the actual effect text) is kept as its
        // own structured field rather than folded into the single opaque payCost string, so a
        // compound cost can be compared part-by-part (project spec: cost-then-effect sequencing).
        if (costText) {
            parsed.activationCost = classifyActivationCost(costText);
            if (!parsed.payCost) parsed.payCost = parsed.activationCost.type;
        }

        // Mana production must be compared by NET mana when an activation itself costs mana.
        // Example: Boros Signet pays {1} to add {R}{W}; output is two mana, but the net increase
        // is one. Both values are retained so color-fixing and gross output remain visible.
        if (parsed.action === 'add_mana') {
            finalizeManaAbilityEffect(parsed);
            parsed.manaAbilityRulesProfile = classifyManaAbilityRules(`${costText || ''} ${clause}`, effectText);
        }

        if (activeModeGroup && isBulletLine) {
            parsed.isMode = true;
            parsed.modeGroupId = activeModeGroup.groupId;
            parsed.modeCount = activeModeGroup.count;
        } else {
            activeModeGroup = null;
        }

        results.push(parsed);

        // Investigate creates a Clue token, whose rules text supplies a repeatable activated draw
        // ability. Add that derived card-advantage node to the source card's mechanical graph so
        // retrieval/scoring can match repeatable draw engines, rather than relying on prose alone.
        if (parsed.clueDrawEngine && parsed.tokenType === 'clue') {
            results.push({
                raw: 'Clue token ability: Pay {2}, sacrifice a Clue token: draw a card.',
                parentRuleText: parentRuleText,
                action: 'draw', object: 'card', from: null, to: 'hand', target: null,
                restriction: [], quantity: 1, isSecondaryAtom: true,
                derivedFromTokenAbility: true,
                activationCost: { type: 'clue_sacrifice_draw', parts: ['pay {2}', 'sacrifice a Clue token'] },
                repeatabilityContextOverride: 'Clue token ability: Pay {2}, sacrifice a Clue token: draw a card.'
            });
        }

        // A compound clause contributes every effect it contains, not only its dominant verb.
        const extraAtoms = extractClauseAtoms(effectText, parsed.action);
        for (const atom of extraAtoms) {
            atom.parentRuleText = atom.parentRuleText || parentRuleText;
            atom.previousRuleText = atom.previousRuleText || previousRuleText;
            if (parsed.isMode) {
                atom.isMode = true;
                atom.modeGroupId = parsed.modeGroupId;
                atom.modeCount = parsed.modeCount;
            }
            results.push(atom);
        }

        // The activation cost is itself an effect (sacrificing, discarding, exiling something),
        // but it's a price paid rather than the ability's purpose - captured so cost structure can
        // be compared, flagged so the importance model never mistakes it for the payoff.
        if (costText) {
            const costAtom = parseZoneMovementEffect(costText);
            if (costAtom && costAtom.action) {
                costAtom.raw = costText;
                costAtom.parentRuleText = parentRuleText;
                costAtom.isCostEffect = true;
                results.push(costAtom);
            }
        }
    }

    // Link adjacent Oracle sentences for impulse draw (e.g. Reckless Impulse: exile top two,
    // then "You may play those cards until the end of your next turn"). The permission often
    // lives in a separate sentence, so clause-local parsing alone loses the defining mechanic.
    const wholeOracleText = String(oracleText).replace(/[’]/g, "'");
    const hasPlayPermissionForExiledCards = /\b(?:you may|you can)\s+(?:play|cast)\s+(?:those cards|that card|the exiled cards|cards exiled this way|that card)\b/i.test(wholeOracleText) ||
        /\bplay those cards until\b/i.test(wholeOracleText) || /\bplay that card for as long as it remains exiled\b/i.test(wholeOracleText);
    if (hasPlayPermissionForExiledCards && /\bexiles?\b[\s\S]{0,100}\b(?:top|from the top)\b[\s\S]{0,80}\blibrary\b/i.test(wholeOracleText)) {
        for (const effect of results) {
            if (effect?.action === 'exile' && (effect.from === 'library' || /\btop\b[\s\S]{0,80}\blibrary\b/i.test(String(effect.parentRuleText || effect.raw || '')))) {
                effect.playFromExile = true;
                effect.accessType = 'impulse_draw';
                effect.playWindow = (wholeOracleText.match(/\buntil the end of (?:your|that player's) next turn\b/i) || [])[0] || null;
            }
        }
    }

    // Add dedicated structured signatures for the mechanic families that a flat keyword anchor
    // cannot explain adequately. Existing parsed atoms remain untouched and continue to describe
    // costs, zone movement, quantities, target scopes, triggers, and outcomes.
    appendNamedMechanicProfiles(results, wholeOracleText, cardContext);

    // Add relationship metadata before canonicalization so the canonical representation can carry
    // target/quantity/trigger/dependency structure downstream.
    annotateEffectArray(results);

    // Derive the canonical function for every effect and work out which one actually defines the
    // card, rather than leaving downstream code to assume "the first one parsed".
    return assignEffectImportance(results);
}

/**
 * Calculates mechanical similarity percentage (0.0 to 1.0) between two parsed card structures.
 * @param {Array<Object>} parsedA 
 * @param {Array<Object>} parsedB 
 * @returns {number} Score between 0.0 and 1.0
 */
// Two-level action taxonomy: family groups actions that serve a similar strategic role
// (e.g. "removal"), while outcome captures what actually happens to the affected object at a
// rules level - "destroy" and "sacrifice" both put a creature in the graveyard (same outcome,
// so death-trigger synergies still line up), while "exile" removes it entirely (same family,
// different outcome, since exile bypasses graveyard-recursion answers). This lets action
// alignment reward a true rules-level equivalent more than a same-family-but-different-effect
// verb, instead of only ever being right or a single flat "related" tier
// (project spec ranking B: Action -> Function -> Outcome hierarchy).
const ACTION_TAXONOMY = {
    destroy:     { family: "removal",               outcome: "creature_to_graveyard" },
    sacrifice:   { family: "removal",               outcome: "creature_to_graveyard" },
    exile:       { family: "removal",               outcome: "removed_from_game" },
    return:      { family: "reanimation_recursion", outcome: "to_battlefield_or_hand" },
    put:         { family: "reanimation_recursion", outcome: "to_battlefield_or_hand" },
    create:      { family: "tokens",                outcome: "new_permanent" },
    multiply:    { family: "tokens",                outcome: "new_permanent" },
    copy_token:  { family: "tokens",                outcome: "new_permanent" },
    draw:        { family: "card_advantage",        outcome: "cards_to_hand" },
    mill:        { family: "card_advantage",        outcome: "cards_to_graveyard" },
    counter:     { family: "counter",                outcome: "spell_or_ability_stopped" },
    gain_control:{ family: "control_change",         outcome: "permanent_control_changed" },
    cost_reduction:{ family: "cost_modification",   outcome: "spell_cost_reduced" },
    search:      { family: "tutor",                  outcome: "card_found" },
    stat_buff:   { family: "stat_buff",              outcome: "stats_or_keywords_changed" },
    discard:     { family: "discard",                outcome: "cards_hand_to_graveyard" },
    damage:      { family: "damage",                 outcome: "damage_dealt" },
    add_mana:    { family: "mana",                   outcome: "mana_added" },
    gain_life:   { family: "life_total",             outcome: "life_total_increased" },
    lose_life:   { family: "life_total",             outcome: "life_total_decreased" },
    // Shares a family with stat_buff (both change a creature's stats/board presence) but a
    // different outcome - a one-shot targeted counter is structurally very different from a
    // continuous team-wide anthem, even though both are "stats go up/down" in spirit.
    place_counter: { family: "stat_buff",            outcome: "stats_changed_one_shot" },
    cast_permission: { family: "casting_permission", outcome: "instant_speed_cast_permission" },
    // Tap and untap share a family (both change a permanent's tapped state) but opposite
    // outcomes - tapping down a blocker and untapping your own permanent for an extra activation
    // serve opposite strategic purposes despite the shared verb family.
    tap:         { family: "tap_control",            outcome: "permanent_tapped" },
    untap:       { family: "tap_control",            outcome: "permanent_untapped" },
    scry:        { family: "library_manipulation",   outcome: "library_top_reordered" },
    surveil:     { family: "library_manipulation",   outcome: "library_top_or_graveyard" },
    proliferate: { family: "counter_manipulation",   outcome: "existing_counters_increased" }
};

// Backward-compatible view used anywhere only the coarse family grouping is needed.
const ACTION_GROUPS = Object.fromEntries(Object.entries(ACTION_TAXONOMY).map(([action, t]) => [action, t.family]));

// ---------------------------------------------------------------------------
// CANONICAL MTG FUNCTION LAYER
// ---------------------------------------------------------------------------
// The raw parser tells us the VERB a clause uses (action: "return"). That isn't enough on its
// own, because the same verb serves completely different strategic purposes depending on the
// zones involved: "return ... from graveyard to battlefield" is reanimation, "return ... to its
// owner's hand" is a bounce/tempo effect, and "return ... from graveyard to hand" is recursion.
// Conversely, different verbs can mean the same thing ("return"/"put" onto the battlefield).
//
// deriveCanonicalFunction() collapses (action + zones + object + params) into one canonical
// {function, outcome, params} record. That record - not the raw verb - is what retrieval query
// generation, mechanical scoring, and the functional embedding all consume, so adding a new
// mechanic means adding a mapping here rather than another special-case branch in three
// different places (review Priority 2 / Priority 5: canonical representation + outcome hierarchy).
//
// "function" = the strategic purpose ("reanimate"). "outcome" = the rules-level game-state change
// ("permanent_enters_from_graveyard"). Two cards can share an outcome without sharing a function
// and vice versa, so both tiers are scored separately.
const FUNCTION_OUTCOMES = {
    reanimate:        "permanent_enters_from_graveyard",
    recursion:        "card_returns_to_hand",
    bounce:           "permanent_leaves_battlefield",
    cheat_into_play:  "permanent_enters",
    tuck:             "permanent_leaves_battlefield",
    zone_change:      "card_changes_zone",
    removal:          "permanent_to_graveyard",
    self_sacrifice:   "own_permanent_to_graveyard",
    sacrifice_other:  "another_permanent_to_graveyard",
    exile_removal:    "permanent_exiled",
    counter:          "spell_or_ability_stopped",
    gain_control:     "permanent_control_changed",
    cost_reduction:   "spell_cost_reduced",
    tutor:            "card_found",
    ramp_tutor:       "resources_increase",
    opponent_ramp:    "opponent_resources_increase",
    opponent_gift:    "opponent_gains_permanent",
    library_exile_access: "card_access_from_exile",
    token_creation:   "new_permanent",
    token_multiplier: "new_permanent",
    tribal_anthem:    "stats_or_keywords_changed",
    anthem:           "stats_or_keywords_changed",
    card_draw:        "cards_to_hand",
    mill:             "cards_to_graveyard",
    discard:          "cards_hand_to_graveyard",
    direct_damage:    "damage_dealt",
    mana_ability:     "mana_added",
    gain_life:        "life_total_increased",
    lose_life:        "life_total_decreased",
    place_counter:    "stats_changed_one_shot",
    tap:              "permanent_tapped",
    untap: "permanent_untapped",
    scry: "library_top_reordered",
    surveil: "library_top_or_graveyard",
    proliferate: "existing_counters_increased",
    cast_timing_permission: "instant_speed_cast_permission",
    mechanic_recruit: "draw_discard_conditional_token_creation",
    mechanic_storied: "persistent_player_designation",
    mechanic_hone_counter: "equipped_creature_counter_scaled_power",
    mechanic_empower_jace: "conditional_jace_token_and_loyalty",
    mechanic_heartwood_token: "red_green_artifact_mana_token",
    mechanic_plan_progression: "counter_milestone_plan_reward",
    mechanic_worthy_equip: "conditional_equipment_target_legality",
    mechanic_vibranium_token: "indestructible_colorless_artifact_mana_token",
    mechanic_prepared_spell: "paired_exiled_spell_cast_permission",
    mechanic_casting_mode_profile: "alternate_or_delayed_casting_mode",
    mechanic_spell_replay_profile: "spell_copy_or_replay_rules",
    mechanic_combat_rules_profile: "combat_keyword_rules",
    mechanic_stateful_game_profile: "persistent_game_designation_or_progression",
    mechanic_permanent_progression_profile: "permanent_state_transition_rules",
    mechanic_game_state_condition_profile: "game_state_condition_signature",
    mechanic_delayed_hand_exile_cast_profile: "delayed_hand_exile_cast_permission",
    mechanic_multiplayer_decision_profile: "multiplayer_choice_or_voting_rules",
    mechanic_auxiliary_game_component_profile: "auxiliary_game_component_rules",
    mechanic_rules_modification_profile: "replacement_prevention_and_static_rule_modification"
};

/**
 * Collapses one parsed effect into its canonical {function, outcome, params} form.
 * @param {Object} effect - a single parsed clause/atom from parseMTGEffect
 * @returns {Object|null} canonical record, or null when the clause had no recognized action
 */
function deriveCanonicalFunction(effect) {
    if (!effect || !effect.action || effect.action === "generic") return null;

    // Named mechanic signatures are first-class nodes in the same canonical graph as ordinary
    // parsed effects. They supplement, rather than replace, the detailed action/zone/cost atoms.
    // This is how multi-clause/stateful mechanics stay connected through retrieval and scoring.
    if (effect.mechanicProfile?.key) {
        const profile = effect.mechanicProfile;
        const functionName = `mechanic_${String(profile.key).replace(/[^a-z0-9]+/gi, '_').replace(/^_|_$/g, '').toLowerCase()}`;
        return {
            function: functionName,
            outcome: FUNCTION_OUTCOMES[functionName] || `named_mechanic_${normalizeMechanicToken(profile.key).replace(/[^a-z0-9]+/g, '_')}`,
            params: {
                object: null, target: null, from: null, to: null,
                mechanicKey: normalizeMechanicToken(profile.key),
                mechanicProfile: {
                    key: normalizeMechanicToken(profile.key),
                    family: normalizeMechanicToken(profile.family || profile.key),
                    label: String(profile.label || profile.key),
                    traits: Array.from(new Set((profile.traits || []).map(normalizeMechanicToken).filter(Boolean))).sort(),
                    threshold: profile.threshold ?? null,
                    quantity: profile.quantity ?? null,
                    condition: normalizeMechanicToken(profile.condition || ''),
                    sequence: (profile.sequence || []).map(normalizeMechanicToken),
                    dimensions: Array.isArray(profile.dimensions) ? profile.dimensions : [],
                    summary: String(profile.summary || '')
                },
                gameStateConditionProfile: effect.gameStateConditionProfile || null,
                raw: effect.raw || null,
                isStatic: Boolean(profile.isStatic)
            }
        };
    }

    const a = effect.action;
    const localRuleContext = `${String(effect.parentRuleText || '')} ${String(effect.contextClause || '')} ${String(effect.raw || '')}`.replace(/[’]/g, "'");
    const previousRuleText = String(effect.previousRuleText || '').replace(/[’]/g, "'");
    const previousRuleSearchesForLands = /\bsearch(?:es)?\b[\s\S]{0,180}\b(?:basic\s+)?land cards?\b/i.test(previousRuleText);
    // Some modal/ramp spells put the searched-for object onto the battlefield in the next printed
    // sentence (Verdant Mastery). Import only the immediately preceding sentence when it clearly
    // searches a library for land cards and this atom is a battlefield put; don't blend whole-card
    // text into every effect and contaminate unrelated mechanics.
    const ruleContext = `${localRuleContext} ${a === 'put' && effect.to === 'battlefield' && previousRuleSearchesForLands ? previousRuleText : ''}`.trim();
    const lowerRuleContext = ruleContext.toLowerCase();
    const topLibraryPattern = /\btop\s+(?:(?:one|two|three|four|five|six|seven|eight|nine|ten|\d+)\s+)?cards?\s+of\s+(?:your|their|that player(?:'s)?|that opponent(?:'s)?|an opponent(?:'s)?|a player(?:'s)?)\s+library\b/i;
    const directlyExilesTopLibrary = /\bexiles?\s+(?:the\s+)?top\s+(?:(?:one|two|three|four|five|six|seven|eight|nine|ten|\d+)\s+)?cards?\s+of\s+(?:your|their|that player(?:'s)?|that opponent(?:'s)?|an opponent(?:'s)?|a player(?:'s)?)\s+library\b/i.test(ruleContext);
    const looksAtThenExilesLibraryCard = /\b(?:look at|reveal)\b[\s\S]{0,140}\btop\s+(?:(?:one|two|three|four|five|six|seven|eight|nine|ten|\d+)\s+)?cards?\s+of\s+(?:your|their|that player(?:'s)?|that opponent(?:'s)?|an opponent(?:'s)?|a player(?:'s)?)\s+library\b[\s\S]{0,170}\bexiles?\s+(?:it|that card)\b/i.test(ruleContext);
    const libraryTopExile = a === 'exile' && (effect.from === 'library' || directlyExilesTopLibrary || looksAtThenExilesLibraryCard);
    // Secondary atoms are re-parsed from a verb offset and can lose structured zone fields. Recover
    // the source zone from the atom's own words and its owning clause before assigning a function:
    // "exile a card from your hand ... and put time counters on it" is hand processing, never removal.
    const explicitExileFrom = a === 'exile'
        ? (ruleContext.match(/\bexiles?\b[\s\S]{0,180}\bfrom\s+(?:your|their|its owner's|that player's|a player's|the player's|the opponent's)?\s*(hand|library|battlefield|graveyard|exile)\b/i) || [])[1]?.toLowerCase() || null
        : null;
    const inferredExileFrom = a === 'exile' && !explicitExileFrom && /\bexiles?\s+(?:(?:target|all|each|up to\s+\d+|a|an|the)\s+)?(?:creatures?|permanents?|artifacts?|enchantments?|planeswalkers?|lands?)\b/i.test(ruleContext)
        ? 'battlefield' : null;
    const from = explicitExileFrom || effect.from || (libraryTopExile ? 'library' : null) || inferredExileFrom;
    const to = effect.to || (a === 'exile' || libraryTopExile ? 'exile' : null);
    const inferredSearchedLand = a === 'put' && to === 'battlefield' && previousRuleSearchesForLands && /\bsearch(?:es)?\b[\s\S]{0,180}\b(?:basic\s+)?land cards?\b/i.test(ruleContext);
    const obj = inferredSearchedLand || (effect.object === 'card' && to === 'battlefield' && /\bland cards?\b/i.test(ruleContext))
        ? 'land' : (effect.object || (libraryTopExile ? 'card' : null));
    const restriction = effect.restriction || [];
    const recipientContext = `${String(effect.raw || '')} ${String(effect.contextClause || '')}`.replace(/[’]/g, "'");
    const recipientScope = effect.recipientScope || (
        /\bunder\s+(?:an?\s+)?opponent's\s+control\b|\b(?:(?:an?|each|target)\s+)?opponents?\s+creates?\b/i.test(recipientContext) ? 'opponent' :
        /\bunder\s+your\s+control\b/i.test(recipientContext) ? 'you' : null
    );
    const libraryOwnerScope = /\byour(?: own)?\s+library\b/i.test(ruleContext) ? 'you'
        : /\b(?:an opponent|target opponent|that opponent)(?:'s)?\s+library\b/i.test(ruleContext) ? 'opponent'
        : /\bthat player(?:'s)?\s+library\b/i.test(ruleContext) ? 'affected_player' : 'unspecified';

    let fn = null;

    if (a === "return" || a === "put") {
        const searchesLibrary = /\bsearch(?:es)?\s+(?:your|the|a|target player's|target opponent's)?\s*library\b/i.test(ruleContext);
        const putsIntoHand = /\b(?:put|place)\b[\s\S]{0,140}\b(?:into|to)\s+(?:your|their|the player's|the opponent's)?\s*hand\b/i.test(ruleContext);
        if (from === "graveyard" && to === "battlefield") fn = "reanimate";
        else if (from === "graveyard" && to === "hand") fn = "recursion";
        // Cards fetched from a library and placed into hand are tutors, not bounce. In particular,
        // Fervent Mastery says "Search your library ... put them into your hand" and never returns
        // permanents from the battlefield.
        else if (to === "hand" && (from === "library" || (searchesLibrary && putsIntoHand))) fn = "tutor";
        else if (to === "hand" && (from === "battlefield" || a === "return" || /\b(?:target|all|each|a|an)\s+(?:permanent|creature|artifact|enchantment|planeswalker|land)\b/i.test(ruleContext))) fn = "bounce";
        else if (to === "hand") fn = "zone_change";
        else if (to === "battlefield" && obj === 'land' && recipientScope === 'opponent') fn = 'opponent_ramp';
        else if (to === "battlefield" && obj === 'land') fn = 'ramp_tutor';
        else if (to === "battlefield" && recipientScope === 'opponent') fn = 'opponent_gift';
        else if (to === "battlefield") fn = "cheat_into_play";
        else if (to === "library") fn = "tuck";
        else fn = "zone_change";
    } else if (a === "destroy" || a === "sacrifice") {
        // "Destroy TARGET creature" is removal aimed at something. "Sacrifice a creature" with no
        // target is you giving up your own permanent - a cost or an aristocrats enabler, not an
        // answer to an opponent's threat. Treating both as plain "removal" made Birthing Pod look
        // like a removal spell and let its sacrifice clause outrank the tutor that actually
        // defines the card.
        const sacrificeText = `${String(effect.raw || '')} ${String(effect.parentRuleText || '')}`.replace(/[’]/g, "'");
        const explicitlySacrificesSource = /\bsacrifice\s+(?:this(?: creature| artifact| enchantment| permanent| planeswalker| land| card)?|the source|~)\b/i.test(sacrificeText);
        const namedCard = String(effect.cardName || '').trim();
        const namesSource = namedCard && new RegExp(`\\bsacrifice\\s+${namedCard.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'i').test(sacrificeText);
        const isSelfSacrifice = (a === "sacrifice") && (explicitlySacrificesSource || namesSource) && !restriction.includes('controlledbyopponent');
        fn = isSelfSacrifice ? "self_sacrifice" : (a === "sacrifice" ? "sacrifice_other" : "removal");
    } else if (a === "exile") {
        // Exiling a library card for later play is card access/impulse draw, not removing a
        // battlefield permanent. Likewise, exiling a card FROM HAND (Alaundo the Seer) is a
        // hand-zone setup/processing action, not removal. The parser used to default every other
        // exile verb to battlefield removal even when the source zone was explicitly the hand.
        fn = libraryTopExile ? "library_exile_access" : (from === "hand" ? "zone_change" : "exile_removal");
    } else if (a === "counter") {
        fn = "counter";
    } else if (a === "gain_control") {
        fn = "gain_control";
    } else if (a === "cost_reduction") {
        fn = "cost_reduction";
    } else if (a === "search") {
        fn = restriction.includes("land") ? "ramp_tutor" : "tutor";
    } else if (a === "multiply" || a === "copy_token") {
        fn = "token_multiplier";
    } else if (a === "create") {
        fn = "token_creation";
    } else if (a === "stat_buff") {
        fn = (effect.subtype && effect.subtype !== "all") ? "tribal_anthem" : "anthem";
    } else if (a === "draw") {
        fn = "card_draw";
    } else if (a === "mill") {
        fn = "mill";
    } else if (a === "discard") {
        fn = "discard";
    } else if (a === "damage") {
        fn = "direct_damage";
    } else if (a === "add_mana") {
        fn = "mana_ability";
    } else if (a === "gain_life" || a === "lose_life") {
        // Kept as two distinct functions, not one "life_change" - gaining and losing life are
        // opposite effects that happen to share a family (see ACTION_TAXONOMY), and collapsing
        // them into one function would let a lifegain card and a life-loss/drain card score as
        // equivalent, which they clearly aren't.
        fn = a;
    } else if (a === "place_counter") {
        fn = "place_counter";
    } else if (a === "tap" || a === "untap") {
        // Same reasoning as gain_life/lose_life: opposite effects, kept as separate functions
        // rather than one "tap_state_change" that would score a Falter effect and an Untap-all
        // ramp effect as equivalent.
        fn = a;
    } else if (a === "scry" || a === "surveil" || a === "proliferate") {
        fn = a;
    } else if (a === "cast_permission") {
        // A real static rules permission to cast a class of spells at instant speed.
        fn = "cast_timing_permission";
    } else {
        return null;
    }

    // A tutor that ends on the battlefield is a materially different outcome from one that ends
    // in hand, so refine the generic outcome where the destination zone is actually known.
    let outcome = FUNCTION_OUTCOMES[fn] || "unknown";
    if (fn === "tutor" && to === "battlefield") outcome = "permanent_enters";
    if (fn === "tutor" && to === "hand") outcome = "card_found_to_hand";

    // Damage amount and mana amount/color both live outside the shared from/to/object shape every
    // other function uses, so they're folded into the existing magnitude/quantity params here
    // rather than adding function-specific fields that every OTHER consumer of a canonical
    // function record would need to know to ignore.
    let magnitude = effect.powerToughness || null;
    let quantity = effect.quantity ?? null;
    if (fn === "direct_damage") {
        magnitude = `${effect.amount} damage`;
        quantity = typeof effect.amount === 'number' ? effect.amount : null;
    } else if (fn === "mana_ability") {
        const netPart = effect.manaNetAmount != null && Number.isFinite(Number(effect.manaNetAmount)) ? ` net ${effect.manaNetAmount}` : '';
        const colorPart = effect.colors && effect.colors.length > 0 ? effect.colors.join('/') : null;
        magnitude = [effect.amount, colorPart, 'mana', netPart].filter(Boolean).join(' ');
        // Quantity is the actual net mana increase when the activation cost is known. Gross
        // production is preserved as manaOutputAmount for a separate, lower-weight comparison.
        quantity = effect.manaNetAmount != null && Number.isFinite(Number(effect.manaNetAmount))
            ? Number(effect.manaNetAmount)
            : (typeof effect.amount === 'number' ? effect.amount : null);
    } else if (fn === "gain_life" || fn === "lose_life") {
        magnitude = `${effect.amount} life`;
        quantity = typeof effect.amount === 'number' ? effect.amount : null;
    } else if (fn === "place_counter") {
        magnitude = effect.counterType || null;
        quantity = typeof effect.quantity === 'number' ? effect.quantity : null;
    }

    return {
        function: fn,
        outcome,
        params: {
            object: obj,
            from,
            to,
            sacrificeScope: fn === 'self_sacrifice' ? 'source_permanent' : (fn === 'sacrifice_other' ? 'another_or_unspecified_permanent' : null),
            target: effect.target || null,
            subtype: effect.subtype && effect.subtype !== "all" ? effect.subtype : null,
            scope: effect.isOther === true ? "other" : (effect.isOther === false ? "all" : null),
            castingScope: effect.castingScope || null,
            timingPermission: effect.timingPermission || null,
            magnitude,
            grantedKeywords: [...new Set([...(effect.grantedKeywords || []), ...(effect.keywords || [])])].map(x => String(x).toLowerCase()),
            scalingProfile: effect.scalingProfile || null,
            quantity,
            manaOutputAmount: fn === 'mana_ability' && effect.manaOutputAmount != null && Number.isFinite(Number(effect.manaOutputAmount)) ? Number(effect.manaOutputAmount) : null,
            manaNetAmount: fn === 'mana_ability' && effect.manaNetAmount != null && Number.isFinite(Number(effect.manaNetAmount)) ? Number(effect.manaNetAmount) : null,
            manaNetMin: fn === 'mana_ability' && effect.manaNetMin != null && Number.isFinite(Number(effect.manaNetMin)) ? Number(effect.manaNetMin) : null,
            manaNetMax: fn === 'mana_ability' && effect.manaNetMax != null && Number.isFinite(Number(effect.manaNetMax)) ? Number(effect.manaNetMax) : null,
            manaOutputMode: fn === 'mana_ability' ? (effect.manaOutputMode || effect.manaOutput?.mode || null) : null,
            manaOutputColors: fn === 'mana_ability' ? (effect.manaOutputColors || effect.manaOutput?.colors || []) : [],
            manaOutputColorCount: fn === 'mana_ability' ? (effect.manaOutputColorCount ?? effect.manaOutput?.uniqueColorCount ?? null) : null,
            manaAbilityRulesProfile: effect.manaAbilityRulesProfile || null,
            duration: effect.isStatic === true ? "static" : (effect.isStatic === false ? "temporary" : null),
            controller: effect.controller || null,
            recipientScope,
            isOpponentBenefit: Boolean(effect.isOpponentBenefit || recipientScope === 'opponent'),
            tokenType: effect.tokenType && effect.tokenType !== 'token' ? String(effect.tokenType).toLowerCase().trim() : null,
            libraryOwnerScope: libraryTopExile ? libraryOwnerScope : null,
            accessType: libraryTopExile ? (effect.playFromExile || /\b(?:you may|you can)\s+(?:play|cast)\b/i.test(ruleContext) ? 'impulse_draw' : 'exile_access') : null,
            playFromExile: Boolean(effect.playFromExile || (libraryTopExile && /\b(?:you may|you can)\s+(?:play|cast)\b/i.test(ruleContext))),
            playWindow: effect.playWindow || null,
            clueDrawEngine: Boolean(effect.clueDrawEngine || (String(effect.raw || '').match(/\binvestigate\b/i) && obj === 'token')),
            derivedFromTokenAbility: Boolean(effect.derivedFromTokenAbility),
            restriction,
            targetProfile: effect.targetProfile || null,
            quantityProfile: effect.quantityProfile || null,
            triggerProfile: effect.triggerProfile || null,
            dependencyProfile: effect.dependencyProfile || null,
            durationProfile: effect.durationProfile || null,
            effectMode: effect.effectMode || "normal",
            controllerScope: effect.controllerScope || null,
            isMode: Boolean(effect.isMode),
            modeGroupId: effect.modeGroupId ?? null,
            modeCount: effect.modeCount || null,
            controlChangeDuration: effect.controlChangeDuration || null,
            condition: effect.condition || null,
            conditionDetail: effect.conditionDetail || null,
            gameStateConditionProfile: effect.gameStateConditionProfile || parseGameStateConditionProfile(ruleContext),
            manaAbilityRulesProfile: effect.manaAbilityRulesProfile || null,
            payCost: effect.payCost || null,
            activationCost: effect.activationCost || null,
            additionalEffects: effect.additionalEffects || [],
            isCostEffect: Boolean(effect.isCostEffect),
            raw: effect.raw || null
        }
    };
}

/**
 * Renders a canonical function as a short natural-language sentence. This is what gets fed to
 * the sentence-embedding model as the *functional* embedding, so the model compares normalized
 * MTG meaning ("reanimate a creature from graveyard to battlefield") rather than being asked to
 * infer mechanics from arbitrary Oracle phrasing itself (review Priority 8).
 * @param {Array<Object>} canonicalFunctions
 * @returns {string}
 */
function canonicalFunctionToText(canonicalFunctions) {
    if (!canonicalFunctions || canonicalFunctions.length === 0) return "";
    return canonicalFunctions.map(cf => {
        const p = cf.params || {};
        if (p.mechanicProfile?.summary) return p.mechanicProfile.summary;
        if ((cf.function === 'anthem' || cf.function === 'tribal_anthem') && p.combatFinisher && p.scalingProfile?.source === 'creatures_you_control') {
            const buffs = p.magnitude || '+X/+X';
            const keywords = (p.grantedKeywords || []).join(', ');
            return `combat anthem/finisher: creatures you control get ${buffs}, where X is the number of creatures you control${keywords ? `, and gain ${keywords}` : ''}${p.duration === 'temporary' ? ' until end of turn' : ''}`;
        }
        if (cf.function === 'zone_change' && p.from === 'hand' && p.to === 'exile') {
            return 'exile a card from hand';
        }
        if (cf.function === 'library_exile_access') {
            const libraryOwner = p.libraryOwnerScope === 'you' ? 'your' : p.libraryOwnerScope === 'opponent' ? "an opponent's" : p.libraryOwnerScope === 'affected_player' ? "that player's" : "a player's";
            const access = p.playFromExile || p.accessType === 'impulse_draw'
                ? `impulse draw: exile the top card${typeof p.quantity === 'number' && p.quantity > 1 ? `s (${p.quantity})` : ''} of ${libraryOwner} library and may play/cast it from exile${p.playWindow ? ` ${p.playWindow}` : ''}`
                : `exile the top card of ${libraryOwner} library for card access`;
            return `${access}; library-card access`;
        }
        if (cf.function === 'token_creation' && p.tokenType === 'clue') {
            return `repeatable Clue token engine from investigate; each Clue can be activated for {2}, sacrifice that Clue token: draw a card (repeatable card advantage when mana and Clues are available)`;
        }
        if (cf.function === 'card_draw' && p.derivedFromTokenAbility) {
            return 'repeatable activated card draw from a Clue token: pay {2}, sacrifice that Clue token, draw a card';
        }
        if (cf.function === 'opponent_ramp') return "put a land onto the battlefield under an opponent's control; this is opponent ramp and grants the opponent a resource, not your own ramp";
        if (cf.function === 'opponent_gift') return "put a permanent onto the battlefield under an opponent's control; this grants the opponent a resource";
        if (cf.function === 'self_sacrifice') return 'sacrifice this source permanent itself; a one-time self-sacrifice is not sacrificing another permanent as a repeatable cost';
        if (cf.function === 'sacrifice_other') return 'sacrifice another or unspecified permanent; this is not the source permanent sacrificing itself';
        if (cf.function === 'token_creation' && p.tokenType) {
            const tokenName = `${p.tokenType} token`;
            const quantityText = typeof p.quantity === 'number'
                ? `${p.quantity} ${tokenName}${p.quantity === 1 ? '' : 's'}`
                : p.quantityProfile?.relation === 'for_each'
                    ? `a ${tokenName} for each matching permanent`
                    : `${tokenName}s`;
            const actorText = p.recipientScope === 'opponent' ? 'an opponent creates' : p.recipientScope === 'you' ? 'you create' : 'create';
            const recipientContext = p.recipientScope === 'opponent'
                ? ' (opponent benefit/resources; potentially a downside for your side or a deliberate political effect)'
                : '';
            return `${actorText} ${quantityText}${recipientContext}`;
        }
        const bits = [cf.function.replace(/_/g, ' ')];
        if (p.tokenType) bits.push(`${p.tokenType} token`);
        else if (p.object) bits.push(p.object);
        if (p.subtype) bits.push(p.subtype);
        if (p.scope === "other") bits.push("other");
        if (p.from) bits.push(`from ${p.from}`);
        if (p.to) bits.push(`to ${p.to}`);
        if (p.magnitude) bits.push(p.magnitude);
        if (typeof p.quantity === 'number') bits.push(`${p.quantity}`);
        else if (p.quantityProfile?.relation === 'for_each') bits.push('for each matching permanent');
        if (p.recipientScope === 'opponent') bits.push('under opponent control; opponent receives the resource');
        if (p.duration) bits.push(p.duration);
        if (p.castingScope) bits.push(`scope ${p.castingScope} spells`);
        if (p.timingPermission) bits.push(p.timingPermission.replace(/_/g, ' '));
        bits.push(cf.outcome.replace(/_/g, ' '));
        return bits.join(' ');
    }).join('; ');
}

// Canonical function text is immutable for a parsed-effects array in normal scoring. Warming the
// embedding cache and the semantic pass previously regenerated the same canonical string twice.
const canonicalFunctionTextByEffects = new WeakMap();
function getCachedCanonicalFunctionText(parsedEffects) {
    if (!Array.isArray(parsedEffects)) return '';
    if (canonicalFunctionTextByEffects.has(parsedEffects)) return canonicalFunctionTextByEffects.get(parsedEffects);
    const value = canonicalFunctionToText(getCanonicalFunctions(parsedEffects));
    canonicalFunctionTextByEffects.set(parsedEffects, value);
    return value;
}

// How strategically defining each canonical function tends to be. Used by the importance model
// below to pick a card's PRIMARY function: on "Sacrifice a creature: Draw a card, then return a
// creature from your graveyard", the reanimation is what defines the card, not the incidental
// draw - and neither is simply "whichever effect was parsed first" (review Priority 1).
const FUNCTION_IMPORTANCE = {
    reanimate: 1.0, counter: 1.0, token_multiplier: 1.0, tribal_anthem: 1.0, gain_control: 0.85,
    removal: 0.9, exile_removal: 0.9, library_exile_access: 0.82, tutor: 0.9, ramp_tutor: 0.85,
    opponent_ramp: 0.82, opponent_gift: 0.72, direct_damage: 0.9,
    self_sacrifice: 0.4, sacrifice_other: 0.48,
    cheat_into_play: 0.85, recursion: 0.75, anthem: 0.75, token_creation: 0.7, mana_ability: 0.85,
    bounce: 0.65, tuck: 0.6, mill: 0.55, discard: 0.5, card_draw: 0.45, cost_reduction: 0.90,
    gain_life: 0.55, lose_life: 0.55,
    // A targeted +1/+1 counter is a real combat trick/pump effect - meaningfully defining for a
    // card built around it (an "outlast"/counters deck payoff), on par with recursion or a
    // one-shot anthem. Tap/untap are usually a supporting piece of a bigger card (a Falter effect,
    // an untap-lands ramp trick) rather than the point of the card on their own, so they sit lower.
    place_counter: 0.7, tap: 0.5, untap: 0.5, proliferate: 0.55, surveil: 0.35, scry: 0.3,
    cast_timing_permission: 0.98,
    mechanic_recruit: 0.90,
    mechanic_storied: 0.88,
    mechanic_hone_counter: 0.84,
    mechanic_empower_jace: 0.94,
    mechanic_heartwood_token: 0.82,
    mechanic_plan_progression: 0.94,
    mechanic_worthy_equip: 0.84,
    mechanic_vibranium_token: 0.82,
    mechanic_prepared_spell: 0.92,
    mechanic_casting_mode_profile: 0.92,
    mechanic_spell_replay_profile: 0.96,
    mechanic_combat_rules_profile: 0.90,
    mechanic_stateful_game_profile: 0.90,
    mechanic_permanent_progression_profile: 0.90,
    mechanic_game_state_condition_profile: 0.86,
    mechanic_delayed_hand_exile_cast_profile: 0.95,
    mechanic_multiplayer_decision_profile: 0.82,
    mechanic_auxiliary_game_component_profile: 0.84,
    mechanic_rules_modification_profile: 0.91,
    zone_change: 0.4
};

/**
 * Assigns an importance score to every parsed effect and marks the primary one.
 * Importance combines: how defining the canonical function is, whether the effect is the clause's
 * main action or a trailing atom, whether it's part of an activation COST rather than the payoff,
 * and (weakly) its position. Position alone is a poor proxy - plenty of cards open with a rider.
 * @param {Array<Object>} effects - parsed effects from parseMTGEffect (mutated in place)
 * @returns {Array<Object>} the same array, with .canonical/.importance/.isPrimary set
 */
function assignEffectImportance(effects) {
    if (!effects || effects.length === 0) return effects || [];

    effects.forEach((eff, index) => {
        eff.canonical = deriveCanonicalFunction(eff);

        if (!eff.canonical) {
            eff.importance = 0.05; // unparsed/generic filler
            return;
        }

        let score = FUNCTION_IMPORTANCE[eff.canonical.function] ?? 0.5;
        if (eff.mechanicProfile?.key) score = Math.max(score, 0.84);
        // Investigate/Clue engines create a reusable resource whose built-in {2}, sacrifice-Clue
        // ability repeatedly draws cards. Treat a repeatable investigate trigger as a defining
        // card-advantage engine rather than generic token production.
        if (eff.canonical.function === 'token_creation' && eff.canonical.params?.tokenType === 'clue' &&
            /\binvestigate\b/i.test(String(eff.raw || '')) && /\b(?:whenever|when)\b/i.test(String(eff.raw || eff.parentRuleText || ''))) {
            score = Math.max(score, 0.92);
        }
        // A temporary team-wide +X/+X whose X equals your creature count and that grants flying
        // is a combat finisher, not just a generic anthem. Preserve its defining mechanic as a
        // high-importance node so retrieval/scoring don't bury it below incidental trigger text.
        if (['anthem','tribal_anthem'].includes(eff.canonical.function) &&
            eff.canonical.params?.scalingProfile?.source === 'creatures_you_control' &&
            (eff.canonical.params?.grantedKeywords || []).includes('flying')) {
            score = Math.max(score, 0.99);
            eff.combatFinisher = true;
            eff.canonical.params.combatFinisher = true;
        }

        // An effect extracted as a trailing atom of a compound clause ("..., then draw a card")
        // is by construction a follow-on, not the headline.
        if (eff.isSecondaryAtom) score *= 0.6;

        // Something you PAY (an activation cost) is a price, not the card's purpose.
        if (eff.isCostEffect) score *= 0.35;

        // A mode of a modal spell is one option among several, so no single mode fully defines
        // the card the way a lone unconditional effect does.
        if (eff.isMode) score *= 0.85;

        // Mild positional prior: leading clauses are somewhat more likely to be the headline.
        score *= (index === 0 ? 1.1 : 1.0);

        eff.importance = Math.min(1, score);
    });

    let best = null;
    effects.forEach(eff => {
        if (!best || (eff.importance || 0) > (best.importance || 0)) best = eff;
    });
    effects.forEach(eff => { eff.isPrimary = (eff === best && (eff.importance || 0) > 0.05); });

    return effects;
}

/**
 * Returns a card's canonical functions ordered by importance (primary first).
 * @param {Array<Object>} effects
 * @returns {Array<Object>} canonical records
 */
function getCanonicalFunctions(effects) {
    return (effects || [])
        .filter(e => e.canonical)
        .slice()
        .sort((a, b) => (b.importance || 0) - (a.importance || 0))
        .map(e => e.canonical);
}


// ---------------------------------------------------------------------------
// STRATEGIC / ARCHETYPAL ROLE LAYER (V16)
// ---------------------------------------------------------------------------
// Mechanical similarity answers "does the candidate perform the same rules action?".
// Strategic-role similarity answers a different question: "does this card occupy a similar
// deckbuilding role, even when the implementation is different?"  This layer is intentionally
// conservative. A role is emitted only when multiple MTG-specific anchors agree, because broad
// words like "card", "mana", or "creature" by themselves are not useful evidence.
const STRATEGIC_ROLE_GROUPS = {
    fast_mana: 'acceleration',
    land_ramp: 'acceleration',
    catch_up_ramp: 'acceleration',
    card_advantage_engine: 'card_advantage',
    token_engine: 'tokens',
    token_multiplier: 'tokens',
    tribal_anthem: 'tribal',
    anthem: 'combat_synergy',
    board_wipe: 'interaction',
    single_target_removal: 'interaction',
    counterspell: 'interaction',
    bounce: 'interaction',
    burn: 'interaction',
    graveyard_recursion: 'recursion',
    tutor: 'tutor',
    discard_engine: 'disruption',
    mill_engine: 'disruption',
    life_gain_engine: 'life_resource',
    life_loss_engine: 'life_resource'
};

const STRATEGIC_ROLE_MIN_SCORE = 0.62;

const strategicRoleTextCacheByCard = new WeakMap();
function strategicRoleCardText(card) {
    if (!card || typeof card !== 'object') return '';
    const directText = card.oracle_text || '';
    const faces = card.card_faces || null;
    const cached = strategicRoleTextCacheByCard.get(card);
    if (cached && cached.directText === directText && cached.faces === faces) return cached.value;
    const value = String(directText || (faces ? faces.map(f => f.oracle_text || '').join(' ') : '') || '').trim();
    strategicRoleTextCacheByCard.set(card, { directText, faces, value });
    return value;
}

function strategicRoleFunctions(parsedEffects) {
    return (parsedEffects || [])
        .filter(e => e && e.canonical)
        .map(e => e.canonical.function)
        .filter(Boolean);
}

function strategicRoleHasFunction(parsedEffects, fn) {
    return strategicRoleFunctions(parsedEffects).includes(fn);
}

function strategicRoleHasTrigger(parsedEffects) {
    return (parsedEffects || []).some(e => e.triggerProfile || e.isTriggered || /\b(?:whenever|at the beginning of|at the end of)\b/i.test(e.raw || ''));
}

// Repeatability is a distinct mechanical property. Matching "draw a card" or "create a
// Treasure" is not enough: an upkeep engine and a one-shot sorcery do fundamentally different
// jobs over the course of a game. These profiles are annotations only; the parsed action,
// quantity, targets, costs, and all existing mechanic bridges remain intact.
const REPEATABILITY_PROFILE_META = Object.freeze({
    periodic_trigger:       { group: 'repeatable_engine', strength: 1.00, label: 'Recurring turn trigger' },
    repeatable_trigger:     { group: 'repeatable_engine', strength: 0.90, label: 'Repeatable triggered ability' },
    repeatable_activation:  { group: 'repeatable_engine', strength: 0.86, label: 'Repeatable activated ability' },
    ongoing_static:         { group: 'repeatable_engine', strength: 0.94, label: 'Ongoing static effect' },
    repeatable_spell:       { group: 'limited_reuse',     strength: 0.66, label: 'Repeatable spell' },
    recastable_spell:       { group: 'limited_reuse',     strength: 0.44, label: 'Spell with another cast available' },
    entry_trigger:          { group: 'single_use',        strength: 0.30, label: 'Entry-triggered effect' },
    delayed_trigger:        { group: 'single_use',        strength: 0.26, label: 'One-time delayed trigger' },
    self_event:             { group: 'single_use',        strength: 0.28, label: 'One-time event for this permanent' },
    single_use_activation:  { group: 'single_use',        strength: 0.18, label: 'Single-use activation' },
    one_shot:               { group: 'single_use',        strength: 0.05, label: 'One-shot effect' },
    unknown:                { group: 'unknown',           strength: null, label: 'Repeatability unclear' }
});

function normalizeRepeatabilityText(value) {
    return String(value || '').toLowerCase()
        .replace(/[’']/g, "'")
        .replace(/[^a-z0-9{}+/'-]+/g, ' ')
        .replace(/\s+/g, ' ').trim();
}

function findRepeatabilityContextClause(effectRaw, fullText) {
    const raw = String(effectRaw || '').trim();
    const text = String(fullText || '').trim();
    if (!text) return raw;
    if (!raw) return text;
    const rawNorm = normalizeRepeatabilityText(raw);
    if (!rawNorm) return text;
    const clauses = text.split(/\n+|(?<=[.!?;])\s+/).map(x => x.trim()).filter(Boolean);
    let best = null, bestScore = -Infinity;
    const rawWords = new Set(rawNorm.split(' ').filter(w => w.length > 2));
    for (let i = 0; i < clauses.length; i++) {
        const clause = clauses[i];
        const norm = normalizeRepeatabilityText(clause);
        if (!norm) continue;
        let score = 0;
        if (norm.includes(rawNorm) || rawNorm.includes(norm)) score += 100;
        // Exact clause alignment beats the small preference for finding a timed trigger. This
        // avoids assigning a standalone "Draw a card." clause to a different upkeep trigger just
        // because both clauses contain the same action words.
        if (norm === rawNorm) score += 40;
        const words = norm.split(' ').filter(w => w.length > 2);
        const overlap = words.reduce((n, w) => n + (rawWords.has(w) ? 1 : 0), 0);
        score += overlap / Math.max(1, Math.min(rawWords.size, words.length)) * 20;
        // When a selected/highlighted fragment such as "draw a card" appears in multiple
        // clauses, prefer the clause that carries explicit ability timing/cost context.
        if (parseTurnTimingProfile(clause) || /\b(?:whenever|when|\{t\}|activate only)\b/i.test(clause)) score += 3;
        if (norm.includes(rawNorm)) score += Math.min(8, norm.length / 30);
        if (score > bestScore) { best = clause; bestScore = score; }
    }
    return best || raw;
}

function inferEffectRepeatabilityProfile(card, effect, fullText = '') {
    if (!effect || effect.isCostEffect) return { kind: 'unknown', group: 'unknown', strength: null, confidence: 0 };
    const raw = String(effect.raw || effect.canonical?.params?.raw || '').trim();
    const contextSeed = String(effect.repeatabilityContextOverride || effect.contextClause || effect.parentClauseRaw || raw).trim();
    const context = (effect.searchIntentContextOverride || effect.repeatabilityContextOverride)
        ? contextSeed
        : findRepeatabilityContextClause(contextSeed, fullText || strategicRoleCardText(card));
    const combined = `${context} ${raw}`.trim();
    const lower = combined.toLowerCase();
    const typeLine = String(card?.type_line || '').toLowerCase();
    const isPermanent = /\b(?:creature|artifact|enchantment|planeswalker|land|battle)\b/.test(typeLine);
    const isInstantSorceryOnly = !isPermanent && /\b(?:instant|sorcery)\b/.test(typeLine);
    const cardName = String(card?.name || '').split(' // ')[0].trim();
    const escapedName = cardName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const selfReference = /\bthis(?: creature| artifact| enchantment| permanent| planeswalker| land| card| spell)?\b/i.test(combined) ||
        Boolean(escapedName && new RegExp(`\\b${escapedName}\\b`, 'i').test(combined));
    const timingProfile = parseTurnTimingProfile(combined);
    const periodicTiming = timingProfile?.cadence === 'periodic';
    const delayedTiming = timingProfile?.cadence === 'delayed';
    const timingText = timingProfile?.timingText || '';
    const activation = Boolean(effect.activationCost) || /(?:^|[.;]\s*)[^.;]*:\s*(?:add|draw|create|put|return|exile|search|destroy|tap|untap|gain|deal|discard|mill|counter)\b/i.test(raw);
    // Replacement effects (for example, doubling tokens or preventing damage) are continuous
    // rules modifications on permanents, not one-shot actions merely because their text lacks a
    // conventional "as long as" clause.
    const replacementEffect = /\bwould\b[^.;]{0,180}\binstead\b/i.test(combined);
    const staticAbilityText = /\b(?:creatures?|artifacts?|enchantments?|tokens?|spells?|cards?|lands?|permanents?) you control (?:get|have|can't|cannot|enter tapped|cost|produce)\b/i.test(combined) ||
        /\b(?:creatures?|artifacts?|enchantments?|tokens?|spells?|cards?|lands?|permanents?) you control are (?:indestructible|unblockable|hexproof|shrouded|indestructible|unaffected|exiled|exempt)\b/i.test(combined) ||
        /\b(?:each|all) (?:creatures?|artifacts?|enchantments?|tokens?|spells?|lands?|permanents?) (?:get|have|enter tapped|cost|produce)\b/i.test(combined);
    const consumesSource = /\b(?:sacrifice|discard|exile)\s+(?:this(?: creature| artifact| enchantment| permanent| planeswalker| land| card)?|the source|~)\b/i.test(context) ||
        Boolean(escapedName && new RegExp(`\\b(?:sacrifice|discard|exile)\\s+${escapedName}\\b`, 'i').test(context));
    const spellReuse = /\b(?:flashback|buyback|retrace|escape|jump-start|rebound|aftermath|disturb|adventure)\b/i.test(strategicRoleCardText(card) || fullText || '');
    const indefiniteCastReuse = /\b(?:buyback|retrace|escape)\b/i.test(strategicRoleCardText(card) || fullText || '');

    let kind = 'one_shot', confidence = 0.82, eventText = '';
    const clueInvestigateTrigger = isPermanent &&
        (effect.tokenType === 'clue' || effect.canonical?.params?.tokenType === 'clue') &&
        /\binvestigate\b/i.test(combined) && /\b(?:when|whenever)\b/i.test(combined) &&
        /\bcast\b[\s\S]{0,80}\b(?:instant|sorcery)\b/i.test(combined);
    // Trail of Evidence's investigate event is repeatable because the player can cast more
    // instants/sorceries. Keep it separate from the Clue's own repeatable activated draw effect.
    const oneTimeSelfSacrifice = isPermanent && consumesSource && /\bsacrifice\s+(?:this(?: creature| artifact| enchantment| permanent| planeswalker| land| card)?|the source|~|[\w'’-]+)\b/i.test(combined) &&
        /\bat the beginning of (?:your|the) end step\b|\bat (?:your|the) end step\b/i.test(combined);
    if (clueInvestigateTrigger) {
        kind = 'repeatable_trigger';
        confidence = 0.97;
        eventText = 'you cast an instant or sorcery spell and investigate';
    } else if (oneTimeSelfSacrifice) {
        kind = 'self_event';
        confidence = 0.96;
        eventText = 'this permanent is sacrificed once at the end step';
    } else if (isInstantSorceryOnly) {
        kind = indefiniteCastReuse ? 'repeatable_spell' : (spellReuse ? 'recastable_spell' : 'one_shot');
        confidence = spellReuse ? 0.76 : 0.88;
    } else if (periodicTiming && (isPermanent || !typeLine)) {
        // Some benchmark/highlight-only card records omit type_line. Explicit recurring
        // turn timing is still strong evidence of cadence in that case; do not downgrade it
        // to one-shot merely because the partial record lacks its card type.
        kind = 'periodic_trigger';
        confidence = typeLine ? (timingProfile?.confidence || 0.96) : 0.90;
    } else if (delayedTiming && (isPermanent || !typeLine)) {
        // "Next upkeep/end step" creates a one-time delayed trigger, not a recurring engine.
        kind = 'delayed_trigger';
        confidence = timingProfile?.confidence || 0.86;
    } else if (activation && isPermanent) {
        kind = consumesSource ? 'single_use_activation' : 'repeatable_activation';
        confidence = 0.88;
    } else if (isPermanent && /\bwhen\b/i.test(combined) && selfReference && /\benters? (?:the )?battlefield\b/i.test(combined) && /\buntil end of turn\b/i.test(combined)) {
        kind = 'entry_trigger';
        confidence = 0.94;
        eventText = 'this permanent enters the battlefield and grants a temporary team buff';
    } else if (isPermanent && (replacementEffect || staticAbilityText || /\b(?:as long as|while)\b/i.test(combined) || effect.isStatic === true) && !/\buntil end of turn\b/i.test(combined)) {
        kind = 'ongoing_static';
        confidence = replacementEffect ? 0.93 : 0.84;
    } else if (/\b(?:when|whenever)\b/i.test(combined) && isPermanent) {
        const ownEntry = selfReference && /\b(?:enters? the battlefield|comes into play)\b/i.test(combined);
        const ownOneTimeEvent = selfReference && /\b(?:dies|leaves the battlefield|is sacrificed|is put into a graveyard)\b/i.test(combined);
        const repeatingCombatEvent = /\b(?:attacks|blocks)\b/i.test(combined) && !ownOneTimeEvent;
        if (ownEntry) {
            kind = 'entry_trigger';
            confidence = 0.88;
        } else if (ownOneTimeEvent && !repeatingCombatEvent) {
            kind = 'self_event';
            confidence = 0.76;
        } else {
            kind = 'repeatable_trigger';
            confidence = 0.84;
            const eventMatch = combined.match(/\b(?:whenever|when)\s+([^,.;]+)/i);
            eventText = eventMatch ? eventMatch[0].trim() : '';
        }
    } else if (isPermanent && /\b(?:creatures?|artifacts?|enchantments?|permanents?|lands?|spells?) you control (?:get|have|can't|cannot)|\bas long as\b/i.test(combined)) {
        kind = 'ongoing_static';
        confidence = 0.74;
    }

    const meta = REPEATABILITY_PROFILE_META[kind] || REPEATABILITY_PROFILE_META.unknown;
    return {
        kind,
        group: meta.group,
        strength: meta.strength,
        confidence,
        timingText,
        eventText,
        context: context.slice(0, 240)
    };
}

function annotateEffectRepeatability(card, parsedEffects, textOverride = '') {
    if (!Array.isArray(parsedEffects) || !card) return parsedEffects || [];
    const fullText = strategicRoleCardText(card) || String(textOverride || '');
    const signature = `${String(card.name || '')}|${String(card.type_line || '')}|${fullText}`;
    if (parsedEffects._repeatabilityContextKey === signature) return parsedEffects;
    for (const effect of parsedEffects) {
        if (!effect || typeof effect !== 'object') continue;
        const profile = inferEffectRepeatabilityProfile(card, effect, fullText);
        effect.repeatabilityProfile = profile;
        if (effect.canonical?.params) effect.canonical.params.repeatabilityProfile = profile;
    }
    try { Object.defineProperty(parsedEffects, '_repeatabilityContextKey', { value: signature, writable: true, configurable: true }); }
    catch (_) { parsedEffects._repeatabilityContextKey = signature; }
    return parsedEffects;
}

function getEffectRepeatabilityProfile(value) {
    return value?.repeatabilityProfile || value?.canonical?.params?.repeatabilityProfile || value?.params?.repeatabilityProfile || null;
}

function repeatabilityProfileSimilarity(profileA, profileB) {
    if (!profileA || !profileB || !profileA.kind || !profileB.kind || profileA.group === 'unknown' || profileB.group === 'unknown') return 1;
    let score;
    if (profileA.kind === profileB.kind) score = 1;
    else if (profileA.group === 'repeatable_engine' && profileB.group === 'repeatable_engine') {
        score = (profileA.kind === 'periodic_trigger' || profileB.kind === 'periodic_trigger') ? 0.78 : 0.74;
    } else if (profileA.group === 'single_use' && profileB.group === 'single_use') {
        score = (profileA.kind === 'one_shot' || profileB.kind === 'one_shot') ? 0.78 : 0.70;
    } else if (profileA.group === 'limited_reuse' && profileB.group === 'single_use' || profileB.group === 'limited_reuse' && profileA.group === 'single_use') {
        score = 0.66;
    } else if (profileA.group === 'repeatable_engine' && profileB.group === 'limited_reuse' || profileB.group === 'repeatable_engine' && profileA.group === 'limited_reuse') {
        score = 0.46;
    } else if (profileA.group === 'repeatable_engine' && profileB.group === 'single_use' || profileB.group === 'repeatable_engine' && profileA.group === 'single_use') {
        const oneShot = (profileA.kind === 'one_shot' || profileB.kind === 'one_shot');
        const entryOnly = (profileA.kind === 'entry_trigger' || profileB.kind === 'entry_trigger' || profileA.kind === 'self_event' || profileB.kind === 'self_event');
        score = oneShot ? 0.10 : (entryOnly ? 0.20 : 0.16);
    } else score = 0.55;
    const confidence = Math.min(Number(profileA.confidence ?? 1), Number(profileB.confidence ?? 1));
    return Math.max(0, Math.min(1, 1 - (1 - score) * Math.max(0, Math.min(1, confidence))));
}

function calculateRepeatabilityMismatchSeverity(parsedA = [], parsedB = []) {
    const byFunction = effects => {
        const map = new Map();
        for (const effect of (effects || [])) {
            if (effect?.isCostEffect || effect?.canonical?.params?.isCostEffect) continue;
            const fn = effect?.canonical?.function;
            const profile = getEffectRepeatabilityProfile(effect);
            if (!fn || !profile || profile.group === 'unknown') continue;
            const list = map.get(fn) || [];
            list.push({ effect, profile, importance: Math.max(0.05, Number(effect.importance) || 0.5) });
            map.set(fn, list);
        }
        return map;
    };
    const aMap = byFunction(parsedA), bMap = byFunction(parsedB);
    let maxSeverity = 0;
    for (const [fn, aList] of aMap) {
        const bList = bMap.get(fn);
        if (!bList?.length) continue;
        let bestSimilarity = 0, bestWeight = 0;
        for (const a of aList) for (const b of bList) {
            const sim = repeatabilityProfileSimilarity(a.profile, b.profile);
            const weight = Math.sqrt(a.importance * b.importance);
            if (sim > bestSimilarity || (sim === bestSimilarity && weight > bestWeight)) {
                bestSimilarity = sim;
                bestWeight = weight;
            }
        }
        // Only treat large repeatability gaps as an important mismatch. Small differences such as
        // periodic upkeep triggers versus other reusable triggers remain reasonably close.
        if (bestSimilarity < 0.42) {
            const severity = (1 - bestSimilarity) * Math.min(1, bestWeight / 0.55 + 0.25);
            maxSeverity = Math.max(maxSeverity, severity);
        }
    }
    return Math.max(0, Math.min(1, maxSeverity));
}

function hasRepeatableEffectForFunctions(parsedEffects, functionNames) {
    const wanted = functionNames instanceof Set ? functionNames : new Set(Array.isArray(functionNames) ? functionNames : [functionNames]);
    return (parsedEffects || []).some(effect => wanted.has(effect?.canonical?.function) &&
        getEffectRepeatabilityProfile(effect)?.group === 'repeatable_engine');
}


// Card acquisition cadence is important for substitution: a one-time ETB cantrip is not a
// functional substitute for a permanent that repeatedly draws cards. Keep this classification
// tied to effects that actually acquire cards; a phrase like "whenever you draw a card" in a
// creature-buff trigger must not be mistaken for that creature drawing cards itself.
function isDirectCardDrawOutcome(effect) {
    if (!effect || effect.isCostEffect || effect.canonical?.params?.isCostEffect) return false;
    const fn = effect.canonical?.function || effect.function || '';
    if (!(fn === 'card_draw' || fn === 'draw' || effect.action === 'draw')) return false;
    // If a clause starts with a draw event, that draw may be the TRIGGER condition rather than
    // the resolution. Only count a draw after the trigger comma as an outcome (e.g. "Whenever
    // you draw a card, this gets +2/+2" must not become a card-draw effect).
    const clause = String(effect.contextClause || effect.parentClauseRaw || effect.raw || effect.canonical?.params?.raw || '').trim();
    const triggerParts = clause.match(/\b(?:when|whenever)\b[^,;]{1,220},\s*([^.;]+)/i);
    const resolution = triggerParts ? triggerParts[1] : clause;
    return /\b(?:draw|draws)\s+(?:a|one|two|three|four|five|\d+|x)\s+cards?\b/i.test(resolution);
}

function getDirectCardAcquisitionCadence(card, parsedEffects = []) {
    const effects = Array.isArray(parsedEffects) ? parsedEffects : [];
    const directDrawEffects = effects.filter(isDirectCardDrawOutcome);
    const profiles = directDrawEffects.map(effect => getEffectRepeatabilityProfile(effect)).filter(Boolean);
    const repeatable = profiles.some(profile => profile.group === 'repeatable_engine');
    const singleUse = profiles.length > 0 && profiles.every(profile => profile.group === 'single_use');
    const entryOnly = profiles.length > 0 && profiles.every(profile =>
        profile.kind === 'entry_trigger' || profile.kind === 'delayed_trigger' || profile.kind === 'one_shot' || profile.kind === 'self_event' || profile.kind === 'single_use_activation'
    );
    return {
        hasAcquisition: directDrawEffects.length > 0,
        repeatable,
        singleUse,
        entryOnly,
        profiles,
        cardName: String(card?.name || '')
    };
}

function calculateCardAcquisitionCadenceMismatch(parsedA = [], parsedB = []) {
    const a = getDirectCardAcquisitionCadence(null, parsedA);
    const b = getDirectCardAcquisitionCadence(null, parsedB);
    if (!a.hasAcquisition || !b.hasAcquisition) return 0;
    // Only compare cadence when one side provides a genuine repeatable engine and the other
    // side's matching card-draw effects are all one-use. A repeatable effect on either card is
    // enough to avoid treating a mixed-cadence card as a pure one-shot substitute.
    if (a.repeatable && !b.repeatable && b.singleUse) return b.entryOnly ? 0.98 : 0.90;
    if (b.repeatable && !a.repeatable && a.singleUse) return a.entryOnly ? 0.98 : 0.90;
    return 0;
}

function calculateSourceAcquisitionCadenceMismatch(sourceCadence, candidateCard, candidateEffects = []) {
    if (!sourceCadence?.hasAcquisition || !sourceCadence.repeatable) return 0;
    const candidate = getDirectCardAcquisitionCadence(candidateCard, candidateEffects);
    if (!candidate.hasAcquisition || candidate.repeatable || !candidate.singleUse) return 0;
    // This is deliberately a ranking penalty, not a hard filter: one-shot draw creatures can
    // still appear as related cards, but they should not outrank genuine recurring draw engines.
    return candidate.entryOnly ? 0.98 : 0.90;
}

function strategicRoleMaxNumber(parsedEffects, fn) {
    let max = 0;
    for (const e of (parsedEffects || [])) {
        if (!e.canonical || e.canonical.function !== fn) continue;
        if (fn === 'mana_ability') {
            if (e.manaNetAmount != null && Number.isFinite(Number(e.manaNetAmount))) max = Math.max(max, Number(e.manaNetAmount));
            else if (e.canonical.params?.manaNetAmount != null && Number.isFinite(Number(e.canonical.params.manaNetAmount))) max = Math.max(max, Number(e.canonical.params.manaNetAmount));
            else if (typeof e.quantity === 'number') max = Math.max(max, e.quantity);
            continue;
        }
        if (typeof e.quantity === 'number') max = Math.max(max, e.quantity);
        if (typeof e.amount === 'number') max = Math.max(max, e.amount);
        if (typeof e.canonical.params?.quantity === 'number') max = Math.max(max, e.canonical.params.quantity);
    }
    return max;
}

function strategicRoleAdd(out, role, score, anchors, confidenceBoost = 0) {
    const cleanAnchors = Array.from(new Set((anchors || []).filter(Boolean)));
    const anchorBonus = Math.min(0.10, cleanAnchors.length * 0.025) + confidenceBoost;
    const finalScore = Math.min(1, score + anchorBonus);
    if (finalScore < STRATEGIC_ROLE_MIN_SCORE) return;
    const existing = out.find(x => x.role === role);
    const record = {
        role,
        group: STRATEGIC_ROLE_GROUPS[role] || role,
        score: finalScore,
        anchors: cleanAnchors
    };
    if (!existing || finalScore > existing.score) {
        if (existing) Object.assign(existing, record);
        else out.push(record);
    }
}

function inferStrategicRoleProfileUncached(card, parsedEffects = [], intentText = '') {
    const text = strategicRoleCardText(card);
    const lower = `${text} ${String(intentText || '')}`.toLowerCase();
    const typeLine = String(card?.type_line || '').toLowerCase();
    annotateEffectRepeatability(card, parsedEffects, text);
    const roles = [];
    const functions = new Set(strategicRoleFunctions(parsedEffects));
    const recurring = (parsedEffects || []).some(e => getEffectRepeatabilityProfile(e)?.group === 'repeatable_engine');
    const activated = (parsedEffects || []).some(e => getEffectRepeatabilityProfile(e)?.kind === 'repeatable_activation') ||
        /\bpay\b|\{t\}|\b:\s*(?:add|draw|return|exile|search|create)/i.test(text);
    const permanent = /\b(?:creature|artifact|enchantment|planeswalker|land|battle)\b/.test(typeLine);

    // Fast mana: require an explicit mana-producing ability plus either >1 mana per activation,
    // or a clearly early/efficient nonland permanent. A generic "add one mana" land is not enough.
    const maxMana = strategicRoleMaxNumber(parsedEffects, 'mana_ability');
    if (functions.has('mana_ability')) {
        // Use net mana, not the number of output symbols. A signet that spends {1} to add two
        // mana is a net +1 mana source, even though its Oracle text contains two output symbols.
        const lowCostPermanent = permanent && Number.isFinite(card?.cmc) && card.cmc <= 2;
        if (maxMana >= 2) {
            strategicRoleAdd(roles, 'fast_mana', 0.82, ['reusable mana production', 'multiple net mana per activation'], lowCostPermanent ? 0.05 : 0);
        } else if (lowCostPermanent && activated) {
            strategicRoleAdd(roles, 'fast_mana', 0.64, ['early permanent mana source', 'activated mana ability']);
        }
    }

    // Land ramp / catch-up ramp. These rely on explicit library/basic-land language plus moving
    // a land into play or a known catch-up condition. This is intentionally narrower than "tutor".
    const searchesLand = functions.has('ramp_tutor') || (functions.has('tutor') && /\b(?:basic|land|plains|island|swamp|mountain|forest)\b/.test(lower));
    const putLandIntoPlay = /\bsearch your library\b[^.]{0,120}\b(?:land|basic land|plains|island|swamp|mountain|forest)\b[^.]{0,120}\bput (?:it|that card|the card)\b[^.]{0,60}\b(?:onto|to) the battlefield\b/.test(lower)
        || /\b(?:put|return)\b[^.]{0,120}\b(?:land|basic land|plains|island|swamp|mountain|forest)\b[^.]{0,60}\b(?:onto|to) the battlefield\b/.test(lower);
    if (searchesLand && putLandIntoPlay) {
        const catchUp = /\b(?:opponent|opponents)\b[^.]{0,90}\b(?:more lands|more land)\b|\bfewer lands\b|\bif an opponent controls more lands\b/.test(lower);
        strategicRoleAdd(roles, catchUp ? 'catch_up_ramp' : 'land_ramp', catchUp ? 0.88 : 0.72,
            [catchUp ? 'opponent has more lands' : 'land-search', 'land into play']);
    }

    // Recurring card advantage engine: a draw effect alone is too broad. Require repeated timing,
    // an activated resource payment, or explicit top-of-library/exile-to-hand acquisition. This
    // intentionally catches Arena, Dark Confidant and Necropotence despite different wording.
    const directDraw = /\bdraw\s+(?:a|one|two|three|four|five|x)\s+cards?\b/.test(lower);
    const handAcquisition = /\b(?:put|puts|return|returns)\b[^.]{0,90}\b(?:card|cards|that card|those cards)\b[^.]{0,50}\b(?:into|to) your hand\b/.test(lower);
    const topCardAcquisition = /\b(?:reveal|exile)\s+the top card\b[^.]{0,100}\b(?:hand|put it into your hand|cards? exiled)\b/.test(lower);
    const recurringAcquisition = directDraw || handAcquisition || topCardAcquisition;
    const acquisitionText = /\bdraw(?:s)?\s+(?:a|one|two|three|four|five|\d+|x)\s+cards?\b|\b(?:put|puts|return|returns)\b[^.;]{0,100}\b(?:card|cards|it|them)\b[^.;]{0,60}\b(?:into|to) your hand\b|\b(?:reveal|exile)\s+the top card\b/i;
    const acquisitionIsRepeatable = (parsedEffects || []).some(e =>
        getEffectRepeatabilityProfile(e)?.group === 'repeatable_engine' &&
        (e?.canonical?.function === 'card_draw' || acquisitionText.test(String(e?.raw || e?.canonical?.params?.raw || '')))
    );
    // Investigate grants a reusable Clue token, whose rules-defined {2}, sacrifice it: draw a card
    // ability turns repeatable token production into repeatable card advantage. The derived draw
    // atom is not literally printed on Trail of Evidence, so join it to the matching Clue trigger.
    const repeatableClueToken = (parsedEffects || []).some(e => e?.canonical?.function === 'token_creation' &&
        e.canonical.params?.tokenType === 'clue' && getEffectRepeatabilityProfile(e)?.group === 'repeatable_engine');
    const repeatableClueDraw = repeatableClueToken && (parsedEffects || []).some(e =>
        e?.canonical?.function === 'card_draw' && e.canonical.params?.derivedFromTokenAbility &&
        getEffectRepeatabilityProfile(e)?.kind === 'repeatable_activation');
    // A trigger elsewhere on a card must not turn its unrelated one-shot draw into an engine.
    // Resource costs alone are not evidence of repeatability, except for this explicit Clue link.
    if ((recurringAcquisition && acquisitionIsRepeatable) || repeatableClueDraw) {
        const timingAnchor = (parsedEffects || []).some(e => getEffectRepeatabilityProfile(e)?.kind === 'periodic_trigger' && acquisitionText.test(String(e?.raw || e?.canonical?.params?.raw || '')));
        strategicRoleAdd(roles, 'card_advantage_engine', 0.84,
            [repeatableClueDraw ? 'repeatable Clue-token draw' : directDraw ? 'card draw' : 'card acquisition', timingAnchor ? 'repeat timing' : 'repeatable acquisition', activated ? 'reusable ability' : null]);
    }

    // Token production is an engine only when the creation effect itself can recur. A permanent
    // with a one-time enters-the-battlefield token trigger is not equivalent to a repeatable token
    // maker, and an instant/sorcery that creates tokens is not an engine at all.
    if (functions.has('token_multiplier') || /\b(?:twice|double|two times)\b[^.]{0,70}\b(?:token|tokens)\b/.test(lower)) {
        strategicRoleAdd(roles, 'token_multiplier', 0.90, ['token multiplication']);
    }
    const repeatableTokenCreation = hasRepeatableEffectForFunctions(parsedEffects, ['token_creation']);
    if (repeatableTokenCreation) {
        strategicRoleAdd(roles, 'token_engine', 0.78, ['token creation', 'repeated creation']);
    }

    // Tribal anthem: subtype-specific team buff is much more discriminating than a generic anthem.
    const tribalBuffPattern = /\bother\s+(?:[a-z]+\s+)?(?:creatures?|merfolk|elves?|goblins?|zombies?|soldiers?|humans?|spirits?|knights?|wizards?|cats?|dogs?|dragons?|angels?|vampires?|clerics?|warriors?)\s+get\s+[+−+\-]\d+\/[+−+\-]\d+/i;
    if (functions.has('tribal_anthem') || tribalBuffPattern.test(lower)) {
        const tribeMatch = lower.match(/\b(?:other\s+)?([a-z]+)\s+(?:creatures?|merfolk|elves?|goblins?|zombies?|soldiers?|humans?|spirits?|knights?|wizards?|cats?|dogs?|dragons?|angels?|vampires?|clerics?|warriors?)\s+get\s+[+−+\-]\d+\/[+−+\-]\d+/i);
        strategicRoleAdd(roles, 'tribal_anthem', 0.86, ['tribe-specific anthem', tribeMatch ? tribeMatch[1] : null]);
    }

    // General anthem: reserve for team-wide stat/keyword changes that are not clearly tribal.
    if (functions.has('anthem') && !functions.has('tribal_anthem')) {
        strategicRoleAdd(roles, 'anthem', 0.70, ['team stat/keyword buff']);
    }
    if ((parsedEffects || []).some(effect => Boolean(effect.canonical?.params?.combatFinisher) || Boolean(effect.combatFinisher))) {
        strategicRoleAdd(roles, 'combat_finisher', 0.96, ['creature-count-scaled team buff', 'flying grant', 'combat finisher']);
    }

    // Interaction roles. Board wipe needs explicit mass language; removal needs a target; counter
    // needs the canonical counter function. Burn is constrained to direct damage + low investment
    // so a big creature's damage trigger doesn't become "Lightning Bolt-like".
    if (functions.has('counter')) {
        strategicRoleAdd(roles, 'counterspell', 0.90, ['counter magic']);
    }
    const massText = /\b(?:destroy|exile)\s+(?:all|each)\s+(?:creatures?|permanents?|planeswalkers?|artifacts?|enchantments?|players?)\b/.test(lower);
    if (massText) {
        strategicRoleAdd(roles, 'board_wipe', 0.90, ['mass removal']);
    } else if ((functions.has('removal') || functions.has('exile_removal')) && /\b(?:destroy|exile)\b/.test(lower)) {
        strategicRoleAdd(roles, 'single_target_removal', 0.75, ['permanent removal']);
    }
    if (/\breturn\b[^.]{0,100}\btarget\b[^.]{0,80}(?:to|into) its owner(?:'s|s) hand\b/.test(lower) || /\breturn\b[^.]{0,100}\b(?:permanent|creature|artifact|enchantment|planeswalker)\b[^.]{0,80}\bto its owner(?:'s|s) hand\b/.test(lower)) {
        strategicRoleAdd(roles, 'bounce', 0.78, ['bounce/tempo']);
    }
    const damage = functions.has('direct_damage');
    if (damage) {
        const lowCost = Number.isFinite(card?.cmc) && card.cmc <= 2;
        const smallSpell = /\b(?:instant|sorcery)\b/.test(typeLine) || /\bdeal(?:s|)\s+\d+\s+damage\b/.test(lower);
        strategicRoleAdd(roles, 'burn', lowCost || smallSpell ? 0.78 : 0.66, ['direct damage', lowCost ? 'low cost' : null]);
    }

    // Recursion and tutors.
    if (functions.has('reanimate') || functions.has('recursion')) {
        strategicRoleAdd(roles, 'graveyard_recursion', 0.88, ['graveyard return']);
    }
    if (functions.has('tutor') || functions.has('ramp_tutor')) {
        strategicRoleAdd(roles, 'tutor', 0.72, ['search library']);
    }
    const repeatableDiscard = hasRepeatableEffectForFunctions(parsedEffects, ['discard']);
    const repeatableMill = hasRepeatableEffectForFunctions(parsedEffects, ['mill']);
    const repeatableLifeGain = hasRepeatableEffectForFunctions(parsedEffects, ['gain_life']);
    const repeatableLifeLoss = hasRepeatableEffectForFunctions(parsedEffects, ['lose_life']);
    if (functions.has('discard')) {
        strategicRoleAdd(roles, 'discard_engine', repeatableDiscard ? 0.72 : 0.63, ['discard', repeatableDiscard ? 'repeated disruption' : null]);
    }
    if (functions.has('mill')) {
        strategicRoleAdd(roles, 'mill_engine', repeatableMill ? 0.72 : 0.63, ['mill', repeatableMill ? 'repeated mill' : null]);
    }
    if (functions.has('gain_life') && /\b(?:gain|gains)\s+(?:\d+|life)\s+life\b/.test(lower)) strategicRoleAdd(roles, 'life_gain_engine', repeatableLifeGain ? 0.72 : 0.63, ['life gain']);
    const directLifeLoss = /\b(?:you|target|each opponent|opponent)\s+(?:lose|loses)\s+(?:\d+|life)\s+life\b/.test(lower);
    // Standard Oracle wording for opponent-turn taxes often names the affected player as "that
    // player", not "each opponent". Preserve the opponent-upkeep context so this is recognized as
    // a recurring life-loss engine without broadly treating every "that player loses life" clause
    // as an opponent-facing engine.
    const opponentUpkeepLifeLoss = /\beach opponent(?:'s|’s) upkeep\b[^.]{0,180}\bthat player loses?\s+(?:\d+|x|life)\s+life\b/i.test(lower);
    if (functions.has('lose_life') && (directLifeLoss || opponentUpkeepLifeLoss)) {
        strategicRoleAdd(roles, 'life_loss_engine', repeatableLifeLoss ? 0.72 : 0.63, ['life loss', opponentUpkeepLifeLoss ? 'opponent upkeep trigger' : null]);
    }

    roles.sort((a, b) => b.score - a.score);
    return roles.slice(0, 4);
}


// Strategic-role inference scans the full Oracle text with many regular expressions. The scoring
// pipeline requests both an intrinsic profile (empty intent text) and an intent-conditioned profile
// for the same card, and benchmark runs revisit many of the same parsed card texts. Parsed-effect
// arrays are immutable in their mechanical meaning after parsing/annotation, so cache by that array
// identity plus the explicit card context and intent. WeakMap ownership avoids retaining old arrays.
const strategicRoleProfileCacheByEffects = new WeakMap();
const strategicRoleProfileCacheStats = { hits: 0, computed: 0 };
function inferStrategicRoleProfile(card, parsedEffects = [], intentText = '') {
    if (!card || typeof card !== 'object' || !Array.isArray(parsedEffects)) {
        return inferStrategicRoleProfileUncached(card, parsedEffects, intentText);
    }
    const oracle = strategicRoleCardText(card);
    const keywords = Array.isArray(card.keywords) ? card.keywords.map(String).join('|') : '';
    const signature = `${normalizeCardNameForIdentity(card.name || '')}|${String(card.type_line || '')}|${Number.isFinite(Number(card.cmc)) ? Number(card.cmc) : ''}|${keywords}|${oracle}|intent:${String(intentText || '')}`;
    let byContext = strategicRoleProfileCacheByEffects.get(parsedEffects);
    if (byContext?.has(signature)) {
        strategicRoleProfileCacheStats.hits++;
        return byContext.get(signature);
    }
    const profile = inferStrategicRoleProfileUncached(card, parsedEffects, intentText);
    if (!byContext) {
        byContext = new Map();
        strategicRoleProfileCacheByEffects.set(parsedEffects, byContext);
    }
    // A parsed array might occasionally be reused with many edited intent contexts. Keep that
    // branch bounded; LRU freshness is not needed for this short per-card cache.
    if (byContext.size >= 8) byContext.clear();
    byContext.set(signature, profile);
    strategicRoleProfileCacheStats.computed++;
    return profile;
}

function calculateStrategicRoleScore(sourceProfile, candidateProfile, sourceFingerprint = null, candidateFingerprint = null) {
    if (!sourceProfile?.length || !candidateProfile?.length) return 0;
    let best = 0;
    for (const sourceRole of sourceProfile) {
        for (const candidateRole of candidateProfile) {
            const sameRole = sourceRole.role === candidateRole.role;
            const sameGroup = sourceRole.group && candidateRole.group && sourceRole.group === candidateRole.group;
            if (!sameRole && !sameGroup) continue;

            const strength = Math.sqrt(Math.max(0, sourceRole.score) * Math.max(0, candidateRole.score));
            let match = 0;
            if (sameRole) {
                const anchorOverlap = new Set(sourceRole.anchors || []).size > 0
                    ? (candidateRole.anchors || []).filter(a => (sourceRole.anchors || []).includes(a)).length / Math.max(1, new Set(sourceRole.anchors || []).size)
                    : 0;
                const fingerprintMatch = roleFingerprintSimilarity(sourceFingerprint, candidateFingerprint);
                // Same role is only a hypothesis. Specific role fingerprints carry most of the
                // evidence so generic rocks/card-draw permanents do not all cluster near 1.0.
                match = 0.15 + (0.30 * strength) + (0.45 * fingerprintMatch) + (0.10 * anchorOverlap);
            } else {
                match = 0.20 + 0.22 * strength;
            }
            best = Math.max(best, Math.min(1, match));
        }
    }
    return best;
}

function extractNumericWords(text) {
    const lower = String(text || '').toLowerCase();
    const wordValues = { one:1, two:2, three:3, four:4, five:5, six:6, seven:7, eight:8, nine:9, ten:10, eleven:11, twelve:12 };
    const out = [];
    for (const m of lower.matchAll(/\b(\d+)\b/g)) out.push(Number(m[1]));
    for (const m of lower.matchAll(/\b(one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve)\b/g)) out.push(wordValues[m[1]]);
    return out.filter(Number.isFinite);
}

function buildStrategicRoleFingerprintUncached(card, parsedEffects = [], profile = []) {
    const text = strategicRoleCardText(card);
    const lower = text.toLowerCase();
    const topRole = profile?.[0]?.role || null;
    annotateEffectRepeatability(card, parsedEffects, text);
    const recurring = (parsedEffects || []).some(e => getEffectRepeatabilityProfile(e)?.group === 'repeatable_engine');
    const permanent = /\b(?:creature|artifact|enchantment|planeswalker)\b/.test(String(card?.type_line || '').toLowerCase());
    const damageAmounts = [...lower.matchAll(/\b(?:deal|deals)\s+(\d+)\s+damage\b/g)].map(m => Number(m[1])).filter(Number.isFinite);
    const manaEffects = (parsedEffects || []).filter(e => e?.canonical?.function === 'mana_ability');
    const manaNetValues = manaEffects.map(e => e.manaNetAmount).filter(value => value != null && Number.isFinite(Number(value))).map(Number);
    const manaOutputValues = manaEffects.map(e => e.manaOutputAmount ?? e.amount).filter(value => value != null && Number.isFinite(Number(value))).map(Number);
    const manaPerActivation = manaNetValues.length ? Math.max(...manaNetValues) : strategicRoleMaxNumber(parsedEffects, 'mana_ability');
    const manaOutputPerActivation = manaOutputValues.length ? Math.max(...manaOutputValues) : null;
    const primaryManaEffect = manaEffects.slice().sort((a,b) => (Number(b.manaNetAmount ?? b.amount) || 0) - (Number(a.manaNetAmount ?? a.amount) || 0))[0] || null;
    const primaryManaProfile = primaryManaEffect?.manaOutput || null;
    const activationManaCost = primaryManaEffect?.activationCost || null;
    const drawAmount = Math.max(
        ...[...lower.matchAll(/\bdraw\s+(\d+)\s+cards?\b/g)].map(m => Number(m[1])).filter(Number.isFinite),
        /\bdraw\s+(?:a|one)\s+card\b/.test(lower) ? 1 : 0,
        0
    );
    const lifePaid = /\b(?:pay|lose)\s+(?:\d+|a|one)\s+life\b|\bpay\s+life\b|\breveal the top card\b|\bskip your draw step\b/.test(lower);
    const lifeLoss = [...lower.matchAll(/\b(?:lose|loses)\s+(\d+)\s+life\b/g)].map(m => Number(m[1])).filter(Number.isFinite);
    const tribeMatch = lower.match(/\b(?:other\s+)?([a-z]+)\s+(?:creatures?|merfolk|elves?|goblins?|zombies?|soldiers?|humans?|spirits?|knights?|wizards?|cats?|dogs?|dragons?|angels?|vampires?|clerics?|warriors?)\s+get\b/i);
    const sourceRole = profile?.find(r => r.role === topRole) || profile?.[0] || null;
    return {
        role: topRole,
        group: sourceRole?.group || null,
        recurring,
        permanent,
        cmc: Number.isFinite(card?.cmc) ? Number(card.cmc) : null,
        primaryFunction: strategicRoleFunctions(parsedEffects)[0] || null,
        manaPerActivation,
        manaOutputPerActivation,
        manaOutputMode: primaryManaEffect?.manaOutputMode || primaryManaProfile?.mode || null,
        manaOutputColors: primaryManaEffect?.manaOutputColors || primaryManaProfile?.colors || [],
        activationManaMin: activationManaCost?.manaMin ?? 0,
        activationManaMax: activationManaCost?.manaMax ?? 0,
        drawAmount,
        damageAmount: Math.max(...damageAmounts, 0),
        lifePaid,
        lifeLoss: Math.max(...lifeLoss, 0),
        tribe: tribeMatch ? tribeMatch[1] : null,
        activated: (parsedEffects || []).some(e => getEffectRepeatabilityProfile(e)?.kind === 'repeatable_activation') || /\bpay\b|\{t\}|\bsacrifice\b.*:\s*/i.test(text),
        strength: sourceRole?.score || 0
    };
}


// The fingerprint repeats text regex scans and several parsed-effect reductions after role inference.
// Cache it by effect-array identity and profile identity (the profile already includes intent text).
// Card signature guards against reusing a fingerprint when card metadata is edited/replaced.
const strategicRoleFingerprintCacheByEffects = new WeakMap();
const strategicRoleFingerprintCacheStats = { hits: 0, computed: 0 };
function buildStrategicRoleFingerprint(card, parsedEffects = [], profile = []) {
    if (!card || typeof card !== 'object' || !Array.isArray(parsedEffects) || !profile || typeof profile !== 'object') {
        return buildStrategicRoleFingerprintUncached(card, parsedEffects, profile);
    }
    let byProfile = strategicRoleFingerprintCacheByEffects.get(parsedEffects);
    if (!byProfile) {
        byProfile = new WeakMap();
        strategicRoleFingerprintCacheByEffects.set(parsedEffects, byProfile);
    }
    let byContext = byProfile.get(profile);
    if (!byContext) {
        byContext = new Map();
        byProfile.set(profile, byContext);
    }
    const text = strategicRoleCardText(card);
    const signature = `${normalizeCardNameForIdentity(card.name || '')}|${String(card.type_line || '')}|${Number.isFinite(Number(card.cmc)) ? Number(card.cmc) : ''}|${Array.isArray(card.keywords) ? card.keywords.map(String).join('|') : ''}|${text}`;
    if (byContext.has(signature)) {
        strategicRoleFingerprintCacheStats.hits++;
        return byContext.get(signature);
    }
    const fingerprint = buildStrategicRoleFingerprintUncached(card, parsedEffects, profile);
    if (byContext.size >= 4) byContext.clear();
    byContext.set(signature, fingerprint);
    strategicRoleFingerprintCacheStats.computed++;
    return fingerprint;
}

const STRATEGIC_INTENT_ROLES = new Set([
    'fast_mana', 'card_advantage_engine', 'token_multiplier', 'tribal_anthem',
    'catch_up_ramp', 'land_ramp', 'token_engine',
    // A highlighted clause narrows *which part* is being compared; it should not erase a strong
    // archetype signal such as low-cost counter-magic, burn, reanimation, sweepers or modal utility.
    'counterspell', 'burn', 'graveyard_recursion', 'board_wipe', 'combat_finisher',
    'anthem', 'bounce', 'tutor', 'life_gain_engine', 'life_loss_engine'
]);

function inferRankingIntent(sourceCard, parsedSourceEffects = [], targetText = '', sourceRoleProfile = [], highlights = []) {
    const exactHighlights = (highlights || []).filter(h => h?.mode === 'exact');
    const flexibleHighlights = (highlights || []).filter(h => h?.mode === 'variable');
    const topRole = sourceRoleProfile?.[0];
    const roleIsStrong = Boolean(topRole && STRATEGIC_INTENT_ROLES.has(topRole.role) && topRole.score >= 0.74);
    const effectCount = (parsedSourceEffects || []).filter(e => e && e.action && e.action !== 'generic').length;
    const fullOracle = String(sourceCard?.oracle_text || (sourceCard?.card_faces || []).map(f => f?.oracle_text || '').join(' ') || '');
    const sourceHasModalSet = shouldUseModalModeIntent(fullOracle, false, [], 0);
    const modalIntentIsExplicit = sourceHasModalSet && (
        !(highlights || []).length ||
        (highlights || []).some(h => /\bchoose\s+(?:up to two|up to three|up to four|one or more|any number|one|two|three|four)\b/i.test(String(h?.text || ''))) ||
        (highlights || []).filter(h => h?.field !== 'type').length >= 2
    );
    // Modal cards may superficially resemble one role (e.g. bounce) because one option is bounce.
    // If the selection covers the modal instruction or multiple options, preserve modal-set context.
    if (modalIntentIsExplicit) {
        return {
            kind: 'hybrid_effect', confidence: exactHighlights.length ? 0.94 : 0.88,
            role: null, hasExactHighlight: exactHighlights.length > 0,
            hasFlexibleHighlight: flexibleHighlights.length > 0, hasModalModes: true
        };
    }
    const allHighlightsFlexible = flexibleHighlights.length > 0 && exactHighlights.length === 0;
    if (allHighlightsFlexible && roleIsStrong && Number(topRole?.score) >= 0.82) {
        return {
            kind: 'strategic_role', confidence: Math.min(1, 0.76 + Number(topRole.score) * 0.24),
            role: topRole.role, hasExactHighlight: false, hasFlexibleHighlight: true,
            roleDrivenFlexibleHighlights: true
        };
    }
    if ((highlights || []).length) {
        return { kind:'highlighted_effect', confidence: exactHighlights.length ? 0.94 : 0.86, role: roleIsStrong ? topRole.role : null, hasExactHighlight: exactHighlights.length > 0, hasFlexibleHighlight: flexibleHighlights.length > 0 };
    }
    if (roleIsStrong) {
        return { kind:'strategic_role', confidence:Math.min(1, 0.72 + topRole.score * 0.28), role:topRole.role, hasExactHighlight:false, hasFlexibleHighlight:false };
    }
    if (effectCount >= 2) {
        return { kind:'hybrid_effect', confidence:Math.min(1, 0.70 + Math.min(0.25, effectCount * 0.04)), role:topRole?.role || null, hasExactHighlight:false, hasFlexibleHighlight:false };
    }
    return { kind:'effect_match', confidence:Math.max(0.55, Math.min(1, 0.55 + (topRole?.score || 0) * 0.20)), role:topRole?.role || null, hasExactHighlight:false, hasFlexibleHighlight:false };
}

function roleFingerprintSimilarity(sourceFingerprint, candidateFingerprint) {
    if (!sourceFingerprint?.role || !candidateFingerprint?.role || sourceFingerprint.role !== candidateFingerprint.role) return 0;
    let score = 0, weight = 0;
    const add = (a, b, w) => {
        if (a === null || a === undefined || b === null || b === undefined) return;
        weight += w;
        if (typeof a === 'boolean' || typeof b === 'boolean' || typeof a === 'string' || typeof b === 'string') {
            score += a === b ? w : 0;
        } else {
            score += w * Math.max(0, 1 - Math.abs(Number(a) - Number(b)) / Math.max(Number(a), Number(b), 1));
        }
    };
    if (sourceFingerprint.role === 'fast_mana') {
        add(sourceFingerprint.manaPerActivation, candidateFingerprint.manaPerActivation, 0.38);
        add(sourceFingerprint.manaOutputPerActivation, candidateFingerprint.manaOutputPerActivation, 0.12);
        add(sourceFingerprint.manaOutputMode, candidateFingerprint.manaOutputMode, 0.16);
        add(sourceFingerprint.activationManaMin, candidateFingerprint.activationManaMin, 0.08);
        add(sourceFingerprint.activationManaMax, candidateFingerprint.activationManaMax, 0.06);
        add(sourceFingerprint.cmc, candidateFingerprint.cmc, 0.10);
        add(sourceFingerprint.recurring, candidateFingerprint.recurring, 0.07);
        add(sourceFingerprint.activated, candidateFingerprint.activated, 0.03);
    } else if (sourceFingerprint.role === 'card_advantage_engine') {
        add(sourceFingerprint.recurring, candidateFingerprint.recurring, 0.30);
        add(sourceFingerprint.lifePaid, candidateFingerprint.lifePaid, 0.20);
        add(sourceFingerprint.drawAmount || 1, candidateFingerprint.drawAmount || 1, 0.20);
        add(sourceFingerprint.permanent, candidateFingerprint.permanent, 0.15);
        add(sourceFingerprint.activated, candidateFingerprint.activated, 0.10);
    } else if (sourceFingerprint.role === 'tribal_anthem') {
        if (sourceFingerprint.tribe || candidateFingerprint.tribe) {
            weight += 0.55;
            score += sourceFingerprint.tribe && candidateFingerprint.tribe && sourceFingerprint.tribe === candidateFingerprint.tribe ? 0.55 : 0;
        }
        add(sourceFingerprint.permanent, candidateFingerprint.permanent, 0.20);
    } else if (sourceFingerprint.role === 'burn') {
        add(sourceFingerprint.damageAmount || 0, candidateFingerprint.damageAmount || 0, 0.60);
        add(sourceFingerprint.cmc, candidateFingerprint.cmc, 0.20);
        add(sourceFingerprint.recurring, candidateFingerprint.recurring, 0.10);
    } else {
        add(sourceFingerprint.recurring, candidateFingerprint.recurring, 0.25);
        add(sourceFingerprint.permanent, candidateFingerprint.permanent, 0.15);
        add(sourceFingerprint.primaryFunction, candidateFingerprint.primaryFunction, 0.30);
    }
    return weight > 0 ? Math.max(0, Math.min(1, score / weight)) : 0;
}

function strategicRoleToText(profile) {
    if (!profile?.length) return '';
    return profile.map(r => `${r.role.replace(/_/g, ' ')} ${r.anchors?.join(' ') || ''}`.trim()).join('; ');
}

// Sparse function-affinity matrix. Related functions get a graded relationship instead of
// collapsing into the old same-function/same-outcome/same-family tiers.
const FUNCTION_LABELS = [
    'removal', 'exile_removal', 'bounce', 'tuck', 'sacrifice', 'self_sacrifice',
    'reanimate', 'recursion', 'cheat_into_play', 'token_creation', 'token_multiplier',
    'card_draw', 'tutor', 'ramp_tutor', 'counter', 'cost_reduction', 'stat_buff', 'tribal_anthem',
    'direct_damage', 'lose_life', 'gain_life', 'discard', 'mill', 'mana_ability',
    'tap', 'untap', 'anthem', 'cast_timing_permission',
    'mechanic_recruit', 'mechanic_storied', 'mechanic_hone_counter', 'mechanic_empower_jace',
    'mechanic_heartwood_token', 'mechanic_plan_progression', 'mechanic_worthy_equip',
    'mechanic_vibranium_token', 'mechanic_prepared_spell', 'mechanic_casting_mode_profile',
    'mechanic_spell_replay_profile', 'mechanic_combat_rules_profile', 'mechanic_stateful_game_profile',
    'mechanic_permanent_progression_profile', 'mechanic_game_state_condition_profile',
    'mechanic_delayed_hand_exile_cast_profile', 'mechanic_multiplayer_decision_profile',
    'mechanic_auxiliary_game_component_profile', 'mechanic_rules_modification_profile'
];
const FUNCTION_INDEX = new Map(FUNCTION_LABELS.map((name, i) => [name, i]));
const FUNCTION_AFFINITY_MATRIX = Array.from({ length: FUNCTION_LABELS.length }, () => Array(FUNCTION_LABELS.length).fill(0));
FUNCTION_LABELS.forEach((fn, i) => { FUNCTION_AFFINITY_MATRIX[i][i] = 1; });
function setFunctionAffinity(a, b, value) {
    const ia = FUNCTION_INDEX.get(a), ib = FUNCTION_INDEX.get(b);
    if (ia === undefined || ib === undefined) return;
    FUNCTION_AFFINITY_MATRIX[ia][ib] = Math.max(FUNCTION_AFFINITY_MATRIX[ia][ib], value);
    FUNCTION_AFFINITY_MATRIX[ib][ia] = Math.max(FUNCTION_AFFINITY_MATRIX[ib][ia], value);
}
[
    ['removal','exile_removal',0.88], ['removal','bounce',0.78], ['removal','tuck',0.72], ['removal','sacrifice',0.62], ['removal','self_sacrifice',0.35],
    ['exile_removal','bounce',0.72], ['exile_removal','tuck',0.82],
    ['bounce','tuck',0.64], ['reanimate','recursion',0.90], ['reanimate','cheat_into_play',0.76],
    ['recursion','cheat_into_play',0.52], ['token_creation','token_multiplier',0.72], ['card_draw','tutor',0.38],
    ['tutor','ramp_tutor',0.72], ['direct_damage','lose_life',0.55], ['lose_life','gain_life',0.35],
    ['counter','removal',0.42], ['counter','bounce',0.30], ['stat_buff','tribal_anthem',0.72], ['stat_buff','anthem',0.68],
    ['stat_buff','token_creation',0.28], ['tribal_anthem','token_creation',0.28], ['discard','card_draw',0.25],
    ['mill','discard',0.25], ['tap','removal',0.18], ['untap','mana_ability',0.32], ['mana_ability','ramp_tutor',0.16]
].forEach(([a,b,v]) => setFunctionAffinity(a,b,v));

function getFunctionAffinity(a, b) {
    if (!a || !b) return 0;
    const ia = FUNCTION_INDEX.get(a), ib = FUNCTION_INDEX.get(b);
    if (ia === undefined || ib === undefined) return 0;
    return FUNCTION_AFFINITY_MATRIX[ia][ib] || 0;
}

function fieldSimilarity(weight, a, b, comparator = null) {
    if (a == null && b == null) return null;
    if (a == null || b == null) return { weight, value: 0 };
    return { weight, value: comparator ? comparator(a, b) : (a === b ? 1 : 0) };
}

function normalizedFieldScore(parts) {
    const usable = parts.filter(Boolean);
    const denominator = usable.reduce((s, p) => s + p.weight, 0);
    return denominator > 0 ? usable.reduce((s, p) => s + p.weight * p.value, 0) / denominator : 0;
}

function scoreContradictions(effA, effB) {
    let penalty = 0;
    const restrA = effA.restriction || [];
    const restrB = effB.restriction || [];

    // "destroy target creature you control" vs "...an opponent controls" - same verb, opposite
    // purpose (one is a drawback/sacrifice outlet, the other is removal).
    const controlClash = (restrA.includes('controlledbyyou') && restrB.includes('controlledbyopponent')) ||
        (restrA.includes('controlledbyopponent') && restrB.includes('controlledbyyou'));
    if (controlClash) penalty += 18;

    // One side restricts to "you control" while the other is unrestricted: narrower, but not
    // opposite, so a smaller penalty than an outright clash.
    const oneSidedControl = !controlClash && (
        (restrA.includes('controlledbyyou') && !restrB.includes('controlledbyyou')) ||
        (restrB.includes('controlledbyyou') && !restrA.includes('controlledbyyou'))
    );
    if (oneSidedControl) penalty += 6;

    // "counter target spell" vs "counter target NONCREATURE spell" - close, but one is
    // conditional on spell type. Any non-/type restriction present on exactly one side narrows
    // that side's applicability.
    const nonRestrA = restrA.filter(r => r.startsWith('non'));
    const nonRestrB = restrB.filter(r => r.startsWith('non'));
    const nonClash = nonRestrA.some(r => !restrB.includes(r)) || nonRestrB.some(r => !restrA.includes(r));
    if (nonClash) penalty += 8;

    // Same function but opposite permanence: a static anthem is not a combat trick.
    if (effA.isStatic !== undefined && effB.isStatic !== undefined && effA.isStatic !== effB.isStatic) {
        penalty += 7;
    }

    // "target one thing" vs "affects everything" is a large practical difference (spot removal
    // vs a board wipe), even though both canonicalize to removal.
    const massA = effA.target === 'all' || effA.target === 'each';
    const massB = effB.target === 'all' || effB.target === 'each';
    if (massA !== massB) penalty += 10;

    // An effect gated behind a cost/condition is strictly worse than the same effect unconditional.
    const gatedA = Boolean(effA.condition || effA.payCost);
    const gatedB = Boolean(effB.condition || effB.payCost);
    if (gatedA !== gatedB) penalty += 5;

    return penalty;
}

function restrictionSimilarityForMechanical(a = [], b = []) {
    const aa = new Set((a || []).filter(Boolean));
    const bb = new Set((b || []).filter(Boolean));
    if (aa.size === 0 && bb.size === 0) return 1;
    if (aa.size === 0 || bb.size === 0) return 0.35;
    const union = new Set([...aa, ...bb]);
    let intersection = 0;
    aa.forEach(v => { if (bb.has(v)) intersection++; });
    return intersection / Math.max(1, union.size);
}

function manaDiscountSimilarity(a, b) {
    if (a == null && b == null) return 1;
    const na = Number.isFinite(a) ? a : null;
    const nb = Number.isFinite(b) ? b : null;
    if (na != null && nb != null) return Math.max(0, 1 - Math.abs(na - nb) / Math.max(na, nb, 1));
    return String(a ?? '').toLowerCase() === String(b ?? '').toLowerCase() ? 1 : 0.45;
}

// Pair-level directional similarity is pure for a parsed effect pair. The same pair was being
// evaluated repeatedly by the base directional score, candidate-only-excess penalty, and effect
// coverage matrix. Cache it by object identity so those scoring channels reuse exactly the same
// calculation without changing a single score formula. WeakMap keeps this cache self-pruning.
const directionalMechanicalPairScoreCache = new WeakMap();
const mechanicalPairCacheStats = {
    directionalComputed: 0, directionalHits: 0,
    graphNodeComputed: 0, graphNodeHits: 0
};

function computeDirectionalMechanicalEffectPairSimilarity(effA, effB) {
    if (!effA?.canonical || !effB?.canonical) return 0;
const cfA = effA.canonical || {}, cfB = effB.canonical || {};
const fnA = cfA.function || null, fnB = cfB.function || null;
const outcomeA = cfA.outcome || null, outcomeB = cfB.outcome || null;
const namedA = String(fnA || '').startsWith('mechanic_'), namedB = String(fnB || '').startsWith('mechanic_');
const profileA = cfA.params?.mechanicProfile || effA.mechanicProfile || null;
const profileB = cfB.params?.mechanicProfile || effB.mechanicProfile || null;
const namedFamiliesCompatible = Boolean(namedA && namedB && profileA?.family && profileA.family === profileB?.family);
if ((namedA || namedB) && fnA !== fnB && !namedFamiliesCompatible) return 0.005;
const taxA = effA.action ? ACTION_TAXONOMY[effA.action] : null;
const taxB = effB.action ? ACTION_TAXONOMY[effB.action] : null;

const affinity = getFunctionAffinity(fnA, fnB);
const sameAction = effA.action && effB.action && effA.action === effB.action;
const sameOutcome = outcomeA && outcomeB && outcomeA === outcomeB;
const sameFamily = taxA?.family && taxB?.family && taxA.family === taxB.family;
const coreAlignment = Math.max(
    affinity,
    namedFamiliesCompatible ? 0.62 : 0,
    sameAction ? 0.96 : 0,
    sameOutcome ? 0.74 : 0,
    sameFamily ? 0.50 : 0
);
if (coreAlignment <= 0) return 0;

const parts = [];
if (namedA && namedB) parts.push({ weight: 20, value: compareNamedMechanicProfiles(profileA, profileB) });
parts.push({ weight: 10, value: compareGameStateConditionProfiles(effA.gameStateConditionProfile || cfA.params?.gameStateConditionProfile, effB.gameStateConditionProfile || cfB.params?.gameStateConditionProfile) });
parts.push(fieldSimilarity(14, cfA.object ?? effA.object, cfB.object ?? effB.object));
parts.push(fieldSimilarity(10, cfA.target ?? effA.target, cfB.target ?? effB.target));
if (fnA === 'cost_reduction' || fnB === 'cost_reduction') {
    parts.push({ weight: 9, value: restrictionSimilarityForMechanical(effA.restriction, effB.restriction) });
    parts.push(fieldSimilarity(6, effA.controller, effB.controller));
    parts.push({ weight: 7, value: manaDiscountSimilarity(effA.amount ?? effA.quantity, effB.amount ?? effB.quantity) });
    parts.push(fieldSimilarity(4, effA.effectMode, effB.effectMode));
}
parts.push(fieldSimilarity(9, effA.from, effB.from));
parts.push(fieldSimilarity(9, effA.to, effB.to));
parts.push(fieldSimilarity(7, effA.subtype, effB.subtype));
parts.push(fieldSimilarity(6, effA.controller, effB.controller));
if (typeof effA.quantity === 'number' || typeof effB.quantity === 'number') {
    parts.push(fieldSimilarity(7, effA.quantity, effB.quantity,
        (a,b) => Math.max(0, 1 - Math.abs(a-b) / Math.max(Math.abs(a), Math.abs(b), 1))));
} else if (effA.quantity != null || effB.quantity != null) {
    parts.push(fieldSimilarity(5, effA.quantity, effB.quantity));
}

if (fnA === 'cast_timing_permission' && fnB === 'cast_timing_permission') {
    const scopeA = String(cfA.params?.castingScope || 'all').toLowerCase();
    const scopeB = String(cfB.params?.castingScope || 'all').toLowerCase();
    const scopeSimilarity = scopeA === scopeB ? 1 : (scopeA === 'all' || scopeB === 'all' ? 0.72 : 0.20);
    parts.push({ weight: 10, value: scopeSimilarity });
    parts.push(fieldSimilarity(8, cfA.params?.timingPermission, cfB.params?.timingPermission));
}

if (fnA === 'mana_ability' && fnB === 'mana_ability') {
    const ma = cfA.params || {}, mb = cfB.params || {};
    const netSim = manaNumericSimilarity(ma.manaNetAmount, mb.manaNetAmount);
    const outputSim = manaNumericSimilarity(ma.manaOutputAmount, mb.manaOutputAmount);
    const colorSim = manaColorProfileSimilarity({
        mode: ma.manaOutputMode,
        colors: ma.manaOutputColors || []
    }, {
        mode: mb.manaOutputMode,
        colors: mb.manaOutputColors || []
    });
    const activationSim = manaActivationSimilarity(ma.activationCost, mb.activationCost);
    if (netSim != null) parts.push({ weight: 12, value: netSim });
    if (outputSim != null) parts.push({ weight: 5, value: outputSim });
    if (colorSim != null) parts.push({ weight: 8, value: colorSim });
    if (activationSim != null) parts.push({ weight: 5, value: activationSim });
    const rulesA = cfA.params?.manaAbilityRulesProfile || effA.manaAbilityRulesProfile || null;
    const rulesB = cfB.params?.manaAbilityRulesProfile || effB.manaAbilityRulesProfile || null;
    if (rulesA || rulesB) parts.push({ weight: 8, value: rulesA && rulesB ? (rulesA.isRulesManaAbility === rulesB.isRulesManaAbility ? 1 : 0.12) : 0.55 });
}
const tpA = effA.targetProfile || {}, tpB = effB.targetProfile || {};
parts.push(fieldSimilarity(4, tpA.kind, tpB.kind));
parts.push(fieldSimilarity(4, tpA.scope, tpB.scope));
const qpA = effA.quantityProfile || {}, qpB = effB.quantityProfile || {};
parts.push(fieldSimilarity(4, qpA.relation, qpB.relation));
parts.push(fieldSimilarity(2, qpA.bound, qpB.bound));
const trA = effA.triggerProfile || {}, trB = effB.triggerProfile || {};
parts.push(fieldSimilarity(4, trA.event, trB.event));
parts.push(fieldSimilarity(3, trA.window, trB.window));
parts.push({ weight: 18, value: repeatabilityProfileSimilarity(getEffectRepeatabilityProfile(effA), getEffectRepeatabilityProfile(effB)) });
parts.push(fieldSimilarity(3, effA.durationProfile, effB.durationProfile));
parts.push(fieldSimilarity(4, effA.effectMode, effB.effectMode));
parts.push(fieldSimilarity(4, effA.condition, effB.condition));
parts.push(fieldSimilarity(3, effA.isStatic, effB.isStatic));
if (effA.action === 'stat_buff' || effB.action === 'stat_buff') {
    parts.push(fieldSimilarity(4, effA.powerToughness, effB.powerToughness));
}
if (effA.action === 'create' || effB.action === 'create') {
    parts.push(fieldSimilarity(5, effA.stats, effB.stats));
}

const structuralEvidence = normalizedFieldScore(parts);
// Core function alignment is multiplicative: structural agreement can refine a real
// function match, but an action-family coincidence can never create a near-perfect score
// on its own. When no structural field is available, retain only a conservative floor.
const fieldFactor = parts.some(Boolean) ? (0.52 + 0.48 * structuralEvidence) : 0.52;
let score = coreAlignment * fieldFactor;
score *= (1 - Math.min(0.45, scoreContradictions(effA, effB) / 100));
    return score;
}

function getDirectionalMechanicalEffectPairSimilarity(effA, effB) {
    if (!effA || typeof effA !== 'object' || !effB || typeof effB !== 'object') {
        return computeDirectionalMechanicalEffectPairSimilarity(effA, effB);
    }
    let row = directionalMechanicalPairScoreCache.get(effA);
    if (row?.has(effB)) {
        mechanicalPairCacheStats.directionalHits++;
        return row.get(effB);
    }
    if (!row) {
        row = new WeakMap();
        directionalMechanicalPairScoreCache.set(effA, row);
    }
    mechanicalPairCacheStats.directionalComputed++;
    const score = computeDirectionalMechanicalEffectPairSimilarity(effA, effB);
    row.set(effB, score);
    return score;
}

function directionalMechanicalSimilarity(parsedA, parsedB) {
    if (!parsedA || !parsedB || parsedA.length === 0 || parsedB.length === 0) return 0;
    let weightedSource = 0, sourceWeight = 0;
    for (const effA of parsedA) {
        if (!effA?.canonical) continue;
        let best = 0;
        for (const effB of parsedB) {
            if (!effB?.canonical) continue;
            best = Math.max(best, getDirectionalMechanicalEffectPairSimilarity(effA, effB));
        }
        const importance = effA.importance ?? 0.05;
        weightedSource += best * Math.max(0.05, importance);
        sourceWeight += Math.max(0.05, importance);
    }
    return sourceWeight > 0 ? Math.max(0, Math.min(1, weightedSource / sourceWeight)) : 0;
}

// A candidate is compared to the same source effects in multiple stages: directional coverage,
// candidate-only excess, and the one-to-one effect-coverage assignment. Build the directional
// pair matrices once and share them across those stages. Pair values are the exact same cached
// primitive comparisons used by the legacy paths; this removes repeated nested loops, temporary
// one-element arrays, filtering, and WeakMap lookups without changing scoring semantics.
function normalizeSingleEffectDirectionalScore(effect, bestPairScore) {
    // Match directionalMechanicalSimilarity([effect], otherEffects) exactly, including its
    // multiply/divide sequence. Though mathematically redundant, preserving that sequence preserves
    // the previous floating-point values and deterministic tie ordering bit-for-bit.
    const weight = Math.max(0.05, effect?.importance ?? 0.05);
    const weightedSource = bestPairScore * weight;
    const sourceWeight = weight;
    return sourceWeight > 0 ? Math.max(0, Math.min(1, weightedSource / sourceWeight)) : 0;
}

function createMechanicalPairComparisonWorkspace(parsedSource, parsedCandidate) {
    const sourceEffects = (Array.isArray(parsedSource) ? parsedSource : []).filter(effect => effect?.canonical);
    const candidateEffects = (Array.isArray(parsedCandidate) ? parsedCandidate : []).filter(effect => effect?.canonical);
    const forward = sourceEffects.map(sourceEffect => candidateEffects.map(candidateEffect =>
        getDirectionalMechanicalEffectPairSimilarity(sourceEffect, candidateEffect)));
    const coverageForward = sourceEffects.map((sourceEffect, i) => candidateEffects.map((candidateEffect, j) =>
        normalizeSingleEffectDirectionalScore(sourceEffect, forward[i][j])));
    const reverse = candidateEffects.map(candidateEffect => sourceEffects.map(sourceEffect =>
        getDirectionalMechanicalEffectPairSimilarity(candidateEffect, sourceEffect)));
    return {
        parsedSource, parsedCandidate, sourceEffects, candidateEffects, forward, coverageForward, reverse,
        sourceIndex: new Map(sourceEffects.map((effect, index) => [effect, index])),
        candidateIndex: new Map(candidateEffects.map((effect, index) => [effect, index]))
    };
}

function directionalMechanicalSimilarityFromWorkspace(workspace) {
    if (!workspace?.sourceEffects?.length || !workspace?.candidateEffects?.length) return 0;
    let weightedSource = 0, sourceWeight = 0;
    for (let i = 0; i < workspace.sourceEffects.length; i++) {
        const effect = workspace.sourceEffects[i];
        const row = workspace.forward[i];
        let best = 0;
        for (let j = 0; j < row.length; j++) if (row[j] > best) best = row[j];
        const weight = Math.max(0.05, effect.importance ?? 0.05);
        weightedSource += best * weight;
        sourceWeight += weight;
    }
    return sourceWeight > 0 ? Math.max(0, Math.min(1, weightedSource / sourceWeight)) : 0;
}

function calculateCandidateMechanicalExcessFromWorkspace(workspace) {
    if (!workspace?.parsedCandidate || !Array.isArray(workspace.parsedCandidate) || workspace.parsedCandidate.length === 0) return 1;
    let weightedExcess = 0, weightTotal = 0;
    const sourceCount = workspace.sourceEffects.length;
    for (const effect of workspace.parsedCandidate) {
        const baseImportance = Math.max(0.05, effect.importance ?? (effect.isPrimary ? 1 : 0.35));
        const importance = baseImportance * (baseImportance >= 0.70 ? 1.20 : 0.80);
        let bestCoverage = 0;
        const candidateIndex = effect?.canonical ? workspace.candidateIndex.get(effect) : undefined;
        if (candidateIndex !== undefined) {
            const row = workspace.reverse[candidateIndex];
            for (let i = 0; i < sourceCount; i++) if (row[i] > bestCoverage) bestCoverage = row[i];
            bestCoverage = normalizeSingleEffectDirectionalScore(effect, bestCoverage);
        }
        weightedExcess += Math.max(0, 1 - bestCoverage) * importance;
        weightTotal += importance;
    }
    return weightTotal > 0 ? Math.min(1, weightedExcess / weightTotal) : 1;
}

// ---------------------------------------------------------------------------
// Reconstruct highlighted text from the source card's original Oracle text instead of
// inserting synthetic sentence boundaries between separately selected spans. A user can highlight
// "White spells you cast cost", then "{1}", then "less to cast"; those are three UI selections
// but one grammatical effect. Synthetic ". " separators turn that into three broken clauses and
// poison the mechanical parser. Position-aware reconstruction keeps the original connective text.
function getCurrentSourceOracleText(sourceCard = currentSourceCard) {
    if (!sourceCard) return '';
    return sourceCard.oracle_text ||
        (sourceCard.card_faces
            ? sourceCard.card_faces.map(f => f.oracle_text || '').filter(Boolean).join('\n\n')
            : '');
}

function normalizeHighlightSelectionOffsets(root, range) {
    if (!root || !range) return null;
    try {
        const pre = document.createRange();
        pre.selectNodeContents(root);
        pre.setEnd(range.startContainer, range.startOffset);
        const rawStart = pre.toString().length;
        pre.selectNodeContents(root);
        pre.setEnd(range.endContainer, range.endOffset);
        const rawEnd = pre.toString().length;
        let start = Math.min(rawStart, rawEnd);
        let end = Math.max(rawStart, rawEnd);
        if (end <= start) return null;
        return { start, end };
    } catch (_) {
        return null;
    }
}

function trimHighlightRangeText(text, start, end) {
    const raw = String(text || '');
    const left = raw.match(/^\s+/)?.[0].length || 0;
    const right = raw.match(/\s+$/)?.[0].length || 0;
    return {
        text: raw.trim(),
        start: start + left,
        end: Math.max(start + left, end - right)
    };
}

function buildHighlightScoringText(highlights, sourceText = getCurrentSourceOracleText()) {
    const hs = (highlights || [])
        .filter(h => h && typeof h.text === 'string' && h.text.trim());
    if (!hs.length) return '';

    // Use the same explicit grouping logic as the mechanical highlight-intent layer. This means
    // a user-added search detail can be attached to an actual source selection and contribute to
    // the semantic target without being mistaken for literal Oracle grammar.
    const groups = annotateHighlightGroups(hs, sourceText);
    if (!groups.length) return '';

    return groups.map(group => {
        const sourceContext = String(group.parseText || group.sourceClauseText || group.contextText || '').trim();
        const overrideTexts = new Set((group.intentOverrideTexts || (group.triggerIntentOverrideText ? [group.triggerIntentOverrideText] : [])).map(value => String(value).trim()));
        const intentHints = (group.connectedIntentTexts || [])
            .filter(value => Boolean(value) && !overrideTexts.has(String(value).trim()))
            .map(v => String(v).trim());
        return [sourceContext, ...intentHints]
            .filter(Boolean)
            .join('. ');
    }).filter(Boolean).join('. ');
}


// HIGHLIGHT INTENT LAYER
// ---------------------------------------------------------------------------
// Highlights are user-authored intent, not merely a shorter Oracle string.  Keep each
// highlight as its own structural request so multiple disjoint highlights do not get
// accidentally blended into one clause.  Exact highlights still participate in literal
// matching; both exact and flexible highlights also participate in mechanical matching.
function highlightRestrictionSimilarity(a = [], b = []) {
    const aa = new Set(a || []);
    const bb = new Set(b || []);
    if (aa.size === 0 && bb.size === 0) return 1;
    if (aa.size === 0 || bb.size === 0) return 0.35;
    let intersection = 0;
    aa.forEach(v => { if (bb.has(v)) intersection++; });
    return intersection / new Set([...aa, ...bb]).size;
}

function highlightQuantitySimilarity(a, b, mode) {
    a = a || {}; b = b || {};
    if (mode === 'variable') {
        if (a.relation && b.relation && a.relation !== b.relation) return 0.45;
        if (a.kind && b.kind) return 1;
        return (a.kind || b.kind) ? 0.65 : 1;
    }
    if (a.relation || b.relation) {
        if (a.relation && b.relation && a.relation === b.relation) return 0.9;
        return 0.35;
    }
    const av = a.value, bv = b.value;
    if (typeof av === 'number' && typeof bv === 'number') return Math.max(0, 1 - Math.abs(av - bv) / Math.max(av, bv, 1));
    if (av == null && bv == null) return 1;
    if (av === bv) return 1;
    if (av == null || bv == null) return 0.35;
    return 0.45;
}

function highlightTargetSimilarity(a = {}, b = {}, mode) {
    if (!a.kind && !b.kind && !a.scope && !b.scope) return 1;
    let score = 0, weight = 0;
    if (a.kind || b.kind) { weight += 0.55; score += a.kind === b.kind ? 0.55 : (mode === 'variable' && (!a.kind || !b.kind) ? 0.30 : 0); }
    if (a.object || b.object) { weight += 0.25; score += a.object === b.object ? 0.25 : 0; }
    if (a.scope || b.scope) { weight += 0.20; score += a.scope === b.scope ? 0.20 : 0; }
    return weight ? score / weight : 1;
}

function highlightRelationshipSimilarity(a, b, mode) {
    const ta = a.triggerProfile || null, tb = b.triggerProfile || null;
    let score = 0, weight = 0;
    if (ta || tb) {
        weight += 0.45;
        if (ta && tb && ta.type === tb.type && (!ta.event || !tb.event || ta.event === tb.event)) score += 0.45;
        else if (mode === 'variable' && (!ta || !tb)) score += 0.18;
    }
    const da = a.dependencyProfile || {}, db = b.dependencyProfile || {};
    const keys = ['hasIfYouDo','hasForEach','hasBasedOn','hasInstead','role'];
    for (const k of keys) {
        if (da[k] !== undefined || db[k] !== undefined) {
            weight += 0.11;
            if (da[k] === db[k]) score += 0.11;
        }
    }
    if (a.durationProfile || b.durationProfile) {
        weight += 0.15;
        if (a.durationProfile === b.durationProfile) score += 0.15;
        else if (mode === 'variable' && (!a.durationProfile || !b.durationProfile)) score += 0.06;
    }
    return weight ? score / weight : 1;
}

function scoreHighlightEffectMatch(highlightEffect, candidateEffect, mode) {
    if (!highlightEffect || !candidateEffect) return 0;
    const ca = highlightEffect.canonical || null, cb = candidateEffect.canonical || null;
    const sameFunction = Boolean(ca && cb && ca.function === cb.function);
    const sameOutcome = Boolean(ca && cb && ca.outcome === cb.outcome);
    const sameAction = Boolean(highlightEffect.action && candidateEffect.action && highlightEffect.action === candidateEffect.action);
    if (!sameFunction && !sameOutcome && !sameAction) return 0;

    let score = sameFunction ? 0.38 : (sameOutcome ? 0.22 : 0.16);
    if (highlightEffect.object && candidateEffect.object) score += highlightEffect.object === candidateEffect.object ? 0.10 : 0;
    else score += (!highlightEffect.object && !candidateEffect.object) ? 0.10 : 0.03;
    score += 0.12 * highlightTargetSimilarity(highlightEffect.targetProfile || {}, candidateEffect.targetProfile || {}, mode);
    score += 0.08 * highlightRestrictionSimilarity(highlightEffect.restriction, candidateEffect.restriction);
    score += 0.10 * highlightQuantitySimilarity(highlightEffect.quantityProfile, candidateEffect.quantityProfile, mode);
    // User-declared structured aspects override generic quantity heuristics; Flexible mode ranks violations down but never filters.
    if (highlightEffect.userAspects && hasActiveHighlightAspects(highlightEffect.userAspects)) {
        const pseudoCard = { oracle_text: String(candidateEffect.raw || candidateEffect.contextClause || '') };
        const aspectResult = highlightAspectEffectMatches({ text: highlightEffect.raw || highlightEffect.contextClause || '', aspects: highlightEffect.userAspects, mode }, pseudoCard);
        if (aspectResult.applies && !aspectResult.matches && mode === 'variable') score *= Math.max(0.12, aspectResult.score || 0.18);
    }
    score += 0.10 * highlightRelationshipSimilarity(highlightEffect, candidateEffect, mode);
    if (highlightEffect.effectMode || candidateEffect.effectMode) {
        score += highlightEffect.effectMode === candidateEffect.effectMode ? 0.07 : (mode === 'variable' ? 0.01 : 0);
    } else score += 0.07;
    return Math.min(1, score);
}

// Maximum-weight one-to-one assignment. A candidate effect can satisfy at most one highlighted
// effect. This prevents one broad candidate clause from falsely satisfying several independent
// highlighted spans. The DP is bounded to the small effect lists produced by Oracle clauses.
function maxOneToOneHighlightAssignment(sourceEffects, candidateEffects, mode) {
    const sources = sourceEffects || [], candidates = candidateEffects || [];
    if (!sources.length || !candidates.length) return { score: 0, matches: [] };

    // Highlight/effect pair similarity is independent of the assignment state. The old recursive
    // DP recomputed these expensive structural comparisons from many branches; precompute the
    // score matrix once and reuse it in both assignment and normalization.
    const pairScores = sources.map(source => candidates.map(candidate =>
        Math.max(0, Number(scoreHighlightEffectMatch(source, candidate, mode)) || 0)
    ));
    const rowMaxima = pairScores.map(row => row.reduce((max, value) => Math.max(max, value), 0));
    const maxPossible = rowMaxima.reduce((sum, value) => sum + value, 0) || 1;
    const n = sources.length;
    const m = candidates.length;

    // Keep the old DP for ordinary card texts so its tie order and exact output remain identical.
    // Estimate its state count first: with many candidate effects, the used-mask state space grows
    // combinatorially and can dominate a broad/highlights search even though each pair score is
    // straightforward. Those pathological cases use an exact maximum-weight assignment instead.
    let combination = 1;
    let estimatedStates = 1;
    for (let k = 1; k <= Math.min(n, m); k++) {
        combination = combination * (m - k + 1) / k;
        estimatedStates += combination;
        if (estimatedStates * Math.max(1, m) > 50000) break;
    }
    if (estimatedStates * Math.max(1, m) <= 50000) {
        const memo = new Map();
        function solve(i, usedMask) {
            if (i >= n) return { score: 0, matches: [] };
            const key = `${i}|${usedMask}`;
            const cached = memo.get(key);
            if (cached) return cached;
            let best = solve(i + 1, usedMask); // Preserve historical tie behavior: unmatched first.
            for (let j = 0; j < m; j++) {
                const pair = pairScores[i][j];
                if (pair <= 0) continue;
                const bit = 1n << BigInt(j);
                if (usedMask & bit) continue;
                const rest = solve(i + 1, usedMask | bit);
                const candidate = { score: pair + rest.score, matches: [[i, j, pair], ...rest.matches] };
                if (candidate.score > best.score) best = candidate;
            }
            memo.set(key, best);
            return best;
        }
        const result = solve(0, 0n);
        return { score: result.score / maxPossible, matches: result.matches };
    }

    // Exact polynomial-time maximum-weight bipartite assignment (Hungarian algorithm). Each source
    // effect receives either one candidate effect or one of n dummy columns (unmatched, zero score).
    // The objective is the same maximum sum of pair scores as the DP, without enumerating candidate
    // masks. This changes execution strategy only for unusually long rules texts.
    const rows = n;
    const realCols = m;
    const cols = m + n;
    const u = new Array(rows + 1).fill(0);
    const v = new Array(cols + 1).fill(0);
    const p = new Array(cols + 1).fill(0);
    const way = new Array(cols + 1).fill(0);
    const cost = (i, j) => j > realCols ? 0 : -(pairScores[i - 1][j - 1] || 0);

    for (let i = 1; i <= rows; i++) {
        p[0] = i;
        let j0 = 0;
        const minv = new Array(cols + 1).fill(Infinity);
        const used = new Array(cols + 1).fill(false);
        do {
            used[j0] = true;
            const i0 = p[j0];
            let delta = Infinity;
            let j1 = 0;
            for (let j = 1; j <= cols; j++) {
                if (used[j]) continue;
                const cur = cost(i0, j) - u[i0] - v[j];
                if (cur < minv[j]) { minv[j] = cur; way[j] = j0; }
                if (minv[j] < delta) { delta = minv[j]; j1 = j; }
            }
            for (let j = 0; j <= cols; j++) {
                if (used[j]) { u[p[j]] += delta; v[j] -= delta; }
                else minv[j] -= delta;
            }
            j0 = j1;
        } while (p[j0] !== 0);
        do {
            const j1 = way[j0];
            p[j0] = p[j1];
            j0 = j1;
        } while (j0 !== 0);
    }

    const assignedColumn = new Array(rows).fill(-1);
    for (let j = 1; j <= cols; j++) if (p[j] > 0) assignedColumn[p[j] - 1] = j - 1;
    const matches = [];
    let score = 0;
    for (let i = 0; i < rows; i++) {
        const j = assignedColumn[i];
        if (j >= 0 && j < realCols) {
            const pair = pairScores[i][j];
            if (pair > 0) {
                score += pair;
                matches.push([i, j, pair]);
            }
        }
    }
    matches.sort((a, b) => a[0] - b[0]);
    return { score: score / maxPossible, matches };
}

// Return the complete Oracle sentence/clause governing a selected span. Parsing only the
// selected words (for example, "draw a card") loses the trigger condition that makes the effect
// mechanically distinctive. The selection remains the literal constraint; this expanded context
// is for mechanic parsing, cadence, intent explanation, and semantic retrieval.
function extractHighlightClauseContext(sourceText, start, end) {
    const text = String(sourceText || '');
    if (!Number.isFinite(start) || !Number.isFinite(end) || start < 0 || end <= start || end > text.length) return '';
    let left = 0;
    for (let i = start - 1; i >= 0; i--) {
        if (/[.!?;\n]/.test(text[i])) { left = i + 1; break; }
    }
    let right = text.length;
    for (let i = end; i < text.length; i++) {
        if (/[.!?;\n]/.test(text[i])) { right = i + 1; break; }
    }
    return text.slice(left, right).trim();
}

// Resolve a highlight's original Oracle-text anchor. Edited wording keeps a nonvisual anchor
// so the scorer can retain trigger/condition context without reverting to the old outcome.
function getHighlightSourceAnchor(highlight, sourceText = getCurrentSourceOracleText()) {
    const oracle = String(sourceText || '');
    const matchesAt = candidate => {
        const start = Number(candidate?.start), end = Number(candidate?.end);
        const expected = String(candidate?.text || '').trim();
        if (!expected || !Number.isInteger(start) || !Number.isInteger(end) || start < 0 || end <= start || end > oracle.length) return null;
        const actual = oracle.slice(start, end).trim();
        if (actual.toLocaleLowerCase() !== expected.toLocaleLowerCase()) return null;
        return { text: expected, start, end };
    };
    const editedAnchor = matchesAt(highlight?.editedFrom);
    if (editedAnchor) return { ...editedAnchor, edited: true };
    if (highlight?.origin === 'user' || highlight?.field === 'type') return null;
    const sourceAnchor = matchesAt(highlight);
    return sourceAnchor ? { ...sourceAnchor, edited: false } : null;
}

// Locate the original rules clause and the selected span's role inside it. The anchor is
// deliberately nonvisual for edited highlights: it preserves grammatical context while the
// current user text remains the actual search intent.
function getHighlightSourceClauseInfo(highlight, sourceText = getCurrentSourceOracleText()) {
    const source = String(sourceText || '');
    const anchor = getHighlightSourceAnchor(highlight, source);
    if (!anchor) return null;
    let left = 0;
    for (let i = anchor.start - 1; i >= 0; i--) {
        if (/[.!?;\n]/.test(source[i])) { left = i + 1; break; }
    }
    let right = source.length;
    for (let i = anchor.end; i < source.length; i++) {
        if (/[.!?;\n]/.test(source[i])) { right = i + 1; break; }
    }
    const raw = source.slice(left, right);
    const leading = raw.match(/^\s*/)?.[0].length || 0;
    const trailing = raw.match(/\s*$/)?.[0].length || 0;
    const start = left + leading;
    const end = Math.max(start, right - trailing);
    const clauseText = source.slice(start, end).trim();
    const comma = clauseText.indexOf(',');
    const triggerLead = comma > 0 && isSearchIntentTriggerPhrase(clauseText.slice(0, comma))
        ? clauseText.slice(0, comma).trim() : '';
    const anchorLocalStart = anchor.start - start;
    const anchorLocalEnd = anchor.end - start;
    const anchorRole = triggerLead && anchorLocalStart < comma && anchorLocalEnd <= comma
        ? 'trigger'
        : (triggerLead ? 'outcome' : 'clause');
    return { anchor, start, end, clauseText, triggerLead, resolutionText: triggerLead ? clauseText.slice(comma + 1).trim() : '', comma, anchorLocalStart, anchorLocalEnd, anchorRole };
}

function isCompleteTriggerOutcomeText(value) {
    const text = String(value || '').trim();
    const comma = text.indexOf(',');
    // The user's complete authored rule is authoritative even when its outcome uses a verb the
    // canonical parser does not yet recognize (for example, a win-the-game or extra-turn effect).
    return comma > 0 && isSearchIntentTriggerPhrase(text.slice(0, comma)) && Boolean(text.slice(comma + 1).trim());
}

// When a source selection was inside the trigger condition, editing it must replace the trigger,
// not append a trigger to an unchanged source trigger or treat it as an outcome. Full trigger
// phrases replace the lead; shorter replacements substitute only the anchored source fragment.
function composeEditedHighlightTriggerOverride(sourceClause, editedTriggerText, sourceAnchorText = '') {
    const source = String(sourceClause || '').trim();
    const comma = source.indexOf(',');
    if (comma <= 0) return null;
    const oldTrigger = source.slice(0, comma).trim();
    if (!isSearchIntentTriggerPhrase(oldTrigger)) return null;
    const resolution = source.slice(comma + 1).trim();
    const replacement = String(editedTriggerText || '').trim().replace(/[\s,;.!?]+$/g, '');
    if (!replacement || !resolution) return null;
    let nextTrigger = replacement;
    if (!isSearchIntentTriggerPhrase(replacement)) {
        const anchor = String(sourceAnchorText || '').trim();
        if (!anchor) return null;
        const at = oldTrigger.toLocaleLowerCase().indexOf(anchor.toLocaleLowerCase());
        if (at < 0) return null;
        nextTrigger = `${oldTrigger.slice(0, at)}${replacement}${oldTrigger.slice(at + anchor.length)}`.replace(/\s+/g, ' ').trim();
    }
    if (!isSearchIntentTriggerPhrase(nextTrigger)) return null;
    return `${nextTrigger}, ${resolution}`;
}

// Replace only the selected result/outcome while retaining its original trigger and safe modal
// prefix (for example, “you may”). The user-authored outcome replaces the prior printed outcome.
function composeEditedHighlightOutcomeOverride(sourceClause, editedOutcomeText, previousSelectedText = '') {
    const outcome = String(editedOutcomeText || '').trim().replace(/[\s,;.!?]+$/g, '');
    if (!outcome) return null;
    if (isCompleteTriggerOutcomeText(outcome)) return outcome;
    const source = String(sourceClause || '').trim();
    const comma = source.indexOf(',');
    const triggerPrefix = comma > 0 && isSearchIntentTriggerPhrase(source.slice(0, comma)) ? source.slice(0, comma).trim() : '';
    const resolution = getResolutionAfterTrigger(source);
    let safePrefix = '';
    const selected = String(previousSelectedText || '').trim();
    if (resolution && selected) {
        const at = resolution.toLocaleLowerCase().indexOf(selected.toLocaleLowerCase());
        if (at >= 0) {
            const prefix = resolution.slice(0, at).trim();
            if (/^(?:(?:you|that player|each player|target player|the controller|its controller|that opponent)(?:\s+|$))?(?:(?:may|must|can|also|then)(?:\s+|$))*$/i.test(prefix)) safePrefix = prefix;
        }
    }
    const replacement = [safePrefix, outcome].filter(Boolean).join(' ');
    return triggerPrefix ? `${triggerPrefix}, ${replacement}` : (replacement || outcome);
}

function isSearchIntentTriggerPhrase(value) {
    const text = String(value || '').trim();
    return /^(?:when|whenever)\b/i.test(text) ||
        /^(?:at\s+(?:(?:the\s+)?(?:beginning|start|end)\s+of|your|each|every|each opponent's|each player's)\b|during\s+|each\s+(?:opponent's|player's)\s+(?:upkeep|end step|draw step|combat|turn)\b)/i.test(text);
}

function isLikelyEffectOutcomeText(value) {
    return /\b(?:draw|create|produce|add|deal|destroy|exile|return|put|move|gain|lose|discard|mill|search|counter|untap|tap|sacrifice|gets?|get|put|place|prevent|double|copy|reveal|shuffle|scry|surveil|transform|fight)\b/i.test(String(value || ''));
}

function getResolutionAfterTrigger(sourceClause) {
    const text = String(sourceClause || '').trim();
    if (!text) return '';
    const comma = text.indexOf(',');
    if (comma > 0) {
        const lead = text.slice(0, comma).trim();
        const rest = text.slice(comma + 1).trim();
        if (isSearchIntentTriggerPhrase(lead) && rest) return rest;
    }
    // If the selected source clause is itself the effect ("Draw a card."), it can be paired
    // with an explicitly supplied trigger detail. Do not use a trigger-only source sentence as an
    // outcome: it contains no resolution to compose.
    if (!isSearchIntentTriggerPhrase(text) && isLikelyEffectOutcomeText(text)) return text;
    return '';
}

function composeHighlightIntentOverride(sourceClause, triggerDetail, selectedEffectText = '') {
    const detail = String(triggerDetail || '').trim().replace(/[\s,;.!?]+$/g, '');
    const source = String(sourceClause || '').trim();
    if (!detail || !isSearchIntentTriggerPhrase(detail)) return null;

    // A user may supply the whole intended rule, e.g. "Whenever an opponent draws a card, draw
    // a card." In that case use it directly rather than adding a duplicate resolution.
    const comma = detail.indexOf(',');
    if (comma > 0 && isLikelyEffectOutcomeText(detail.slice(comma + 1))) return detail;

    const resolution = getResolutionAfterTrigger(source);
    const selected = String(selectedEffectText || '').trim();
    if (!resolution || !isLikelyEffectOutcomeText(resolution)) return null;
    if (selected && !resolution.toLowerCase().includes(selected.toLowerCase())) return null;

    // When the user focuses specifically on "draw a card", don't carry over the tail of a
    // different source trigger such as "unless that player pays {1}". That restriction belongs
    // to Rhystic Study's original cast trigger, not the user's replacement trigger. Keep a simple
    // optional/subject prefix ("you may draw a card"), but stop at the selected draw outcome.
    let intendedResolution = resolution;
    if (/\bdraw\s+(?:(?:a|one|two|three|four|five|six|seven|eight|nine|ten|\d+)\s+)?cards?\b/i.test(selected)) {
        const selectedAt = resolution.toLowerCase().indexOf(selected.toLowerCase());
        if (selectedAt >= 0) {
            const prefix = resolution.slice(0, selectedAt).trim();
            const safePrefix = /^(?:(?:you|that player|each player|target player|the controller|its controller|that opponent)(?:\s+|$))?(?:(?:may|must|can|also|then)(?:\s+|$))*$/i.test(prefix);
            if (safePrefix) intendedResolution = [prefix, selected].filter(Boolean).join(' ');
        }
    }
    return `${detail}, ${intendedResolution}`;
}

// Group multiple UI selections that belong to one grammatical effect. The source text between
// the selections is preserved, because the connective words often carry the actual rules syntax.
function annotateHighlightGroups(highlights, sourceText = getCurrentSourceOracleText()) {
    const original = Array.isArray(highlights) ? highlights : [];
    const hs = original
        .filter(h => h && typeof h.text === 'string' && h.text.trim())
        .map((h, index) => ({ ...h, _highlightIndex: index }));
    if (!hs.length) return [];

    // Start with the normal position-based grouping. This keeps nearby selections from the same
    // Oracle sentence/effect together without requiring the user to perfectly select the whole
    // sentence in one drag.
    const parent = hs.map((_, i) => i);
    const find = (x) => {
        let root = x;
        while (parent[root] !== root) root = parent[root];
        while (parent[x] !== x) {
            const next = parent[x];
            parent[x] = root;
            x = next;
        }
        return root;
    };
    const union = (a, b) => {
        const ra = find(a), rb = find(b);
        if (ra !== rb) parent[rb] = ra;
    };

    const positioned = hs
        .map(h => ({ highlight: h, anchor: getHighlightSourceAnchor(h, sourceText) }))
        .filter(item => item.anchor)
        .sort((a, b) => a.anchor.start - b.anchor.start || a.highlight._highlightIndex - b.highlight._highlightIndex);
    for (let i = 1; i < positioned.length; i++) {
        const prev = positioned[i - 1];
        const next = positioned[i];
        const gap = String(sourceText || '').slice(prev.anchor.end, next.anchor.start);
        if (!/[.!?\n]/.test(gap) && gap.length <= 96) {
            union(hs.indexOf(prev.highlight), hs.indexOf(next.highlight));
        }
    }

    // Explicit user connections override physical proximity. This is the important part for
    // cases such as: highlight "{T}: Add {C}{C}" and then attach an intent like "produces 3
    // colorless mana". The attached intent belongs to that effect even though it does not exist
    // literally in the source Oracle text.
    const indexByOriginal = new Map(hs.map((h, i) => [h._highlightIndex, i]));

    // Older/manual search details may not have an explicit attachment yet. If exactly one
    // trigger-shaped search detail and one source-backed effect selection exist, infer that
    // unambiguous relationship unless the user explicitly saved it as Independent. This is what
    // makes adding "Whenever an opponent draws a card" beside a selected "draw a card" phrase work
    // without requiring a hidden connection-setting step.
    const validSourceEffectHighlights = hs.filter(h => h && (h.origin !== 'user' || Boolean(h.editedFrom)) && h.field !== 'type' && getHighlightSourceAnchor(h, sourceText));
    const unconnectedTriggerDetails = hs.filter(h => h?.origin === 'user' && !h.editedFrom && !Number.isInteger(h.attachedTo) && h.intentConnection !== 'independent' && isSearchIntentTriggerPhrase(h.text));
    if (validSourceEffectHighlights.length && unconnectedTriggerDetails.length === 1) {
        // Multiple highlight chips can belong to the same Oracle clause. Count distinct clauses,
        // not chips, so one custom trigger can still connect when the user selected two spans.
        const candidateClauses = new Map();
        for (const candidate of validSourceEffectHighlights) {
            const anchor = getHighlightSourceAnchor(candidate, sourceText);
            if (!anchor) continue;
            const sourceClause = extractHighlightClauseContext(sourceText, anchor.start, anchor.end);
            const resolution = getResolutionAfterTrigger(sourceClause);
            if (!resolution || !isLikelyEffectOutcomeText(resolution) || !resolution.toLowerCase().includes(String(anchor.text || '').trim().toLowerCase())) continue;
            const key = sourceClause.toLocaleLowerCase();
            if (!candidateClauses.has(key)) candidateClauses.set(key, candidate);
        }
        if (candidateClauses.size === 1) {
            unconnectedTriggerDetails[0].attachedTo = [...candidateClauses.values()][0]._highlightIndex;
            unconnectedTriggerDetails[0].intentConnection = 'inferred';
        }
    }

    hs.forEach((h, localIndex) => {
        const targetOriginalIndex = Number.isInteger(h.attachedTo) ? h.attachedTo : null;
        if (targetOriginalIndex === null || targetOriginalIndex === h._highlightIndex) return;
        const targetLocalIndex = indexByOriginal.get(targetOriginalIndex);
        if (targetLocalIndex == null) return;
        union(localIndex, targetLocalIndex);
    });

    const buckets = new Map();
    hs.forEach((h, localIndex) => {
        const root = find(localIndex);
        if (!buckets.has(root)) buckets.set(root, []);
        buckets.get(root).push(h);
    });

    const groups = Array.from(buckets.values())
        .map(group => group.sort((a, b) => {
            const as = Number.isFinite(a.start) ? a.start : Number.POSITIVE_INFINITY;
            const bs = Number.isFinite(b.start) ? b.start : Number.POSITIVE_INFINITY;
            return as - bs || a._highlightIndex - b._highlightIndex;
        }))
        .sort((a, b) => {
            const as = Number.isFinite(a[0]?.start) ? a[0].start : Number.POSITIVE_INFINITY;
            const bs = Number.isFinite(b[0]?.start) ? b[0].start : Number.POSITIVE_INFINITY;
            return as - bs || (a[0]?._highlightIndex || 0) - (b[0]?._highlightIndex || 0);
        });

    groups.forEach((group, groupId) => {
        const positionedMembers = group.map(h => ({ highlight: h, anchor: getHighlightSourceAnchor(h, sourceText) })).filter(item => item.anchor);
        const start = positionedMembers.length ? Math.min(...positionedMembers.map(item => item.anchor.start)) : null;
        const end = positionedMembers.length ? Math.max(...positionedMembers.map(item => item.anchor.end)) : null;
        // Keep original Oracle context for parsing, but always use the current edited text as intent.
        const contextText = start !== null && end !== null ? String(sourceText || '').slice(start, end).trim() : '';
        const sourceClauseText = start !== null && end !== null ? extractHighlightClauseContext(sourceText, start, end) : '';
        const connectedIntentTexts = group
            .filter(h => h.origin === 'user' || h.field === 'type' || !getHighlightSourceAnchor(h, sourceText))
            .map(h => h.field === 'type' ? `Card type line: ${String(h.text || '').trim()}` : String(h.text || '').trim())
            .filter(Boolean);
        const positionedEffectSelections = group.filter(h => h.field !== 'type' && (
            (h.origin !== 'user' && getHighlightSourceAnchor(h, sourceText)) ||
            (h.origin === 'user' && h.editedFrom && getHighlightSourceAnchor(h, sourceText))
        ));
        const triggerIntentText = connectedIntentTexts.find(isSearchIntentTriggerPhrase) || '';
        const selectedOutcomeTexts = positionedEffectSelections
            .map(h => String(h.origin === 'user' && h.editedFrom ? h.editedFrom.text : h.text || '').trim())
            .filter(text => text && isLikelyEffectOutcomeText(text));
        const selectedEffectText = selectedOutcomeTexts[0] || positionedEffectSelections
            .map(h => String(h.origin === 'user' && h.editedFrom ? h.editedFrom.text : h.text || '').trim()).filter(Boolean).join(' ');

        // A user-edited selection keeps its original source anchor only for grammar. Its current
        // wording is authoritative and must not be filtered through a small list of recognized verbs:
        // valid custom effects such as "take an extra turn" or "win the game" must still reach the
        // parser, semantic retrieval, and ranking even when the canonical parser does not know them.
        const editedSourceSelections = group.filter(h => h.origin === 'user' && h.editedFrom && h.field !== 'type');
        const editedSourceRecords = editedSourceSelections.map(highlight => ({
            highlight,
            info: getHighlightSourceClauseInfo(highlight, sourceText)
        })).filter(record => record.info);
        const editedTriggerRecord = editedSourceRecords.find(record => record.info.anchorRole === 'trigger') || null;
        const editedOutcomeRecord = editedSourceRecords.find(record => record.info.anchorRole !== 'trigger') || null;
        const editedOutcomeSelection = editedOutcomeRecord?.highlight || null;
        const completeCustomRule = connectedIntentTexts.find(isCompleteTriggerOutcomeText)
            || editedSourceSelections.map(h => String(h.text || '').trim()).find(isCompleteTriggerOutcomeText)
            || '';
        let triggerOverrideClause = null;
        const intentOverrideTexts = [];

        if (completeCustomRule) {
            triggerOverrideClause = String(completeCustomRule).trim();
            intentOverrideTexts.push(completeCustomRule);
        } else if (editedTriggerRecord && editedOutcomeRecord) {
            const triggerInfo = editedTriggerRecord.info;
            const outcomeInfo = editedOutcomeRecord.info;
            const triggerClause = composeEditedHighlightTriggerOverride(
                triggerInfo.clauseText, editedTriggerRecord.highlight.text, triggerInfo.anchor?.text || editedTriggerRecord.highlight.editedFrom?.text
            ) || triggerInfo.clauseText;
            triggerOverrideClause = composeEditedHighlightOutcomeOverride(
                triggerClause || outcomeInfo.clauseText,
                editedOutcomeRecord.highlight.text,
                outcomeInfo.anchor?.text || editedOutcomeRecord.highlight.editedFrom?.text
            );
            if (!triggerOverrideClause) {
                const triggerText = String(editedTriggerRecord.highlight.text || '').trim().replace(/[\s,;.!?]+$/g, '');
                const outcomeText = String(editedOutcomeRecord.highlight.text || '').trim().replace(/[\s,;.!?]+$/g, '');
                triggerOverrideClause = isSearchIntentTriggerPhrase(triggerText) ? `${triggerText}, ${outcomeText}` : null;
            }
            if (triggerOverrideClause) intentOverrideTexts.push(editedTriggerRecord.highlight.text, editedOutcomeRecord.highlight.text);
        } else if (editedTriggerRecord) {
            const info = editedTriggerRecord.info;
            triggerOverrideClause = composeEditedHighlightTriggerOverride(
                info.clauseText, editedTriggerRecord.highlight.text, info.anchor?.text || editedTriggerRecord.highlight.editedFrom?.text
            );
            if (triggerOverrideClause) intentOverrideTexts.push(editedTriggerRecord.highlight.text);
        } else if (editedOutcomeSelection && triggerIntentText) {
            // Combine the explicitly requested trigger with the user's current outcome text. The
            // anchor's old wording is only used to retain safe grammatical prefixes such as "you may".
            const info = editedOutcomeRecord.info;
            const selectedAnchorText = info.anchor?.text || editedOutcomeSelection.editedFrom?.text || '';
            const triggerClause = composeHighlightIntentOverride(
                info.clauseText || sourceClauseText || contextText, triggerIntentText, selectedAnchorText
            );
            triggerOverrideClause = composeEditedHighlightOutcomeOverride(
                triggerClause || info.clauseText || sourceClauseText || contextText,
                editedOutcomeSelection.text,
                selectedAnchorText
            );
            if (!triggerOverrideClause) {
                const triggerText = String(triggerIntentText).trim().replace(/[\s,;.!?]+$/g, '');
                const outcomeText = String(editedOutcomeSelection.text).trim().replace(/[\s,;.!?]+$/g, '');
                if (isSearchIntentTriggerPhrase(triggerText) && outcomeText) triggerOverrideClause = `${triggerText}, ${outcomeText}`;
            }
            if (triggerOverrideClause) intentOverrideTexts.push(triggerIntentText, editedOutcomeSelection.text);
        } else if (editedOutcomeSelection) {
            const info = editedOutcomeRecord.info;
            const selectedAnchorText = info.anchor?.text || editedOutcomeSelection.editedFrom?.text || '';
            triggerOverrideClause = composeEditedHighlightOutcomeOverride(
                info.clauseText || sourceClauseText || contextText,
                editedOutcomeSelection.text,
                selectedAnchorText
            );
            // If the original clause is not parseable, do not silently discard the user's revised
            // text. The plain custom text remains available to semantic and lexical fallback paths.
            if (!triggerOverrideClause) triggerOverrideClause = String(editedOutcomeSelection.text || '').trim();
            if (triggerOverrideClause) intentOverrideTexts.push(editedOutcomeSelection.text);
        } else if (triggerIntentText && positionedEffectSelections.length) {
            triggerOverrideClause = composeHighlightIntentOverride(sourceClauseText || contextText, triggerIntentText, selectedEffectText);
            if (triggerOverrideClause) intentOverrideTexts.push(triggerIntentText);
        } else if (editedSourceSelections.length) {
            // Last-resort safety path: even if no trigger/outcome grammar could be composed, retain
            // the current authored text rather than reverting all the way to the old printed clause.
            triggerOverrideClause = editedSourceSelections.map(h => String(h.text || '').trim()).filter(Boolean).join('. ');
            if (triggerOverrideClause) intentOverrideTexts.push(...editedSourceSelections.map(h => String(h.text || '').trim()));
        }
        // Parse the full source clause for natural highlights, but when users edit a selected
        // outcome/trigger, compose their current wording into the effective parser/scorer clause.
        const parseText = triggerOverrideClause || sourceClauseText || contextText || group.map(h => h.text).filter(Boolean).join(' ');
        const overrideSet = new Set(intentOverrideTexts.map(value => String(value).trim()));
        const remainingIntentTexts = connectedIntentTexts.filter(value => !overrideSet.has(String(value).trim()));
        const intentModes = group.map(h => h.mode || 'variable').filter(mode => mode !== 'context');
        const hasExact = intentModes.includes('exact');
        const hasVariable = intentModes.includes('variable');
        const allAvoid = intentModes.length > 0 && intentModes.every(mode => mode === 'avoid');
        const groupMode = allAvoid ? 'avoid' : (hasExact && hasVariable ? 'mixed' : (hasVariable ? 'variable' : (hasExact ? 'exact' : 'context')));
        const benchmarkIntentOnly = group.some(h => h.origin === 'benchmark') && groupMode === 'mixed';
        const exactTexts = group.filter(h => h.mode === 'exact').map(h => h.text.trim());
        const variableTexts = group.filter(h => h.mode === 'variable').map(h => h.text.trim());
        const modes = group.map(h => ['variable', 'exact', 'context', 'avoid'].includes(h.mode) ? h.mode : 'exact');
        group.contextText = contextText || group.filter(h => Number.isFinite(h.start)).map(h => h.text.trim()).join(' ');
        group.sourceClauseText = sourceClauseText || group.contextText;
        group.parseText = parseText;
        group.triggerIntentOverrideText = triggerOverrideClause ? (intentOverrideTexts[0] || triggerIntentText) : '';
        group.triggerIntentOverride = Boolean(triggerOverrideClause);
        group.intentOverrideTexts = [...new Set(intentOverrideTexts.map(value => String(value || '').trim()).filter(Boolean))];
        group.editedFromSource = group.some(h => Boolean(h.editedFrom));
        group.connectedIntentTexts = connectedIntentTexts;
        group.searchIntentText = [parseText, ...remainingIntentTexts].filter(Boolean).join('. ');
        group.sourceStart = start;
        group.sourceEnd = end;
        group.mode = groupMode;
        group.modes = modes;
        group.selections = group.map(h => ({
            text: h.text.trim(),
            mode: h.mode === 'variable' ? 'variable' : 'exact',
            intent: h.intent || '',
            origin: h.origin || 'user',
            attachedTo: Number.isInteger(h.attachedTo) ? h.attachedTo : null
        }));
        group.exactTexts = exactTexts;
        group.variableTexts = variableTexts;
        group.benchmarkIntentOnly = benchmarkIntentOnly;
        group.origin = group.some(h => h.origin === 'benchmark') ? 'benchmark' : 'user';
        group.forEach(h => {
            h.groupId = groupId;
            h.groupStart = start;
            h.groupEnd = end;
            h.groupContextText = group.contextText;
            h.groupMode = groupMode;
            h.benchmarkIntentOnly = benchmarkIntentOnly;
        });
    });
    return groups;
}

function buildHighlightIntentProfiles(highlights, sourceCard = currentSourceCard, sourceText = getCurrentSourceOracleText(sourceCard)) {
    const allHighlights = Array.isArray(highlights) ? highlights : [];
    const effectEntries = allHighlights.map((highlight, originalIndex) => ({ highlight, originalIndex }))
        .filter(entry => entry.highlight?.field !== 'type');
    const remappedIndex = new Map(effectEntries.map((entry, index) => [entry.originalIndex, index]));
    const effectHighlights = effectEntries.map(({ highlight }) => ({
        ...highlight,
        attachedTo: Number.isInteger(highlight.attachedTo) ? (remappedIndex.get(highlight.attachedTo) ?? null) : null
    }));
    const groups = annotateHighlightGroups(effectHighlights, sourceText);
    return groups.map((group, index) => {
        // Source-selected text is parsed in its full clause context so trigger conditions survive
        // selection of only the outcome phrase. A connected trigger-shaped Search detail is a
        // deliberate override and is composed with that outcome in group.parseText; ordinary
        // Search details (e.g. "produces three colorless mana") remain semantic hints only.
        let parsedEffects = parseMTGEffect(group.parseText || group.sourceClauseText || group.contextText || group.map(h => h.text).filter(Boolean).join(' '));
        parsedEffects.forEach(effect => {
            if (effect && typeof effect === 'object') {
                effect.contextClause = String(group.parseText || group.sourceClauseText || group.contextText || effect.raw || '').trim();
                effect.searchIntentContextOverride = Boolean(group.triggerIntentOverride);
                const matchingHighlight = group.find(h => deriveHighlightAspectKind(h, sourceText) && (h.aspects || hasActiveHighlightAspects(h.aspects)));
                if (matchingHighlight) effect.userAspects = normalizeHighlightAspects(matchingHighlight.aspects);
                else { const atomicMana = group.find(h => /^(?:\s*\{[wubrgc]\}\s*)+$/i.test(String(h.text || '').trim())); if (atomicMana) { const derived = deriveHighlightAspectKind(atomicMana, sourceText); if (derived?.kind === 'mana') effect.userAspects = { mana: { amount: { rule: 'exact', value: derived.amount }, color: { rule: 'same', colors: derived.colors }, activation: { rule: 'auto' } } }; } }
            }
        });
        let canonicalFunctions = getCanonicalFunctions(parsedEffects);
        let recognizedEffects = parsedEffects.filter(e => e.action && e.action !== 'generic');

        // Fallback: mask Variable selections only if the unmasked excerpt failed to parse. This is
        // useful for numeric/custom tokens that would otherwise interrupt a parser pattern while
        // keeping the surrounding grammar intact.
        if (!recognizedEffects.length && group.some(h => h.mode === 'variable')) {
            let normalized = String(group.parseText || group.sourceClauseText || group.contextText || group.map(h => h.text).join(' '));
            // Only mask literal variable spans that come from the printed source text. A user-edited
            // phrase is the intended replacement, not a variable token to erase from the query.
            for (const h of group.filter(x => x.mode === 'variable' && !(x.origin === 'user' && x.editedFrom))) {
                const escaped = h.text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                normalized = normalized.replace(new RegExp(escaped, 'g'), 'N');
            }
            const normalizedEffects = parseMTGEffect(normalized);
            const normalizedRecognized = normalizedEffects.filter(e => e.action && e.action !== 'generic');
            if (normalizedRecognized.length) {
                parsedEffects = normalizedEffects;
                recognizedEffects = normalizedRecognized;
                canonicalFunctions = getCanonicalFunctions(normalizedEffects);
            }
        }

        return {
            index,
            groupId: index,
            text: group.contextText,
            contextText: group.contextText,
            searchIntentText: group.searchIntentText,
            sourceClauseText: group.sourceClauseText || '',
            parseText: group.parseText || '',
            triggerIntentOverrideText: group.triggerIntentOverrideText || '',
            triggerIntentOverride: Boolean(group.triggerIntentOverride),
            userAuthoredOverride: Boolean(group.triggerIntentOverride && group.some(h => h.origin === 'user')),
            editedFromSource: Boolean(group.editedFromSource),
            // Any active highlight is a deliberate user focus. For edited/custom text, parseText is
            // the authoritative composed rule; this text is also the lexical fallback when a new
            // phrase is not yet covered by the canonical MTG action parser.
            explicitUserIntent: Boolean(group.length && !group.some(h => h.origin === 'benchmark')),
            explicitIntentText: String(group.parseText || group.searchIntentText || group.contextText || group.map(h => h.text).filter(Boolean).join('. ')).trim(),
            intentOverrideTexts: group.intentOverrideTexts || [],
            connectedIntentTexts: (group.connectedIntentTexts || []).filter(value => !(group.intentOverrideTexts || [group.triggerIntentOverrideText]).includes(String(value).trim())),
            selections: group.selections,
            modes: group.modes,
            mode: group.mode,
            exactTexts: group.exactTexts,
            variableTexts: group.variableTexts,
            benchmarkIntentOnly: Boolean(group.benchmarkIntentOnly),
            origin: group.origin,
            parsedEffects,
            recognizedEffects,
            canonicalFunctions,
            parserConfidence: calculateCardFieldConfidence(parsedEffects).overall || 0,
            canonicalText: canonicalFunctionToText(canonicalFunctions)
        };
    });
}

function calculateHighlightIntentMatch(profiles, candidateEffects, candidateCard = null) {
    if (!profiles?.length) return 0;
    const safeEffects = Array.isArray(candidateEffects) ? candidateEffects : [];
    const candidateOracle = candidateCard ? getCardOracleText(candidateCard) : '';
    const clamp01 = value => Math.max(0, Math.min(1, Number(value) || 0));
    const profileScores = profiles.map(profile => {
        const sourceEffects = profile.recognizedEffects?.length ? profile.recognizedEffects : (profile.parsedEffects || []);
        let structuralScore = 0;
        let coverage = 0;
        if (sourceEffects.length && safeEffects.length) {
            const matchingMode = ['exact', 'variable'].includes(profile.mode) ? profile.mode : 'variable';
            const assignment = maxOneToOneHighlightAssignment(sourceEffects, safeEffects, matchingMode);
            coverage = sourceEffects.length ? assignment.matches.length / sourceEffects.length : 0;
            const lexicalWeight = profile.benchmarkIntentOnly ? 0.05 : 0.12;
            const structuralWeight = profile.benchmarkIntentOnly ? 0.78 : 0.76;
            const coverageWeight = profile.benchmarkIntentOnly ? 0.17 : 0.12;
            let lexicalSupport = 0;
            if (candidateOracle && profile.exactTexts?.length) {
                const oracle = candidateOracle.toLocaleLowerCase();
                lexicalSupport = profile.exactTexts.filter(t => oracle.includes(String(t).toLocaleLowerCase())).length / profile.exactTexts.length;
            }
            structuralScore = clamp01(assignment.score * structuralWeight + coverage * coverageWeight + lexicalSupport * lexicalWeight);
            if (profile.mode === 'avoid') structuralScore = 1 - structuralScore;
            else if (profile.mode === 'context') structuralScore = 0.5;
        }

        // Strong text fallback for explicit user intent. This is intentionally independent of parser
        // recognition: custom wording such as "take an extra turn" must still steer retrieval/ranking
        // even if the current rules parser returns only a generic effect for it.
        const explicitQuery = String(profile.explicitIntentText || profile.parseText || profile.searchIntentText || '').trim();
        let textSupport = 0;
        if (profile.explicitUserIntent && explicitQuery && candidateOracle) {
            const simple = clamp01(calculateSimpleSimilarity(explicitQuery, candidateOracle));
            const fuzzy = clamp01(calculateFuzzyTextMatch(explicitQuery, candidateOracle));
            const coverageText = clamp01(lexicalTokenCoverage(explicitQuery, candidateOracle));
            // Preserve phrase/trigger identity over unordered word overlap; lexical coverage is only
            // a supplement, not enough on its own to call two mechanically different rules equal.
            textSupport = clamp01(simple * 0.42 + fuzzy * 0.43 + coverageText * 0.15);
        }

        const hasRecognizedStructure = sourceEffects.some(effect => effect?.canonical || (effect?.action && effect.action !== 'generic'));
        const strongUserIntent = Boolean(profile.userAuthoredOverride || profile.editedFromSource || (profile.connectedIntentTexts || []).length);
        let score = structuralScore;
        if (profile.explicitUserIntent) {
            // For user-authored edits, the words they wrote get greater say even when the canonical
            // parser cannot fully classify the effect. When structure is known it remains the
            // majority signal; when it is unknown, text intent becomes the safe fallback.
            score = hasRecognizedStructure
                ? structuralScore * (strongUserIntent ? 0.62 : 0.72) + textSupport * (strongUserIntent ? 0.38 : 0.28)
                : textSupport * (strongUserIntent ? 0.92 : 0.88) + structuralScore * (strongUserIntent ? 0.08 : 0.12);
        }

        let confidence = 0.55 + 0.45 * (profile.parserConfidence || 0);
        if (strongUserIntent && hasRecognizedStructure) confidence = Math.max(confidence, 0.90);
        else if (strongUserIntent) confidence = Math.max(confidence, 0.84);
        else if (profile.explicitUserIntent) confidence = Math.max(confidence, 0.78);
        const explicitIntentPriority = profile.userAuthoredOverride ? 1.12 : (strongUserIntent ? 1.08 : (profile.explicitUserIntent ? 1.06 : 1));
        // Do not punish a usable text-only intent because parsing returned no candidate effects.
        return clamp01(score * explicitIntentPriority * confidence);
    });
    const average = profileScores.reduce((a,b) => a+b,0) / profileScores.length;
    const fullCoverage = profileScores.filter(v => v >= 0.55).length / profileScores.length;
    return clamp01(average * 0.80 + fullCoverage * 0.20);
}


function getHighlightRankingWeight(profiles = [], { hasHighlight = false, hasEffectHighlight = false, hasTypeHighlight = false } = {}) {
    if (!hasHighlight) return 0;
    if (!hasEffectHighlight) return hasTypeHighlight ? 0.18 : 0;
    const strongIntent = (profiles || []).some(profile =>
        profile?.userAuthoredOverride || profile?.editedFromSource ||
        (profile?.connectedIntentTexts || []).length > 0
    );
    // The selected/edited text is an explicit user instruction, not a weak side channel. It gets
    // 30% of the normalized rank for ordinary selections and 42% when the user edits/composes a
    // search intent. The remaining score still preserves mechanical, semantic, and role evidence.
    return strongIntent ? 0.42 : 0.30;
}

function blendHighlightIntentScore(baseScore, highlightScore, profiles = [], options = {}) {
    const clamp01 = value => Math.max(0, Math.min(1, Number(value) || 0));
    const base = clamp01(baseScore);
    const highlight = clamp01(highlightScore);
    const weight = getHighlightRankingWeight(profiles, options);
    return {
        score: clamp01(base * (1 - weight) + highlight * weight),
        weight,
        highlightScore: highlight,
        explicitUserIntent: Boolean(weight >= 0.42)
    };
}

function calculateHighlightIntentRetrievalText(profiles) {
    if (!profiles || profiles.length === 0) return '';
    const canonical = profiles.flatMap(p => p.canonicalFunctions || []);
    const canonicalText = canonicalFunctionToText(canonical);
    const groupedText = profiles.map(p => p.searchIntentText || p.contextText || p.text).filter(Boolean);
    const connected = profiles.flatMap(p => p.connectedIntentTexts || []).filter(Boolean);
    return [...new Set([canonicalText, ...groupedText, ...connected].filter(Boolean))].join('. ');
}

/**
 * Estimates how much *candidate-only* functionality is unrelated to the source.
 *
 * This is intentionally NOT a reciprocal similarity score. Reciprocal scoring was the source of
 * the old harmonic-mean problem: a useful card with the same core effect plus a drawback or rider
 * could be dragged down by its extra text. Instead we measure the amount of candidate functionality
 * that fails to map back to the source, weight it by effect importance, and apply only a bounded
 * penalty. Secondary riders therefore cost much less than an unrelated primary function.
 */
function calculateCandidateMechanicalExcess(parsedSource, parsedCandidate, pairWorkspace = null) {
    if (pairWorkspace?.parsedSource === parsedSource && pairWorkspace?.parsedCandidate === parsedCandidate) {
        return calculateCandidateMechanicalExcessFromWorkspace(pairWorkspace);
    }
    if (!parsedSource || !parsedCandidate || parsedCandidate.length === 0) return 1;

    let weightedExcess = 0;
    let weightTotal = 0;

    parsedCandidate.forEach(effB => {
        const baseImportance = Math.max(0.05, effB.importance ?? (effB.isPrimary ? 1 : 0.35));
        // Substantial standalone effects deserve a little more excess weight; tiny riders/costs
        // remain intentionally cheap. This is what distinguishes "same function + drawback" from
        // "same function + an entire unrelated second purpose" without reverting to symmetry.
        const importance = baseImportance * (baseImportance >= 0.70 ? 1.20 : 0.80);
        const bestCoverage = directionalMechanicalSimilarity([effB], parsedSource);
        const excess = Math.max(0, 1 - bestCoverage);
        weightedExcess += excess * importance;
        weightTotal += importance;
    });

    return weightTotal > 0 ? Math.min(1, weightedExcess / weightTotal) : 1;
}

/**
 * Source-centric mechanical similarity.
 *
 * The score answers the useful search question first: "How much of the SOURCE card's important
 * functionality is represented by this candidate?" Candidate-only functionality is considered
 * separately as a small excess penalty. This prevents extra drawbacks, riders, costs, or secondary
 * abilities from overwhelming an otherwise excellent match, while still keeping a genuinely
 * unrelated multi-function card from receiving a free perfect score.
 */

/**
 * Ranking-specific effect coverage.
 *
 * directionalMechanicalSimilarity() is intentionally source-centric, but the ranker also needs
 * to know HOW that coverage was achieved. A compound card that matches 2/3 important effects is
 * meaningfully different from a card that matches only its strongest effect. This profile keeps
 * those distinctions separate from the legacy mechanicalScore so the existing score presentation
 * remains stable while the final ordering gets better evidence.
 */
function calculateEffectCoverageProfile(parsedSource, parsedCandidate, pairWorkspace = null) {
    const source = (parsedSource || []).filter(e => e?.canonical);
    const candidate = (parsedCandidate || []).filter(e => e?.canonical);
    if (!source.length || !candidate.length) {
        return {
            sourceCoverage: 0, candidateCoverage: 0, balancedCoverage: 0,
            primaryMatch: 0, matchedWeight: 0, sourceWeight: 0,
            candidateWeight: 0, unmatchedSourceWeight: 1, unmatchedCandidateWeight: 1,
            matches: []
        };
    }

    const sourceWeights = source.map(e => Math.max(0.05, e.importance ?? (e.isPrimary ? 1 : 0.35)));
    const candidateWeights = candidate.map(e => Math.max(0.05, e.importance ?? (e.isPrimary ? 1 : 0.35)));
    // Pair quality depends only on an effect pair, not on the current assignment mask. The former
    // recursive DP recomputed these expensive structural comparisons in many different branches.
    // Compute the exact same pair scores once and share them between the small-card DP and the
    // large-card polynomial assignment path.
    const reusableWorkspace = pairWorkspace?.parsedSource === parsedSource && pairWorkspace?.parsedCandidate === parsedCandidate &&
        pairWorkspace.sourceEffects.length === source.length && pairWorkspace.candidateEffects.length === candidate.length &&
        source.every((effect, index) => effect === pairWorkspace.sourceEffects[index]) &&
        candidate.every((effect, index) => effect === pairWorkspace.candidateEffects[index]);
    const pairScores = reusableWorkspace
        ? pairWorkspace.coverageForward
        : source.map(a => candidate.map(b => directionalMechanicalSimilarity([a], [b])));
    const pairScore = (i, j) => pairScores[i][j];

    const n = source.length;
    const m = candidate.length;
    const maxPairs = Math.min(n, m);
    let combination = 1;
    let estimatedStates = 1;
    for (let k = 1; k <= maxPairs; k++) {
        combination = combination * (m - k + 1) / k;
        estimatedStates += combination;
        if (estimatedStates * Math.max(1, m) > 50000) break;
    }

    let assignment;
    if (estimatedStates * Math.max(1, m) <= 50000) {
        // Exact memoized assignment for ordinary cards. Store choices instead of a fresh matches
        // array at every state, reducing allocation without changing tie order or score math.
        const memo = new Map();
        function solve(i, usedMask) {
            if (i >= n) return 0;
            const key = `${i}|${usedMask}`;
            const cached = memo.get(key);
            if (cached !== undefined) return cached.score;
            let bestScore = solve(i + 1, usedMask); // leave source effect unmatched, as before
            let bestChoice = -1;
            for (let j = 0; j < m; j++) {
                const bit = 1n << BigInt(j);
                if (usedMask & bit) continue;
                const pair = pairScore(i, j);
                if (pair <= 0.02) continue;
                const restScore = solve(i + 1, usedMask | bit);
                const score = pair * sourceWeights[i] + restScore;
                if (score > bestScore) {
                    bestScore = score;
                    bestChoice = j;
                }
            }
            memo.set(key, { score: bestScore, choice: bestChoice });
            return bestScore;
        }
        const score = solve(0, 0n);
        const matches = [];
        let usedMask = 0n;
        for (let i = 0; i < n; i++) {
            const entry = memo.get(`${i}|${usedMask}`);
            const j = entry?.choice ?? -1;
            if (j >= 0) {
                matches.push([i, j, pairScore(i, j)]);
                usedMask |= 1n << BigInt(j);
            }
        }
        assignment = { score, matches };
    } else {
        // Exact maximum-weight bipartite matching (Hungarian algorithm). This solves the same
        // objective as the DP in O(n^2 * m), avoiding combinatorial explosions on long multi-effect
        // cards. Each source row also receives a dummy unmatched column with zero weight.
        // Positive pair scores <= 0.02 are treated as no match, identically to the DP path.
        const rows = n;
        const realCols = m;
        const cols = m + n;
        const u = new Array(rows + 1).fill(0);
        const v = new Array(cols + 1).fill(0);
        const p = new Array(cols + 1).fill(0);
        const way = new Array(cols + 1).fill(0);
        const cost = (i, j) => {
            if (j > realCols) return 0; // dummy unmatched source effect
            const pair = pairScore(i - 1, j - 1);
            return pair > 0.02 ? -(pair * sourceWeights[i - 1]) : 0;
        };
        for (let i = 1; i <= rows; i++) {
            p[0] = i;
            let j0 = 0;
            const minv = new Array(cols + 1).fill(Infinity);
            const used = new Array(cols + 1).fill(false);
            do {
                used[j0] = true;
                const i0 = p[j0];
                let delta = Infinity;
                let j1 = 0;
                for (let j = 1; j <= cols; j++) {
                    if (used[j]) continue;
                    const cur = cost(i0, j) - u[i0] - v[j];
                    if (cur < minv[j]) {
                        minv[j] = cur;
                        way[j] = j0;
                    }
                    if (minv[j] < delta) {
                        delta = minv[j];
                        j1 = j;
                    }
                }
                for (let j = 0; j <= cols; j++) {
                    if (used[j]) {
                        u[p[j]] += delta;
                        v[j] -= delta;
                    } else {
                        minv[j] -= delta;
                    }
                }
                j0 = j1;
            } while (p[j0] !== 0);
            do {
                const j1 = way[j0];
                p[j0] = p[j1];
                j0 = j1;
            } while (j0 !== 0);
        }
        const assignedColumn = new Array(rows + 1).fill(0);
        for (let j = 1; j <= cols; j++) if (p[j] > 0) assignedColumn[p[j]] = j;
        const matches = [];
        let score = 0;
        for (let i = 1; i <= rows; i++) {
            const j = assignedColumn[i];
            if (j >= 1 && j <= realCols) {
                const pair = pairScore(i - 1, j - 1);
                if (pair > 0.02) {
                    matches.push([i - 1, j - 1, pair]);
                    score += pair * sourceWeights[i - 1];
                }
            }
        }
        assignment = { score, matches };
    }

    const sourceWeight = sourceWeights.reduce((a,b) => a+b, 0) || 1;
    const candidateWeight = candidateWeights.reduce((a,b) => a+b, 0) || 1;
    const sourceCoverage = Math.max(0, Math.min(1, assignment.score / sourceWeight));

    let candidateMatchedWeight = 0;
    for (const [, j, pair] of assignment.matches) candidateMatchedWeight += candidateWeights[j] * pair;
    const candidateCoverage = Math.max(0, Math.min(1, candidateMatchedWeight / candidateWeight));
    const balancedCoverage = Math.sqrt(sourceCoverage * candidateCoverage);

    let primaryMatch = 0;
    const sourcePrimaryIndex = source.findIndex(e => e.isPrimary);
    if (sourcePrimaryIndex >= 0) {
        const match = assignment.matches.find(([i]) => i === sourcePrimaryIndex);
        primaryMatch = match ? match[2] : 0;
    }

    return {
        sourceCoverage,
        candidateCoverage,
        balancedCoverage,
        primaryMatch,
        matchedWeight: assignment.score,
        sourceWeight,
        candidateWeight,
        unmatchedSourceWeight: Math.max(0, 1 - sourceCoverage),
        unmatchedCandidateWeight: Math.max(0, 1 - candidateCoverage),
        matches: assignment.matches
    };
}

/**
 * Functional substitute similarity. This intentionally operates above exact mechanics: exile,
 * bounce, and destroy can all be useful creature-interaction substitutes, while draw and discard
 * are related resource/card-advantage functions without being treated as identical.
 */
function calculateFunctionalSimilarity(parsedSource, parsedCandidate, precomputed = null) {
    const source = (parsedSource || []).filter(e => e?.canonical);
    const candidate = (parsedCandidate || []).filter(e => e?.canonical);
    const sourceProfile = parsedSource?._mechanicProfile || buildUniversalMechanicProfile(null, '', parsedSource || []);
    const candidateProfile = parsedCandidate?._mechanicProfile || buildUniversalMechanicProfile(null, '', parsedCandidate || []);
    const universal = precomputed?.universal || calculateUniversalMechanicSimilarity(sourceProfile, candidateProfile);
    if (!source.length || !candidate.length) return universal.score * 0.88;
    const sourceFns = source.map(e => e.canonical.function).filter(Boolean);
    const candidateFns = candidate.map(e => e.canonical.function).filter(Boolean);
    let total = 0, weight = 0;
    for (const fnA of sourceFns) {
        const importance = FUNCTION_IMPORTANCE[fnA] ?? 0.5;
        const best = candidateFns.reduce((m, fnB) => Math.max(m, getFunctionAffinity(fnA, fnB)), 0);
        total += best * Math.max(0.05, importance);
        weight += Math.max(0.05, importance);
    }
    const canonicalScore = weight ? total / weight : 0;
    const graphA = parsedSource?._mechanicalGraph || buildMechanicalEffectGraph(null, '', parsedSource || []);
    const graphB = parsedCandidate?._mechanicalGraph || buildMechanicalEffectGraph(null, '', parsedCandidate || []);
    const graphScore = Number.isFinite(precomputed?.graphDetail?.score)
        ? precomputed.graphDetail.score
        : calculateMechanicalGraphSimilarity(graphA, graphB).score;
    return Math.max(0, Math.min(1, canonicalScore * 0.62 + graphScore * 0.23 + universal.score * 0.15));
}

/**
 * Quantity compatibility rewards nearby magnitudes without confusing unrelated numeric values.
 * The parser's effect-level comparison already uses quantities; this aggregate signal helps the
 * final ranker preserve that information when a compound card contains several effects.
 */
function calculateAggregateQuantitySimilarity(parsedSource, parsedCandidate, coverageProfile) {
    if (!coverageProfile?.matches?.length) return 0;
    let total = 0, weight = 0;
    for (const [i, j, pair] of coverageProfile.matches) {
        const a = parsedSource?.[i], b = parsedCandidate?.[j];
        const qa = a?.quantity ?? a?.amount ?? a?.canonical?.params?.quantity ?? null;
        const qb = b?.quantity ?? b?.amount ?? b?.canonical?.params?.quantity ?? null;
        if (qa == null || qb == null || !Number.isFinite(Number(qa)) || !Number.isFinite(Number(qb))) continue;
        const av = Number(qa), bv = Number(qb);
        const similarity = Math.max(0, 1 - Math.abs(av - bv) / Math.max(Math.abs(av), Math.abs(bv), 1));
        const w = Math.max(0.05, a?.importance ?? 0.35);
        total += similarity * w * Math.max(0.25, pair);
        weight += w;
    }
    return weight ? Math.max(0, Math.min(1, total / weight)) : 0;
}


// ---------------------------------------------------------------------------
// UNIVERSAL MECHANIC SIGNATURE
// ---------------------------------------------------------------------------
// The finite effect parser remains useful for detailed rules structure, but Magic's mechanic
// vocabulary is much larger than any sensible hand-written parser table. bundled card records carry
// the card's structured `keywords` array, so use that as the universal mechanic layer. This means
// obscure, historic, and newly introduced keyword abilities/actions can participate in mechanical
// matching without adding a new branch to the parser each time Wizards adds a mechanic.
//
// The current 2026 Comprehensive Rules/releases demonstrate why this matters: new mechanics such as
// sneak, storied, heal, blight, increment, paradigm, preparation, power-up, and teamwork have been
// added during 2026. The keyword metadata path catches those automatically. The text-derived action
// and rules-context signature then handles keyword actions and mechanically meaningful text that is
// not represented as a single keyword field.
const UNIVERSAL_RULE_ACTION_TERMS = [
    'activate','adapt','amass','assemble','attach','bolster','bury','cast','clash','cloak','connive',
    'counter','create','crew','cycle','dash','discover','discard','disguise','double','draw','embalm',
    'enlist','escape','exert','explore','fight','foretell','goad','investigate','learn','manifest',
    'meld','mill','monstrous','mutate','phase out','populate','proliferate','plot','regenerate',
    'reveal','sacrifice','scry','search','shuffle','skirmish','solve','sneak','spree','support',
    'surveil','suspect','tap','transform','turn face up','untap','venture','vote','ward','roll',
    'choose','exchange','exile','heal','blight','recruit','increment','prepare','preparation',
    'power-up','teamwork','storied','refine','offspring','saddle','craft','collect evidence',
    'incubate','incite','train','open an attraction','take the initiative','become the monarch',
    'initiative','dungeon','daybound','nightbound','convert','stash','impending','bargain',
    'corrupted','for mirrodin','living weapon','reconfigure','equip','fortify','level up','level-up',
    'transfigure','transmute','cycling','kicker','flashback','madness','suspend','cascade','storm',
    'prowess','convoke','delve','affinity','improvise','offering','evoke','ninjutsu','jutsu','channel',
    'splice','buyback','retrace','recover','scavenge','unearth','encore','disturb','decayed','aftermath',
    'adventure','partner','battle cry','bloodthirst','bushido','flanking','fading','vanishing','undying',
    'persist','infect','wither','deathtouch','defender','double strike','first strike','flying','haste',
    'hexproof','indestructible','lifelink','menace','protection','reach','shroud','trample','vigilance',
    'fear','intimidate','shadow','skulk','horsemanship','landwalk','extort','cipher','evolve','bestow',
    'tribute','surge','delirium','revolt','ascend','enrage','riot','mentor','spectacle','afterlife',
    'saga','constellation','landfall','metalcraft','spell mastery','ferocious','raid','formidable','morbid',
    'threshold','hellbent','magecraft','paradigm','preparation'
];

function escapeMechanicRegexTerm(term) {
    return String(term || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

const UNIVERSAL_RULE_ACTION_REGEX = new RegExp(
    '\\b(?:' + UNIVERSAL_RULE_ACTION_TERMS
        .slice()
        .sort((a, b) => b.length - a.length)
        .map(term => escapeMechanicRegexTerm(term).replace(/\s+/g, '\\s+'))
        .join('|') + ')\\b',
    'gi'
);

const UNIVERSAL_ZONE_TERMS = [
    'battlefield','graveyard','hand','library','stack','exile','command zone','outside the game',
    'ante','sideboard','dungeon','attraction','sticker sheet'
];
// These terms are static for the lifetime of the app. Building/escaping the expression once avoids
// several array allocations and a RegExp compile on every candidate's universal-profile pass.
const UNIVERSAL_ZONE_REGEX = new RegExp(
    '(?:' + UNIVERSAL_ZONE_TERMS.map(escapeMechanicRegexTerm).map(v => v.replace(/\s+/g, '\\s+')).join('|') + ')',
    'gi'
);
const UNIVERSAL_CONTEXT_PATTERNS = {
    target: /\b(?:target|each|all|any|another|one or more|up to|a|an)\s+(?:creature|permanent|artifact|enchantment|land|planeswalker|battle|player|opponent|spell|ability|card|kindred|token|permanents?|creatures?|cards?)\b/gi,
    scope: /\b(?:you control|your opponents? control|each player|each opponent|all players|nonland|nontoken|legendary|nonlegendary|nonbasic|basic|multicolored|monocolored|historic|modified|attacking|blocking|tapped|untapped|dying|damaged|discarded|sacrificed|cast|crewed|equipped|enchanted|opponents?|you|your)\b/gi,
    trigger: /\b(?:when|whenever|at the beginning of|at the end of|if|unless|as long as|while|after|before|until|the next time|each upkeep|each end step|your upkeep|your end step)\b/gi,
    cost: /\b(?:pay|sacrifice|discard|exile|tap|untap|remove|spend|return|reveal|mill|cast)\b|\{[^}]+\}/gi,
    choice: /\b(?:choose|chosen|may|modal|one or more|any number|up to|for each|x|random|vote|secretly)\b/gi
};
const UNIVERSAL_RESOURCE_REGEX = /\b(?:life|mana|cards?|counters?|tokens?|treasure|clue|food|blood|map|powerstone|incubator|energy|poison|experience|rad|stun|finality|shield|ticket|evidence|junk|role|ring-bearer|attraction|dungeon|initiative|monarch|city's blessing)\b/gi;
const UNIVERSAL_STAT_REGEX = /(?:[+\-−]\d+\/[+\-−]\d+|[+\-−]\d+|\bdouble\b|\bhalf\b|\btriple\b|\bgets?\b|\bbecomes?\b)/gi;
const UNIVERSAL_COUNTER_REGEX = /(?:[+\-−]\d+\/[+\-−]\d+\s*)?\b[a-z][a-z0-9-]*\s+counters?\b/gi;
const UNIVERSAL_TOKEN_REGEX = /\b([a-z][a-z0-9' -]{1,32})\s+tokens?\b/gi;
const UNIVERSAL_MANA_SYMBOL_REGEX = /\{[^}]+\}/g;

// Many mechanical-pair comparisons repeatedly normalize the same small vocabulary (function,
// zone, target, trigger, resource and scope labels). Memoize this pure operation in a bounded LRU
// so the hot scoring loops avoid allocating and running the same regex replacements thousands of
// times. Raw strings are exact cache keys, so this cannot merge values that were distinct before.
const mechanicTokenNormalizationCache = new Map();
const mechanicTokenNormalizationCacheStats = { hits: 0, computed: 0, evictions: 0 };
const MECHANIC_TOKEN_NORMALIZATION_CACHE_MAX = 12000;
function normalizeMechanicToken(value) {
    const raw = String(value || '');
    if (mechanicTokenNormalizationCache.has(raw)) {
        mechanicTokenNormalizationCacheStats.hits++;
        const cached = mechanicTokenNormalizationCache.get(raw);
        mechanicTokenNormalizationCache.delete(raw);
        mechanicTokenNormalizationCache.set(raw, cached);
        return cached;
    }
    const normalized = raw
        .toLowerCase()
        .replace(/[’']/g, "'")
        .replace(/[‐‑‒–—]/g, '-')
        .replace(/\s+/g, ' ')
        .trim();
    mechanicTokenNormalizationCache.set(raw, normalized);
    mechanicTokenNormalizationCacheStats.computed++;
    if (mechanicTokenNormalizationCache.size > MECHANIC_TOKEN_NORMALIZATION_CACHE_MAX) {
        // Amortized eviction keeps the common hit path small while bounding retained strings.
        const removeCount = Math.max(1024, Math.floor(MECHANIC_TOKEN_NORMALIZATION_CACHE_MAX * 0.12));
        const iterator = mechanicTokenNormalizationCache.keys();
        let removed = 0;
        for (let i = 0; i < removeCount; i++) {
            const next = iterator.next();
            if (next.done) break;
            mechanicTokenNormalizationCache.delete(next.value);
            removed++;
        }
        mechanicTokenNormalizationCacheStats.evictions += removed;
    }
    return normalized;
}

function setCoverage(sourceSet, candidateSet) {
    const a = sourceSet instanceof Set ? sourceSet : new Set(sourceSet || []);
    const b = candidateSet instanceof Set ? candidateSet : new Set(candidateSet || []);
    if (!a.size || !b.size) return 0;
    let overlap = 0;
    a.forEach(v => { if (b.has(v)) overlap++; });
    return overlap / a.size;
}

// Reuse per-keyword expressions across candidate parses. Previously these three regexes were
// recompiled for each candidate/effect/profile pass, creating a large amount of short-lived
// RegExp objects in the hottest structural-scoring path. Bounded LRU keeps user-defined keywords safe.
const mechanicKeywordRegexCache = new Map();
const mechanicKeywordRegexCacheStats = { hits: 0, computed: 0, evictions: 0 };
const MECHANIC_KEYWORD_REGEX_CACHE_MAX = 2048;
function getMechanicKeywordRegexes(keyword) {
    const normalized = normalizeMechanicToken(keyword);
    if (!normalized) return null;
    const cached = mechanicKeywordRegexCache.get(normalized);
    if (cached) {
        mechanicKeywordRegexCacheStats.hits++;
        mechanicKeywordRegexCache.delete(normalized);
        mechanicKeywordRegexCache.set(normalized, cached);
        return cached;
    }
    const escaped = escapeMechanicRegexTerm(normalized).replace(/\s+/g, '\\s+');
    const regexes = {
        contains: new RegExp('\\b' + escaped + '\\b', 'i'),
        parameter: new RegExp('\\b' + escaped + '\\b(?:\\s+|[-—:]\\s+)([0-9]+|x|any|all|\\{[^}]+\\})', 'i'),
        bridgeContains: new RegExp('(?:^|[^a-z0-9])' + escaped + '(?=$|[^a-z0-9])', 'i')
    };
    mechanicKeywordRegexCache.set(normalized, regexes);
    mechanicKeywordRegexCacheStats.computed++;
    if (mechanicKeywordRegexCache.size > MECHANIC_KEYWORD_REGEX_CACHE_MAX) {
        const removeCount = Math.max(128, Math.floor(MECHANIC_KEYWORD_REGEX_CACHE_MAX * 0.15));
        const iterator = mechanicKeywordRegexCache.keys();
        let removed = 0;
        for (let i = 0; i < removeCount; i++) {
            const next = iterator.next();
            if (next.done) break;
            mechanicKeywordRegexCache.delete(next.value);
            removed++;
        }
        mechanicKeywordRegexCacheStats.evictions += removed;
    }
    return regexes;
}

function extractMechanicKeywords(card, text) {
    const fromCard = Array.isArray(card?.keywords) ? card.keywords : [];
    const fullOracle = String(card?.oracle_text || (card?.card_faces ? card.card_faces.map(f => f.oracle_text || '').join(' ') : '') || '');
    const normalizedText = normalizeMechanicToken(text);
    const normalizedFull = normalizeMechanicToken(fullOracle);
    const isTextSubset = Boolean(normalizedText && normalizedFull && normalizedText !== normalizedFull);

    // Scryfall's `keywords` field is authoritative. When the scorer is working from a highlighted
    // subset of Oracle text, keep only the keyword mechanics actually present in that highlighted
    // span so an unrelated keyword elsewhere on the source card cannot inflate the mechanical score.
    const keywords = new Set(fromCard.map(normalizeMechanicToken).filter(Boolean));
    if (isTextSubset) {
        for (const keyword of [...keywords]) {
            const patterns = getMechanicKeywordRegexes(keyword);
            if (!patterns?.contains.test(String(text))) keywords.delete(keyword);
        }
    }
    return keywords;
}

function extractMechanicKeywordParameters(keywords, text) {
    const params = new Set();
    const lowerText = String(text || '').toLowerCase();
    for (const keyword of keywords || []) {
        const patterns = getMechanicKeywordRegexes(keyword);
        const match = patterns?.parameter.exec(lowerText);
        if (match) params.add(`${keyword}:${match[1] || ''}`);
    }
    return params;
}

function collectRegexTokens(text, regex) {
    const out = new Set();
    const input = String(text || '');
    regex.lastIndex = 0;
    let match;
    while ((match = regex.exec(input))) {
        const token = normalizeMechanicToken(match[0]);
        if (token) out.add(token);
        if (regex.lastIndex === match.index) regex.lastIndex++;
    }
    return out;
}

function collectRegexGroupTokens(text, regex) {
    const out = new Set();
    const input = String(text || '');
    regex.lastIndex = 0;
    let match;
    while ((match = regex.exec(input))) {
        const token = normalizeMechanicToken(match[1] || match[0]);
        if (token) out.add(token);
        if (regex.lastIndex === match.index) regex.lastIndex++;
    }
    return out;
}

function buildUniversalMechanicProfile(card = null, text = '', parsedEffects = null) {
    const oracle = String(text || card?.oracle_text || (card?.card_faces ? card.card_faces.map(f => f.oracle_text || '').join(' ') : '') || '');
    const keywords = extractMechanicKeywords(card, oracle);
    const keywordParameters = extractMechanicKeywordParameters(keywords, oracle);

    const actions = new Set();
    UNIVERSAL_RULE_ACTION_REGEX.lastIndex = 0;
    let actionMatch;
    while ((actionMatch = UNIVERSAL_RULE_ACTION_REGEX.exec(oracle))) {
        const action = normalizeMechanicToken(actionMatch[0]);
        const isDrawStepLabel = action === 'draw' && /^\s+step\b/i.test(oracle.slice(actionMatch.index + actionMatch[0].length));
        if (action && !isDrawStepLabel) actions.add(action);
        if (UNIVERSAL_RULE_ACTION_REGEX.lastIndex === actionMatch.index) UNIVERSAL_RULE_ACTION_REGEX.lastIndex++;
    }

    const canonicalFunctions = new Set();
    const canonicalOutcomes = new Set();
    const parsedActions = new Set();
    for (const effect of (parsedEffects || [])) {
        if (!effect) continue;
        if (effect.action && effect.action !== 'generic') parsedActions.add(normalizeMechanicToken(effect.action));
        if (effect.canonical?.function) canonicalFunctions.add(normalizeMechanicToken(effect.canonical.function));
        if (effect.canonical?.outcome) canonicalOutcomes.add(normalizeMechanicToken(effect.canonical.outcome));
    }

    const zones = collectRegexTokens(oracle, UNIVERSAL_ZONE_REGEX);
    const context = {};
    for (const [name, regex] of Object.entries(UNIVERSAL_CONTEXT_PATTERNS)) context[name] = collectRegexTokens(oracle, regex);
    const resources = collectRegexTokens(oracle, UNIVERSAL_RESOURCE_REGEX);
    const stats = collectRegexTokens(oracle, UNIVERSAL_STAT_REGEX);
    const counters = collectRegexTokens(oracle, UNIVERSAL_COUNTER_REGEX);
    const tokens = collectRegexGroupTokens(oracle, UNIVERSAL_TOKEN_REGEX);
    const manaSymbols = collectRegexTokens(oracle, UNIVERSAL_MANA_SYMBOL_REGEX);
    const polarity = polarityProfile(oracle);
    const semanticMechanicBridge = buildSemanticMechanicBridgeProfile(card, oracle);

    const atoms = new Set();
    keywords.forEach(v => atoms.add(`keyword:${v}`));
    keywordParameters.forEach(v => atoms.add(`keyword_param:${v}`));
    actions.forEach(v => atoms.add(`action:${v}`));
    parsedActions.forEach(v => atoms.add(`parsed_action:${v}`));
    canonicalFunctions.forEach(v => atoms.add(`function:${v}`));
    canonicalOutcomes.forEach(v => atoms.add(`outcome:${v}`));
    zones.forEach(v => atoms.add(`zone:${v}`));
    resources.forEach(v => atoms.add(`resource:${v}`));
    counters.forEach(v => atoms.add(`counter:${v}`));
    tokens.forEach(v => atoms.add(`token:${v}`));
    stats.forEach(v => atoms.add(`stat:${v}`));
    manaSymbols.forEach(v => atoms.add(`mana:${v}`));
    Object.entries(polarity).forEach(([kind, value]) => { if (value) atoms.add(`polarity:${kind}`); });
    Object.entries(context).forEach(([kind, set]) => set.forEach(v => atoms.add(`${kind}:${v}`)));

    return {
        keywords,
        keywordParameters,
        actions,
        parsedActions,
        canonicalFunctions,
        canonicalOutcomes,
        zones,
        context,
        resources,
        stats,
        counters,
        tokens,
        manaSymbols,
        polarity,
        semanticMechanicBridge,
        semanticBridgeAnchors: semanticMechanicBridge.anchors,
        atoms,
        keywordCount: keywords.size,
        actionCount: actions.size,
        hasStructuredKeywordData: Array.isArray(card?.keywords) && card.keywords.length > 0
    };
}


// V22: universal evidence weighting. Generic Oracle grammar tokens are useful for parsing but are
// weak proof of a shared mechanic. Specific actions, outcomes, zones, counters, and keyword data
// therefore carry more weight while the generic signature remains a recall backstop for mechanics
// the finite parser does not recognize.
const UNIVERSAL_FEATURE_WEIGHTS = Object.freeze({
    actions: 0.78, parsedActions: 0.86, canonicalFunctions: 1.10, canonicalOutcomes: 1.12,
    zones: 0.90, resources: 0.62, target: 0.62, scope: 0.46, trigger: 0.68,
    cost: 0.34, choice: 0.30, counters: 0.80, tokens: 0.76, stats: 0.58, polarity: 0.90
});
const UNIVERSAL_GENERIC_TOKENS = new Set([
    'choose', 'chosen', 'target', 'a', 'an', 'the', 'you', 'your', 'card', 'cards', 'permanent',
    'permanents', 'player', 'players', 'opponent', 'opponents', 'may', 'one', 'two', 'three',
    'each', 'all', 'any', 'some', 'this', 'that', 'those', 'when', 'whenever', 'if', 'unless',
    'then', 'instead', 'for each', 'up to'
]);
function weightedSymmetricCoverage(sourceSet, candidateSet, factor = 0.9) {
    const source = sourceSet instanceof Set ? sourceSet : new Set(sourceSet || []);
    const candidate = candidateSet instanceof Set ? candidateSet : new Set(candidateSet || []);
    if (!source.size && !candidate.size) return 1;
    if (!source.size || !candidate.size) return 0;
    const useful = value => !UNIVERSAL_GENERIC_TOKENS.has(normalizeMechanicToken(value));
    const a = [...source].filter(useful);
    const b = [...candidate].filter(useful);
    const aa = a.length ? a : [...source];
    const bb = b.length ? b : [...candidate];
    const overlap = aa.filter(v => bb.includes(v)).length;
    const directionalA = overlap / Math.max(1, aa.length);
    const directionalB = overlap / Math.max(1, bb.length);
    return Math.max(0, Math.min(1, Math.sqrt(directionalA * directionalB) * factor + (1 - factor) * Math.min(directionalA, directionalB)));
}
function polarityProfile(text) {
    const value = String(text || '').toLowerCase();
    return {
        negative: /\b(?:can't|cannot|do not|doesn't|don't|isn't|aren't|never|no longer)\b/.test(value),
        replacement: /\b(?:instead|replace|rather than)\b/.test(value),
        prevention: /\b(?:prevent|prevents|prevented)\b/.test(value),
        prohibition: /\b(?:can't|cannot|may not|don't)\b/.test(value)
    };
}
function comparePolarity(a = {}, b = {}) {
    const keys = ['negative', 'replacement', 'prevention', 'prohibition'];
    let seen = 0, equal = 0;
    for (const key of keys) {
        if (a[key] !== undefined || b[key] !== undefined) {
            seen++;
            if (a[key] === b[key]) equal++;
        }
    }
    return seen ? equal / seen : 1;
}
function buildUniversalFunctionalText(card = null, text = '', parsedEffects = null) {
    const oracle = String(text || card?.oracle_text || (card?.card_faces ? card.card_faces.map(f => f.oracle_text || '').join(' ') : '') || '').trim();
    let parsed = parsedEffects;
    try { parsed = Array.isArray(parsed) ? parsed : parseMTGEffect(oracle); } catch (_) { parsed = []; }
    const profile = buildUniversalMechanicProfile(card, oracle, parsed);
    const parts = [];
    const canonical = getCachedCanonicalFunctionText(parsed);
    if (canonical) parts.push(canonical);
    if (profile.keywords.size) parts.push(`keywords ${[...profile.keywords].join(' ')}`);
    const usefulActions = [...profile.actions].filter(x => !UNIVERSAL_GENERIC_TOKENS.has(x));
    if (usefulActions.length) parts.push(`actions ${usefulActions.join(' ')}`);
    if (profile.zones.size) parts.push(`zones ${[...profile.zones].join(' ')}`);
    if (profile.resources.size) parts.push(`resources ${[...profile.resources].join(' ')}`);
    if (profile.counters.size) parts.push(`counters ${[...profile.counters].join(' ')}`);
    if (profile.stats.size) parts.push(`stats ${[...profile.stats].join(' ')}`);
    if (profile.context?.target?.size) parts.push(`targets ${[...profile.context.target].join(' ')}`);
    if (profile.context?.scope?.size) parts.push(`scope ${[...profile.context.scope].join(' ')}`);
    if (profile.context?.trigger?.size) parts.push(`triggers ${[...profile.context.trigger].join(' ')}`);
    return parts.join('. ');
}

const universalMechanicSimilarityPairCache = new WeakMap();
function calculateUniversalMechanicSimilarity(profileA, profileB) {
    if (!profileA || !profileB) return { score: 0, keywordCoverage: 0, keywordParameterCoverage: 0, actionCoverage: 0, parsedActionCoverage: 0, functionCoverage: 0, outcomeCoverage: 0, zoneCoverage: 0, targetCoverage: 0, scopeCoverage: 0, triggerCoverage: 0, costCoverage: 0, choiceCoverage: 0, resourceCoverage: 0, atomCoverage: 0, counterCoverage: 0, tokenCoverage: 0, statCoverage: 0, polaritySimilarity: 0, sharedKeywords: [] };
    let profileRow = universalMechanicSimilarityPairCache.get(profileA);
    if (profileRow?.has(profileB)) return profileRow.get(profileB);
    const values = (set) => set instanceof Set ? [...set] : Array.isArray(set) ? set : set && typeof set === 'object' ? Object.keys(set) : [];
    const size = set => values(set).length;
    // No evidence on either card is missing information, not a perfect match. This is critical:
    // the old empty/empty=1 behavior let unrelated unrecognized cards reach ~0.92 similarity.
    const evidenceCoverage = (a, b, factor = 0.9) => size(a) === 0 && size(b) === 0 ? 0 : weightedSymmetricCoverage(a, b, factor);
    const keywordCoverage = evidenceCoverage(profileA.keywords, profileB.keywords, 1.0);
    const keywordParameterCoverage = evidenceCoverage(profileA.keywordParameters, profileB.keywordParameters, 1.0);
    const actionCoverage = evidenceCoverage(profileA.actions, profileB.actions, 0.90);
    const parsedActionCoverage = evidenceCoverage(profileA.parsedActions, profileB.parsedActions, 0.92);
    const functionCoverage = evidenceCoverage(profileA.canonicalFunctions, profileB.canonicalFunctions, 1.0);
    const outcomeCoverage = evidenceCoverage(profileA.canonicalOutcomes, profileB.canonicalOutcomes, 1.0);
    const zoneCoverage = evidenceCoverage(profileA.zones, profileB.zones, 0.95);
    const targetCoverage = evidenceCoverage(profileA.context?.target, profileB.context?.target, 0.78);
    const scopeCoverage = evidenceCoverage(profileA.context?.scope, profileB.context?.scope, 0.68);
    const triggerCoverage = evidenceCoverage(profileA.context?.trigger, profileB.context?.trigger, 0.82);
    const costCoverage = evidenceCoverage(profileA.context?.cost, profileB.context?.cost, 0.52);
    const choiceCoverage = evidenceCoverage(profileA.context?.choice, profileB.context?.choice, 0.48);
    const resourceCoverage = evidenceCoverage(profileA.resources, profileB.resources, 0.72);
    const counterCoverage = evidenceCoverage(profileA.counters, profileB.counters, 0.88);
    const tokenCoverage = evidenceCoverage(profileA.tokens, profileB.tokens, 0.84);
    const statCoverage = evidenceCoverage(profileA.stats, profileB.stats, 0.65);
    const atomCoverage = evidenceCoverage(profileA.atoms, profileB.atoms, 0.82);
    const polaritySimilarity = comparePolarity(profileA.polarity || {}, profileB.polarity || {});
    const sharedKeywords = [...(profileA.keywords || [])].filter(k => (profileB.keywords || new Set()).has(k));
    const exactKeywordEvidence = keywordCoverage > 0
        ? Math.min(1, keywordCoverage * 0.78 + keywordParameterCoverage * 0.16)
        : 0;
    const weights = UNIVERSAL_FEATURE_WEIGHTS;
    const pairs = [
        ['actions', profileA.actions, profileB.actions, actionCoverage, weights.actions],
        ['parsedActions', profileA.parsedActions, profileB.parsedActions, parsedActionCoverage, weights.parsedActions],
        ['canonicalFunctions', profileA.canonicalFunctions, profileB.canonicalFunctions, functionCoverage, weights.canonicalFunctions],
        ['canonicalOutcomes', profileA.canonicalOutcomes, profileB.canonicalOutcomes, outcomeCoverage, weights.canonicalOutcomes],
        ['zones', profileA.zones, profileB.zones, zoneCoverage, weights.zones],
        ['target', profileA.context?.target, profileB.context?.target, targetCoverage, weights.target],
        ['scope', profileA.context?.scope, profileB.context?.scope, scopeCoverage, weights.scope],
        ['trigger', profileA.context?.trigger, profileB.context?.trigger, triggerCoverage, weights.trigger],
        ['cost', profileA.context?.cost, profileB.context?.cost, costCoverage, weights.cost],
        ['choice', profileA.context?.choice, profileB.context?.choice, choiceCoverage, weights.choice],
        ['resources', profileA.resources, profileB.resources, resourceCoverage, weights.resources],
        ['counters', profileA.counters, profileB.counters, counterCoverage, weights.counters],
        ['tokens', profileA.tokens, profileB.tokens, tokenCoverage, weights.tokens],
        ['stats', profileA.stats, profileB.stats, statCoverage, weights.stats],
        ['polarity', null, null, polaritySimilarity, weights.polarity]
    ];
    let numerator = 0, denominator = 0;
    for (const [key, a, b, coverage, weight] of pairs) {
        const informative = key === 'polarity'
            ? Object.values(profileA.polarity || {}).some(Boolean) || Object.values(profileB.polarity || {}).some(Boolean)
            : size(a) > 0 || size(b) > 0;
        if (!informative) continue;
        numerator += (Number(coverage) || 0) * weight;
        denominator += weight;
    }
    const weightedTextEvidence = denominator ? numerator / denominator : 0;
    const signatureEvidence = Math.max(weightedTextEvidence, exactKeywordEvidence, atomCoverage * 0.72,
        keywordCoverage * 0.70 + counterCoverage * 0.15 + tokenCoverage * 0.15);
    const result = {
        score: Math.max(0, Math.min(1, signatureEvidence)), keywordCoverage, keywordParameterCoverage,
        actionCoverage, parsedActionCoverage, functionCoverage, outcomeCoverage, zoneCoverage,
        targetCoverage, scopeCoverage, triggerCoverage, costCoverage, choiceCoverage, resourceCoverage,
        atomCoverage, counterCoverage, tokenCoverage, statCoverage, polaritySimilarity, sharedKeywords
    };
    if (!profileRow) {
        profileRow = new WeakMap();
        universalMechanicSimilarityPairCache.set(profileA, profileRow);
    }
    profileRow.set(profileB, result);
    return result;
}

// ---------------------------------------------------------------------------
// V21 MECHANICAL GRAPH + RULES-AWARE RANKING LAYER
// ---------------------------------------------------------------------------
// The parser/universal-keyword layer is now promoted into a graph representation. A Magic card is
// not merely a bag of words or isolated effects: effects have triggers, targets, costs, zones,
// restrictions, quantities, durations, replacement/static modes, and an order/dependency relation.
// This layer compares those relationships explicitly while remaining tolerant of wording changes.
//
// Important design rule: this is still evidence, not a rules oracle. The parser can miss things;
// raw Oracle semantics and Scryfall keyword metadata remain parallel evidence sources. The graph
// therefore never hard-vetoes a candidate solely because a heuristic field is absent.

